def memory_pressure_plan(pressure: str) -> dict[str, Any]:
    """CP-05: map a memory-pressure level to the work the scan/monitor should shed.

    Pure (no I/O) so it is unit-testable in isolation. ``batchScale`` is a hint
    in (0, 1] for the embedding/cluster batch size; the optional flags tell the
    pipeline to skip regenerable work (previews) and force a GC under pressure.
    """
    level = str(pressure or "normal").lower()
    if level == "critical":
        return {"collectGarbage": True, "reducePreviews": True, "batchScale": 0.25}
    if level == "high":
        return {"collectGarbage": True, "reducePreviews": True, "batchScale": 0.5}
    if level == "elevated":
        return {"collectGarbage": False, "reducePreviews": False, "batchScale": 0.75}
    return {"collectGarbage": False, "reducePreviews": False, "batchScale": 1.0}


class DesktopApi(PublicDatasetBenchmarkMixin):
    def __init__(self, workspace: Path, actor: str = "desktop", startup: Any | None = None) -> None:
        self.actor = actor
        self.startup = startup
        self.project = ProjectState(workspace, actor=actor)
        self.consent_on_file = self.project.consent_on_file()
        self._engine: EmbeddingEngine | None = None
        self._engine_model_name = self._infer_engine_name()
        self._verification_engine_cache: tuple[str, Any] | None = None
        self._startup("workspace", f"Workspace ready: {self.project.root}")
        self._startup("engine", "Recognition engine will load when needed")
        self._startup("platform", "Detecting platform acceleration")
        self.platform_report = build_platform_report()
        self._last_progress_state_at = 0.0
        self._last_progress_state_added = 0
        self._last_resource_status_at = 0.0
        self._last_resource_status: dict[str, Any] = {}
        self._photo_reverse_geocode_cache: dict[str, dict[str, Any]] = {}
        self._photo_reverse_geocode_provider = None
        self._startup("ready", "Backend ready")

    def _startup(self, phase: str, message: str) -> None:
        if self.startup:
            self.startup({"phase": phase, "message": message})

    @property
    def engine_name(self) -> str:
        return self._engine.model_name if self._engine is not None else self._engine_model_name

    def _engine_instance(self) -> EmbeddingEngine:
        if self._engine is None:
            self._startup("engine", "Loading recognition engine")
            with redirect_stdout(sys.stderr):
                self._engine = create_embedding_engine(self._effective_engine_config())
            self._engine_model_name = self._engine.model_name
            self._startup("engine", f"Recognition engine ready: {self._engine_model_name}")
        return self._engine

    def _reset_engine(self) -> None:
        self._engine = None
        self._verification_engine_cache = None
        self._engine_model_name = self._infer_engine_name()

    def _build_info(self) -> dict[str, Any]:
        commit = (
            os.environ.get("VINTRACE_BUILD_SHA")
            or os.environ.get("GITHUB_SHA")
            or self._git_value(["rev-parse", "--short=12", "HEAD"])
        )
        branch = (
            os.environ.get("VINTRACE_BUILD_REF")
            or os.environ.get("GITHUB_REF_NAME")
            or self._git_value(["rev-parse", "--abbrev-ref", "HEAD"])
        )
        return {
            "name": "Vintrace",
            "version": __version__,
            "commit": commit or "local",
            "branch": branch or "",
            "buildDate": os.environ.get("VINTRACE_BUILD_DATE", ""),
            "channel": os.environ.get("VINTRACE_UPDATE_CHANNEL", os.environ.get("CROSSAGE_UPDATE_CHANNEL", "stable")),
            "packaged": bool(getattr(sys, "frozen", False) or os.environ.get("CROSSAGE_PACKAGED_BACKEND") == "1"),
            "python": sys.version.split()[0],
        }

    def _git_value(self, args: list[str]) -> str:
        try:
            repo_root = Path(__file__).resolve().parents[1]
            completed = subprocess.run(
                ["git", *args],
                cwd=repo_root,
                check=False,
                capture_output=True,
                text=True,
                timeout=1.5,
            )
            if completed.returncode == 0:
                return completed.stdout.strip()
        except Exception:
            pass
        return ""

    def _infer_engine_name(self) -> str:
        if os.environ.get("CROSSAGE_FORCE_FALLBACK") == "1":
            return "local-image-fingerprint"
        if importlib.util.find_spec("insightface") is None:
            return "local-image-fingerprint"
        candidates = [self.project.config.model_pack]
        if "buffalo_l" not in candidates:
            candidates.append("buffalo_l")
        for pack in candidates:
            if any(model_pack_ready(root, pack) for root in model_roots_for_engine(self.project.config)):
                return f"insightface-{pack}"
        return "local-image-fingerprint (face model download needed)"

    def _model_name_for_pack(self, pack: str) -> str:
        spec = MODEL_PACKAGES.get(pack)
        if spec and spec.embedding_space:
            return spec.embedding_space
        return f"insightface-{pack}"

    def _effective_performance_mode(self) -> str:
        mode = str(getattr(self.project.config, "performance_mode", "auto") or "auto").lower()
        if mode == "auto":
            mode = str(getattr(self.platform_report, "recommended_performance_mode", "balanced") or "balanced").lower()
        return mode if mode in {"fast", "balanced", "quality"} else "balanced"

    def _effective_engine_config(self) -> Any:
        config = deepcopy(self.project.config)
        mode = self._effective_performance_mode()
        if mode == "fast":
            config.face_detector_size = min(int(config.face_detector_size), 384)
            config.two_pass_scan = False
            config.verification_detector_size = config.face_detector_size
        elif mode == "balanced":
            config.face_detector_size = min(int(config.face_detector_size), 512)
            config.verification_detector_size = min(max(int(config.verification_detector_size), int(config.face_detector_size)), 640)
        return config

    def _require_scan_model_compatibility(self, engine: EmbeddingEngine, params: dict[str, Any]) -> None:
        if bool(params.get("allowIncompatibleModel", False)):
            return
        report = self.project.model_compatibility_report(str(getattr(engine, "model_name", "") or ""))
        if not report.get("needsBackfill"):
            return
        raise ValueError(
            "[E-MODEL-BACKFILL] Saved person photos were embedded with another model pack. "
            "Backfill saved photos before scanning, or explicitly allow an incompatible-model scan."
        )

    def _model_switch_dry_run(self, target_pack: str) -> dict[str, Any]:
        pack = str(target_pack or self.project.config.model_pack or "").strip()
        if pack not in MODEL_PACKAGES:
            raise ValueError("Choose a known face model package.")
        spec = MODEL_PACKAGES[pack]
        setup = model_status(self.project.config, self.engine_name)
        package = next((item for item in setup.get("packages", []) if item.get("pack") == pack), {})
        installed = bool(package.get("available", False))
        current_pack = str(self.project.config.model_pack or "")
        target_model_name = self._model_name_for_pack(pack)
        current_report = self.project.model_compatibility_report(self.engine_name)
        target_report = self.project.model_compatibility_report(target_model_name)
        affected_candidates = sum(
            1
            for candidate in self.project.candidates.values()
            if candidate.model_name and not self.project._compatible_reference_model_name(target_model_name, candidate.model_name)
        )
        total_references = int(target_report.get("totalReferences", len(self.project.references)) or 0)
        backfill_count = int(target_report.get("otherModelReferences", 0) or 0)
        existing_bytes = int(package.get("installedBytes", 0) or 0)
        download_bytes = 0 if installed else int(spec.size_bytes)
        backfill_metadata_bytes = backfill_count * 4096
        effective_mode = self._effective_performance_mode()
        per_reference_seconds = 0.35 if effective_mode == "fast" else 0.55 if effective_mode == "balanced" else 0.8
        estimated_backfill_seconds = round(backfill_count * per_reference_seconds, 1)
        blockers: list[str] = []
        warnings: list[str] = []
        actions: list[str] = []
        if not installed:
            blockers.append("Download the selected model before saving this switch.")
            actions.append("Download selected model.")
        if pack != current_pack:
            actions.append("Save model choice after the dry run looks correct.")
        if backfill_count:
            warnings.append(f"{backfill_count} saved person photo(s) need embeddings for this model.")
            actions.append("Backfill saved photos after saving the switch.")
        if affected_candidates:
            warnings.append(f"{affected_candidates} existing review row(s) were produced by another model space.")
        if spec.pose_aware:
            warnings.append("Pose-aware model spaces are isolated; do not compare old embeddings directly.")
        if not total_references:
            warnings.append("No saved person photos exist yet, so accuracy cannot be judged after switching.")
        if not actions:
            actions.append("No model migration action is required.")
        return {
            "targetPack": pack,
            "targetLabel": spec.label,
            "targetModelName": target_model_name,
            "currentPack": current_pack,
            "currentModelName": self.engine_name,
            "modelRoot": str(setup.get("modelRoot", model_root_for_config(self.project.config))),
            "installed": installed,
            "safeToSave": installed,
            "willResetEngine": pack != current_pack,
            "poseAware": bool(spec.pose_aware),
            "downloadBytes": download_bytes,
            "installedBytes": existing_bytes,
            "estimatedDiskImpactBytes": download_bytes + backfill_metadata_bytes,
            "estimatedBackfillSeconds": estimated_backfill_seconds,
            "totalReferences": total_references,
            "compatibleReferences": int(target_report.get("compatibleReferences", 0) or 0),
            "referencesNeedingBackfill": backfill_count,
            "currentCompatibleReferences": int(current_report.get("compatibleReferences", 0) or 0),
            "affectedCandidates": affected_candidates,
            "rollbackPack": current_pack if current_pack in MODEL_PACKAGES else "",
            "thresholds": spec.thresholds,
            "blockers": blockers,
            "warnings": warnings,
            "actions": actions,
            "summary": (
                "Ready to save; backfill saved photos afterwards."
                if installed and backfill_count
                else "Ready to save."
                if installed
                else "Download required before this switch can run offline."
            ),
        }

    # MA-4: required-parameter schema validated once at the dispatch boundary.
    # Seeded from the commands whose handlers directly index params[...] (an
    # absent key currently raises an opaque KeyError); this turns that into a
    # clear, uniform error. Per-command typed/range specs extend this dict.
    _COMMAND_REQUIRED_PARAMS = {
        "set_workspace": ("path",),
        "set_status": ("candidateId", "status"),
        "bulk_set_status": ("status",),
        "set_candidate_note": ("candidateId",),
        "block_false_match": ("candidateId",),
        "reassign_candidate_person": ("candidateId", "personName"),
        "semantic_search_photos": ("query",),
        "delete_reference": ("refId",),
        "delete_person": ("personName",),
        "rename_person": ("oldName", "newName"),
        "rename_photo_pet": ("oldName", "newName"),
        "assign_photo_pet": ("petName",),
    }

    def handle(self, command: str, params: dict[str, Any], progress: Any | None = None) -> Any:
        if not isinstance(params, dict):
            raise ValueError("Command parameters must be an object.")
        # MA-2: O(1) registry dispatch replaces the former 96-branch if-chain.
        handler = self._COMMAND_HANDLERS.get(command)
        if handler is None:
            raise ValueError(f"Unknown command: {command}")
        # MA-4: validate required params once, at the boundary.
        required = self._COMMAND_REQUIRED_PARAMS.get(command)
        if required:
            missing = [key for key in required if key not in params]
            if missing:
                raise ValueError(f"{command} requires parameter(s): {', '.join(missing)}.")
        return getattr(self, handler)(params, progress)

