    def _cmd_export_photo_selection(self, params, progress=None):
        source_paths = params.get("sourcePaths", [])
        if not isinstance(source_paths, list):
            raise ValueError("sourcePaths must be a list.")
        folder_param = str(params.get("folder", "")).strip()
        return {
            "value": self.export_photo_selection(
                [str(path) for path in source_paths],
                Path(folder_param).expanduser() if folder_param else None,
                action=str(params.get("action", "export") or "export"),
                include_metadata=bool(params.get("includeMetadata")),
                include_xmp=bool(params.get("includeXmp")),
                include_existing_sidecars=bool(params.get("includeExistingSidecars")),
                strip_location=bool(params.get("stripLocation")),
                layout=str(params.get("layout", "bundle") or "bundle"),
                filename_mode=str(params.get("filenameMode", "numbered") or "numbered"),
                filename_template=str(params.get("filenameTemplate", "") or ""),
                subfolder_template=str(params.get("subfolderTemplate", "") or ""),
                export_variant=str(params.get("exportVariant", params.get("variant", "original")) or "original"),
                render_format=str(params.get("renderFormat", params.get("format", "jpeg")) or "jpeg"),
                render_quality=params.get("renderQuality", params.get("quality", 92)),
                render_max_dimension=params.get("renderMaxDimension", params.get("maxDimension", 0)),
                preserve_color_profile=bool(params.get("preserveColorProfile", True)),
                target_color_profile=str(params.get("targetColorProfile", params.get("colorProfileTarget", "")) or ""),
                target_color_profile_path=str(params.get("targetColorProfilePath", params.get("colorProfilePath", "")) or ""),
                allow_render_fallback=bool(params.get("allowRenderFallback", True)),
                video_render_format=str(params.get("videoRenderFormat", params.get("renderVideoFormat", "mp4")) or "mp4"),
                video_render_quality=str(params.get("videoRenderQuality", params.get("renderVideoQuality", params.get("videoQuality", "medium"))) or "medium"),
            )
        }

