    def _cmd_self_learning_rd_status(self, params, progress=None):
        try:
            from crossage_fr.experiments import self_learning_audit

            repo_root = Path(__file__).resolve().parents[1]
            evidence_root = repo_root / "benchmarks" / "evidence" / "self-learning-rd"
            audit_path = evidence_root / "self_learning_rd_audit.json"
            if not audit_path.is_file():
                return {
                    "ok": False,
                    "status": "missing",
                    "notProductionAuthorization": True,
                    "auditPath": str(audit_path),
                    "satisfied": [],
                    "blocked": [],
                    "blockers": ["self-learning-audit-missing"],
                    "sourceReports": {},
                    "message": "Self-learning R&D evidence is not bundled in this build.",
                }
            verification = self_learning_audit.verify_self_learning_rd_audit(audit_path)
            payload = verification.get("payload") if isinstance(verification.get("payload"), dict) else {}
            if verification.get("verified") is not True:
                return {
                    "ok": False,
                    "status": "invalid",
                    "notProductionAuthorization": True,
                    "auditPath": str(audit_path),
                    "satisfied": [],
                    "blocked": [],
                    "blockers": [str(error) for error in verification.get("errors", [])],
                    "sourceReports": {},
                    "message": "Self-learning R&D evidence failed verification.",
                }
            requirements = payload.get("requirements") if isinstance(payload.get("requirements"), list) else []
            satisfied = [
                str(row.get("id", "") or "")
                for row in requirements
                if isinstance(row, dict) and row.get("ok") is True and str(row.get("id", "") or "")
            ]
            blocked = [
                str(row.get("id", "") or "")
                for row in requirements
                if isinstance(row, dict) and row.get("ok") is not True and str(row.get("id", "") or "")
            ]
            return {
                "ok": bool(payload.get("ok")),
                "status": str(payload.get("status", "") or ""),
                "notProductionAuthorization": payload.get("notProductionAuthorization") is True,
                "auditPath": str(audit_path),
                "satisfied": satisfied,
                "blocked": blocked,
                "blockers": [str(item) for item in payload.get("blockers", []) if str(item)],
                "sourceReports": payload.get("sourceReports") if isinstance(payload.get("sourceReports"), dict) else {},
                "reportHash": str(payload.get("reportHash", "") or ""),
                "message": str(payload.get("message", "") or "Self-learning R&D evidence loaded."),
            }
        except Exception as exc:
            return {
                "ok": False,
                "status": "error",
                "notProductionAuthorization": True,
                "auditPath": "",
                "satisfied": [],
                "blocked": [],
                "blockers": [f"self-learning-rd-status-error:{exc.__class__.__name__}"],
                "sourceReports": {},
                "message": "Self-learning R&D status could not be read.",
            }

