    def _reference_suggestion_embedding(self, candidate: ReviewCandidate, engine: EmbeddingEngine) -> EmbeddingResult:
        path = Path(candidate.source_path).expanduser()
        if not path.exists():
            raise ValueError("Candidate source image is missing.")
        image = load_image(path)
        embeddings = engine.embed_loaded_image(image, path)
        if not embeddings and self.project.config.two_pass_scan:
            rescue_method = getattr(engine, "embed_loaded_image_rescue", None)
            embeddings = rescue_method(image, path) if callable(rescue_method) else []
        if not embeddings:
            raise ValueError("No face embedding was found in the accepted candidate image.")
        compatible = [
            embedding
            for embedding in embeddings
            if not candidate.model_name or self.project._compatible_reference_model_name(candidate.model_name, embedding.model_name)
        ]
        return max(compatible or embeddings, key=lambda item: float(item.quality or 0.0))

    def _cmd_reference_suggestion_status(self, params, progress=None):
        return self.project.reference_suggestion_status(limit=int(params.get("limit", 20) or 20))

    def _cmd_stage_reference_suggestions(self, params, progress=None):
        limit = max(1, min(50, int(params.get("limit", 20) or 20)))
        engine = self._engine_instance()
        embeddings: dict[str, EmbeddingResult] = {}
        embedding_errors: list[dict[str, str]] = []
        for candidate in self.project.reference_suggestion_candidates(limit=limit * 4):
            try:
                embeddings[candidate.candidate_id] = self._reference_suggestion_embedding(candidate, engine)
            except Exception as exc:
                embedding_errors.append({"candidateId": candidate.candidate_id, "error": str(exc)})
        result = self.project.stage_reference_suggestions(embeddings, limit=limit)
        if embedding_errors:
            result["embeddingErrors"] = embedding_errors[:20]
        return {"value": result, "state": self.state(preview_create_budget=0)}

    def _cmd_approve_reference_suggestion(self, params, progress=None):
        artifact_id = str(params.get("artifactId", "") or "")
        artifact = self.project.db.learned_artifact_by_id(artifact_id)
        payload = artifact.get("payload") if artifact and isinstance(artifact.get("payload"), dict) else {}
        candidate_id = str(payload.get("candidateId", payload.get("candidate_id", "")) or "")
        candidate = self.project.candidates.get(candidate_id)
        if candidate is None:
            raise ValueError("The source candidate for this reference suggestion is no longer available.")
        embedding = self._reference_suggestion_embedding(candidate, self._engine_instance())
        result = self.project.approve_reference_suggestion(artifact_id, embedding, operator=self.actor)
        return {"value": result, "state": self.state()}

