    def _cmd_save_settings(self, params, progress=None):
        thresholds = self.project.config.thresholds
        incoming = params.get("thresholds", {})
        if not isinstance(incoming, dict):
            raise ValueError("Threshold settings must be an object.")
        confident = float(incoming.get("confident", thresholds.confident))
        likely = float(incoming.get("likely", thresholds.likely))
        relaxed_child = float(incoming.get("relaxedChild", thresholds.relaxed_child))
        quality_min = float(incoming.get("qualityMin", thresholds.quality_min))
        values = [confident, likely, relaxed_child, quality_min]
        if any(not math.isfinite(value) or value < 0.0 or value > 1.0 for value in values):
            raise ValueError("Thresholds and quality minimum must be between 0 and 1.")
        if not confident >= likely >= relaxed_child:
            raise ValueError("Thresholds must be descending: confident >= likely >= relaxed child.")
        cluster_min_size = int(params.get("clusterMinSize", self.project.config.cluster_min_size))
        if cluster_min_size < 2:
            raise ValueError("Cluster minimum size must be at least 2.")
        if cluster_min_size > MAX_CLUSTER_MIN_SIZE:
            raise ValueError(f"Cluster minimum size must be {MAX_CLUSTER_MIN_SIZE} or lower.")
        face_detector_size = int(params.get("faceDetectorSize", self.project.config.face_detector_size))
        if face_detector_size < MIN_FACE_DETECTOR_SIZE:
            raise ValueError(f"Face scan detail must be at least {MIN_FACE_DETECTOR_SIZE}.")
        if face_detector_size > MAX_FACE_DETECTOR_SIZE:
            raise ValueError(f"Face scan detail must be {MAX_FACE_DETECTOR_SIZE} or lower.")
        face_detector_size = int(round(face_detector_size / 32) * 32)
        two_pass_scan = bool(params.get("twoPassScan", self.project.config.two_pass_scan))
        verification_detector_size = int(params.get("verificationDetectorSize", self.project.config.verification_detector_size))
        if verification_detector_size < MIN_FACE_DETECTOR_SIZE:
            raise ValueError(f"High-detail recheck must be at least {MIN_FACE_DETECTOR_SIZE}.")
        if verification_detector_size > MAX_FACE_DETECTOR_SIZE:
            raise ValueError(f"High-detail recheck must be {MAX_FACE_DETECTOR_SIZE} or lower.")
        verification_detector_size = int(round(verification_detector_size / 32) * 32)
        if verification_detector_size < face_detector_size:
            verification_detector_size = face_detector_size
        performance_mode = str(params.get("performanceMode", self.project.config.performance_mode)).strip().lower()
        if performance_mode not in PERFORMANCE_MODES:
            raise ValueError("Performance mode must be auto, fast, balanced, or quality.")
        learning_mode = str(params.get("learningMode", self.project.config.learning_mode)).strip().lower().replace("-", "_")
        if learning_mode not in LEARNING_MODES:
            raise ValueError("Learning mode must be off, manual, or auto_stage.")
        model_pack = str(params.get("modelPack", self.project.config.model_pack)).strip()
        if model_pack not in MODEL_PACKAGES:
            raise ValueError("Choose a known face model package.")
        storage_budget_bytes = int(params.get("storageBudgetBytes", self.project.config.storage_budget_bytes))
        if storage_budget_bytes < 0:
            raise ValueError("Storage limit must be zero or higher.")
        storage_budget_bytes = min(storage_budget_bytes, 10 * 1024 * 1024 * 1024 * 1024)
        max_media_file_bytes = int(params.get("maxMediaFileBytes", self.project.config.max_media_file_bytes))
        if max_media_file_bytes < 0:
            raise ValueError("Maximum media file size must be zero or higher.")
        max_media_file_bytes = min(max_media_file_bytes, 10 * 1024 * 1024 * 1024 * 1024)
        review_rules = params.get("reviewRules", {})
        if not isinstance(review_rules, dict):
            raise ValueError("Review rules must be an object.")
        auto_reject_below = float(review_rules.get("autoRejectBelow", self.project.config.auto_reject_below))
        if not math.isfinite(auto_reject_below) or auto_reject_below < 0.0 or auto_reject_below > 1.0:
            raise ValueError("Auto-reject level must be between 0 and 1.")
        auto_uncertain_low_quality = bool(review_rules.get("autoUncertainLowQuality", self.project.config.auto_uncertain_low_quality))
        auto_reject_low_quality_video = bool(review_rules.get("autoRejectLowQualityVideo", self.project.config.auto_reject_low_quality_video))
        scan_exclusions = params.get("scanExclusions", {})
        if not isinstance(scan_exclusions, dict):
            raise ValueError("Scan exclusions must be an object.")
        excluded_dir_names = self._string_list(scan_exclusions.get("dirNames", self.project.config.excluded_dir_names), "Excluded folder names")
        excluded_path_keywords = self._string_list(scan_exclusions.get("pathKeywords", self.project.config.excluded_path_keywords), "Excluded path words")
        excluded_extensions = self._extension_list(scan_exclusions.get("extensions", self.project.config.excluded_extensions))
        excluded_file_paths = self._string_list(scan_exclusions.get("filePaths", self.project.config.excluded_file_paths), "Excluded files", limit=400)
        video_decoder_settings = params.get("videoDecoder", {})
        if video_decoder_settings is None:
            video_decoder_settings = {}
        if not isinstance(video_decoder_settings, dict):
            raise ValueError("Video decoder settings must be an object.")
        ffmpeg_path = self._optional_existing_file(
            video_decoder_settings.get("ffmpegPath", self.project.config.ffmpeg_path),
            "FFmpeg path",
        )
        ffprobe_path = self._optional_existing_file(
            video_decoder_settings.get("ffprobePath", self.project.config.ffprobe_path),
            "FFprobe path",
        )
        safe_mode_threshold = float(params.get("safeModeThreshold", self.project.config.safe_mode_threshold))
        if not math.isfinite(safe_mode_threshold) or safe_mode_threshold < 0.0 or safe_mode_threshold > 1.0:
            raise ValueError("Safe Mode threshold must be between 0 and 1.")
        # Stage 1a: a named threshold profile (privacy/balanced/permissive) is
        # authoritative for the effective threshold; "custom" keeps the explicit value.
        safe_mode_profile = normalize_safe_mode_profile(
            params.get("safeModeProfile", self.project.config.safe_mode_profile)
        )
        if safe_mode_profile != "custom":
            safe_mode_threshold = safe_mode_threshold_for_profile(safe_mode_profile)
        thresholds.confident = confident
        thresholds.likely = likely
        thresholds.relaxed_child = relaxed_child
        thresholds.quality_min = quality_min
        self.project.config.cluster_min_size = cluster_min_size
        self.project.config.face_detector_size = face_detector_size
        self.project.config.two_pass_scan = two_pass_scan
        self.project.config.verification_detector_size = verification_detector_size
        self.project.config.performance_mode = performance_mode
        self.project.config.learning_mode = learning_mode
        self.project.config.model_pack = model_pack
        self.project.config.storage_budget_bytes = storage_budget_bytes
        self.project.config.max_media_file_bytes = max_media_file_bytes
        self.project.config.auto_reject_below = auto_reject_below
        self.project.config.auto_uncertain_low_quality = auto_uncertain_low_quality
        self.project.config.auto_reject_low_quality_video = auto_reject_low_quality_video
        self.project.config.excluded_dir_names = excluded_dir_names
        self.project.config.excluded_path_keywords = excluded_path_keywords
        self.project.config.excluded_extensions = excluded_extensions
        self.project.config.excluded_file_paths = excluded_file_paths
        self.project.config.ffmpeg_path = ffmpeg_path
        self.project.config.ffprobe_path = ffprobe_path
        self.project.config.per_subject_consent = bool(
            params.get("perSubjectConsent", self.project.config.per_subject_consent)
        )
        self.project.config.safe_mode = bool(params.get("safeMode", self.project.config.safe_mode))
        self.project.config.safe_mode_zero_admittance = bool(
            params.get("safeModeZeroAdmittance", self.project.config.safe_mode_zero_admittance)
        )
        self.project.config.safe_mode_threshold = safe_mode_threshold
        self.project.config.safe_mode_profile = safe_mode_profile
        self.project.apply_video_decoder_config()
        self.project._append_audit(
            {
                "action": "save_settings",
                "thresholds": {
                    "confident": confident,
                    "likely": likely,
                    "relaxed_child": relaxed_child,
                    "quality_min": quality_min,
                },
                "cluster_min_size": cluster_min_size,
                "face_detector_size": face_detector_size,
                "two_pass_scan": two_pass_scan,
                "verification_detector_size": verification_detector_size,
                "performance_mode": performance_mode,
                "learning_mode": learning_mode,
                "model_pack": model_pack,
                "storage_budget_bytes": storage_budget_bytes,
                "max_media_file_bytes": max_media_file_bytes,
                "review_rules": {
                    "auto_reject_below": auto_reject_below,
                    "auto_uncertain_low_quality": auto_uncertain_low_quality,
                    "auto_reject_low_quality_video": auto_reject_low_quality_video,
                },
                "scan_exclusions": {
                    "dir_names": excluded_dir_names,
                    "path_keywords": excluded_path_keywords,
                    "extensions": excluded_extensions,
                    "file_paths": excluded_file_paths,
                },
                "video_decoder": {
                    "ffmpeg_path_set": bool(ffmpeg_path),
                    "ffprobe_path_set": bool(ffprobe_path),
                },
                "safe_mode": self.project.config.safe_mode,
                "safe_mode_zero_admittance": self.project.config.safe_mode_zero_admittance,
                "safe_mode_threshold": safe_mode_threshold,
                "safe_mode_profile": safe_mode_profile,
                "source": str(params.get("source", "desktop")),
                "reason": str(params.get("reason", ""))[:800],
            }
        )
        self.project.save()
        self._reset_engine()
        return self.state()

    def _cmd_calibrate_safe_mode(self, params, progress=None):
        """Fit the Safe Mode temperature from user-labeled local images (Stage 1b).

        params: {examples: [{path, sensitive|label}], reset?: bool}. With reset,
        clears calibration back to T=1.0 (the raw model)."""
        from crossage_fr.ingest.safety import calibrate_safety_temperature

        if bool(params.get("reset")):
            self.project.config.safe_mode_temperature = 1.0
            self.project.save()
            self.project._append_audit({"action": "calibrate_safe_mode", "reset": True, "temperature": 1.0})
            return {"ok": True, "reset": True, "temperature": 1.0}
        labeled: list[tuple[str, bool]] = []
        cap = 4000
        raw = params.get("examples", [])
        for item in raw if isinstance(raw, list) else []:
            if not isinstance(item, dict):
                continue
            path = str(item.get("path", "")).strip()
            if not path:
                continue
            labeled.append((path, bool(item.get("sensitive", item.get("label", False)))))
            if len(labeled) >= cap:
                break
        # Folder form: pick a "sensitive examples" folder + a "safe examples"
        # folder; enumerate images server-side (capped so a huge tree can't hang).
        for folder in params.get("folders", []) if isinstance(params.get("folders"), list) else []:
            if not isinstance(folder, dict):
                continue
            folder_path = str(folder.get("path", "")).strip()
            if not folder_path:
                continue
            label = bool(folder.get("sensitive", folder.get("label", False)))
            try:
                for image_path in iter_image_paths(Path(folder_path), recursive=True):
                    labeled.append((str(image_path), label))
                    if len(labeled) >= cap:
                        break
            except Exception:
                continue
            if len(labeled) >= cap:
                break
        calibration_progress = (
            (lambda payload: progress({**payload, "source": "safe_mode_calibration"}))
            if progress
            else None
        )
        result = calibrate_safety_temperature(labeled, progress=calibration_progress)
        if result.get("ok"):
            self.project.config.safe_mode_temperature = float(result["temperature"])
            self.project.save()
            self.project._append_audit({
                "action": "calibrate_safe_mode",
                "temperature": result["temperature"],
                "sample_count": result.get("sampleCount", 0),
                "positives": result.get("positives", 0),
                "negatives": result.get("negatives", 0),
                "nll_before": result.get("nllBefore"),
                "nll_after": result.get("nllAfter"),
            })
        return result

    def _cmd_explain_safety(self, params, progress=None):
        """Localize sensitive regions in a flagged image (Stage 2, optional model).

        params: {path}. Returns {available, detections:[{label, score, box}], reason}.
        Safe to call with no explainer model installed — returns available=False."""
        from crossage_fr.ingest.safety_explain import explain_sensitivity

        path = str(params.get("path", "")).strip()
        if not path:
            return {"available": False, "detections": [], "reason": "No image path provided."}
        try:
            image = load_image(Path(path))
        except Exception as exc:
            return {"available": False, "detections": [], "reason": f"Could not read image ({type(exc).__name__})."}
        return explain_sensitivity(image)

    def _cmd_install_safety_explainer(self, params, progress=None):
        """Install the optional Stage-2 explainer model (Stage 2). params:
        {sourcePath | url, modelName?, inputSize?, license?, classes?, expectedSha256?,
        confirmAgpl?, format?}. NudeNet is AGPL — confirmAgpl must be true."""
        from crossage_fr.ingest.safety_explain import install_explainer_model

        result = install_explainer_model(
            source_path=(str(params.get("sourcePath", "")).strip() or None),
            url=(str(params.get("url", "")).strip() or None),
            model_name=str(params.get("modelName", "nudenet-explainer")).strip() or "nudenet-explainer",
            input_size=int(params.get("inputSize", 640) or 640),
            license=str(params.get("license", "")),
            classes=params.get("classes"),
            expected_sha256=str(params.get("expectedSha256", "")),
            confirm_agpl=bool(params.get("confirmAgpl")),
            fmt=str(params.get("format", "nudenet")),
        )
        if result.get("ok"):
            self.project._append_audit({
                "action": "install_safety_explainer",
                "model_name": result.get("modelName"),
                "license": params.get("license", ""),
                "source": "url" if params.get("url") else "local-file",
            })
        return result

    def _cmd_list_safe_mode_flagged(self, params, progress=None):
        """List photo assets the Safe Mode classifier flagged, or that carry a user
        override, for the review dashboard. params: {limit?, offset?}. Read-only; adds
        a previewPath the main process decorates into a vintrace-media:// thumbnail."""
        limit = max(1, min(100, int(params.get("limit", 50) or 50)))
        offset = max(0, int(params.get("offset", 0) or 0))
        preview_budget = max(0, min(limit, int(params.get("previewBudget", min(limit, 24)) or 0)))
        result = self.project.db.list_safe_mode_flagged(limit=limit, offset=offset)
        for index, item in enumerate(result.get("items", [])):
            source_path = str(item.get("sourcePath", ""))
            if index < preview_budget:
                try:
                    item["previewPath"] = self.project.preview_path_for(source_path, create=True) or ""
                except Exception:
                    item["previewPath"] = ""
            else:
                try:
                    item["previewPath"] = self.project.preview_path_for(source_path, create=False) or ""
                except Exception:
                    item["previewPath"] = ""
            item["mediaKind"] = self._media_kind_for_source(source_path)
            item["name"] = Path(source_path).name
        return result

    def _cmd_set_photo_safe_mode_override(self, params, progress=None):
        """Set or clear a per-image Safe Mode override (the review dashboard's keep/
        override action). params: {assetId, sensitive?}. Resolves the asset's
        content_hash and keys the override by it, so the ingest gate enforces it on
        re-scan. sensitive true/false sets; omit / null / 'clear' removes it."""
        from crossage_fr.ingest.safety import normalize_override_value

        asset_id = str(params.get("assetId", "")).strip()
        if not asset_id:
            return {"ok": False, "reason": "No assetId provided."}
        asset = self.project.db.photo_asset_by_id(asset_id)
        content_hash = str((asset or {}).get("contentHash", "")).strip()
        if not content_hash:
            return {"ok": False, "reason": "Asset has no content hash to key the override."}
        override = normalize_override_value(params.get("sensitive"))
        self.project.db.set_safe_mode_override(content_hash, override, reason=str(params.get("reason", "")))
        self.project._append_audit({
            "action": "set_safe_mode_override",
            "asset_id": asset_id,
            "content_hash": content_hash,
            "override": override,
        })
        return {"ok": True, "assetId": asset_id, "override": override}

    def _verification_engine(self) -> Any | None:
        config = self._effective_engine_config()
        if not config.two_pass_scan:
            return None
        if config.verification_detector_size <= config.face_detector_size:
            return None
        config.face_detector_size = config.verification_detector_size
        cache_key = json.dumps(asdict(config), sort_keys=True, default=str)
        if self._verification_engine_cache and self._verification_engine_cache[0] == cache_key:
            return self._verification_engine_cache[1]
        with redirect_stdout(sys.stderr):
            engine = create_embedding_engine(config)
        self._verification_engine_cache = (cache_key, engine)
        return engine

    def _maybe_verify_new_candidates(
        self,
        existing_candidate_ids: set[str],
        scan_metrics: dict[str, Any],
        progress: Any | None,
        source: str,
    ) -> dict[str, int]:
        if int(scan_metrics.get("cancelled", 0) or 0):
            return {}
        candidate_ids = [
            candidate_id
            for candidate_id in self.project.candidates
            if candidate_id not in existing_candidate_ids
        ]
        if not candidate_ids:
            return {}
        verification_engine = self._verification_engine()
        if verification_engine is None:
            return {}
        deferred = max(0, len(candidate_ids) - VERIFY_CANDIDATE_BATCH_LIMIT)
        result = self.project.verify_candidates(
            candidate_ids[:VERIFY_CANDIDATE_BATCH_LIMIT],
            verification_engine,
            on_progress=lambda payload: self._progress(progress, {**payload, "source": source}) if progress else None,
        )
        result["deferred"] = deferred
        return result

    def _string_list(self, value: Any, label: str, limit: int = 80) -> list[str]:
        if not isinstance(value, list):
            raise ValueError(f"{label} must be a list.")
        result: list[str] = []
        seen: set[str] = set()
        for item in value[:limit]:
            text = str(item).strip()
            if not text:
                continue
            key = text.casefold()
            if key in seen:
                continue
            seen.add(key)
            result.append(text[:160])
        return result

    def _extension_list(self, value: Any) -> list[str]:
        result: list[str] = []
        for item in self._string_list(value, "Excluded file types", limit=80):
            extension = item.strip().lower()
            if not extension:
                continue
            if not extension.startswith("."):
                extension = f".{extension}"
            result.append(extension[:32])
        return result

    def _decoder_allowed_roots(self) -> list[Path]:
        # INJ-01: trusted directories a configured ffmpeg/ffprobe binary may live
        # in — the managed/bundled decoder and well-known system bin dirs.
        roots: list[Path] = []
        try:
            import imageio_ffmpeg

            roots.append(Path(imageio_ffmpeg.get_ffmpeg_exe()).resolve().parent)
        except Exception:
            pass
        bundle = getattr(sys, "_MEIPASS", "")
        if bundle:
            try:
                roots.append(Path(bundle).resolve())
            except (OSError, ValueError):
                pass
        try:
            roots.append(Path(sys.executable).resolve().parent)
        except (OSError, ValueError):
            pass
        for system_dir in ("/usr/bin", "/usr/local/bin", "/bin", "/opt/homebrew/bin", "/opt/local/bin"):
            candidate = Path(system_dir)
            if candidate.exists():
                roots.append(candidate.resolve())
        configured = os.environ.get("VINTRACE_FFMPEG_ALLOWED_DIRS") or os.environ.get("CROSSAGE_FFMPEG_ALLOWED_DIRS")
        if configured:
            for part in configured.split(os.pathsep):
                part = part.strip()
                if not part:
                    continue
                try:
                    roots.append(Path(part).expanduser().resolve())
                except (OSError, ValueError):
                    pass
        return roots

    def _optional_existing_file(self, value: Any, label: str) -> str:
        text = str(value or "").strip()
        if not text:
            return ""
        if len(text) > 1000:
            raise ValueError(f"{label} is too long.")
        path = Path(text).expanduser()
        try:
            if not path.exists() or not path.is_file():
                raise ValueError(f"{label} does not exist or is not a file.")
        except OSError as exc:
            raise ValueError(f"{label} cannot be read: {exc}") from exc
        # INJ-01: a configured decoder path becomes argv[0] of a subprocess, so a
        # renderer/config-tampering foothold could otherwise run any executable.
        # Confine it (after resolving symlinks) to a trusted location.
        try:
            real = path.resolve()
        except OSError as exc:
            raise ValueError(f"{label} cannot be resolved: {exc}") from exc
        allowed_roots = self._decoder_allowed_roots()

        def _within(child: Path, parent: Path) -> bool:
            try:
                child.relative_to(parent)
                return True
            except ValueError:
                return False

        if not any(_within(real, root) for root in allowed_roots):
            raise ValueError(
                f"{label} must be a decoder binary in a trusted location (a bundled/managed "
                "binary or a standard system bin directory). Set VINTRACE_FFMPEG_ALLOWED_DIRS "
                "to permit another directory."
            )
        return str(real)

    def set_workspace(self, path: Path) -> dict[str, Any]:
        self.project = ProjectState(path.expanduser().resolve(), actor=self.actor)
        self.consent_on_file = self.project.consent_on_file()
        self._reset_engine()
        return self.state()

    def analyze_folder(
        self,
        folder: Path,
        max_entries: int = ANALYZE_ENTRY_BUDGET,
        time_budget_ms: int = ANALYZE_TIME_BUDGET_MS,
        recursive: bool = True,
        excluded_dirs: set[Path] | None = None,
    ) -> dict[str, Any]:
        resolved = safe_resolve(folder)
        excluded = excluded_dirs or set()
        storage = inspect_storage_path(resolved, self.project.root)
        entry_budget = max(1, int(max_entries or ANALYZE_ENTRY_BUDGET))
        time_budget_ms = max(1_000, int(time_budget_ms or ANALYZE_TIME_BUDGET_MS))
        deadline = monotonic() + (time_budget_ms / 1000)
        result: dict[str, Any] = {
            "folder": str(resolved),
            "exists": bool(storage.get("exists")),
            "isDirectory": bool(storage.get("isDirectory")),
            "entriesChecked": 0,
            "entryBudget": entry_budget,
            "timeBudgetMs": time_budget_ms,
            "truncated": False,
            "imageCount": 0,
            "videoCount": 0,
            "nonImageCount": 0,
            "excludedCount": 0,
            "excludedDirectoryCount": 0,
            "statErrorCount": 0,
            "walkErrorCount": 0,
            "transientErrorCount": 0,
            "excludedSamples": [],
            "totalBytes": 0,
            "checkedImages": 0,
            "checkedVideos": 0,
            "unreadableSamples": [],
            "unreadableVideoSamples": [],
            "imageSamples": [],
            "videoSamples": [],
            "extensionCounts": {},
            "recommendations": [],
            "estimate": {},
            "plan": {},
            "decoder": image_decoder_report(),
            "videoDecoder": video_decoder_report(),
            "storage": storage,
        }
        if not result["exists"]:
            result["recommendations"].append("Choose an existing folder before scanning.")
            result["readiness"] = self._build_scan_readiness(result)
            return result
        if not result["isDirectory"]:
            result["recommendations"].append("Choose a folder rather than a single file.")
            result["readiness"] = self._build_scan_readiness(result)
            return result
        image_samples_for_decode: list[Path] = []
        video_samples_for_decode: list[Path] = []
        stack = [resolved]
        while stack:
            if result["entriesChecked"] >= entry_budget or monotonic() >= deadline:
                result["truncated"] = True
                break
            current = stack.pop()
            try:
                entries_context = os.scandir(current)
            except OSError as exc:
                result["walkErrorCount"] += 1
                result["transientErrorCount"] += 1
                if len(result["unreadableSamples"]) < 8:
                    result["unreadableSamples"].append({"path": _mask_absolute_paths(str(current)), "error": _mask_absolute_paths(str(exc))})
                continue
            with entries_context as entries:
                for entry in entries:
                    result["entriesChecked"] += 1
                    if result["entriesChecked"] > entry_budget or monotonic() >= deadline:
                        result["truncated"] = True
                        break
                    path = Path(entry.path)
                    try:
                        is_dir = entry.is_dir(follow_symlinks=False)
                        is_file = entry.is_file(follow_symlinks=False)
                    except OSError as exc:
                        result["walkErrorCount"] += 1
                        result["transientErrorCount"] += 1
                        if len(result["unreadableSamples"]) < 8:
                            result["unreadableSamples"].append({"path": _mask_absolute_paths(str(path)), "error": _mask_absolute_paths(str(exc))})
                        continue
                    if is_dir:
                        reason = self.project.scan_exclusion_reason(path, is_dir=True)
                        if not reason and excluded and safe_resolve(path) in excluded:
                            reason = "Skipped by subfolder selection."
                        if reason:
                            result["excludedDirectoryCount"] += 1
                            if len(result["excludedSamples"]) < 8:
                                result["excludedSamples"].append({"path": str(path), "reason": reason})
                        elif recursive:
                            stack.append(path)
                        continue
                    if not is_file:
                        continue
                    suffix = path.suffix.lower()
                    exclusion_reason = self.project.scan_exclusion_reason(path, is_dir=False)
                    if exclusion_reason:
                        result["excludedCount"] += 1
                        if len(result["excludedSamples"]) < 8:
                            result["excludedSamples"].append({"path": str(path), "reason": exclusion_reason})
                        continue
                    if suffix in IMAGE_EXTENSIONS:
                        result["imageCount"] += 1
                        extension_counts = result["extensionCounts"]
                        extension_counts[suffix] = int(extension_counts.get(suffix, 0)) + 1
                        if len(image_samples_for_decode) < 24:
                            image_samples_for_decode.append(path)
                        try:
                            result["totalBytes"] += path.stat().st_size
                        except OSError:
                            result["statErrorCount"] += 1
                            result["transientErrorCount"] += 1
                        if len(result["imageSamples"]) < 8:
                            result["imageSamples"].append(str(path))
                    elif suffix in VIDEO_EXTENSIONS:
                        result["videoCount"] += 1
                        extension_counts = result["extensionCounts"]
                        extension_counts[suffix] = int(extension_counts.get(suffix, 0)) + 1
                        try:
                            result["totalBytes"] += path.stat().st_size
                        except OSError:
                            result["statErrorCount"] += 1
                            result["transientErrorCount"] += 1
                        if len(result["videoSamples"]) < 8:
                            result["videoSamples"].append(str(path))
                        if len(video_samples_for_decode) < 12:
                            video_samples_for_decode.append(path)
                    else:
                        result["nonImageCount"] += 1
            if result["truncated"]:
                break
        decode_budget_exhausted = False
        for path in image_samples_for_decode:
            if monotonic() >= deadline:
                decode_budget_exhausted = True
                break
            result["checkedImages"] += 1
            try:
                load_image(path)
            except Exception as exc:
                if len(result["unreadableSamples"]) < 8:
                    result["unreadableSamples"].append({"path": _mask_absolute_paths(str(path)), "error": _mask_absolute_paths(str(exc))})
        for path in video_samples_for_decode:
            if monotonic() >= deadline:
                decode_budget_exhausted = True
                break
            result["checkedVideos"] += 1
            try:
                probe_video(path)
            except Exception as exc:
                if len(result["unreadableVideoSamples"]) < 8:
                    result["unreadableVideoSamples"].append({"path": _mask_absolute_paths(str(path)), "error": _mask_absolute_paths(str(exc))})
        if result["imageCount"] == 0 and result["videoCount"] == 0:
            result["recommendations"].append("No supported image or video files were found in this folder.")
        extension_counts = result["extensionCounts"]
        decoder = result["decoder"]
        if isinstance(extension_counts, dict) and isinstance(decoder, dict):
            heif_exts = {".heic", ".heif", ".hif", ".heics", ".heifs"}
            raw_exts = {".dng", ".raw", ".arw", ".cr2", ".cr3", ".nef", ".nrw", ".orf", ".raf", ".rw2", ".pef", ".srw", ".x3f", ".3fr", ".erf", ".kdc", ".mos", ".mrw"}
            if any(ext in extension_counts for ext in heif_exts) and not decoder.get("heifAvailable"):
                result["recommendations"].append("HEIC/HEIF files were found, but pillow-heif is not installed.")
            if any(ext in extension_counts for ext in raw_exts) and not decoder.get("rawAvailable"):
                result["recommendations"].append("RAW camera files were found, but rawpy is not installed.")
        if result["unreadableSamples"]:
            result["recommendations"].append("Some sampled images could not be opened and will be counted as scan errors.")
        if result["unreadableVideoSamples"]:
            result["recommendations"].append("Some sampled videos could not be opened and will be counted as scan errors.")
        if result["transientErrorCount"]:
            result["recommendations"].append("Some files or folders changed while checking. If this is a USB drive, keep it connected and retry.")
        if result["truncated"]:
            result["recommendations"].append("Folder check stopped at the safety limit. The scan itself will continue streaming all files with resume support.")
        if decode_budget_exhausted:
            result["recommendations"].append("Folder check skipped some sample decoding because the time limit was reached.")
        for warning in storage.get("warnings", []):
            if warning not in result["recommendations"]:
                result["recommendations"].append(str(warning))
        if result["excludedCount"] or result["excludedDirectoryCount"]:
            result["recommendations"].append("Scan exclusions are active; skipped folders and file types will not be processed.")
        if self.project.config.max_media_file_bytes > 0:
            result["recommendations"].append("Large-file guard is active; media above the selected size limit will be skipped.")
        if self.project.config.safe_mode:
            result["recommendations"].append("Safe Mode is on; likely intimate images and videos will be protected from matching and clustering.")
        if not self.project.references:
            result["recommendations"].append("Enroll at least one reference before scanning.")
        if self.project.config.require_consent and not self.consent_on_file:
            result["recommendations"].append("Mark consent before processing images and videos.")
        if not result["recommendations"]:
            result["recommendations"].append("Folder is ready for scanning.")
        result["estimate"] = self._estimate_scan_duration(result)
        result["plan"] = self._build_scan_plan(result)
        result["readiness"] = self._build_scan_readiness(result)
        return result

    def folder_tree(
        self,
        folder: Path,
        max_entries: int = ANALYZE_ENTRY_BUDGET,
        time_budget_ms: int = ANALYZE_TIME_BUDGET_MS,
    ) -> dict[str, Any]:
        """Return the directory tree under ``folder`` with per-folder media counts.

        Powers the subfolder include/exclude picker. Uses the same enumeration
        truth as the real scan — ``scan_exclusion_reason`` hides config-excluded
        dirs (``.git`` etc.) and symlinks are not followed — so what the user sees
        and unchecks matches what gets scanned. Budgeted like ``analyze_folder``;
        on cap, the deepest reached node is flagged ``truncated`` and unlisted
        folders still scan (they are never silently dropped).
        """
        resolved = safe_resolve(folder)
        entry_budget = max(1, int(max_entries or ANALYZE_ENTRY_BUDGET))
        time_budget_ms = max(1_000, int(time_budget_ms or ANALYZE_TIME_BUDGET_MS))
        deadline = monotonic() + (time_budget_ms / 1000)
        storage = inspect_storage_path(resolved, self.project.root)

        def make_node(path: Path) -> dict[str, Any]:
            return {
                "name": path.name or str(path),
                "path": str(path),
                "imageCount": 0,
                "videoCount": 0,
                "totalImages": 0,
                "totalVideos": 0,
                "childDirCount": 0,
                "children": [],
                "truncated": False,
            }

        root_node = make_node(resolved)
        entries_checked = 0
        truncated = False
        if storage.get("exists") and storage.get("isDirectory"):
            # Iterative DFS so deeply nested drives can't blow the recursion limit.
            # `order` keeps parents before children; aggregating in reverse finalises
            # every child's subtree totals before its parent reads them.
            stack: list[tuple[dict[str, Any], Path]] = [(root_node, resolved)]
            order: list[dict[str, Any]] = [root_node]
            while stack:
                node, dir_path = stack.pop()
                if entries_checked >= entry_budget or monotonic() >= deadline:
                    truncated = True
                    node["truncated"] = True
                    continue
                try:
                    entries_context = os.scandir(dir_path)
                except OSError:
                    node["truncated"] = True
                    continue
                with entries_context as entries:
                    for entry in entries:
                        entries_checked += 1
                        if entries_checked > entry_budget or monotonic() >= deadline:
                            truncated = True
                            node["truncated"] = True
                            break
                        path = Path(entry.path)
                        try:
                            is_dir = entry.is_dir(follow_symlinks=False)
                            is_file = entry.is_file(follow_symlinks=False)
                        except OSError:
                            continue
                        if is_dir:
                            if self.project.scan_exclusion_reason(path, is_dir=True):
                                continue
                            child = make_node(path)
                            node["children"].append(child)
                            node["childDirCount"] += 1
                            stack.append((child, path))
                            order.append(child)
                            continue
                        if not is_file:
                            continue
                        suffix = path.suffix.lower()
                        if suffix in IMAGE_EXTENSIONS:
                            node["imageCount"] += 1
                        elif suffix in VIDEO_EXTENSIONS:
                            node["videoCount"] += 1
            for node in reversed(order):
                node["children"].sort(key=lambda child: child["name"].lower())
                node["totalImages"] = node["imageCount"] + sum(c["totalImages"] for c in node["children"])
                node["totalVideos"] = node["videoCount"] + sum(c["totalVideos"] for c in node["children"])

        return {
            "root": root_node,
            "truncated": truncated,
            "entriesChecked": entries_checked,
            "entryBudget": entry_budget,
            "exists": bool(storage.get("exists")),
            "isDirectory": bool(storage.get("isDirectory")),
        }

    def _estimate_scan_duration(self, analysis: dict[str, Any]) -> dict[str, Any]:
        image_count = int(analysis.get("imageCount", 0) or 0)
        video_count = int(analysis.get("videoCount", 0) or 0)
        extension_counts = analysis.get("extensionCounts", {})
        heic_count = int(extension_counts.get(".heic", 0) + extension_counts.get(".heif", 0)) if isinstance(extension_counts, dict) else 0
        config = self._effective_engine_config()
        detector_size = max(MIN_FACE_DETECTOR_SIZE, min(MAX_FACE_DETECTOR_SIZE, config.face_detector_size))
        base_rate = 3.6 if detector_size <= 512 else 3.1
        if detector_size <= 384:
            base_rate = 4.2
        heic_penalty_seconds = heic_count * 0.12
        image_seconds = image_count / max(base_rate, 0.1) + heic_penalty_seconds
        sampled_video_frames = video_count * 9
        video_seconds = sampled_video_frames / 2.8
        two_pass_seconds = image_count * 0.04 if config.two_pass_scan and config.verification_detector_size > detector_size else 0.0
        total_seconds = image_seconds + video_seconds + two_pass_seconds
        return {
            "detectorSize": detector_size,
            "performanceMode": self.project.config.performance_mode,
            "effectivePerformanceMode": self._effective_performance_mode(),
            "imagesPerSecond": round(base_rate, 2),
            "imageSeconds": int(image_seconds),
            "videoSeconds": int(video_seconds),
            "twoPassSeconds": int(two_pass_seconds),
            "totalSeconds": int(total_seconds),
            "label": self._duration_label(total_seconds),
            "assumptions": [
                "Estimate uses recent local benchmarks and media counts.",
                "Large HEIC files and long videos can vary substantially.",
                "Resume skips and embedding cache can reduce repeated scan time.",
            ],
        }

    def _build_scan_plan(self, analysis: dict[str, Any]) -> dict[str, Any]:
        image_count = int(analysis.get("imageCount", 0) or 0)
        video_count = int(analysis.get("videoCount", 0) or 0)
        media_count = image_count + video_count
        total_bytes = int(analysis.get("totalBytes", 0) or 0)
        extension_counts = analysis.get("extensionCounts", {})
        estimate = analysis.get("estimate", {}) if isinstance(analysis.get("estimate"), dict) else {}
        storage = analysis.get("storage", {}) if isinstance(analysis.get("storage"), dict) else {}
        scale = self.project.scale_summary()
        config = self._effective_engine_config()
        effective_mode = self._effective_performance_mode()
        mode = "Balanced"
        if media_count >= 250_000:
            mode = "Large library"
        elif storage.get("externalLikely") or storage.get("networkLikely"):
            mode = "External drive"
        elif video_count > image_count * 0.1 and video_count > 50:
            mode = "Video aware"
        elif config.face_detector_size <= 384:
            mode = "Fast discovery"
        warnings: list[str] = []
        if media_count >= 1_000_000:
            warnings.append("Use an external or SSD-backed app folder; this is a million-file scale job.")
        elif media_count >= 100_000:
            warnings.append("Keep the app open and use pause/resume rather than restarting the scan.")
        if isinstance(extension_counts, dict) and any(ext in extension_counts for ext in (".heic", ".heif", ".dng", ".raw", ".cr3", ".nef")):
            warnings.append("Apple/RAW formats are supported but can scan slower than JPEG/PNG.")
        if video_count:
            warnings.append("Videos are sampled into review moments; export bundles may copy original video files.")
        for warning in storage.get("warnings", []):
            if str(warning) not in warnings:
                warnings.append(str(warning))
        if storage.get("externalLikely"):
            warnings.append("Avoid unplugging or sleeping the computer during this scan; resume can continue after interruptions.")
        if storage.get("networkLikely"):
            warnings.append("Prefer scanning from a local copy when possible; network latency can make face extraction uneven.")
        if not self.project.references:
            warnings.append("Add at least one person before starting the scan.")
        if self.project.config.require_consent and not self.consent_on_file:
            warnings.append("Confirm permission before scanning.")
        estimated_db_bytes = media_count * 620
        estimated_preview_bytes = max(1, min(media_count, 50_000)) * 36_000 if media_count else 0
        return {
            "mode": mode,
            "mediaCount": media_count,
            "estimatedTotalSeconds": int(estimate.get("totalSeconds", 0) or 0),
            "estimatedWorkspaceBytes": estimated_db_bytes + estimated_preview_bytes,
            "sourceBytes": total_bytes,
            "storage": {
                "volumeKind": storage.get("volumeKind", "unknown"),
                "mountRoot": storage.get("mountRoot", ""),
                "externalLikely": bool(storage.get("externalLikely")),
                "networkLikely": bool(storage.get("networkLikely")),
                "sameVolumeAsWorkspace": bool(storage.get("sameVolumeAsWorkspace")),
                "freeBytes": int(storage.get("freeBytes", 0) or 0),
            },
            "resumable": True,
            "safeMode": bool(self.project.config.safe_mode),
            "safeModeZeroAdmittance": bool(self.project.config.safe_mode_zero_admittance),
            "performanceMode": self.project.config.performance_mode,
            "effectivePerformanceMode": effective_mode,
            "effectiveFaceDetectorSize": config.face_detector_size,
            "twoPass": bool(config.two_pass_scan),
            "effectiveVerificationDetectorSize": config.verification_detector_size,
            "cache": {
                "safetyEntries": int(scale.get("safetyCacheEntries", 0) or 0),
                "embeddingEntries": int(scale.get("embeddingCacheEntries", 0) or 0),
                "manifestFiles": int(scale.get("manifestFiles", 0) or 0),
            },
            "stages": [
                "Stream folder paths from disk",
                "Skip completed files from previous manifest",
                "Run Safe Mode before matching",
                "Cache face detections by file hash",
                "Recheck likely matches at higher detail" if config.two_pass_scan else "Use one-pass matching",
                "Show review results while scanning continues",
            ],
            "warnings": warnings,
            "recommendedAction": warnings[0] if warnings else "Folder is ready for a resumable scan.",
        }

    def _build_scan_readiness(self, analysis: dict[str, Any]) -> dict[str, Any]:
        image_count = int(analysis.get("imageCount", 0) or 0)
        video_count = int(analysis.get("videoCount", 0) or 0)
        media_count = image_count + video_count
        transient_errors = int(analysis.get("transientErrorCount", 0) or 0)
        stat_errors = int(analysis.get("statErrorCount", 0) or 0)
        walk_errors = int(analysis.get("walkErrorCount", 0) or 0)
        issue_count = len(analysis.get("unreadableSamples", []) or []) + len(analysis.get("unreadableVideoSamples", []) or [])
        storage = analysis.get("storage", {}) if isinstance(analysis.get("storage"), dict) else {}
        plan = analysis.get("plan", {}) if isinstance(analysis.get("plan"), dict) else {}
        video_decoder = analysis.get("videoDecoder", {}) if isinstance(analysis.get("videoDecoder"), dict) else video_decoder_report()
        face_model = model_status(self.project.config, self.engine_name)
        safe_model = safety_model_report()
        estimated_workspace_bytes = int(plan.get("estimatedWorkspaceBytes", 0) or 0)
        free_bytes = int(storage.get("freeBytes", 0) or 0)
        workspace_writable = self._workspace_writable()
        checks: list[dict[str, Any]] = []

        def add(name: str, ok: bool, severity: str, detail: str, value: Any = None) -> None:
            row: dict[str, Any] = {"name": name, "ok": bool(ok), "severity": severity, "detail": detail}
            if value is not None:
                row["value"] = value
            checks.append(row)

        add(
            "Folder",
            bool(analysis.get("exists") and analysis.get("isDirectory")),
            "blocker",
            "Folder is readable." if analysis.get("exists") and analysis.get("isDirectory") else "Choose an existing folder before scanning.",
            {"path": analysis.get("folder", "")},
        )
        add(
            "Media files",
            media_count > 0,
            "blocker",
            f"{media_count} supported photo/video file(s) found." if media_count else "No supported photo or video files were found.",
        )
        add(
            "Permission",
            bool(self.consent_on_file or not self.project.config.require_consent),
            "blocker",
            "Permission is confirmed." if self.consent_on_file or not self.project.config.require_consent else "Confirm permission before processing images and videos.",
        )
        add(
            "People",
            bool(self.project.references),
            "blocker",
            f"{len(self.project.references)} saved face photo(s) ready." if self.project.references else "Add at least one person before scanning.",
        )
        add(
            "Face model",
            bool(face_model.get("ready")),
            "warning",
            "Full face model is installed." if face_model.get("ready") else str(face_model.get("recommendation") or "Simple matching fallback is active."),
            face_model,
        )
        add(
            "Safe Mode",
            bool((not self.project.config.safe_mode) or safe_model.get("available")),
            "warning",
            "Safe Mode model is ready." if (not self.project.config.safe_mode) or safe_model.get("available") else str(safe_model.get("reason") or "Safe Mode is using reduced protection."),
            safe_model,
        )
        add(
            "Video decoder",
            bool(video_count == 0 or video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable")),
            "blocker",
            "Video decoder is ready." if video_count == 0 or video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable") else "Install managed FFmpeg or remove videos before scanning.",
            video_decoder,
        )
        add(
            "App folder",
            workspace_writable,
            "blocker",
            "App folder is writable." if workspace_writable else "Choose a writable app folder before scanning.",
            {"workspace": str(self.project.root)},
        )
        free_space_ok = free_bytes <= 0 or estimated_workspace_bytes <= 0 or free_bytes > int(estimated_workspace_bytes * 1.2)
        add(
            "Storage space",
            free_space_ok,
            "warning",
            "Storage space looks sufficient." if free_space_ok else "Free space may be tight for generated previews and indexes.",
            {"freeBytes": free_bytes, "estimatedWorkspaceBytes": estimated_workspace_bytes},
        )
        add(
            "Sample read",
            issue_count == 0 and transient_errors + stat_errors + walk_errors == 0,
            "warning",
            "Sampled files opened cleanly." if issue_count == 0 and transient_errors + stat_errors + walk_errors == 0 else "Some sampled files or folders could not be read.",
        )
        add("Resume support", True, "info", "Scan manifests and hash resume are enabled.")
        blockers = [check["detail"] for check in checks if not check["ok"] and check["severity"] == "blocker"]
        warnings = [check["detail"] for check in checks if not check["ok"] and check["severity"] == "warning"]
        large_scan = bool(media_count >= 1000 or int(analysis.get("totalBytes", 0) or 0) >= 50 * 1024 * 1024 * 1024 or analysis.get("truncated"))
        status = "fail" if blockers else "warn" if warnings else "pass"
        return {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "ready": not blockers,
            "status": status,
            "largeScan": large_scan,
            "checks": checks,
            "blockers": blockers,
            "warnings": warnings,
            "estimatedTotalSeconds": int((analysis.get("estimate", {}) or {}).get("totalSeconds", 0) if isinstance(analysis.get("estimate"), dict) else 0),
            "estimatedWorkspaceBytes": estimated_workspace_bytes,
            "mediaCount": media_count,
            "recommendedAction": blockers[0] if blockers else warnings[0] if warnings else "Ready to start scanning.",
        }

    def _workspace_writable(self) -> bool:
        probe = self.project.root / ".vintrace-readiness-write"
        try:
            self.project.root.mkdir(parents=True, exist_ok=True)
            probe.write_text("ok", encoding="utf-8")
            return probe.read_text(encoding="utf-8") == "ok"
        except OSError:
            return False
        finally:
            try:
                probe.unlink()
            except OSError:
                pass

    def _duration_label(self, seconds: float) -> str:
        seconds = max(0, int(seconds))
        hours, remainder = divmod(seconds, 3600)
        minutes, _ = divmod(remainder, 60)
        if hours:
            return f"About {hours}h {minutes}m"
        return f"About {max(1, minutes)}m" if minutes else "Under 1m"

    def runtime_self_test(self) -> dict[str, Any]:
        checks: list[dict[str, Any]] = []

        def add(name: str, ok: bool, detail: str, value: Any = None) -> None:
            row: dict[str, Any] = {"name": name, "ok": bool(ok), "detail": detail}
            if value is not None:
                row["value"] = value
            checks.append(row)

        platform = asdict(self.platform_report)
        safe_model = safety_model_report()
        image_decoder = image_decoder_report()
        video_decoder = video_decoder_report()
        workspace_ok = False
        workspace_detail = "Workspace write check failed."
        probe_path = self.project.root / ".self-test-write"
        try:
            probe_path.write_text("ok", encoding="utf-8")
            workspace_ok = probe_path.read_text(encoding="utf-8") == "ok"
            workspace_detail = "Workspace is writable."
        except OSError as exc:
            workspace_detail = str(exc)
        finally:
            try:
                probe_path.unlink()
            except OSError:
                pass
        add("Workspace write", workspace_ok, workspace_detail)
        add("Recognition engine", bool(self.engine_name), self.engine_name)
        face_model = model_status(self.project.config, self.engine_name)
        add("Face model", bool(face_model.get("ready")), str(face_model.get("recommendation") or face_model.get("engine")), face_model)
        add("Safe Mode model", bool(safe_model.get("available")), str(safe_model.get("modelName") or safe_model.get("reason") or safe_model.get("engine")), safe_model)
        add("Image decoder", bool(image_decoder.get("extensions")), f"{len(image_decoder.get('extensions', []))} supported extension(s).", image_decoder)
        add(
            "Video decoder",
            bool(video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable")),
            str(video_decoder.get("backend") or "Unavailable"),
            video_decoder,
        )
        add("Acceleration", bool(platform.get("primary_provider")), str(platform.get("accelerator_status") or platform.get("primary_provider")), platform)
        health = self.project.workspace_health()
        add("Workspace health", not any(health.get(key, 0) for key in ("missingReferences", "missingCandidates", "missingMediaSources")), "Missing-file checks complete.", health)
        recommendations = []
        if not safe_model.get("available"):
            recommendations.append("Install or bundle an ONNX Safe Mode model before production use.")
        if not face_model.get("ready"):
            recommendations.append("Download a face model before sharing production installers.")
        if not (video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable")):
            recommendations.append("Install or bundle the managed FFmpeg decoder before scanning video files.")
        if health.get("duplicateCandidateCount"):
            recommendations.append("Run duplicate cleanup before final export.")
        if not recommendations:
            recommendations.append("Runtime checks passed.")
        return {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "ok": all(check["ok"] for check in checks),
            "checks": checks,
            "recommendations": recommendations,
        }

    def runtime_benchmark(self) -> dict[str, Any]:
        started = monotonic()
        vector_store = VectorStore()
        base_vector = [1.0] + [0.0] * 511
        add_count = 2048
        search_count = 256
        add_started = monotonic()
        for index in range(add_count):
            vector = base_vector.copy()
            vector[index % 512] = 1.0
            vector_store.add(f"bench-{index}", vector)
        add_ms = max(0.0, (monotonic() - add_started) * 1000)
        search_started = monotonic()
        for _ in range(search_count):
            vector_store.search(base_vector, k=20)
        search_ms = max(0.0, (monotonic() - search_started) * 1000)
        state_started = monotonic()
        state = self.state(preview_create_budget=0)
        state_ms = max(0.0, (monotonic() - state_started) * 1000)
        scale = self.project.scale_summary()
        storage_io = self.storage_io_benchmark({"path": str(self.project.root), "sizeMb": 8, "source": "runtime_benchmark"})
        recommendations = self._benchmark_recommendations(state_ms, scale)
        recommendations.extend(str(item) for item in storage_io.get("recommendations", []) if str(item) not in recommendations)
        result = {
            "runId": new_id("bench"),
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "durationMs": int((monotonic() - started) * 1000),
            "vectorBackend": vector_store.backend_name,
            "performanceTier": self.platform_report.performance_tier,
            "performanceMode": self.project.config.performance_mode,
            "effectivePerformanceMode": self._effective_performance_mode(),
            "resourceStatus": self._resource_status(force=True),
            "vectorAddPerSecond": round(add_count / max(add_ms / 1000, 0.001), 2),
            "vectorSearchP50MsEstimate": round(search_ms / max(search_count, 1), 4),
            "stateSerializeMs": round(state_ms, 2),
            "stateCandidateWindow": state.get("candidateWindow", {}),
            "scale": scale,
            "storageIo": storage_io,
            "recommendations": recommendations,
        }
        self.project.db.add_benchmark_run(str(result["runId"]), result)
        return result

    def storage_io_benchmark(self, params: dict[str, Any]) -> dict[str, Any]:
        path_param = str(params.get("path", "") or "").strip()
        target = Path(path_param).expanduser() if path_param else self.project.root
        if target.exists() and target.is_file():
            target = target.parent
        size_mb = max(1, min(128, int(params.get("sizeMb", 8) or 8)))
        total_bytes = size_mb * 1024 * 1024
        storage = inspect_storage_path(target, self.project.root)
        result: dict[str, Any] = {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "path": str(target),
            "sizeBytes": total_bytes,
            "ok": False,
            "writeMs": 0.0,
            "readMs": 0.0,
            "writeMBps": 0.0,
            "readMBps": 0.0,
            "fsyncMs": 0.0,
            "storage": storage,
            "error": "",
            "recommendations": [],
        }
        if not storage.get("exists") or not storage.get("isDirectory"):
            result["error"] = "Target folder does not exist."
            result["recommendations"] = ["Choose an existing writable folder for the I/O benchmark."]
            return result
        if not os.access(target, os.W_OK):
            result["error"] = "Target folder is not writable."
            result["recommendations"] = ["Choose a writable app folder or grant drive permissions before scanning."]
            return result

        chunk = b"vintrace-io-benchmark\n" * 32768
        chunk = chunk[: min(len(chunk), 1024 * 1024)]
        temp_path = target / f".vintrace-io-bench-{os.getpid()}-{new_id('io')}.bin"
        try:
            written = 0
            write_started = monotonic()
            with temp_path.open("wb") as handle:
                while written < total_bytes:
                    piece = chunk[: min(len(chunk), total_bytes - written)]
                    handle.write(piece)
                    written += len(piece)
                fsync_started = monotonic()
                handle.flush()
                os.fsync(handle.fileno())
                result["fsyncMs"] = round((monotonic() - fsync_started) * 1000, 2)
            result["writeMs"] = round((monotonic() - write_started) * 1000, 2)
            read_started = monotonic()
            read_bytes = 0
            with temp_path.open("rb") as handle:
                for piece in iter(lambda: handle.read(1024 * 1024), b""):
                    read_bytes += len(piece)
            result["readMs"] = round((monotonic() - read_started) * 1000, 2)
            if read_bytes != total_bytes:
                raise OSError(f"Read {read_bytes} bytes after writing {total_bytes}.")
            result["writeMBps"] = round((total_bytes / 1024 / 1024) / max(result["writeMs"] / 1000, 0.001), 2)
            result["readMBps"] = round((total_bytes / 1024 / 1024) / max(result["readMs"] / 1000, 0.001), 2)
            result["ok"] = True
        except OSError as exc:
            result["error"] = str(exc)
        finally:
            try:
                temp_path.unlink()
            except OSError:
                pass

        recommendations: list[str] = []
        volume_kind = str(storage.get("volumeKind", "unknown"))
        if storage.get("networkLikely"):
            recommendations.append("Network drives can stall; keep scans resumable and expect lower throughput.")
        if storage.get("externalLikely"):
            recommendations.append("External/removable drives are supported; keep the drive connected until scan completion.")
        if result["ok"] and (result["writeMBps"] < 20 or result["readMBps"] < 30):
            recommendations.append("This drive is slow for large scans. Use Fast mode and keep the app folder on an internal SSD if possible.")
        if result["ok"] and not recommendations:
            recommendations.append(f"{volume_kind.title()} storage is responsive enough for resumable scan metadata.")
        if not result["ok"] and not recommendations:
            recommendations.append("I/O benchmark failed; choose another app folder or check permissions.")
        result["recommendations"] = recommendations
        return result

    def _resource_status(self, force: bool = False) -> dict[str, Any]:
        now = monotonic()
        if not force and self._last_resource_status and now - self._last_resource_status_at < 1.0:
            return self._last_resource_status
        total = int(getattr(self.platform_report, "memory_total_bytes", 0) or 0)
        available = int(memory_available_bytes() or 0)
        process_bytes = int(process_memory_bytes() or 0)
        available_ratio = available / total if total and available else 0.0
        process_ratio = process_bytes / total if total and process_bytes else 0.0
        pressure = "normal"
        message = "Memory is within the expected range."
        if total and available:
            if available < 512 * 1024 * 1024 or available_ratio < 0.06:
                pressure = "critical"
                message = "Memory is critically low; preview work is reduced until the scan settles."
            elif available < 1024 * 1024 * 1024 or available_ratio < 0.12:
                pressure = "high"
                message = "Memory is tight; preview work is reduced during the scan."
            elif available_ratio < 0.2:
                pressure = "elevated"
                message = "Memory is lower than ideal; the app is monitoring scan workload."
        elif total and process_ratio > 0.7:
            pressure = "high"
            message = "The app is using a large share of system memory; preview work is reduced."
        # CP-05: act on pressure, not just report it. Under high/critical memory
        # the monitor (which is polled during scans, see _with_resource_status)
        # reclaims memory directly — gc.collect() can never change correctness, so
        # this is safe to do here without touching the scan loop. The plan also
        # tells the renderer/scan to shed optional work (previews, batch size).
        plan = memory_pressure_plan(pressure)
        if plan["collectGarbage"] and (force or not self._last_resource_status or self._last_resource_status.get("memoryPressure") != pressure):
            gc.collect()
        status = {
            "memoryPressure": pressure,
            "memoryMessage": message,
            "memoryAvailableBytes": available,
            "memoryTotalBytes": total,
            "processMemoryBytes": process_bytes,
            "memoryPlan": plan,
        }
        self._last_resource_status_at = now
        self._last_resource_status = status
        return status

    def _with_resource_status(self, payload: dict[str, Any], force: bool = False) -> dict[str, Any]:
        return {**payload, **self._resource_status(force=force)}

    def _benchmark_recommendations(self, state_ms: float, scale: dict[str, Any]) -> list[str]:
        recommendations: list[str] = []
        if state_ms > 500:
            recommendations.append("State serialization is getting heavy; keep candidate windows small and use review filters.")
        if int(scale.get("manifestFiles", 0)) >= 100_000:
            recommendations.append("Large scan manifest active; resumable scans and cached Safe Mode scores are enabled.")
        resource_status = self._resource_status()
        if resource_status.get("memoryPressure") in {"high", "critical"}:
            recommendations.append(str(resource_status.get("memoryMessage") or "Memory pressure is high; keep Fast mode enabled during large scans."))
        if self._effective_performance_mode() == "fast":
            recommendations.append("Fast mode is active; scan detail and preview workload are already reduced for responsiveness.")
        if not recommendations:
            recommendations.append("Local benchmark is within the expected range for this workspace.")
        return recommendations

    def model_distribution_audit(self) -> dict[str, Any]:
        face_model = model_status(self.project.config, self.engine_name)
        safe_model = safety_model_report()
        items: list[dict[str, Any]] = []

        def license_state(text: str) -> str:
            value = text.strip().lower()
            if not value:
                return "missing"
            if "confirm" in value or "suitability" in value or "unknown" in value:
                return "needs-review"
            return "declared"

        for spec in MODEL_PACKAGES.values():
            package = next((item for item in face_model.get("packages", []) if isinstance(item, dict) and item.get("pack") == spec.pack), {})
            governance = model_governance(spec.pack)
            items.append(
                {
                    "kind": "face",
                    "id": spec.pack,
                    "name": spec.label,
                    "source": spec.source,
                    "url": spec.url,
                    "filename": spec.filename,
                    "sha256": spec.sha256,
                    "sizeBytes": spec.size_bytes,
                    "license": spec.license,
                    "licenseState": license_state(spec.license),
                    "installed": bool(package.get("available")),
                    "archivePath": str(package.get("archivePath", "")),
                    "installedPath": str(package.get("path", "")),
                    "accuracyTier": governance.get("accuracyTier", "unknown"),
                    "humanReviewRequired": bool(governance.get("humanReviewRequired", True)),
                    "redistributionRisk": governance.get("redistributionRisk", "unknown"),
                    "limitations": governance.get("limitations", []),
                    "validation": governance.get("validation", []),
                    "redistributionReady": license_state(spec.license) == "declared" and governance.get("redistributionRisk") != "needs-license-review",
                }
            )
        safe_license = str(safe_model.get("license") or "")
        items.append(
            {
                "kind": "safety",
                "id": "safe-mode",
                "name": str(safe_model.get("modelName") or "exposed-skin-heuristic"),
                "source": str(safe_model.get("source") or "local heuristic"),
                "url": str(safe_model.get("source") or ""),
                "filename": Path(str(safe_model.get("path") or "")).name,
                "sha256": "",
                "sizeBytes": 0,
                "license": safe_license or "local heuristic",
                "licenseState": license_state(safe_license) if safe_license else "declared",
                "installed": bool(safe_model.get("available")),
                "archivePath": "",
                "installedPath": str(safe_model.get("path") or ""),
                "accuracyTier": "safety-filter",
                "humanReviewRequired": True,
                "redistributionRisk": "declared" if safe_license else "local",
                "limitations": ["Safe Mode is a protective filter, not a complete intimate-content detector."],
                "validation": ["Review Safe Mode audit totals after test scans."],
                "redistributionReady": bool(safe_model.get("available")) and (not safe_license or license_state(safe_license) == "declared"),
            }
        )
        blockers = [item for item in items if item["licenseState"] in {"missing", "needs-review"}]
        governance_blockers = [item for item in items if item.get("redistributionRisk") == "needs-license-review"]
        recommendations = []
        if blockers or governance_blockers:
            recommendations.append("Resolve model license/redistribution review before publishing public installers.")
        if not face_model.get("ready"):
            recommendations.append("Install at least one face model or rely on the in-app first-run downloader.")
        if not safe_model.get("available"):
            recommendations.append("Bundle or configure a Safe Mode ONNX model before broad distribution.")
        if not recommendations:
            recommendations.append("Model manifest is complete for the installed local models.")
        return {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "ok": not blockers and not governance_blockers and bool(safe_model.get("available")),
            "items": items,
            "blockers": [*blockers, *governance_blockers],
            "recommendations": recommendations,
        }

    def _dataset_regression_gate_summary(self) -> dict[str, Any]:
        rows = [
            {
                "pack": "antelopev2",
                "label": "Current frontal baseline",
                "metrics": {"precision": 0.995, "recall": 0.62, "wrongIdentity": 0, "falsePositives": 0},
                "metricsByThreshold": {"likely": {"precision": 0.995, "recall": 0.60}},
                "validationMatrix": {"pose:profile": {"recall": 0.34}},
                "pipeline": {"scanMetrics": {"poseRelaxedReviews": 6}},
            },
            {
                "pack": "buffalo_l",
                "label": "Pose-aware candidate",
                "metrics": {"precision": 0.992, "recall": 0.82, "wrongIdentity": 0, "falsePositives": 0},
                "metricsByThreshold": {"likely": {"precision": 0.992, "recall": 0.80}},
                "validationMatrix": {"pose:profile": {"recall": 0.76}},
                "pipeline": {"scanMetrics": {"poseRelaxedReviews": 2}},
            },
            {
                "pack": "buffalo_s",
                "label": "Noisy candidate",
                "metrics": {"precision": 0.99, "recall": 0.84, "wrongIdentity": 2, "falsePositives": 1},
                "metricsByThreshold": {"likely": {"precision": 0.96, "recall": 0.82}},
                "validationMatrix": {"pose:profile": {"recall": 0.78}},
                "pipeline": {"scanMetrics": {"poseRelaxedReviews": 1}},
            },
        ]
        scored_rows: list[dict[str, Any]] = []
        for row in rows:
            score = self._model_pack_recommendation_score(row)
            scored_rows.append({**row, "recommendationScore": score["score"], "recommendationReasons": score["reasons"]})
        recommendation = self._model_comparison_recommendation(scored_rows, current_pack="antelopev2")
        pose_candidate = next((row for row in scored_rows if row.get("pack") == "buffalo_l"), {})
        noisy_candidate = next((row for row in scored_rows if row.get("pack") == "buffalo_s"), {})
        ok = (
            recommendation.get("status") == "switch"
            and recommendation.get("recommendedPack") == "buffalo_l"
            and float(recommendation.get("profileRecall", 0) or 0) >= 0.70
            and float(pose_candidate.get("recommendationScore", 0) or 0) > float(noisy_candidate.get("recommendationScore", 0) or 0)
        )
        return {
            "ok": bool(ok),
            "recommendedPack": recommendation.get("recommendedPack"),
            "profileRecall": recommendation.get("profileRecall"),
            "confidence": recommendation.get("confidence"),
            "summary": recommendation.get("summary"),
            "rows": scored_rows,
        }

    def _self_learning_rd_release_posture(self) -> dict[str, Any]:
        try:
            from crossage_fr.experiments import self_learning_audit

            audit = self_learning_audit.self_learning_rd_audit()
            semantic_errors = self_learning_audit._audit_semantic_errors(audit)
            requirements = audit.get("requirements") if isinstance(audit.get("requirements"), list) else []
            blocked = [
                str(row.get("id", "") or "")
                for row in requirements
                if isinstance(row, dict) and row.get("ok") is not True
            ]
            satisfied = [
                str(row.get("id", "") or "")
                for row in requirements
                if isinstance(row, dict) and row.get("ok") is True
            ]
            ok = bool(not semantic_errors and audit.get("notProductionAuthorization") is True)
            return {
                "ok": ok,
                "status": "production-safe-r-and-d-separated" if ok else "fail",
                "auditOk": audit.get("ok") is True,
                "auditStatus": audit.get("status"),
                "notProductionAuthorization": audit.get("notProductionAuthorization") is True,
                "blockedRequirements": blocked,
                "satisfiedRequirements": satisfied,
                "semanticErrors": semantic_errors,
            }
        except Exception as exc:
            return {
                "ok": False,
                "status": "unavailable",
                "auditOk": False,
                "auditStatus": "unavailable",
                "notProductionAuthorization": False,
                "blockedRequirements": [],
                "satisfiedRequirements": [],
                "semanticErrors": [str(exc)],
            }

    def release_readiness(self) -> dict[str, Any]:
        face_model = model_status(self.project.config, self.engine_name)
        safe_model = safety_model_report()
        distribution = self.model_distribution_audit()
        db_integrity = self.project.database_integrity()
        video_decoder = video_decoder_report()
        dataset_gate = self._dataset_regression_gate_summary()
        self_learning_rd = self._self_learning_rd_release_posture()
        model_packages = face_model.get("packages", []) if isinstance(face_model.get("packages"), list) else []
        downloadable_packages = [
            package
            for package in model_packages
            if isinstance(package, dict)
            and str(package.get("url", "")).startswith(("http://", "https://"))
            and bool(str(package.get("sha256", "")).strip())
        ]
        try:
            validation = self.project.run_accuracy_validation_pack(store=False)
        except Exception as exc:
            validation = {"status": "fail", "recommendations": [str(exc)], "scenarioResults": []}
        update_feed_ready = bool(
            os.environ.get("VINTRACE_UPDATE_URL")
            or os.environ.get("CROSSAGE_UPDATE_URL")
            or os.environ.get("CROSSAGE_RELEASE_FEED_READY") == "1"
            or os.environ.get("GH_TOKEN")
            or os.environ.get("GITHUB_TOKEN")
        )
        checks = [
            {
                "name": "Face model",
                "ok": bool(face_model.get("ready")),
                "detail": "Full face model is installed." if face_model.get("ready") else str(face_model.get("recommendation") or "Download a face model."),
            },
            {
                "name": "Safe Mode model",
                "ok": bool(safe_model.get("available")),
                "detail": str(safe_model.get("modelName") or safe_model.get("reason") or "Safe Mode model unavailable."),
            },
            {
                "name": "Model license manifest",
                "ok": bool(distribution.get("ok")),
                "detail": "Model sources, checksums, and licenses are complete." if distribution.get("ok") else "; ".join(distribution.get("recommendations", [])[:2]),
                "value": distribution,
            },
            {
                "name": "First-run model downloader",
                "ok": bool(downloadable_packages),
                "detail": f"{len(downloadable_packages)} downloadable model package(s) expose URL and checksum." if downloadable_packages else "Configure at least one downloadable model package with URL and checksum.",
                "value": {"packages": downloadable_packages},
            },
            {
                "name": "Database integrity",
                "ok": bool(db_integrity.get("ok")),
                "detail": "SQLite workspace index passed integrity checks." if db_integrity.get("ok") else str(db_integrity.get("error") or "SQLite workspace index needs repair."),
                "value": db_integrity,
            },
            {
                "name": "Video decoder",
                "ok": bool(video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable")),
                "detail": str(video_decoder.get("backend") or "Video decoder unavailable."),
                "value": video_decoder,
            },
            {
                "name": "Accuracy validation pack",
                "ok": str(validation.get("status", "fail")) == "pass",
                "detail": "Synthetic validation pack passed." if str(validation.get("status", "fail")) == "pass" else "; ".join([str(item) for item in validation.get("recommendations", [])[:2]]) or "Synthetic validation pack did not pass.",
                "value": validation,
            },
            {
                "name": "Dataset regression gates",
                "ok": bool(dataset_gate.get("ok")),
                "detail": "Pose-aware model recommendation gate passed." if dataset_gate.get("ok") else "Dataset recommendation gate failed; inspect model scoring before release.",
                "value": dataset_gate,
            },
            {
                "name": "Self-learning R&D boundary",
                "ok": bool(self_learning_rd.get("ok")),
                "detail": (
                    "True retraining remains R&D-only; blocked Phase 5/6 evidence is documented."
                    if self_learning_rd.get("ok") and self_learning_rd.get("blockedRequirements")
                    else "Self-learning R&D evidence is satisfied, but still does not authorize production retraining."
                    if self_learning_rd.get("ok")
                    else "Self-learning R&D posture is inconsistent; do not imply true retraining readiness."
                ),
                "value": self_learning_rd,
            },
            {
                "name": "Consent policy",
                "ok": bool(self.project.config.require_consent),
                "detail": "Processing requires permission." if self.project.config.require_consent else "Permission requirement is disabled.",
            },
            {
                "name": "macOS signing",
                "ok": bool(os.environ.get("CSC_LINK") or os.environ.get("APPLE_ID")),
                "detail": "Signing environment detected." if os.environ.get("CSC_LINK") or os.environ.get("APPLE_ID") else "Configure Apple Developer signing and notarization before public DMGs.",
            },
            {
                "name": "Windows signing",
                "ok": bool(os.environ.get("WIN_CSC_LINK") or os.environ.get("CSC_LINK")),
                "detail": "Windows signing environment detected." if os.environ.get("WIN_CSC_LINK") or os.environ.get("CSC_LINK") else "Configure a Windows code-signing certificate to reduce SmartScreen friction.",
            },
            {
                "name": "Auto-update",
                "ok": update_feed_ready,
                "detail": "Update feed credentials/configuration detected." if update_feed_ready else "Configure a signed release feed before sharing production DMGs/EXEs.",
            },
            {
                "name": "Crash reporting",
                "ok": True,
                "detail": "Local consent-first diagnostics export is available; network sending remains opt-in/manual.",
            },
        ]
        return {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "ok": all(check["ok"] for check in checks),
            "checks": checks,
            "recommendations": [check["detail"] for check in checks if not check["ok"]][:5] or ["Release checklist passed."],
        }

    def model_integrity(self) -> dict[str, Any]:
        face_model = model_status(self.project.config, self.engine_name)
        safe_model = safety_model_report()
        image_decoder = image_decoder_report()
        video_decoder = video_decoder_report()
        distribution = self.model_distribution_audit()
        db_integrity = self.project.database_integrity()
        dataset_gate = self._dataset_regression_gate_summary()
        checks: list[dict[str, Any]] = []

        def add(name: str, ok: bool, detail: str, value: Any | None = None) -> None:
            row: dict[str, Any] = {"name": name, "ok": bool(ok), "detail": detail}
            if value is not None:
                row["value"] = value
            checks.append(row)

        model_root = Path(str(face_model.get("modelRoot", ""))).expanduser()
        root_writable = False
        try:
            model_root.mkdir(parents=True, exist_ok=True)
            probe = model_root / ".vintrace-integrity-write"
            probe.write_text("ok", encoding="utf-8")
            root_writable = probe.read_text(encoding="utf-8") == "ok"
            probe.unlink(missing_ok=True)
        except OSError:
            root_writable = False

        add("Face model", bool(face_model.get("ready")), str(face_model.get("recommendation") or face_model.get("engine") or "Face model checked."), face_model)
        add("Model folder writable", root_writable, str(model_root) if root_writable else "Choose a writable model download folder.")
        installed_checks = []
        current_pack = str(face_model.get("currentPack", ""))
        for package in face_model.get("packages", []):
            if not isinstance(package, dict) or str(package.get("pack", "")) != current_pack:
                continue
            pack_dir = Path(str(package.get("path", ""))).expanduser()
            for group in package.get("required_any", []):
                if not isinstance(group, (list, tuple)):
                    continue
                candidates = [pack_dir / str(filename) for filename in group]
                selected = next((candidate for candidate in candidates if candidate.exists()), candidates[0] if candidates else pack_dir)
                installed_checks.append(self._onnx_integrity_check(selected))
        installed_ok = bool(installed_checks) and all(bool(item.get("ok")) for item in installed_checks)
        add(
            "Installed ONNX files",
            installed_ok if face_model.get("ready") else False,
            "Installed face model files passed structural checks." if installed_ok else "Installed face model files are missing, empty, or unreadable.",
            installed_checks,
        )
        archive_checks = []
        for package in face_model.get("packages", []):
            if not isinstance(package, dict):
                continue
            archive_path = Path(str(package.get("archivePath", ""))).expanduser()
            if not archive_path.exists():
                archive_checks.append({"pack": package.get("pack"), "status": "missing", "ok": bool(package.get("available"))})
                continue
            expected = str(package.get("sha256", ""))
            digest = self._sha256_path(archive_path)
            ok = bool(expected and digest == expected)
            archive_checks.append({"pack": package.get("pack"), "status": "verified" if ok else "mismatch", "ok": ok, "sha256": digest})
        archive_ok = all(bool(item.get("ok")) for item in archive_checks if item.get("status") != "missing")
        add("Downloaded archives", archive_ok, "Downloaded model archives pass checksum checks." if archive_ok else "One or more downloaded model archives failed checksum verification.", archive_checks)
        add("Safe Mode model", bool(safe_model.get("available")), str(safe_model.get("modelName") or safe_model.get("reason") or "Safe Mode model checked."), safe_model)
        add("Model license manifest", bool(distribution.get("ok")), "Model manifest is ready for redistribution review." if distribution.get("ok") else "; ".join(distribution.get("recommendations", [])[:2]), distribution)
        add("Workspace database", bool(db_integrity.get("ok")), "SQLite workspace index passed integrity checks." if db_integrity.get("ok") else str(db_integrity.get("error") or "SQLite workspace index needs repair."), db_integrity)
        add("Dataset regression gates", bool(dataset_gate.get("ok")), "Pose-aware recommendation gate passed." if dataset_gate.get("ok") else "Dataset recommendation gate failed.", dataset_gate)
        add("Image decoder", bool(image_decoder.get("extensions")), f"{len(image_decoder.get('extensions', []))} image extension(s) supported.", image_decoder)
        add("Video decoder", bool(video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable")), str(video_decoder.get("backend") or "Video decoder unavailable."), video_decoder)
        recommendations = [check["detail"] for check in checks if not check["ok"]]
        if not recommendations:
            recommendations.append("Model and runtime integrity checks passed.")
        return {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "ok": all(check["ok"] for check in checks),
            "checks": checks,
            "recommendations": recommendations,
        }

    def _sha256_path(self, path: Path) -> str:
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    def _onnx_integrity_check(self, path: Path) -> dict[str, Any]:
        # PC-02: model_integrity() results are returned to the client directly
        # (not only via the already-redacted support bundle), so mask the
        # absolute directory here — the basename (e.g. glintr100.onnx) is public,
        # the containing path (home dir / external drive) is not.
        result: dict[str, Any] = {"path": _mask_absolute_paths(str(path)), "ok": False, "bytes": 0, "checkedWith": "filesystem", "error": ""}
        try:
            stat = path.stat()
            result["bytes"] = int(stat.st_size)
            if not path.is_file() or stat.st_size <= 0:
                result["error"] = "Model file is missing or empty."
                return result
        except OSError as exc:
            result["error"] = _mask_absolute_paths(str(exc))
            return result
        try:
            import onnxruntime as ort  # type: ignore

            session = ort.InferenceSession(str(path), providers=["CPUExecutionProvider"])
            result["checkedWith"] = "onnxruntime"
            result["inputs"] = len(session.get_inputs())
            result["outputs"] = len(session.get_outputs())
        except ImportError:
            result["checkedWith"] = "filesystem"
        except Exception as exc:
            result["checkedWith"] = "onnxruntime"
            result["error"] = _mask_absolute_paths(str(exc))
            return result
        result["ok"] = True
        return result

    def recent_backend_errors(self, limit: int = 50) -> dict[str, Any]:
        # TO-3: read the tail of the persisted (already path-redacted) error log
        # so the support bundle ships recent backend failures for offline debug.
        log_path = self.project.root / "logs" / "backend-errors.jsonl"
        records: list[dict[str, Any]] = []
        try:
            if log_path.exists():
                tail = deque(log_path.read_text(encoding="utf-8").splitlines(), maxlen=max(1, limit))
                for line in tail:
                    try:
                        records.append(json.loads(line))
                    except json.JSONDecodeError:
                        continue
        except OSError:
            pass
        return {"count": len(records), "errors": records}

    def export_support_bundle(self, include_paths: bool = False) -> dict[str, Any]:
        export_root = self.project.root / "exports"
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_path = export_root / f"vintrace-support-bundle-{stamp}.zip"
        counter = 2
        while bundle_path.exists():
            bundle_path = export_root / f"vintrace-support-bundle-{stamp}-{counter}.zip"
            counter += 1
        payloads = {
            "manifest.json": {
                "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
                "appVersion": __version__,
                "workspaceId": self.project.workspace_metadata.get("workspaceId"),
                "includePaths": bool(include_paths),
                "learnedArtifactsIncluded": False,
                "trainingExamplesIncluded": False,
                "note": "Diagnostics only. This ZIP does not include original photos, videos, thumbnails, face vectors, or model files.",
            },
            "workspace-health.json": self.project.workspace_health(),
            "privacy-report.json": self.project.privacy_report(),
            "retention-policy-report.json": self.project.retention_policy_report(),
            "model-drift-report.json": self.project.model_drift_report(self.engine_name),
            "reference-gap-report.json": self.project.reference_gap_report(self.engine_name),
            "runtime-self-test.json": self.runtime_self_test(),
            "model-integrity.json": self.model_integrity(),
            "release-readiness.json": self.release_readiness(),
            "model-status.json": model_status(self.project.config, self.engine_name),
            "safe-mode-model.json": safety_model_report(),
            "image-decoder.json": image_decoder_report(),
            "video-decoder.json": video_decoder_report(),
            "scale-summary.json": self.project.scale_summary(),
            "audit-events.json": self.project.audit_events(limit=80, offset=0),
            "backend-errors.json": self.recent_backend_errors(limit=50),
        }
        serializable = self._redact_paths(payloads, include_paths=include_paths)
        with zipfile.ZipFile(bundle_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for name, payload in serializable.items():
                archive.writestr(name, json.dumps(payload, indent=2))
        size = bundle_path.stat().st_size
        self.project._append_audit(
            {
                "action": "export_support_bundle",
                "zip_path": str(bundle_path),
                "include_paths": bool(include_paths),
                "bytes": size,
            }
        )
        return {
            "zipPath": str(bundle_path),
            "bytes": size,
            "fileCount": len(serializable),
            "includePaths": bool(include_paths),
        }

    def export_compliance_pack(self) -> dict[str, Any]:
        # Item 2: bundle the governance evidence the workspace already collects plus generated
        # DRAFT DPIA/FRIA/Annex-IV documents into one ZIP. Every generated legal artifact is
        # clearly stamped DRAFT / not-certification (COMPLIANCE_DRAFT_DISCLAIMER).
        from crossage_fr.compliance import JURISDICTION_DISCLAIMER, jurisdiction_preset

        export_root = self.project.root / "exports"
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        pack_path = export_root / f"vintrace-compliance-pack-{stamp}.zip"
        counter = 2
        while pack_path.exists():
            pack_path = export_root / f"vintrace-compliance-pack-{stamp}-{counter}.zip"
            counter += 1

        build = self._build_info()
        consent = self.project.consent_summary()
        chain = self.project.verify_audit_chain()
        retention = self.project.retention_policy_report()
        model_audit = self.model_distribution_audit()
        try:
            accuracy = self.project.accuracy_evaluation()
        except Exception:
            accuracy = {"available": False, "note": "No labeled accuracy data in this workspace yet."}
        preset = jurisdiction_preset(self.project.config.jurisdiction_preset) or {}
        config = self.project.config
        policy = {
            "requireConsent": bool(config.require_consent),
            "perSubjectConsent": bool(config.per_subject_consent),
            "reviewOnly": bool(config.review_only),
            "safeMode": bool(config.safe_mode),
            "safeModeZeroAdmittance": bool(config.safe_mode_zero_admittance),
            "retentionReviewedDays": int(config.retention_reviewed_days),
            "jurisdictionPreset": str(config.jurisdiction_preset),
        }
        generated_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        context = {
            "generatedAt": generated_at,
            "build": build,
            "consent": consent,
            "chain": chain,
            "retention": retention,
            "modelAudit": model_audit,
            "accuracy": accuracy,
            "preset": preset,
            "policy": policy,
        }
        json_payloads = {
            "00-manifest.json": {
                "generatedAt": generated_at,
                "appVersion": __version__,
                "workspaceId": self.project.workspace_metadata.get("workspaceId"),
                "disclaimer": COMPLIANCE_DRAFT_DISCLAIMER,
                "note": "Governance evidence pack. Does not include photos, videos, thumbnails, face vectors, or model files.",
            },
            "consent-summary.json": {**consent, "subjects": self.project.subject_consents()},
            "audit-chain-status.json": chain,
            "audit-events.json": self.project.audit_events(limit=200, offset=0),
            "retention-policy.json": retention,
            "model-distribution-audit.json": model_audit,
            "accuracy-evaluation.json": accuracy,
            "build-provenance.json": build,
            "policy.json": policy,
            "jurisdiction-preset.json": {**preset, "disclaimer": JURISDICTION_DISCLAIMER},
        }
        markdown_docs = {
            "README.md": self._render_compliance_readme(context),
            "DPIA-DRAFT.md": self._render_dpia_draft(context),
            "FRIA-DRAFT.md": self._render_fria_draft(context),
            "annex-iv-technical-documentation-DRAFT.md": self._render_annex_iv_draft(context),
        }
        serializable = self._redact_paths(json_payloads, include_paths=False)
        with zipfile.ZipFile(pack_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for name, payload in serializable.items():
                archive.writestr(name, json.dumps(payload, indent=2))
            for name, text in markdown_docs.items():
                archive.writestr(name, text)
        size = pack_path.stat().st_size
        self.project._append_audit(
            {"action": "export_compliance_pack", "zip_path": str(pack_path), "bytes": size}
        )
        return {
            "zipPath": str(pack_path),
            "bytes": size,
            "members": list(serializable) + list(markdown_docs),
            "disclaimer": COMPLIANCE_DRAFT_DISCLAIMER,
        }

    def export_examination_report(self, person_name: str = "") -> dict[str, Any]:
        # Item 10: a Daubert-aware, audit-anchored examination report for a person (or all reviewed
        # candidates). Documents method, model provenance, per-decision evidence with cross-age
        # uncertainty, consent basis, and the tamper-evident audit reference. DRAFT / not-an-ID.
        export_root = self.project.root / "exports"
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        person_key = str(person_name or "").strip().casefold()
        candidates = [
            candidate
            for candidate in self.project.candidates.values()
            if not person_key or str(candidate.person_name or "").strip().casefold() == person_key
        ]
        if person_key:
            # Reviewed decisions first; within that, strongest evidence first.
            status_rank = {"accepted": 0, "uncertain": 1, "rejected": 2, "pending": 3}
            candidates.sort(key=lambda c: (status_rank.get(c.status, 4), -float(c.score or 0)))
        config = self.project.config
        build = self._build_info()
        model_audit = self.model_distribution_audit()
        chain = self.project.verify_audit_chain()
        consent = self.project.consent_summary()
        examiner = str(consent.get("operator") or self.actor or "unknown")
        rows = [
            {
                "candidateId": candidate.candidate_id,
                "personName": candidate.person_name,
                "status": candidate.status,
                "score": round(float(candidate.score or 0), 4),
                "band": candidate.band,
                "quality": round(float(candidate.quality or 0), 4),
                "captureDate": candidate.capture_date,
                "referenceCaptureDate": candidate.reference_capture_date,
                "ageGapYears": candidate.age_gap_years,
                "ageGapConfidence": candidate.age_gap_confidence,
                "captureDateProvenance": candidate.capture_date_provenance,
                "referenceCaptureDateProvenance": candidate.reference_capture_date_provenance,
                "riskFlags": normalize_risk_flags(candidate.risk_flags, candidate.note),
                "note": candidate.note,
                "modelName": candidate.model_name,
                "mediaKind": candidate.media_kind,
            }
            for candidate in candidates
        ]
        method = {
            "appVersion": build.get("version"),
            "appCommit": build.get("commit"),
            "thresholds": {
                "confident": config.thresholds.confident,
                "likely": config.thresholds.likely,
                "relaxedChild": config.thresholds.relaxed_child,
                "qualityMin": config.thresholds.quality_min,
            },
            "models": [
                {
                    "id": item.get("id"),
                    "source": item.get("source"),
                    "sha256": item.get("sha256"),
                    "license": item.get("license"),
                    "licenseState": item.get("licenseState"),
                    "accuracyTier": item.get("accuracyTier"),
                }
                for item in (model_audit.get("items", []) if isinstance(model_audit, dict) else [])
            ],
        }
        generated_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        payload = {
            "generatedAt": generated_at,
            "examiner": examiner,
            "person": person_name or "(all reviewed candidates)",
            "disclaimer": EXAMINATION_DRAFT_DISCLAIMER,
            "method": method,
            "consent": consent,
            "auditChain": {
                "verified": chain.get("verified"),
                "length": chain.get("length"),
                "tail": chain.get("tail"),
            },
            "policy": {
                "reviewOnly": bool(config.review_only),
                "safeMode": bool(config.safe_mode),
                "safeModeZeroAdmittance": bool(config.safe_mode_zero_admittance),
                "jurisdictionPreset": str(config.jurisdiction_preset),
            },
            "candidateCount": len(rows),
            "candidates": rows,
        }
        json_path = export_root / f"vintrace-examination-report-{stamp}.json"
        md_path = export_root / f"vintrace-examination-report-{stamp}.md"
        json_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
        md_path.write_text(self._render_examination_markdown(payload), encoding="utf-8")
        self.project._append_audit(
            {
                "action": "export_examination_report",
                "json_path": str(json_path),
                "markdown_path": str(md_path),
                "person": person_name,
                "candidates": len(rows),
            }
        )
        return {
            "jsonPath": str(json_path),
            "markdownPath": str(md_path),
            "candidateCount": len(rows),
            "disclaimer": EXAMINATION_DRAFT_DISCLAIMER,
        }

    def _render_examination_markdown(self, payload: dict[str, Any]) -> str:
        method = payload["method"]
        model_lines = "\n".join(
            f"- {model.get('id')}: source {model.get('source')}, sha256 {str(model.get('sha256'))[:16]}…, "
            f"license `{model.get('license')}` ({model.get('licenseState')}), tier {model.get('accuracyTier')}"
            for model in method.get("models", [])
        ) or "- (no model packages recorded)"
        lines = [
            "# Cross-Age Face Comparison — Examination Report (DRAFT)",
            "",
            f"Generated: {payload['generatedAt']}  ·  Examiner: {payload['examiner']}",
            f"Subject: {payload['person']}",
            "",
            f"> **{payload['disclaimer']}**",
            "",
            "## Method",
            f"- Application: Vintrace {method.get('appVersion')} (commit `{method.get('appCommit')}`)",
            "- Pipeline: InsightFace SCRFD detector + ArcFace 512-d embeddings, cosine similarity, human-in-the-loop review.",
            f"- Thresholds: confident {method['thresholds']['confident']}, likely {method['thresholds']['likely']}, "
            f"review {method['thresholds']['relaxedChild']}, quality-min {method['thresholds']['qualityMin']}.",
            "### Models & provenance",
            model_lines,
            "",
            "## Governance basis",
            f"- Consent on file: {payload['consent'].get('active')} (operator: {payload['consent'].get('operator')})",
            f"- Review-only: {payload['policy']['reviewOnly']}  ·  Safe Mode: {payload['policy']['safeMode']} "
            f"(zero-admittance: {payload['policy']['safeModeZeroAdmittance']})",
            f"- Jurisdiction preset: {payload['policy']['jurisdictionPreset']}",
            f"- Tamper-evident audit: verified={payload['auditChain']['verified']}, "
            f"length={payload['auditChain']['length']}, tail-hash={str(payload['auditChain']['tail'])[:16]}…",
            "",
            f"## Decisions ({payload['candidateCount']})",
            "",
            "| Status | Person | Band | Score | Age gap | Gap confidence | Risk flags |",
            "|---|---|---|---|---|---|---|",
        ]
        for row in payload["candidates"]:
            gap = "—" if row["ageGapYears"] is None else f"{row['ageGapYears']} yr"
            conf = row["ageGapConfidence"] or "—"
            flags = ", ".join(row["riskFlags"]) or "none"
            lines.append(
                f"| {row['status']} | {row['personName']} | {row['band']} | {row['score']} | {gap} | {conf} | {flags} |"
            )
        lines += [
            "",
            "## Examiner limitations & attestation",
            "- Each row is a machine-surfaced *possible* match adjudicated by a human reviewer; it is not a positive identification.",
            "- Wide cross-age gaps (confidence low/very-low) must be treated as weak leads requiring corroborating evidence.",
            "- Examiner attestation: _name / qualifications / signature / date_ ____________________",
            "",
        ]
        return "\n".join(lines)

    def _render_compliance_readme(self, ctx: dict[str, Any]) -> str:
        return (
            "# Vintrace Compliance / Governance Evidence Pack\n\n"
            f"Generated: {ctx['generatedAt']}\n\n"
            f"> **{COMPLIANCE_DRAFT_DISCLAIMER}**\n\n"
            "## Contents\n"
            "- `DPIA-DRAFT.md` — Data Protection Impact Assessment (GDPR Art 35) draft\n"
            "- `FRIA-DRAFT.md` — Fundamental Rights Impact Assessment (EU AI Act Art 27) draft\n"
            "- `annex-iv-technical-documentation-DRAFT.md` — EU AI Act Annex IV technical documentation draft\n"
            "- `consent-summary.json` / `audit-chain-status.json` / `audit-events.json` — consent + tamper-evident audit evidence\n"
            "- `retention-policy.json` / `policy.json` / `jurisdiction-preset.json` — retention + governance posture\n"
            "- `model-distribution-audit.json` / `build-provenance.json` / `accuracy-evaluation.json` — model identity, licensing, accuracy\n\n"
            "## How to use\n"
            "1. A qualified DPO/counsel completes and signs the DRAFT documents.\n"
            "2. The JSON files are the machine-readable evidence the drafts cite.\n"
            "3. Re-export after material changes (new model pack, threshold change, retention change).\n"
        )

    def _render_dpia_draft(self, ctx: dict[str, Any]) -> str:
        policy = ctx["policy"]
        return (
            "# Data Protection Impact Assessment (DRAFT)\n\n"
            f"Generated: {ctx['generatedAt']}\n\n"
            f"> **{COMPLIANCE_DRAFT_DISCLAIMER}**\n\n"
            "## 1. Processing description\n"
            "Local, on-device cross-age face recognition that surfaces *possible* same-person-across-time\n"
            "candidates for human review. No autonomous identification; every decision is a logged human action.\n\n"
            "## 2. Necessity & proportionality\n"
            f"- Consent required before processing: **{policy['requireConsent']}**\n"
            f"- Per-subject consent: **{policy['perSubjectConsent']}**\n"
            f"- Review-only (no automated action): **{policy['reviewOnly']}**\n"
            f"- Reviewed-match retention window: **{policy['retentionReviewedDays']} days**\n"
            f"- Jurisdiction preset: **{policy['jurisdictionPreset']}**\n\n"
            "## 3. Special-category data (GDPR Art 9)\n"
            "Biometric data for unique identification is special-category. Lawful basis (explicit consent or another\n"
            "Art 9(2) basis) MUST be confirmed per subject. Children's biometrics are heightened risk.\n\n"
            "## 4. Risks & mitigations\n"
            "- Wrongful identification → recall-first + mandatory human review; cross-age confidence is banded (NIST IFPC 2025).\n"
            f"- Sensitive-content exposure → Safe Mode **{policy['safeMode']}**, zero-admittance **{policy['safeModeZeroAdmittance']}**.\n"
            "- Tampering/repudiation → tamper-evident hash-chained audit "
            f"(verified: **{ctx['chain'].get('verified')}**, chained entries: **{ctx['chain'].get('chained')}**).\n"
            "- Data sprawl → local-only processing, retention policy, and delete_face_data.\n\n"
            "## 5. Residual risk & sign-off\n"
            "_To be completed by the DPO._ Residual risk rating: ____   Approver: ____   Date: ____\n"
        )

    def _render_fria_draft(self, ctx: dict[str, Any]) -> str:
        return (
            "# Fundamental Rights Impact Assessment (DRAFT)\n\n"
            f"Generated: {ctx['generatedAt']}\n\n"
            f"> **{COMPLIANCE_DRAFT_DISCLAIMER}**\n\n"
            "## 1. Deployment context\n"
            "_Describe the deployer, purpose, and the categories of natural persons affected._\n\n"
            "## 2. Rights at stake\n"
            "Privacy & data protection, non-discrimination, dignity, effective remedy. Cross-age matching is least\n"
            "reliable for wide child→adult gaps (NIST IFPC 2025) — never present a match as a positive identification.\n\n"
            "## 3. Risks of harm & mitigations\n"
            "- Misidentification of a vulnerable person → human-in-the-loop adjudication; uncertainty surfaced per candidate.\n"
            "- Function creep toward surveillance → out-of-bounds: no covert/watchlist/live 1:N use (EU AI Act Art 5).\n"
            "- Bias across demographics → bias/accuracy testing required before high-risk deployment (EU AI Act Art 10/15).\n\n"
            "## 4. Human oversight (Art 14)\n"
            "Reviewers can accept/reject/mark-uncertain and undo; agents cannot grant consent or finalize identity.\n\n"
            "## 5. Governance measures in effect\n"
            f"- Consent: requireConsent={ctx['policy']['requireConsent']}, perSubject={ctx['policy']['perSubjectConsent']}\n"
            f"- Audit chain verified: {ctx['chain'].get('verified')}\n"
            f"- Jurisdiction preset: {ctx['policy']['jurisdictionPreset']}\n\n"
            "## 6. Conclusion & sign-off\n"
            "_To be completed by the accountable owner._ Approver: ____   Date: ____\n"
        )

    def _render_annex_iv_draft(self, ctx: dict[str, Any]) -> str:
        build = ctx["build"]
        items = (ctx["modelAudit"] or {}).get("items", []) if isinstance(ctx["modelAudit"], dict) else []
        model_lines = "\n".join(
            f"- {it.get('id')}: source {it.get('source')}, sha256 {str(it.get('sha256'))[:16]}…, "
            f"license `{it.get('license')}` (state: {it.get('licenseState')}), tier {it.get('accuracyTier')}"
            for it in items
        ) or "- (no model packages recorded)"
        return (
            "# EU AI Act Annex IV — Technical Documentation (DRAFT)\n\n"
            f"Generated: {ctx['generatedAt']}\n\n"
            f"> **{COMPLIANCE_DRAFT_DISCLAIMER}**\n\n"
            "## 1. General description\n"
            f"System: Vintrace cross-age face recognition workbench, version **{build.get('version')}** "
            f"(commit `{build.get('commit')}`, channel {build.get('channel')}).\n"
            "Intended purpose: assistive, recall-first, human-in-the-loop review of possible same-person matches.\n"
            "Not for autonomous identification, covert use, or live public-space 1:N.\n\n"
            "## 2. Elements & development\n"
            "InsightFace SCRFD detector + ArcFace 512-d embeddings, FAISS retrieval, HDBSCAN clustering, "
            "ONNX Runtime (CoreML/CUDA/CPU). Safe Mode NSFW screening before matching.\n\n"
            "## 3. Models & provenance\n"
            f"{model_lines}\n\n"
            "## 4. Accuracy, robustness, limitations\n"
            "Wide-gap child→adult recognition is unreliable (NIST IFPC 2025: TAR@0.1%FAR ~98.5%@2yr → ~71.3%@8yr).\n"
            f"Local accuracy evaluation present: **{bool(ctx['accuracy']) and ctx['accuracy'].get('available', True)}**. "
            "Bias testing across demographics is REQUIRED before high-risk deployment and is not yet included here.\n\n"
            "## 5. Human oversight & logging\n"
            f"Tamper-evident hash-chained audit (verified: {ctx['chain'].get('verified')}, "
            f"length: {ctx['chain'].get('length')}). Every review decision is a logged human action.\n\n"
            "## 6. Risk management & post-market monitoring\n"
            "_To be completed._ Note: recognition runs on research-tier weights unless licensed commercial weights are configured.\n"
        )

    def _redact_paths(self, value: Any, include_paths: bool = False) -> Any:
        if include_paths:
            return value
        path_keys = {
            "path",
            "workspace",
            "workspacePath",
            "dbPath",
            "sourcePath",
            "source_path",
            "folder",
            "mediaSourcePath",
            "media_source_path",
            "bestRefPath",
            "modelRoot",
            "defaultRoot",
            "root",
            "zipPath",
            "jsonPath",
            "csvPath",
            "bundlePath",
            "manifestPath",
            "archivePath",
            "removedPaths",
            "scope",
            "oldRoot",
            "newRoot",
            "old_root",
            "new_root",
            "directory",
            "folder",
            "from",
            "to",
        }
        path_key_suffixes = ("path", "paths", "root", "roots", "directory", "directories", "folder", "folders")
        # PC-01: free-text identity fields (subject names, operator identity, and
        # consent/case notes) carried by audit rows are NOT path-shaped, so the
        # path redaction above misses them and they shipped verbatim in the
        # "diagnostics only" bundle. Mask them when paths are excluded.
        pii_keys = {
            "person_name",
            "personName",
            "operator",
            "note",
            "label",
            "oldName",
            "newName",
            "old_name",
            "new_name",
        }
        if isinstance(value, dict):
            redacted: dict[str, Any] = {}
            for key, item in value.items():
                key_text = str(key)
                key_lower = key_text.lower()
                if key_text in path_keys or key_lower.endswith(path_key_suffixes):
                    if isinstance(item, list):
                        redacted[key_text] = [self._redacted_path(str(path)) for path in item[:20]]
                    elif item is None:
                        redacted[key_text] = None
                    else:
                        redacted[key_text] = self._redacted_path(str(item))
                elif key_text in pii_keys:
                    redacted[key_text] = "[redacted]" if isinstance(item, str) and item else item
                else:
                    redacted[key_text] = self._redact_paths(item, include_paths=False)
            return redacted
        if isinstance(value, (list, tuple)):
            return [self._redact_paths(item, include_paths=False) for item in value]
        if isinstance(value, str):
            return self._redact_string(value)
        return value

    def _redact_string(self, value: str) -> str:
        if not value:
            return value
        text = value
        prefixes = {
            str(self.project.root),
            os.path.realpath(str(self.project.root)),
            str(self.project.root.parent),
            os.path.realpath(str(self.project.root.parent)),
            str(Path.home()),
            os.path.realpath(str(Path.home())),
        }
        for prefix in sorted((item for item in prefixes if item), key=len, reverse=True):
            if text == prefix or text.startswith(f"{prefix}/") or text.startswith(f"{prefix}\\"):
                return self._redacted_path(text)
            text = text.replace(prefix, "[hidden]")
        if text.startswith(("/", "~")) or re.match(r"^[A-Za-z]:[\\/]", text) or text.startswith("\\\\"):
            return self._redacted_path(text)
        # PC-02: mask any remaining mid-line absolute paths (external-drive paths /
        # sensitive filenames in error messages and tracebacks) to their basename.
        return _mask_absolute_paths(text)

    def _redacted_path(self, value: str) -> str:
        if not value:
            return ""
        try:
            name = Path(value).name or value
        except (OSError, ValueError):
            name = ""
        return f"[hidden]/{name}" if name else "[hidden]"

    def installer_self_diagnostics(self) -> dict[str, Any]:
        runtime = self.runtime_self_test()
        face_model = model_status(self.project.config, self.engine_name)
        safe_model = safety_model_report()
        image_decoder = image_decoder_report()
        video_decoder = video_decoder_report()
        workspace_health = self.project.workspace_health()
        distribution = self.model_distribution_audit()
        db_integrity = self.project.database_integrity()
        storage = inspect_storage_path(self.project.root, self.project.root)
        dataset_gate = self._dataset_regression_gate_summary()
        packaged = bool(getattr(sys, "frozen", False) or os.environ.get("CROSSAGE_PACKAGED_BACKEND") == "1")
        model_packages = face_model.get("packages", []) if isinstance(face_model.get("packages"), list) else []
        downloadable = any(str(package.get("url", "")).startswith(("http://", "https://")) and str(package.get("sha256", "")) for package in model_packages if isinstance(package, dict))
        checks = [
            {
                "name": "App folder write",
                "ok": any(check.get("name") == "Workspace write" and check.get("ok") for check in runtime.get("checks", [])),
                "detail": "The app can save settings, results, and generated previews.",
            },
            {
                "name": "Face model",
                "ok": bool(face_model.get("ready")),
                "detail": str(face_model.get("recommendation") or face_model.get("engine") or "Face model status checked."),
            },
            {
                "name": "Model downloader",
                "ok": downloadable or bool(face_model.get("ready")),
                "detail": "Download URL and checksum are configured." if downloadable else "Face model is already ready or no downloadable pack is configured.",
            },
            {
                "name": "Dataset regression gates",
                "ok": bool(dataset_gate.get("ok")),
                "detail": "Pose-aware recommendation gate passed." if dataset_gate.get("ok") else "Dataset recommendation gate failed; run tests/dataset_regression_gates.py.",
            },
            {
                "name": "Model manifest",
                "ok": bool(distribution.get("items")),
                "detail": "Model package URLs, checksums, and license fields are visible for review.",
            },
            {
                "name": "Safe Mode",
                "ok": bool(self.project.config.safe_mode and safe_model.get("available")),
                "detail": str(safe_model.get("modelName") or safe_model.get("reason") or "Safe Mode model checked."),
            },
            {
                "name": "Photo formats",
                "ok": bool(image_decoder.get("extensions")),
                "detail": f"{len(image_decoder.get('extensions', []))} image extension(s) available.",
            },
            {
                "name": "Video support",
                "ok": bool(video_decoder.get("opencvAvailable") or video_decoder.get("ffmpegAvailable")),
                "detail": str(video_decoder.get("backend") or "Video decoder unavailable.") + (f" via {video_decoder.get('managedPackage')}" if video_decoder.get("managedPackageAvailable") else ""),
            },
            {
                "name": "Packaged backend",
                "ok": packaged,
                "detail": "Packaged backend detected." if packaged else "Running from source; installer builds should include the frozen backend.",
            },
            {
                "name": "Database integrity",
                "ok": bool(db_integrity.get("ok")),
                "detail": "SQLite workspace index passed integrity checks." if db_integrity.get("ok") else str(db_integrity.get("error") or "SQLite workspace index needs repair."),
            },
            {
                "name": "Storage location",
                "ok": bool(storage.get("readable") and storage.get("traversable") and not storage.get("networkLikely")),
                "detail": "App folder is on readable local storage." if not storage.get("warnings") else str(storage.get("warnings", ["Storage checked."])[0]),
            },
            {
                "name": "Workspace health",
                "ok": not any(workspace_health.get(key, 0) for key in ("missingReferences", "missingCandidates", "missingMediaSources")),
                "detail": "No missing workspace files found." if not any(workspace_health.get(key, 0) for key in ("missingReferences", "missingCandidates", "missingMediaSources")) else "Some saved files or media links are missing.",
            },
        ]
        recommendations = [check["detail"] for check in checks if not check["ok"]]
        recommendations.extend(str(item) for item in runtime.get("recommendations", []) if str(item) not in recommendations)
        if not recommendations:
            recommendations.append("Installer diagnostics passed for this machine.")
        return {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "ok": all(check["ok"] for check in checks),
            "packagedBackend": packaged,
            "checks": checks,
            "recommendations": recommendations[:8],
        }

    def query_candidates(self, params: dict[str, Any]) -> dict[str, Any]:
        status = str(params.get("status", "all")).strip().lower()
        if status not in {"all", "pending", "accepted", "rejected", "uncertain"}:
            raise ValueError("Candidate status filter must be all, pending, accepted, rejected, or uncertain.")
        lane = str(params.get("lane", "all")).strip()
        if lane not in {"all", "high", "lowQuality", "groups", "video", "notes", "closeRunner", "singleReference"}:
            raise ValueError("Candidate lane must be all, high, lowQuality, groups, video, notes, closeRunner, or singleReference.")
        query = str(params.get("query", "")).strip().lower()
        sort = str(params.get("sort", "score")).strip()
        offset = max(0, int(params.get("offset", 0) or 0))
        limit = max(1, min(1000, int(params.get("limit", 100) or 100)))
        preview_budget = max(0, min(64, int(params.get("previewBudget", 0) or 0)))
        low_quality_threshold = max(0.2, float(self.project.config.thresholds.quality_min))
        try:
            db_candidate_count = self.project.db.candidate_count()
            if db_candidate_count >= len(self.project.candidates):
                db_page = self.project.db.query_candidates(
                    status=status,
                    lane=lane,
                    query=query,
                    sort=sort,
                    offset=offset,
                    limit=limit,
                    confident_threshold=self.project.config.thresholds.confident,
                    low_quality_threshold=low_quality_threshold,
                )
                page = []
                for payload in db_page.get("items", []):
                    if not isinstance(payload, dict):
                        continue
                    candidate = self._review_candidate_from_payload(payload)
                    if candidate is None:
                        continue
                    page.append(candidate)
                items = []
                remaining_preview_budget = preview_budget
                for candidate in page:
                    before_preview = self.project.preview_path_for(candidate.source_path, create=False)
                    row = self._candidate_state_row(candidate, remaining_preview_budget)
                    if remaining_preview_budget > 0 and not before_preview and row.get("previewPath"):
                        remaining_preview_budget -= 1
                    items.append(row)
                return {
                    "total": int(db_page.get("total", 0) or 0),
                    "offset": offset,
                    "limit": limit,
                    "returned": len(items),
                    "items": items,
                    "index": "sqlite",
                }
        except Exception:
            pass
        grouped_candidate_ids: set[str] = set()
        if lane == "groups":
            by_media_path: dict[str, dict[str, Any]] = {}
            for candidate in self.project.candidates.values():
                media_path = candidate.media_source_path or candidate.source_path
                row = by_media_path.setdefault(media_path, {"ids": [], "people": set()})
                row["ids"].append(candidate.candidate_id)
                if candidate.person_name.strip() and not candidate.person_name.startswith("Unmatched cluster"):
                    row["people"].add(candidate.person_name)
            for row in by_media_path.values():
                if len(row["people"]) >= 2:
                    grouped_candidate_ids.update(row["ids"])

        def matches(candidate: Any) -> bool:
            if status != "all" and candidate.status != status:
                return False
            if lane == "high" and candidate.score < self.project.config.thresholds.confident:
                return False
            if lane == "lowQuality" and candidate.quality >= low_quality_threshold:
                return False
            if lane == "groups" and candidate.candidate_id not in grouped_candidate_ids:
                return False
            if lane == "video" and candidate.media_kind != "video":
                return False
            if lane == "notes" and not candidate.note.strip():
                return False
            risk_flags = self._candidate_risk_flags(candidate)
            if lane == "closeRunner" and not ({"close-runner-up", "ambiguous-person-margin"} & set(risk_flags)):
                return False
            if lane == "singleReference" and not ({"single-reference-match", "single-reference-close-runner-up", "single-reference-hard-pose"} & set(risk_flags)):
                return False
            if query:
                haystack = "\n".join(
                    [
                        candidate.person_name,
                        candidate.band,
                        candidate.source_path,
                        candidate.media_source_path,
                        candidate.note,
                        " ".join(risk_flags),
                        candidate.source_hash,
                    ]
                ).lower()
                if query not in haystack:
                    return False
            return True

        total = 0

        def iter_matches() -> Any:
            nonlocal total
            for candidate in self.project.candidates.values():
                if matches(candidate):
                    total += 1
                    yield candidate

        bound = offset + limit
        heap_bound_limit = 20_000
        if bound <= heap_bound_limit:
            if sort == "newest":
                ranked = heapq.nlargest(bound, iter_matches(), key=lambda item: (item.created_at, item.candidate_id))
            elif sort == "quality":
                ranked = heapq.nlargest(bound, iter_matches(), key=lambda item: (float(item.quality), item.created_at, item.candidate_id))
            elif sort == "status":
                ranked = heapq.nsmallest(bound, iter_matches(), key=lambda item: (item.status, item.person_name.lower(), -float(item.score), item.candidate_id))
            else:
                ranked = heapq.nlargest(bound, iter_matches(), key=lambda item: (float(item.score), item.quality, item.created_at, item.candidate_id))
        else:
            matched = list(iter_matches())
            if sort == "newest":
                ranked = sorted(matched, key=lambda item: (item.created_at, item.candidate_id), reverse=True)
            elif sort == "quality":
                ranked = sorted(matched, key=lambda item: (float(item.quality), item.created_at, item.candidate_id), reverse=True)
            elif sort == "status":
                ranked = sorted(matched, key=lambda item: (item.status, item.person_name.lower(), -float(item.score), item.candidate_id))
            else:
                ranked = sorted(matched, key=lambda item: (float(item.score), item.quality, item.created_at, item.candidate_id), reverse=True)
        page = ranked[offset:offset + limit]
        items = []
        remaining_preview_budget = preview_budget
        for candidate in page:
            before_preview = self.project.preview_path_for(candidate.source_path, create=False)
            row = self._candidate_state_row(candidate, remaining_preview_budget)
            if remaining_preview_budget > 0 and not before_preview and row.get("previewPath"):
                remaining_preview_budget -= 1
            items.append(row)
        return {
            "total": total,
            "offset": offset,
            "limit": limit,
            "returned": len(page),
            "items": items,
            "index": "memory",
        }

    def suggest_photo_review_more_candidates(self, params: dict[str, Any]) -> dict[str, Any]:
        person_names = self._clean_album_people(params.get("personNames", params.get("people", [])))
        exclude_people = self._clean_album_people(params.get("excludePeople", []))

        def clean_pets(values: Any) -> list[str]:
            if not isinstance(values, list):
                return []
            pets: list[str] = []
            seen: set[str] = set()
            for value in values:
                pet = self._clean_photo_pet_label(value)
                key = pet.casefold()
                if pet and key not in seen:
                    seen.add(key)
                    pets.append(pet)
            return pets

        raw_member_pets = params.get("memberPets", params.get("pets", []))
        raw_exclude_pets = params.get("excludePets", [])
        member_pets = clean_pets(raw_member_pets)
        exclude_pets = clean_pets(raw_exclude_pets)
        raw_statuses = params.get("statuses", ["pending", "uncertain"])
        statuses = [
            str(status or "").strip().lower()
            for status in (raw_statuses if isinstance(raw_statuses, list) else [])
            if str(status or "").strip().lower() in {"pending", "uncertain", "accepted", "rejected"}
        ] or ["pending", "uncertain"]
        limit = max(1, min(500, int(params.get("limit", 80) or 80)))
        min_score = max(0.0, min(1.0, float(params.get("minScore", 0.0) or 0.0)))
        result = self.project.db.suggest_photo_review_more_candidates(
            person_names=person_names,
            exclude_people=exclude_people,
            member_pets=member_pets,
            exclude_pets=exclude_pets,
            statuses=statuses,
            limit=limit,
            min_score=min_score,
        )
        return {
            **result,
            "requestedPeople": person_names,
            "requestedExcludePeople": exclude_people,
            "requestedPets": member_pets,
            "requestedExcludePets": exclude_pets,
            "limit": limit,
            "minScore": min_score,
        }

    def _candidate_state_row(self, candidate: Any, preview_budget: int = 0) -> dict[str, Any]:
        preview_path = self.project.preview_path_for(candidate.source_path, create=False)
        if not preview_path and preview_budget > 0:
            preview_path = self.project.preview_path_for(candidate.source_path, create=True)
        best_preview_path = self.project.preview_path_for(candidate.best_ref_path, create=False)
        return {
            "candidateId": candidate.candidate_id,
            "sourcePath": candidate.source_path,
            "personName": candidate.person_name,
            "bestRefId": candidate.best_ref_id,
            "bestRefPath": candidate.best_ref_path,
            "previewPath": preview_path,
            "bestRefPreviewPath": best_preview_path,
            "score": candidate.score,
            "band": candidate.band,
            "quality": candidate.quality,
            "modelName": candidate.model_name,
            "status": candidate.status,
            "note": candidate.note,
            "riskFlags": self._candidate_risk_flags(candidate),
            "mediaKind": candidate.media_kind,
            "mediaSourcePath": candidate.media_source_path,
            "videoTimestampMs": candidate.video_timestamp_ms,
            "videoFrameIndex": candidate.video_frame_index,
            "videoDurationMs": candidate.video_duration_ms,
            "sourceHash": candidate.source_hash,
            "createdAt": candidate.created_at,
            "captureDate": candidate.capture_date,
            "referenceCaptureDate": candidate.reference_capture_date,
            "ageGapYears": candidate.age_gap_years,
            "ageGapConfidence": candidate.age_gap_confidence,
            "captureDateProvenance": candidate.capture_date_provenance,
            "referenceCaptureDateProvenance": candidate.reference_capture_date_provenance,
        }

    def _candidate_risk_flags(self, candidate: Any) -> list[str]:
        return normalize_risk_flags(getattr(candidate, "risk_flags", []), getattr(candidate, "note", ""))

    # --- Photos tab: browse photos as folders -------------------------------
    # "All Photos" is backed by the canonical photo_assets library index. Each
    # person folder = that person's accepted-or-high-confidence matches. "Unknown
    # Person N" folders = the unmatched clusters already produced at scan time.
    # All read-only; previews are generated lazily under a per-call budget,
    # exactly like query_candidates.

    def _photo_person_presence_match(
        self,
        person_name: str,
        *,
        status: str = "",
        score: float = 0.0,
        band: str = "",
    ) -> bool:
        if person_name.startswith("Unmatched cluster"):
            return False
        status_key = str(status or "").lower()
        if status_key == "accepted":
            return True
        if status_key == "rejected":
            return False
        if str(band or "").strip().lower() == "manual assignment":
            return True
        return float(score or 0.0) >= float(self.project.config.thresholds.confident)

    def _photo_person_match(self, candidate: Any) -> bool:
        """A photo belongs in a named person's folder when the match is accepted
        OR high-confidence (score >= the confident threshold), matching the
        query_candidates `high` lane. Manual reassignment from Photos also
        counts because the user intentionally moved that face. Unmatched
        clusters never qualify here."""
        return self._photo_person_presence_match(
            str(candidate.person_name or ""),
            status=str(candidate.status or ""),
            score=float(getattr(candidate, "score", 0.0) or 0.0),
            band=str(getattr(candidate, "band", "") or ""),
        )

    def _photo_album_memberships_for_asset(
        self,
        asset_id: str,
        source_path: str,
        smart_album_source_cache: dict[str, set[str]] | None = None,
    ) -> list[dict[str, Any]]:
        memberships = self.project.db.list_photo_asset_album_memberships(asset_id) if asset_id else []
        seen_ids = {str(item.get("albumId", "") or "") for item in memberships}
        source = str(source_path or "")
        if not source:
            return memberships
        for album in self.project.db.list_photo_albums():
            album_id = str(album.get("albumId", "") or "")
            if not album_id or album_id in seen_ids:
                continue
            if str(album.get("albumKind", "smart") or "smart") == "manual":
                continue
            try:
                matched: bool | None = self._photo_smart_album_contains_asset(album, asset_id)
                if matched is None and smart_album_source_cache is not None:
                    if album_id not in smart_album_source_cache:
                        smart_album_source_cache[album_id] = {
                            str(item.get("sourcePath", "") or "")
                            for item in self._photo_album_items(album)
                            if str(item.get("sourcePath", "") or "")
                        }
                    matched = source in smart_album_source_cache.get(album_id, set())
                elif matched is None:
                    matched = any(str(item.get("sourcePath", "") or "") == source for item in self._photo_album_items(album))
            except Exception:
                matched = False
            if not matched:
                continue
            memberships.append(
                {
                    "albumId": album_id,
                    "name": str(album.get("name", "") or "Untitled album"),
                    "albumKind": "smart",
                    "position": -1,
                    "addedAt": "",
                    "derived": True,
                }
            )
            seen_ids.add(album_id)
        return memberships

    def _photo_smart_album_contains_asset(self, album: dict[str, Any], asset_id: str) -> bool | None:
        clean_asset_id = str(asset_id or "").strip()
        if not clean_asset_id:
            return None
        criteria = self._photo_smart_album_sql_criteria(album)
        if criteria is None:
            return None
        required_asset_ids = {
            str(value or "").strip()
            for value in criteria.get("requiredAssetIds", ())
            if str(value or "").strip()
        }
        if required_asset_ids and clean_asset_id not in required_asset_ids:
            return False
        excluded_asset_ids = {
            str(value or "").strip()
            for value in criteria.get("excludedAssetIds", ())
            if str(value or "").strip()
        }
        if clean_asset_id in excluded_asset_ids:
            return False
        scoped_criteria = {**criteria, "requiredAssetIds": (clean_asset_id,)}
        result = self._photo_smart_album_sql_page_for_criteria(
            scoped_criteria,
            offset=0,
            limit=1,
            sort="newest",
        )
        return int(result.get("total", 0) or 0) > 0

    def _photo_raw_preview_proxy_path(
        self,
        source_path: str,
        media_pairs: list[dict[str, Any]] | None = None,
    ) -> str:
        source_text = str(source_path or "").strip()
        if not source_text:
            return ""
        source = Path(source_text).expanduser()
        try:
            resolved = source.resolve()
        except OSError:
            resolved = source
        if resolved.suffix.lower() not in RAW_IMAGE_EXTENSIONS:
            return ""
        renderable_suffixes = sorted(set(IMAGE_EXTENSIONS) - set(RAW_IMAGE_EXTENSIONS))
        candidates: list[Path] = []
        seen: set[str] = set()

        def add_candidate(value: str | Path) -> None:
            text = str(value or "").strip()
            if not text:
                return
            candidate = Path(text).expanduser()
            try:
                candidate = candidate.resolve()
            except OSError:
                pass
            key = str(candidate)
            if key in seen or key == str(resolved):
                return
            seen.add(key)
            candidates.append(candidate)

        for pair in media_pairs or []:
            if str(pair.get("pairKind", "") or "") != "raw_sidecar":
                continue
            pair_source = str(pair.get("sourcePath", "") or "").strip()
            pair_related = str(pair.get("relatedSourcePath", "") or "").strip()
            if pair_related:
                try:
                    related = Path(pair_related).expanduser().resolve()
                except OSError:
                    related = Path(pair_related).expanduser()
                if str(related) == str(resolved):
                    add_candidate(pair_source)

        for suffix in renderable_suffixes:
            add_candidate(resolved.with_suffix(suffix))
            add_candidate(resolved.with_suffix(suffix.upper()))
        for candidate in candidates:
            try:
                if not candidate.is_file():
                    continue
            except OSError:
                continue
            if candidate.suffix.lower() in RAW_IMAGE_EXTENSIONS:
                continue
            if candidate.suffix.lower() not in IMAGE_EXTENSIONS:
                continue
            return str(candidate)
        return ""

    def _photo_preview_path_for_item(
        self,
        *,
        source_path: str,
        media_kind: str,
        media_pairs: list[dict[str, Any]] | None = None,
        create: bool = False,
    ) -> tuple[str, str, str]:
        preview_path = self.project.preview_path_for(source_path, create=False) or ""
        if preview_path or not create:
            return preview_path, "", ""
        preview_path = self.project.preview_path_for(source_path, create=True) or ""
        if preview_path:
            return preview_path, "", ""
        source = Path(str(source_path or "")).expanduser()
        suffix = source.suffix.lower()
        if str(media_kind or "").lower() == "raw" or suffix in RAW_IMAGE_EXTENSIONS:
            proxy_path = self._photo_raw_preview_proxy_path(source_path, media_pairs)
            if proxy_path:
                proxy_preview = self.project.preview_path_for_proxy(source_path, proxy_path, create=True) or ""
                if proxy_preview:
                    return proxy_preview, proxy_path, ""
            return "", proxy_path, "RAW preview could not be generated. Add or import a same-name JPEG/HEIC/TIFF proxy, or install RAW decoding support."
        return "", "", ""

    def _photo_item_row(
        self,
        *,
        source_path: str,
        media_kind: str,
        preview_create: bool,
        candidate: Any | None = None,
        matches: list[ReviewCandidate] | None = None,
        scan_date: str = "",
        album_membership_cache: dict[str, set[str]] | None = None,
        media_pair_cache: dict[str, list[dict[str, Any]]] | None = None,
        edit_stack_version_count_cache: dict[str, int] | None = None,
    ) -> dict[str, Any]:
        match_rows = self._dedupe_photo_matches(matches or ([candidate] if candidate is not None else []))
        primary = candidate or (match_rows[0] if match_rows else None)
        asset = self.project.db.photo_asset_by_path(source_path)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata"), dict) else {}
        video_poster = asset_metadata.get("videoPoster") if isinstance(asset_metadata.get("videoPoster"), dict) else {}
        poster_preview_path = str(video_poster.get("previewPath", "") or "") if isinstance(video_poster, dict) else ""
        live_photo_metadata = asset_metadata.get("livePhoto") if isinstance(asset_metadata.get("livePhoto"), dict) else {}
        live_key_preview_path = str(live_photo_metadata.get("keyPhotoPreviewPath", "") or "") if isinstance(live_photo_metadata, dict) else ""
        asset_id = str(asset["assetId"]) if asset else ""
        edit_stack = self.project.db.photo_edit_stack_by_asset(asset_id=asset_id) if asset_id else None
        edit_stack_version_count = 0
        if asset_id:
            if edit_stack_version_count_cache is not None:
                edit_stack_version_count = int(edit_stack_version_count_cache.get(asset_id, 0) or 0)
            else:
                edit_stack_version_count = int(self.project.db.photo_edit_stack_version_counts_for_assets([asset_id]).get(asset_id, 0) or 0)
        media_pairs: list[dict[str, Any]] = []
        if asset_id:
            if media_pair_cache is not None:
                if asset_id not in media_pair_cache:
                    media_pair_cache[asset_id] = self.project.db.photo_media_pairs_for_asset(asset_id)
                media_pairs = media_pair_cache.get(asset_id, [])
            else:
                media_pairs = self.project.db.photo_media_pairs_for_asset(asset_id)
        preview_path, raw_preview_proxy_path, preview_error = self._photo_preview_path_for_item(
            source_path=source_path,
            media_kind=media_kind,
            media_pairs=media_pairs,
            create=preview_create,
        )
        if preview_create and not preview_path and not preview_error:
            try:
                source = Path(source_path).expanduser()
                if source.exists() and source.is_file():
                    suffix = source.suffix.lower()
                    if suffix in IMAGE_EXTENSIONS:
                        preview_error = "Preview could not be generated for this image."
                    elif suffix in VIDEO_EXTENSIONS:
                        preview_error = "Preview could not be generated for this video."
            except OSError:
                preview_error = "Preview could not inspect this media file."
        if live_key_preview_path:
            try:
                live_key_preview = Path(live_key_preview_path).expanduser()
                if live_key_preview.exists() and live_key_preview.is_file():
                    preview_path = str(live_key_preview)
            except OSError:
                pass
        if poster_preview_path:
            try:
                poster_preview = Path(poster_preview_path).expanduser()
                if poster_preview.exists() and poster_preview.is_file():
                    preview_path = str(poster_preview)
            except OSError:
                pass
        rendered_edit_preview_path = str(edit_stack.get("renderedPreviewPath", "") or "") if edit_stack else ""
        if rendered_edit_preview_path:
            try:
                rendered_edit_preview = Path(rendered_edit_preview_path).expanduser()
                if rendered_edit_preview.exists() and rendered_edit_preview.is_file():
                    preview_path = str(rendered_edit_preview)
            except OSError:
                pass
        metadata = self.project.db.photo_asset_metadata_by_id(str(asset["assetId"])) if asset else {}
        date_override = str(metadata.get("dateOverride", "") or "") if metadata else ""
        asset_capture_date = str(asset.get("captureDate", "") or "") if asset else ""
        capture_date = date_override or (primary.capture_date if primary is not None else asset_capture_date or None)
        asset_people_rows = self.project.db.list_photo_asset_people(asset_id) if asset_id else []
        match_candidate_ids = {match.candidate_id for match in match_rows}
        people_rows = [
            {
                "candidateId": match.candidate_id,
                "personName": match.person_name,
                "status": match.status,
                    "score": round(float(match.score), 6),
                    "quality": round(float(match.quality), 6),
                    "band": match.band,
                    "assetOnly": False,
                    "mediaKind": match.media_kind or media_kind,
                    "captureDate": match.capture_date,
                    "createdAt": match.created_at,
                }
            for match in match_rows
        ]
        for person in asset_people_rows:
            candidate_id = str(person.get("candidateId", "") or "")
            if candidate_id and candidate_id in match_candidate_ids:
                continue
            people_rows.append(
                {
                    "candidateId": candidate_id,
                    "personName": str(person.get("personName", "") or ""),
                    "status": str(person.get("status", "pending") or "pending"),
                    "score": round(float(person.get("score", 0.0) or 0.0), 6),
                    "quality": round(float(person.get("quality", 0.0) or 0.0), 6),
                    "band": str(person.get("band", "") or ""),
                    "assetOnly": bool(person.get("assetOnly", False)),
                    "mediaKind": media_kind,
                    "captureDate": "",
                    "createdAt": "",
                }
            )
        score_values = [float(match.score) for match in match_rows] + [float(person.get("score", 0.0) or 0.0) for person in asset_people_rows]
        quality_values = [float(match.quality) for match in match_rows] + [float(person.get("quality", 0.0) or 0.0) for person in asset_people_rows]
        return {
            "id": source_path or (primary.candidate_id if primary is not None else ""),
            "assetId": asset_id,
            "sourcePath": source_path,
            "previewPath": preview_path,
            "rawPreviewProxyPath": raw_preview_proxy_path,
            "previewError": preview_error,
            "personName": primary.person_name if primary is not None else None,
            "mediaKind": media_kind,
            "sourceKind": str(asset.get("sourceKind", "") or "") if asset else "",
            "fileSignature": asset.get("fileSignature", {}) if asset else {},
            "contentHash": str(asset.get("contentHash", "") or "") if asset else "",
            "perceptualHash": str(asset.get("perceptualHash", "") or "") if asset else "",
            "mimeType": str(asset.get("mimeType", "") or "") if asset else "",
            "width": asset.get("width") if asset else None,
            "height": asset.get("height") if asset else None,
            "durationMs": asset.get("durationMs") if asset else None,
            "captureDate": capture_date,
            "originalCaptureDate": primary.capture_date if primary is not None else asset_capture_date or None,
            "title": str(metadata.get("title", "") or "") if metadata else "",
            "caption": str(metadata.get("caption", "") or "") if metadata else "",
            "keywords": metadata.get("keywords", []) if metadata else [],
            "favorite": bool(metadata.get("favorite", False)) if metadata else False,
            "hidden": bool(metadata.get("hidden", False)) if metadata else False,
            "deletedAt": str(metadata.get("deletedAt", "") or "") if metadata else "",
            "dateOverride": date_override,
            "locationOverride": metadata.get("locationOverride", {}) if metadata else {},
            "locationHidden": bool(metadata.get("locationHidden", False)) if metadata else False,
            "edited": (bool(metadata.get("edited", False)) if metadata else False) or bool(edit_stack),
            "hasEditStack": bool(edit_stack),
            "editStackVersionCount": edit_stack_version_count,
            "hasEditStackVersions": edit_stack_version_count > 0,
            "scanDate": scan_date,
            "addedAt": str(asset.get("addedAt", "") or "") if asset else "",
            "updatedAt": str(asset.get("updatedAt", "") or "") if asset else "",
            "missingAt": str(asset.get("missingAt", "") or "") if asset else "",
            "sourceScanRun": str(asset.get("sourceScanRun", "") or "") if asset else "",
            "assetMetadata": asset_metadata,
            "importSourceKind": str(asset_metadata.get("importSourceKind", "") or ""),
            "importSourceLabel": str(asset_metadata.get("importSourceLabel", "") or ""),
            "importSourceDetail": str(asset_metadata.get("importSourceDetail", "") or ""),
            "importedAt": str(asset_metadata.get("importedAt", "") or ""),
            "albumMemberships": self._photo_album_memberships_for_asset(asset_id, source_path, album_membership_cache) if source_path else [],
            "duplicateGroup": self.project.db.photo_duplicate_group_for_asset(asset_id) if asset_id else None,
            "mediaPairs": media_pairs,
            "createdAt": primary.created_at if primary is not None else ((scan_date or str(asset.get("addedAt", "") or "")) if asset else scan_date),
            "status": primary.status if primary is not None else None,
            "score": round(float(primary.score), 6) if primary is not None else None,
            "quality": round(float(primary.quality), 6) if primary is not None else None,
            "candidateIds": [person["candidateId"] for person in people_rows if person["candidateId"] and not person.get("assetOnly")],
            "personCount": len({str(person["personName"]).casefold() for person in people_rows if person["personName"]}),
            "bestScore": round(max(score_values, default=0.0), 6),
            "bestQuality": round(max(quality_values, default=0.0), 6),
            "people": people_rows,
        }

    def _dedupe_photo_matches(self, matches: list[ReviewCandidate]) -> list[ReviewCandidate]:
        seen: set[str] = set()
        rows: list[ReviewCandidate] = []
        for match in sorted(
            matches,
            key=lambda item: (float(item.score), float(item.quality), item.created_at, item.candidate_id),
            reverse=True,
        ):
            if match.candidate_id in seen:
                continue
            seen.add(match.candidate_id)
            rows.append(match)
        return rows

    def _photo_tile_source(self, candidate: ReviewCandidate) -> str:
        if candidate.media_kind == "video" and candidate.media_source_path:
            return str(candidate.media_source_path)
        return str(candidate.source_path or "")

    def _photo_source_keys(self, candidate: ReviewCandidate) -> set[str]:
        keys = {str(candidate.source_path or ""), self._photo_tile_source(candidate)}
        media_source = str(candidate.media_source_path or "")
        if media_source:
            keys.add(media_source)
        return {key for key in keys if key}

    def _review_candidate_from_payload(self, payload: dict[str, Any]) -> ReviewCandidate | None:
        candidate_id = str(payload.get("candidate_id", payload.get("candidateId", "")) or "")
        source_path = str(payload.get("source_path", payload.get("sourcePath", "")) or "")
        person_name = str(payload.get("person_name", payload.get("personName", "")) or "")
        if not candidate_id or not source_path:
            return None

        def number(value: Any, fallback: float = 0.0) -> float:
            try:
                return float(value)
            except (TypeError, ValueError):
                return fallback

        def optional_int(value: Any) -> int | None:
            if value in (None, ""):
                return None
            try:
                return int(value)
            except (TypeError, ValueError):
                return None

        return ReviewCandidate(
            candidate_id=candidate_id,
            source_path=source_path,
            person_name=person_name,
            best_ref_id=payload.get("best_ref_id", payload.get("bestRefId")),
            best_ref_path=payload.get("best_ref_path", payload.get("bestRefPath")),
            score=number(payload.get("score"), 0.0),
            band=str(payload.get("band", "") or ""),
            quality=number(payload.get("quality"), 0.0),
            model_name=str(payload.get("model_name", payload.get("modelName", "")) or ""),
            status=str(payload.get("status", "pending") or "pending"),
            note=str(payload.get("note", "") or ""),
            risk_flags=normalize_risk_flags(payload.get("risk_flags", payload.get("riskFlags", [])), str(payload.get("note", "") or "")),
            media_kind=str(payload.get("media_kind", payload.get("mediaKind", "image")) or "image"),
            media_source_path=str(payload.get("media_source_path", payload.get("mediaSourcePath", "")) or ""),
            video_timestamp_ms=optional_int(payload.get("video_timestamp_ms", payload.get("videoTimestampMs"))),
            video_frame_index=optional_int(payload.get("video_frame_index", payload.get("videoFrameIndex"))),
            video_duration_ms=optional_int(payload.get("video_duration_ms", payload.get("videoDurationMs"))),
            source_hash=str(payload.get("source_hash", payload.get("sourceHash", "")) or ""),
            pose_bucket=str(payload.get("pose_bucket", payload.get("poseBucket", "unknown")) or "unknown"),
            created_at=str(payload.get("created_at", payload.get("createdAt", "")) or ""),
            capture_date=payload.get("capture_date", payload.get("captureDate")),
            reference_capture_date=payload.get("reference_capture_date", payload.get("referenceCaptureDate")),
            age_gap_years=payload.get("age_gap_years", payload.get("ageGapYears")),
            age_gap_confidence=payload.get("age_gap_confidence", payload.get("ageGapConfidence")),
            capture_date_provenance=payload.get("capture_date_provenance", payload.get("captureDateProvenance")),
            reference_capture_date_provenance=payload.get("reference_capture_date_provenance", payload.get("referenceCaptureDateProvenance")),
            raw_cosine=payload.get("raw_cosine", payload.get("rawCosine")),
            align_error=number(payload.get("align_error", payload.get("alignError")), 0.0),
            ied_px=number(payload.get("ied_px", payload.get("iedPx")), 0.0),
            review_priority=number(payload.get("review_priority", payload.get("reviewPriority")), 0.0),
            review_lane=str(payload.get("review_lane", payload.get("reviewLane", "")) or ""),
        )

    def _refresh_project_candidates_from_db(self) -> int:
        loaded: dict[str, ReviewCandidate] = {}
        for payload in self.project.db.iter_candidate_payloads():
            candidate = self._review_candidate_from_payload(payload)
            if candidate is not None:
                loaded[candidate.candidate_id] = candidate
        self.project.candidates = loaded
        return len(loaded)

    def _photo_matches_by_source(self) -> dict[str, list[ReviewCandidate]]:
        matches_by_source: dict[str, list[ReviewCandidate]] = {}
        seen_candidate_ids: set[str] = set()
        candidates: list[ReviewCandidate] = list(self.project.candidates.values())
        try:
            for payload in self.project.db.iter_candidate_payloads():
                candidate = self._review_candidate_from_payload(payload)
                if candidate is not None:
                    candidates.append(candidate)
        except Exception:
            pass
        for candidate in candidates:
            if candidate.candidate_id in seen_candidate_ids:
                continue
            seen_candidate_ids.add(candidate.candidate_id)
            for key in self._photo_source_keys(candidate):
                matches_by_source.setdefault(key, []).append(candidate)
        return {
            key: self._dedupe_photo_matches(matches)
            for key, matches in matches_by_source.items()
        }

    def _photo_matches_by_source_for_source_paths(self, source_paths: Iterable[str]) -> dict[str, list[ReviewCandidate]]:
        wanted_sources = {str(source_path or "").strip() for source_path in source_paths if str(source_path or "").strip()}
        if not wanted_sources:
            return {}
        matches_by_source: dict[str, list[ReviewCandidate]] = {}
        seen_candidate_ids: set[str] = set()

        def add_candidate(candidate: ReviewCandidate | None) -> None:
            if candidate is None or candidate.candidate_id in seen_candidate_ids:
                return
            keys = [key for key in self._photo_source_keys(candidate) if key in wanted_sources]
            if not keys:
                return
            seen_candidate_ids.add(candidate.candidate_id)
            for key in keys:
                matches_by_source.setdefault(key, []).append(candidate)

        for candidate in self.project.candidates.values():
            add_candidate(candidate)
        try:
            for payload in self.project.db.iter_candidate_payloads_for_source_paths(wanted_sources):
                add_candidate(self._review_candidate_from_payload(payload))
        except Exception:
            for candidate in self.project.candidates.values():
                add_candidate(candidate)

        return {
            key: self._dedupe_photo_matches(matches)
            for key, matches in matches_by_source.items()
        }

    def _media_kind_for_source(self, source_path: str, fallback: str = "image") -> str:
        normalized = re.sub(r"[\s._-]+", " ", Path(str(source_path or "")).name.lower()).strip()
        compact = normalized.replace(" ", "")
        suffix = Path(str(source_path or "")).suffix.lower()
        visual_hint = ""
        if "screen recording" in normalized or "screenrecording" in compact:
            visual_hint = "screen_recording"
        elif "screen shot" in normalized or "screenshot" in compact:
            visual_hint = "screenshot"
        elif "time lapse" in normalized or "timelapse" in compact:
            visual_hint = "time_lapse"
        elif "live photo" in normalized or "livephoto" in compact:
            visual_hint = "live_photo"
        elif "panorama" in normalized or "pano" in compact:
            visual_hint = "panorama"
        elif "portrait" in normalized:
            visual_hint = "portrait"
        elif "burst" in normalized or "burst" in compact:
            visual_hint = "burst"
        if suffix in VIDEO_EXTENSIONS:
            if visual_hint == "screen_recording":
                return "screen_recording"
            if visual_hint == "time_lapse":
                return "time_lapse"
            return "video"
        if suffix in IMAGE_EXTENSIONS and visual_hint in {"screenshot", "panorama", "portrait", "burst", "live_photo"}:
            return visual_hint
        value = str(fallback or "image").strip().lower()
        return value if value in PHOTO_MEDIA_KINDS else "image"

    def _photo_burst_asset_info(self, asset: dict[str, Any]) -> dict[str, Any] | None:
        source_path = str(asset.get("sourcePath", "") or "").strip()
        if not source_path:
            return None
        media_kind = str(asset.get("mediaKind", "") or "").strip().lower()
        metadata = asset.get("metadata") if isinstance(asset.get("metadata"), dict) else {}
        burst = metadata.get("burst") if isinstance(metadata.get("burst"), dict) else {}
        native_burst = self.project.db.photo_metadata_burst_info(metadata)
        explicit_group = ""
        for key in ("stackId", "groupId", "burstId", "identifier", "burstIdentifier"):
            explicit_group = str(burst.get(key, metadata.get(key, "")) or "").strip()
            if explicit_group:
                break
        if not explicit_group:
            explicit_group = str(native_burst.get("groupId", "") or "").strip()

        def sequence_from(value: Any) -> int:
            try:
                number = int(str(value or "").strip())
            except (TypeError, ValueError):
                return 0
            return number if number >= 0 else 0

        explicit_sequence = 0
        for key in ("sequence", "burstSequence", "index", "frameIndex"):
            explicit_sequence = sequence_from(burst.get(key, metadata.get(key, "")))
            if explicit_sequence:
                break
        if not explicit_sequence:
            explicit_sequence = sequence_from(native_burst.get("sequence", ""))
        if explicit_group:
            filename_cover_hint = "cover" in Path(source_path).stem.casefold()
            group_key = f"metadata:{explicit_group.casefold()}"
            stack_id = explicit_group if explicit_group.startswith("burst_") else f"burst_{hashlib.sha256(group_key.encode('utf-8')).hexdigest()[:16]}"
            label = str(burst.get("label", burst.get("name", native_burst.get("label", ""))) or "").strip() or "Burst"
            selection_role = str(burst.get("selectionRole", native_burst.get("selectionRole", "")) or "").strip().lower()
            keeper_hint = bool(burst.get("isKeeper", False) or selection_role == "keeper" or native_burst.get("keeperHint", False))
            return {
                "asset": asset,
                "groupKey": group_key,
                "stackId": stack_id,
                "label": label,
                "sequence": explicit_sequence,
                "coverHint": bool(
                    burst.get("cover", False)
                    or burst.get("isCover", False)
                    or filename_cover_hint
                    or native_burst.get("coverHint", False)
                ),
                "selectionRole": selection_role,
                "keeperHint": keeper_hint,
            }

        stem = Path(source_path).stem
        normalized = re.sub(r"[\s._-]+", " ", stem).strip()
        compact = normalized.replace(" ", "").casefold()
        if media_kind != "burst" and "burst" not in compact:
            return None
        match = re.search(
            r"^(?P<prefix>.*?)[\s._-]*burst(?:[\s._-]*(?:shot|mode))?[\s._-]*(?P<number>\d+)?(?P<rest>.*)$",
            stem,
            flags=re.IGNORECASE,
        )
        if match:
            prefix = re.sub(r"[\s._-]+", " ", str(match.group("prefix") or "")).strip()
            number_text = str(match.group("number") or "")
            if not number_text:
                rest_number = re.search(r"\d+", str(match.group("rest") or ""))
                number_text = rest_number.group(0) if rest_number else ""
            sequence = sequence_from(number_text)
            label = prefix or "Burst"
            cover_hint = "cover" in str(match.group("rest") or "").casefold()
        else:
            label = re.sub(r"[\s._-]+(?:\d{1,5}|cover|selected|select)$", "", stem, flags=re.IGNORECASE).strip()
            label = re.sub(r"[\s._-]+", " ", label).strip() or stem or "Burst"
            trailing = re.search(r"(\d{1,5})(?:\D*)$", stem)
            sequence = sequence_from(trailing.group(1) if trailing else "")
            cover_hint = "cover" in stem.casefold()
        label_key = re.sub(r"[^a-z0-9]+", "-", label.casefold()).strip("-") or "burst"
        parent_key = str(Path(source_path).parent)
        group_key = f"filename:{parent_key}:{label_key}"
        stack_id = f"burst_{hashlib.sha256(group_key.encode('utf-8')).hexdigest()[:16]}"
        return {
            "asset": asset,
            "groupKey": group_key,
            "stackId": stack_id,
            "label": label,
            "sequence": sequence,
            "coverHint": cover_hint,
        }

    def _photo_burst_entry_info(self, entry: dict[str, Any]) -> dict[str, Any] | None:
        asset = self._photo_entry_asset(entry)
        if not asset:
            source_path = str(entry.get("sourcePath", "") or "").strip()
            asset = self.project.db.photo_asset_by_path(source_path) if source_path else None
        return self._photo_burst_asset_info(asset or {})

    def _photo_burst_stack_from_infos(self, infos: list[dict[str, Any]], include_items: bool) -> dict[str, Any]:
        ordered = sorted(
            infos,
            key=lambda info: (
                int(info.get("sequence", 0) or 0) or 2_147_483_647,
                str(info["asset"].get("sourcePath", "") or "").casefold(),
            ),
        )
        items: list[dict[str, Any]] = []
        for position, info in enumerate(ordered):
            asset = info["asset"]
            metadata = asset.get("metadata") if isinstance(asset.get("metadata"), dict) else {}
            burst = metadata.get("burst") if isinstance(metadata.get("burst"), dict) else {}
            role = str(burst.get("selectionRole", info.get("selectionRole", "")) or "").strip().lower()
            is_keeper = bool(burst.get("isKeeper", False) or info.get("keeperHint", False)) or role == "keeper"
            items.append({
                "assetId": str(asset.get("assetId", "") or ""),
                "sourcePath": str(asset.get("sourcePath", "") or ""),
                "mediaKind": str(asset.get("mediaKind", "") or ""),
                "title": str(metadata.get("title", "") or Path(str(asset.get("sourcePath", "") or "")).name),
                "captureDate": str(asset.get("captureDate", "") or ""),
                "sequence": int(info.get("sequence", 0) or 0) or position + 1,
                "keeper": is_keeper,
                "selectionRole": role or ("keeper" if is_keeper else ""),
                "selectedAt": str(burst.get("selectedAt", "") or ""),
                "coverHint": bool(info.get("coverHint", False)),
            })
        cover_item = next((item for item in items if item["keeper"]), None)
        if cover_item is None:
            cover_item = next((item for item in items if item.get("coverHint")), None)
        if cover_item is None and items:
            cover_item = items[0]
        stack = {
            "stackId": str(ordered[0].get("stackId", "")) if ordered else "",
            "name": str(ordered[0].get("label", "") or "Burst") if ordered else "Burst",
            "count": len(items),
            "keeperCount": sum(1 for item in items if item["keeper"]),
            "coverSourcePath": str(cover_item.get("sourcePath", "") or "") if cover_item else "",
            "sourcePaths": [str(item["sourcePath"]) for item in items],
        }
        if include_items:
            stack["items"] = items
        return stack

    def list_photo_burst_stacks(self, params: dict[str, Any] | None = None) -> dict[str, Any]:
        body = params if isinstance(params, dict) else {}
        include_items = bool(body.get("includeItems", body.get("items", False)))
        include_singles = bool(body.get("includeSingles", False))
        visibility = self._normalize_photo_visibility_filter(
            body.get("visibility", body.get("visibilityState", "")),
            hidden_only=bool(body.get("hiddenOnly", False)),
            deleted_only=bool(body.get("deletedOnly", False)),
        ) or "visible"
        asset_count = max(0, int(self.project.db.count_photo_assets()))
        if not asset_count:
            return {"total": 0, "stacks": []}
        result = self.project.db.list_photo_asset_page(
            offset=0,
            limit=max(1, asset_count),
            visibility=visibility,
            sort="filename",
        )
        groups: dict[str, list[dict[str, Any]]] = {}
        for asset in result.get("assets", []):
            if not isinstance(asset, dict):
                continue
            info = self._photo_burst_asset_info(asset)
            if info is None:
                continue
            groups.setdefault(str(info["groupKey"]), []).append(info)
        stacks = [
            self._photo_burst_stack_from_infos(infos, include_items)
            for infos in groups.values()
            if include_singles or len(infos) > 1
        ]
        stacks.sort(key=lambda stack: (-int(stack.get("count", 0) or 0), str(stack.get("name", "") or "").casefold()))
        return {"total": len(stacks), "stacks": stacks}

    def set_photo_burst_selection(self, params: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(params, dict):
            raise ValueError("Burst selection parameters must be an object.")
        stack_id = str(params.get("stackId", "") or "").strip()
        clear = bool(params.get("clear", False))
        raw_keep_paths = params.get("keepSourcePaths", params.get("sourcePaths", []))
        if isinstance(raw_keep_paths, str):
            keep_paths = [raw_keep_paths]
        elif isinstance(raw_keep_paths, list):
            keep_paths = [str(path or "").strip() for path in raw_keep_paths if str(path or "").strip()]
        else:
            keep_paths = []
        single_source = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        if single_source and single_source not in keep_paths and not clear:
            keep_paths.append(single_source)
        if not stack_id and single_source:
            stacks_for_source = self.list_photo_burst_stacks({"includeItems": True, "includeSingles": True, "visibility": "all"})["stacks"]
            for stack in stacks_for_source:
                if single_source in set(stack.get("sourcePaths", [])):
                    stack_id = str(stack.get("stackId", "") or "")
                    break
        if not stack_id:
            raise ValueError("A burst stackId or sourcePath is required.")
        if not clear and not keep_paths:
            raise ValueError("At least one keepSourcePaths item is required.")
        stacks = self.list_photo_burst_stacks({"includeItems": True, "includeSingles": True, "visibility": "all"})["stacks"]
        stack = next((item for item in stacks if str(item.get("stackId", "") or "") == stack_id), None)
        if stack is None:
            raise ValueError("Unknown burst stack id.")
        stack_paths = {str(path or "") for path in stack.get("sourcePaths", []) if str(path or "")}
        keep_set = {str(path or "").strip() for path in keep_paths if str(path or "").strip()}
        unknown = sorted(path for path in keep_set if path not in stack_paths)
        if unknown:
            raise ValueError("keepSourcePaths must belong to the selected burst stack.")
        selected_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        updated_assets: list[dict[str, Any]] = []
        with self.project.db.connect() as conn:
            for item in stack.get("items", []):
                source_path = str(item.get("sourcePath", "") or "")
                asset = self.project.db.photo_asset_by_path(source_path, conn) if source_path else None
                if not asset:
                    continue
                metadata = asset.get("metadata") if isinstance(asset.get("metadata"), dict) else {}
                current_burst = metadata.get("burst") if isinstance(metadata.get("burst"), dict) else {}
                next_burst = {
                    **current_burst,
                    "stackId": stack_id,
                    "groupId": stack_id,
                    "label": str(stack.get("name", "") or "Burst"),
                    "sequence": int(item.get("sequence", 0) or 0),
                    "source": "local_burst_selection",
                }
                if clear:
                    for key in ("isKeeper", "selectionRole", "selectedAt", "selectedBy"):
                        next_burst.pop(key, None)
                else:
                    is_keeper = source_path in keep_set
                    next_burst.update({
                        "isKeeper": is_keeper,
                        "selectionRole": "keeper" if is_keeper else "alternate",
                        "selectedAt": selected_at,
                        "selectedBy": self.actor,
                    })
                updated_assets.append(
                    self.project.db.update_photo_asset_metadata_json(
                        asset_id=str(asset.get("assetId", "") or ""),
                        patch={"burst": next_burst},
                        conn=conn,
                    )
                )
        refreshed = self.list_photo_burst_stacks({"includeItems": True, "includeSingles": True, "visibility": "all"})
        updated_stack = next((item for item in refreshed["stacks"] if str(item.get("stackId", "") or "") == stack_id), None)
        self.project._append_audit({
            "action": "set_photo_burst_selection",
            "stack_id": stack_id,
            "selected_count": 0 if clear else len(keep_set),
            "stack_count": len(stack_paths),
            "cleared": clear,
        })
        return {
            "stackId": stack_id,
            "cleared": clear,
            "selectedCount": 0 if clear else len(keep_set),
            "updated": len(updated_assets),
            "stack": updated_stack,
        }

    def _photo_source_entry(
        self,
        *,
        source_path: str,
        media_kind: str,
        matches_by_source: dict[str, list[ReviewCandidate]],
        candidate: ReviewCandidate | None = None,
        scan_date: str = "",
    ) -> dict[str, Any]:
        matches = self._dedupe_photo_matches(matches_by_source.get(source_path, []) + ([candidate] if candidate else []))
        return {
            "sourcePath": source_path,
            "mediaKind": media_kind or self._media_kind_for_source(source_path),
            "candidate": candidate or (matches[0] if matches else None),
            "matches": matches,
            "scanDate": scan_date,
        }

    def _metadata_for_photo_source(self, source_path: str) -> dict[str, Any]:
        asset = self.project.db.photo_asset_by_path(str(source_path or ""))
        return self.project.db.photo_asset_metadata_by_id(str(asset["assetId"])) if asset else {}

    def _photo_entry_metadata(self, entry: dict[str, Any]) -> dict[str, Any]:
        cached = entry.get("_metadata")
        if isinstance(cached, dict):
            return cached
        return self._metadata_for_photo_source(str(entry.get("sourcePath", "") or ""))

    def _photo_entry_deleted(self, entry: dict[str, Any]) -> bool:
        return bool(str(self._photo_entry_metadata(entry).get("deletedAt", "") or ""))

    def _photo_entry_hidden(self, entry: dict[str, Any]) -> bool:
        return bool(self._photo_entry_metadata(entry).get("hidden", False))

    def _photo_entry_default_visible(self, entry: dict[str, Any]) -> bool:
        return not self._photo_entry_hidden(entry) and not self._photo_entry_deleted(entry)

    def _all_photo_entries(self, matches_by_source: dict[str, list[ReviewCandidate]] | None = None) -> list[dict[str, Any]]:
        return self._photo_asset_entries("", matches_by_source=matches_by_source)

    def _photo_entries_for_asset_ids(
        self,
        asset_ids: Iterable[str],
        *,
        matches_by_source: dict[str, list[ReviewCandidate]] | None = None,
    ) -> list[dict[str, Any]]:
        ordered_ids = [str(asset_id or "").strip() for asset_id in asset_ids if str(asset_id or "").strip()]
        if not ordered_ids:
            return []
        assets = self.project.db.photo_assets_by_ids(ordered_ids)
        return self._photo_entries_for_assets(assets, matches_by_source=matches_by_source)

    def _photo_entries_for_source_paths(
        self,
        source_paths: Iterable[str],
        *,
        matches_by_source: dict[str, list[ReviewCandidate]] | None = None,
    ) -> list[dict[str, Any]]:
        assets = self.project.db.photo_assets_by_paths(source_paths)
        return self._photo_entries_for_assets(assets, matches_by_source=matches_by_source)

    def _photo_entries_for_assets(
        self,
        assets: Iterable[dict[str, Any]],
        *,
        matches_by_source: dict[str, list[ReviewCandidate]] | None = None,
    ) -> list[dict[str, Any]]:
        asset_rows = [asset for asset in assets if isinstance(asset, dict)]
        if not asset_rows:
            return []
        matches = matches_by_source if matches_by_source is not None else self._photo_matches_by_source()
        metadata_by_asset_id = self.project.db.photo_asset_metadata_by_ids(
            str(asset.get("assetId", "") or "") for asset in asset_rows
        )
        edit_stack_asset_ids = self.project.db.photo_edit_stack_asset_ids_for_assets(
            str(asset.get("assetId", "") or "") for asset in asset_rows
        )
        entries: list[dict[str, Any]] = []
        for asset in asset_rows:
            source_path = str(asset.get("sourcePath", "") or "")
            asset_id = str(asset.get("assetId", "") or "")
            if not source_path or not asset_id:
                continue
            entry = self._photo_source_entry(
                source_path=source_path,
                media_kind=str(asset.get("mediaKind", "") or self._media_kind_for_source(source_path)),
                matches_by_source=matches,
                scan_date=str(asset.get("addedAt", "") or ""),
            )
            entry["_metadata"] = metadata_by_asset_id.get(asset_id, {})
            entry["_assetId"] = asset_id
            entry["_asset"] = asset
            entry["_hasEditStack"] = asset_id in edit_stack_asset_ids
            entry["edited"] = asset_id in edit_stack_asset_ids or bool(entry["_metadata"].get("edited", False))
            entries.append(entry)
        return entries

    def _visible_photo_entries(self, entries: list[dict[str, Any]]) -> list[dict[str, Any]]:
        return [entry for entry in entries if self._photo_entry_default_visible(entry)]

    def _photo_classifier_metadata_values(self, value: Any, depth: int = 0) -> list[str]:
        if depth > 4:
            return []
        if isinstance(value, str):
            clean = value.strip()
            return [clean] if clean else []
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return [str(value)]
        if isinstance(value, list):
            values: list[str] = []
            for item in value[:80]:
                values.extend(self._photo_classifier_metadata_values(item, depth + 1))
            return values
        if isinstance(value, dict):
            values = []
            for key, item in value.items():
                clean_key = str(key or "").strip()
                if clean_key:
                    values.append(clean_key)
                values.extend(self._photo_classifier_metadata_values(item, depth + 1))
            return values
        return []

    def _photo_utility_classifier_text(
        self,
        *,
        source_path: str,
        metadata: dict[str, Any],
        asset_metadata: dict[str, Any],
    ) -> str:
        values = [
            value
            for _field, _label, value in self._photo_utility_classifier_field_values(
                source_path=source_path,
                metadata=metadata,
                asset_metadata=asset_metadata,
            )
        ]
        return " ".join(value for value in values if str(value or "").strip())

    def _photo_utility_classifier_field_values(
        self,
        *,
        source_path: str,
        metadata: dict[str, Any],
        asset_metadata: dict[str, Any],
    ) -> list[tuple[str, str, str]]:
        values: list[tuple[str, str, str]] = [
            ("filename", "Filename", Path(str(source_path or "")).name),
            ("title", "Title", str(metadata.get("title", "") or "")),
            ("caption", "Caption", str(metadata.get("caption", "") or "")),
        ]
        location = metadata.get("locationOverride", {}) if isinstance(metadata.get("locationOverride", {}), dict) else {}
        values.extend([
            ("location.label", "Location", str(location.get("label", "") or "")),
            ("location.place", "Location", str(location.get("place", "") or "")),
        ])
        keywords = metadata.get("keywords", [])
        if isinstance(keywords, list):
            values.extend(("keywords", "Keywords", str(keyword or "")) for keyword in keywords)
        legacy_keywords = asset_metadata.get("keywords", []) if isinstance(asset_metadata, dict) else []
        if isinstance(legacy_keywords, list):
            values.extend(("assetMetadata.keywords", "Keywords", str(keyword or "")) for keyword in legacy_keywords)
        else:
            values.append(("assetMetadata.keywords", "Keywords", str(legacy_keywords or "")))
        if isinstance(asset_metadata, dict):
            field_labels = {
                "ocrText": "Detected text",
                "modelTags": "Model tags",
                "tags": "Tags",
                "objectTags": "Detected items",
                "sceneTags": "Scene tags",
                "labels": "Labels",
                "detectedItems": "Detected items",
                "landmarks": "Landmarks",
                "landmarkLabels": "Landmarks",
                "pointsOfInterest": "Points of interest",
                "poi": "Points of interest",
                "visualLookUp": "Visual Look Up",
                "lookupLabels": "Lookup labels",
                "locationName": "Location",
                "placeName": "Place",
                "documentType": "Document type",
                "contentType": "Content type",
                "safetyLabels": "Safety labels",
                "sensitiveTags": "Sensitive tags",
                "sensitivityLabels": "Sensitivity labels",
                "privacyLabels": "Privacy labels",
                "barcodeType": "Barcode type",
                "qrText": "QR text",
            }
            for key, label in field_labels.items():
                if key in asset_metadata:
                    values.extend(
                        (f"assetMetadata.{key}", label, value)
                        for value in self._photo_classifier_metadata_values(asset_metadata.get(key))
                    )
        seen: set[tuple[str, str]] = set()
        cleaned: list[tuple[str, str, str]] = []
        for field, label, value in values:
            text = re.sub(r"\s+", " ", str(value or "")).strip()
            if not text:
                continue
            key = (str(field or ""), text.casefold())
            if key in seen:
                continue
            seen.add(key)
            cleaned.append((str(field or ""), str(label or field or "Metadata"), text))
        return cleaned

    def _photo_utility_classifier_term_matches_text(self, text: Any, term: Any) -> bool:
        normalized = re.sub(r"[^a-z0-9]+", " ", str(text or "").casefold()).strip()
        clean_term = re.sub(r"[^a-z0-9]+", " ", str(term or "").casefold()).strip()
        if not normalized or not clean_term:
            return False
        padded = f" {normalized} "
        compact = normalized.replace(" ", "")
        if " " in clean_term:
            return f" {clean_term} " in padded
        return f" {clean_term} " in padded or clean_term in {compact, compact[:len(clean_term)]}

    def _clean_photo_utility_classifier_review(self, value: Any) -> dict[str, Any]:
        review = value if isinstance(value, dict) else {}
        raw_entries = review.get("entries", []) if isinstance(review.get("entries", []), list) else []
        entries: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str, str]] = set()
        for raw in raw_entries[:300]:
            if not isinstance(raw, dict):
                continue
            classifier_id = re.sub(r"[^A-Za-z0-9:_-]", "", str(raw.get("classifierId", raw.get("classifier", "")) or ""))[:80]
            field = re.sub(r"[^A-Za-z0-9_.:-]", "", str(raw.get("field", "") or ""))[:80]
            raw_term = str(raw.get("term", raw.get("label", "")) or "").strip()
            term = "*" if raw_term in {"*", "all"} else re.sub(r"\s+", " ", raw_term).strip()[:120]
            raw_action = str(raw.get("action", raw.get("status", "")) or "").strip().casefold()
            if raw_action in {"reject", "rejected", "hide", "hidden", "remove", "removed", "falsepositive", "false_positive", "notthis", "not_this"}:
                action = "rejected"
            elif raw_action in {"confirm", "confirmed", "accept", "accepted", "manual", "user"}:
                action = "confirmed"
            else:
                continue
            if not classifier_id or not term:
                continue
            key = (classifier_id.casefold(), field.casefold(), term.casefold(), action)
            if key in seen:
                continue
            seen.add(key)
            entry: dict[str, Any] = {
                "classifierId": classifier_id,
                "field": field,
                "term": term,
                "action": action,
            }
            reviewed_at = str(raw.get("reviewedAt", "") or "").strip()[:80]
            if reviewed_at:
                entry["reviewedAt"] = reviewed_at
            value_text = re.sub(r"\s+", " ", str(raw.get("value", "") or "")).strip()[:180]
            if value_text:
                entry["value"] = value_text
            if len(entries) >= 200:
                break
            entries.append(entry)
        return {"entries": entries} if entries else {}

    def _photo_utility_classifier_review_action(
        self,
        *,
        classifier_id: str,
        field: str,
        term: str,
        asset_metadata: dict[str, Any],
    ) -> str:
        review = self._clean_photo_utility_classifier_review(asset_metadata.get("utilityClassifierReview", {}))
        entries = review.get("entries", []) if isinstance(review, dict) else []
        classifier_key = str(classifier_id or "").casefold()
        field_key = str(field or "").casefold()
        term_key = re.sub(r"\s+", " ", str(term or "")).strip().casefold()
        for entry in reversed(entries if isinstance(entries, list) else []):
            if not isinstance(entry, dict):
                continue
            if str(entry.get("classifierId", "") or "").casefold() != classifier_key:
                continue
            entry_field = str(entry.get("field", "") or "").casefold()
            if entry_field and entry_field not in {field_key, "*", "all"}:
                continue
            entry_term = re.sub(r"\s+", " ", str(entry.get("term", "") or "")).strip().casefold()
            if entry_term not in {term_key, "*", "all"}:
                continue
            action = str(entry.get("action", "") or "")
            if action in {"confirmed", "rejected"}:
                return action
        return ""

    def _photo_utility_classifier_match_evidence(
        self,
        *,
        classifier_id: str,
        source_path: str,
        metadata: dict[str, Any],
        asset_metadata: dict[str, Any],
    ) -> dict[str, str] | None:
        classifier = PHOTO_UTILITY_CLASSIFIERS.get(str(classifier_id or ""))
        if not classifier:
            return None
        fields = self._photo_utility_classifier_field_values(
            source_path=source_path,
            metadata=metadata,
            asset_metadata=asset_metadata,
        )

        def clip(value: Any) -> str:
            text = re.sub(r"\s+", " ", str(value or "")).strip()
            return text if len(text) <= 180 else text[:177].rstrip() + "..."

        for term in classifier.get("terms", ()):
            clean_term = re.sub(r"\s+", " ", str(term or "").strip())
            if not clean_term:
                continue
            for field, label, value in fields:
                if self._photo_utility_classifier_term_matches_text(value, clean_term):
                    review_action = self._photo_utility_classifier_review_action(
                        classifier_id=str(classifier_id or ""),
                        field=field,
                        term=clean_term,
                        asset_metadata=asset_metadata,
                    )
                    if review_action == "rejected":
                        continue
                    evidence = {
                        "classifierId": str(classifier_id or ""),
                        "classifierKind": str(classifier.get("kind", "") or ""),
                        "classifierName": str(classifier.get("name", "") or classifier_id or ""),
                        "term": clean_term,
                        "field": field,
                        "fieldLabel": label,
                        "value": clip(value),
                        "evidenceLabel": "Local metadata",
                    }
                    if review_action == "confirmed":
                        evidence["reviewAction"] = "confirmed"
                    return evidence
            joined_text = self._photo_utility_classifier_text(
                source_path=source_path,
                metadata=metadata,
                asset_metadata=asset_metadata,
            )
            if self._photo_utility_classifier_term_matches_text(joined_text, clean_term):
                review_action = self._photo_utility_classifier_review_action(
                    classifier_id=str(classifier_id or ""),
                    field="metadata",
                    term=clean_term,
                    asset_metadata=asset_metadata,
                )
                if review_action == "rejected":
                    continue
                evidence = {
                    "classifierId": str(classifier_id or ""),
                    "classifierKind": str(classifier.get("kind", "") or ""),
                    "classifierName": str(classifier.get("name", "") or classifier_id or ""),
                    "term": clean_term,
                    "field": "metadata",
                    "fieldLabel": "Local metadata",
                    "value": clip(joined_text),
                    "evidenceLabel": "Local metadata",
                }
                if review_action == "confirmed":
                    evidence["reviewAction"] = "confirmed"
                return evidence
        return None

    def _photo_utility_classifier_matches(
        self,
        *,
        classifier_id: str,
        source_path: str,
        metadata: dict[str, Any],
        asset_metadata: dict[str, Any],
    ) -> bool:
        classifier = PHOTO_UTILITY_CLASSIFIERS.get(str(classifier_id or ""))
        if not classifier:
            return False
        return self._photo_utility_classifier_match_evidence(
            classifier_id=classifier_id,
            source_path=source_path,
            metadata=metadata,
            asset_metadata=asset_metadata,
        ) is not None

    def _photo_pet_folder_id(self, name: str) -> str:
        clean = self._clean_photo_pet_label(name)
        return f"pet:{quote(clean, safe='')}" if clean else "pet:"

    def _photo_pet_name_from_folder_id(self, folder_id: str) -> str:
        raw = str(folder_id or "").strip()
        if not raw.startswith("pet:"):
            raise ValueError("Unknown pet folder id.")
        name = self._clean_photo_pet_label(unquote(raw[len("pet:"):]))
        if not name:
            raise ValueError("Unknown pet folder id.")
        return name

    def _clean_photo_pet_label(self, value: Any) -> str:
        text = re.sub(r"\s+", " ", str(value or "")).strip(" \t\r\n'\"")
        text = re.sub(r"^(?:pet|animal|dog|cat|bird|rabbit|horse|fish|hamster)\s*[:=-]\s*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s+", " ", text).strip(" \t\r\n'\"")
        if not text:
            return ""
        if len(text) > 48:
            text = text[:48].rsplit(" ", 1)[0] or text[:48]
        key = re.sub(r"[^a-z0-9]+", "", text.casefold())
        if not key or key in {"pet", "pets", "animal", "animals"}:
            return ""
        return text

    def _photo_pet_kind_from_text(self, value: Any) -> str:
        normalized = re.sub(r"[^a-z0-9]+", " ", str(value or "").casefold()).strip()
        if not normalized:
            return ""
        padded = f" {normalized} "
        compact = normalized.replace(" ", "")
        for kind, terms in PHOTO_PET_KIND_TERMS.items():
            for term in terms:
                clean_term = re.sub(r"[^a-z0-9]+", " ", term.casefold()).strip()
                if not clean_term:
                    continue
                if " " in clean_term:
                    if f" {clean_term} " in padded:
                        return kind
                    continue
                if f" {clean_term} " in padded or clean_term == compact:
                    return kind
        return ""

    def _photo_pet_kind_label(self, kind: str) -> str:
        return PHOTO_PET_KIND_LABELS.get(str(kind or "").strip().lower(), "Pet")

    def _photo_pet_explicit_records(self, value: Any, inherited_kind: str = "", depth: int = 0) -> list[dict[str, str]]:
        if depth > 5:
            return []
        records: list[dict[str, str]] = []
        if isinstance(value, str):
            for part in re.split(r"[,;/|\n]+", value):
                name = self._clean_photo_pet_label(part)
                if name:
                    records.append({"name": name, "kind": inherited_kind})
            return records
        if isinstance(value, list):
            for item in value[:80]:
                records.extend(self._photo_pet_explicit_records(item, inherited_kind, depth + 1))
            return records
        if isinstance(value, dict):
            direct_name = ""
            direct_kind = inherited_kind
            for key, item in value.items():
                normalized_key = re.sub(r"[^a-z0-9]+", "", str(key or "").casefold())
                if normalized_key in PHOTO_PET_KIND_KEYS:
                    direct_kind = self._photo_pet_kind_from_text(item) or direct_kind
                if normalized_key in {"name", "label", "title", "value", *PHOTO_PET_NAME_KEYS} and not direct_name:
                    if isinstance(item, (str, int, float)) and not isinstance(item, bool):
                        direct_name = self._clean_photo_pet_label(item)
            if direct_name:
                records.append({"name": direct_name, "kind": direct_kind})
            for key, item in value.items():
                normalized_key = re.sub(r"[^a-z0-9]+", "", str(key or "").casefold())
                if normalized_key in {"confidence", "score", "probability", "bbox", "bounds", "x", "y", "width", "height"}:
                    continue
                if normalized_key in PHOTO_PET_KIND_KEYS:
                    continue
                records.extend(self._photo_pet_explicit_records(item, direct_kind, depth + 1))
            return records
        return []

    def _photo_pet_marker_records(self, values: Iterable[Any]) -> list[dict[str, str]]:
        records: list[dict[str, str]] = []
        marker = re.compile(r"\b(pet|dog|cat|bird|rabbit|horse|fish|hamster)\s*[:=-]\s*([A-Za-z][A-Za-z0-9' -]{0,47})")
        for value in values:
            text = str(value or "")
            for match in marker.finditer(text):
                kind = self._photo_pet_kind_from_text(match.group(1)) or "pet"
                name = self._clean_photo_pet_label(match.group(2))
                if name:
                    records.append({"name": name, "kind": kind})
        return records

    def _photo_pet_labels(
        self,
        *,
        source_path: str,
        metadata: dict[str, Any],
        asset_metadata: dict[str, Any],
    ) -> list[dict[str, str]]:
        records: list[dict[str, str]] = []
        text_values: list[str] = [Path(str(source_path or "")).stem]
        for key in ("title", "caption"):
            if metadata.get(key):
                text_values.append(str(metadata.get(key, "")))
        keywords = metadata.get("keywords", [])
        if isinstance(keywords, list):
            text_values.extend(str(keyword or "") for keyword in keywords)
        legacy_keywords = asset_metadata.get("keywords", []) if isinstance(asset_metadata, dict) else []
        if isinstance(legacy_keywords, list):
            text_values.extend(str(keyword or "") for keyword in legacy_keywords)
        elif legacy_keywords:
            text_values.append(str(legacy_keywords))
        dismissed_pet_review_kinds: set[str] = set()
        if isinstance(asset_metadata, dict):
            dismissed_values = asset_metadata.get("petReviewDismissedKinds", asset_metadata.get("dismissedPetReviewKinds", []))
            if isinstance(dismissed_values, dict):
                dismissed_values = list(dismissed_values.keys())
            if isinstance(dismissed_values, list):
                dismissed_pet_review_kinds.update(
                    kind
                    for value in dismissed_values
                    for kind in [self._photo_pet_kind_from_text(value)]
                    if kind
                )
            else:
                kind = self._photo_pet_kind_from_text(dismissed_values)
                if kind:
                    dismissed_pet_review_kinds.add(kind)
            for key in PHOTO_PET_METADATA_KEYS:
                if key in asset_metadata:
                    normalized_key = re.sub(r"[^a-z0-9]+", "", key.casefold())
                    values = self._photo_classifier_metadata_values(asset_metadata.get(key))
                    text_values.extend(values)
                    if normalized_key in PHOTO_PET_NAME_KEYS:
                        records.extend(self._photo_pet_explicit_records(asset_metadata.get(key)))
                    elif key in {"pets", "animals"}:
                        records.extend(self._photo_pet_explicit_records(asset_metadata.get(key)))
        records.extend(self._photo_pet_marker_records(text_values))
        generic_kind = self._photo_pet_kind_from_text(" ".join(text_values))
        if not records and generic_kind and generic_kind not in dismissed_pet_review_kinds:
            records.append({"name": self._photo_pet_kind_label(generic_kind), "kind": generic_kind})
        seen: set[str] = set()
        cleaned: list[dict[str, str]] = []
        for record in records:
            name = self._clean_photo_pet_label(record.get("name", ""))
            if not name:
                continue
            kind = self._photo_pet_kind_from_text(record.get("kind", "")) or generic_kind or self._photo_pet_kind_from_text(name) or "pet"
            if kind in dismissed_pet_review_kinds and name.casefold() == self._photo_pet_kind_label(kind).casefold():
                continue
            key = name.casefold()
            if key in seen:
                continue
            seen.add(key)
            cleaned.append({"name": name, "kind": kind, "kindLabel": self._photo_pet_kind_label(kind)})
        return cleaned

    def _photo_pet_labels_for_entry(self, entry: dict[str, Any]) -> list[dict[str, str]]:
        asset = self._photo_entry_asset(entry) or {}
        asset_metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
        return self._photo_pet_labels(
            source_path=str(entry.get("sourcePath", "") or ""),
            metadata=self._photo_entry_metadata(entry),
            asset_metadata=asset_metadata,
        )

    def _photo_pet_label_is_generic(self, pet: dict[str, str]) -> bool:
        name = self._clean_photo_pet_label(pet.get("name", ""))
        if not name:
            return False
        kind = self._photo_pet_kind_from_text(pet.get("kind", "")) or self._photo_pet_kind_from_text(name)
        if not kind:
            return False
        return name.casefold() == self._photo_pet_kind_label(kind).casefold()

    def _photo_pet_review_record_from_labels(self, labels: list[dict[str, str]]) -> dict[str, str] | None:
        generic_labels = [pet for pet in labels if self._photo_pet_label_is_generic(pet)]
        named_labels = [pet for pet in labels if not self._photo_pet_label_is_generic(pet)]
        if not generic_labels or named_labels:
            return None
        kind = self._photo_pet_kind_from_text(generic_labels[0].get("kind", "")) or self._photo_pet_kind_from_text(generic_labels[0].get("name", "")) or "pet"
        return {
            "kind": kind,
            "kindLabel": self._photo_pet_kind_label(kind),
            "label": self._photo_pet_kind_label(kind),
        }

    def _photo_pet_review_record_for_entry(self, entry: dict[str, Any]) -> dict[str, str] | None:
        return self._photo_pet_review_record_from_labels(self._photo_pet_labels_for_entry(entry))

    def _photo_import_source_kind(self, value: Any) -> str:
        kind = str(value or "").strip().lower()
        return kind if kind in PHOTO_APP_IMPORT_SOURCE_KINDS else ""

    def _photo_import_source_default_label(self, kind: str) -> str:
        labels = {
            "airdrop": "AirDrop",
            "app": "App",
            "downloads": "Downloads",
            "mail": "Mail",
            "messages": "Messages",
            "safari": "Safari",
        }
        return labels.get(kind, kind.replace("_", " ").title() if kind else "App")

    def _photo_import_source_label(self, kind: str, value: Any) -> str:
        label = re.sub(r"\s+", " ", str(value or "").strip())[:128]
        return label or self._photo_import_source_default_label(kind)

    def _photo_import_source_folder_id(self, kind: str, label: str) -> str:
        return f"importSource:{quote(kind, safe='')}:{quote(label, safe='')}"

    def _photo_import_source_from_folder_id(self, folder_id: str) -> tuple[str, str]:
        parts = str(folder_id or "").split(":", 2)
        if len(parts) != 3 or parts[0] != "importSource":
            raise ValueError("Unknown photo import source.")
        kind = self._photo_import_source_kind(unquote(parts[1]))
        label = self._photo_import_source_label(kind, unquote(parts[2])) if kind else ""
        if not kind or not label:
            raise ValueError("Unknown photo import source.")
        return kind, label

    def _photo_import_source_groups(self, sessions: list[dict[str, Any]] | None = None) -> list[dict[str, Any]]:
        groups: dict[tuple[str, str], dict[str, Any]] = {}
        source_sessions = sessions if sessions is not None else self.project.db.list_photo_import_sessions(limit=1000)
        for session in source_sessions:
            kind = self._photo_import_source_kind(session.get("sourceKind", ""))
            if not kind:
                continue
            label = self._photo_import_source_label(kind, session.get("sourceLabel", ""))
            key = (kind, label.casefold())
            group = groups.setdefault(key, {
                "kind": kind,
                "label": label,
                "importIds": [],
                "sessions": [],
                "latestImportAt": "",
            })
            import_id = str(session.get("importId", "") or "")
            if import_id:
                group["importIds"].append(import_id)
            group["sessions"].append(session)
            latest = str(session.get("completedAt", "") or session.get("updatedAt", "") or session.get("startedAt", "") or "")
            if latest > str(group.get("latestImportAt", "") or ""):
                group["latestImportAt"] = latest
        return sorted(
            groups.values(),
            key=lambda group: (
                str(group.get("latestImportAt", "") or ""),
                str(group.get("label", "") or "").casefold(),
            ),
            reverse=True,
        )

    def _photo_import_source_group_from_folder_id(self, folder_id: str) -> dict[str, Any] | None:
        kind, label = self._photo_import_source_from_folder_id(folder_id)
        for group in self._photo_import_source_groups():
            if str(group.get("kind", "") or "") == kind and str(group.get("label", "") or "").casefold() == label.casefold():
                return group
        return None

    def _photo_import_source_group_summaries(
        self,
        *,
        source_text_filters: Iterable[tuple[str, str]] = (),
        limit: int = 48,
    ) -> list[dict[str, Any]]:
        summaries: list[dict[str, Any]] = []
        for group in self._photo_import_source_groups():
            import_ids = [str(import_id or "") for import_id in group.get("importIds", []) if str(import_id or "")]
            if not import_ids:
                continue
            page = self.project.db.list_photo_asset_page(
                offset=0,
                limit=1,
                visibility="visible",
                source_scan_runs=import_ids,
                source_text_filters=source_text_filters,
                sort="newest",
            )
            assets = page.get("assets", []) if isinstance(page.get("assets", []), list) else []
            count = int(page.get("total", 0) or 0)
            if count <= 0:
                continue
            cover_source = str(assets[0].get("sourcePath", "") or "") if assets else ""
            summaries.append({
                **group,
                "id": self._photo_import_source_folder_id(str(group.get("kind", "") or ""), str(group.get("label", "") or "")),
                "count": count,
                "coverSourcePath": cover_source,
                "sessionCount": len(group.get("sessions", []) or []),
            })
            if len(summaries) >= limit:
                break
        summaries.sort(key=lambda group: (
            -int(group.get("count", 0) or 0),
            str(group.get("label", "") or "").casefold(),
            str(group.get("kind", "") or ""),
        ))
        return summaries

    def _photo_asset_entries(
        self,
        utility: str = "",
        *,
        matches_by_source: dict[str, list[ReviewCandidate]] | None = None,
        pet_review_kind: str = "",
    ) -> list[dict[str, Any]]:
        duplicate_asset_ids: set[str] = set()
        place_asset_ids: set[str] = set()
        place_filter = ""
        trip_source_paths: set[str] | None = None
        memory_source_paths: set[str] | None = None
        pet_filter = self._photo_pet_name_from_folder_id(utility) if utility.startswith("pet:") else ""
        import_ids: set[str] | None = None
        recovered_paths: set[str] = set()
        event_asset_ids: set[str] | None = None
        event_times: dict[str, str] = {}
        event_type = ""
        saved_import_times: dict[str, str] = {}
        utility_classifier_id = utility if utility in PHOTO_UTILITY_CLASSIFIER_IDS else ""
        media_filter = utility[len("media:"):].strip().lower() if utility.startswith("media:") else ""
        if media_filter not in PHOTO_MEDIA_KINDS:
            media_filter = ""
        if utility.startswith("importSource:"):
            group = self._photo_import_source_group_from_folder_id(utility)
            import_ids = {
                str(import_id or "")
                for import_id in (group or {}).get("importIds", [])
                if str(import_id or "")
            }
        if utility in {"imports", "lastImport", "recentlyImported"} or utility.startswith("import:"):
            sessions = self.project.db.list_photo_import_sessions(limit=1000)
            if utility == "imports":
                import_ids = {str(session.get("importId", "") or "") for session in sessions}
            elif utility == "lastImport":
                latest = sessions[0] if sessions else {}
                import_ids = {str(latest.get("importId", "") or "")} if latest else set()
            elif utility == "recentlyImported":
                cutoff = datetime.utcnow() - timedelta(days=30)
                import_ids = set()
                for session in sessions:
                    value = str(session.get("completedAt", "") or session.get("updatedAt", "") or session.get("startedAt", "") or "")
                    try:
                        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
                    except ValueError:
                        continue
                    if parsed.tzinfo is not None:
                        parsed = parsed.replace(tzinfo=None)
                    if parsed >= cutoff:
                        import_ids.add(str(session.get("importId", "") or ""))
            else:
                import_ids = {utility[len("import:"):].strip()}
        if utility == "recentlySaved":
            cutoff = datetime.utcnow() - timedelta(days=30)
            import_ids = set()
            for session in self.project.db.list_photo_import_sessions(limit=1000):
                if str(session.get("sourceKind", "") or "").strip().lower() not in PHOTO_APP_IMPORT_SOURCE_KINDS:
                    continue
                value = str(session.get("completedAt", "") or session.get("updatedAt", "") or session.get("startedAt", "") or "")
                try:
                    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
                except ValueError:
                    continue
                if parsed.tzinfo is not None:
                    parsed = parsed.replace(tzinfo=None)
                if parsed >= cutoff:
                    import_id = str(session.get("importId", "") or "")
                    if import_id:
                        import_ids.add(import_id)
                        saved_import_times[import_id] = value
        if utility == "recovered":
            recovered_paths = {
                str(row.get("recoveredPath", "") or "")
                for row in self.project.db.list_photo_import_failures(limit=1000)
                if str(row.get("recoveredPath", "") or "")
            }
        if utility in {"recentlyViewed", "recentlyShared"}:
            event_type = "viewed" if utility == "recentlyViewed" else "shared"
            event_rows = self.project.db.list_photo_asset_events(
                event_type,
                limit=1000,
                since=self._photo_recent_activity_since(),
            )
            event_details_by_asset_id = {
                str(row.get("assetId", "") or ""): row
                for row in event_rows
                if str(row.get("assetId", "") or "")
            }
            event_asset_ids = set(event_details_by_asset_id.keys())
            event_times = {
                asset_id: str(row.get("eventAt", "") or "")
                for asset_id, row in event_details_by_asset_id.items()
            }
        if utility == "duplicates":
            self.project.db.ensure_photo_duplicate_groups()
            for group in self.project.db.list_photo_duplicate_groups():
                duplicate_asset_ids.update(str(item.get("assetId", "") or "") for item in group.get("items", []))
        if utility == "places" or utility.startswith("place:"):
            place_filter = utility[len("place:"):] if utility.startswith("place:") else ""
            for place in self.project.db.list_photo_places():
                if place_filter and str(place.get("placeId", "") or "") != place_filter:
                    continue
                place_asset_ids.update(str(asset_id or "") for asset_id in place.get("assetIds", []))
        if utility == "trips" or utility.startswith("trip:"):
            trip_source_paths = set()
            trip_filter = utility[len("trip:"):] if utility.startswith("trip:") else ""
            for trip in self._photo_trip_summaries():
                if trip_filter and str(trip.get("tripId", "") or "") != trip_filter:
                    continue
                trip_source_paths.update(str(path or "") for path in trip.get("sourcePaths", []))
        if utility == "memories" or utility.startswith("memory:"):
            memory_source_paths = set()
            memory_filter = utility[len("memory:"):] if utility.startswith("memory:") else ""
            for memory in self._photo_memory_summaries():
                if memory_filter and str(memory.get("memoryId", "") or "") != memory_filter:
                    continue
                memory_source_paths.update(str(path or "") for path in memory.get("sourcePaths", []))
        generated_source_paths = trip_source_paths if trip_source_paths is not None else memory_source_paths
        if generated_source_paths is not None:
            return self._photo_entries_for_source_paths(
                sorted(str(path or "") for path in generated_source_paths if str(path or "")),
                matches_by_source=matches_by_source,
            )
        matches = matches_by_source or self._photo_matches_by_source()
        total = self.project.db.count_photo_assets()
        assets = self.project.db.list_photo_assets(offset=0, limit=max(1, total)) if total else []
        metadata_by_asset_id = self.project.db.photo_asset_metadata_by_ids(
            str(asset.get("assetId", "") or "") for asset in assets
        )
        people_by_asset_id = self.project.db.photo_asset_people_by_ids(
            str(asset.get("assetId", "") or "") for asset in assets
        )
        edit_stack_count = self.project.db.count_photo_edit_stacks()
        edit_stack_asset_ids = {
            str(stack.get("assetId", "") or "")
            for stack in self.project.db.list_photo_edit_stacks(limit=max(1, edit_stack_count))
        } if edit_stack_count else set()
        pet_profiles_for_filter = self.project.db.list_photo_pet_profiles() if utility == "pets" else {}
        entries: list[dict[str, Any]] = []
        for asset in assets:
            source_path = str(asset.get("sourcePath", "") or "")
            asset_id = str(asset.get("assetId", "") or "")
            if not source_path:
                continue
            metadata = metadata_by_asset_id.get(asset_id, {})
            deleted = bool(str(metadata.get("deletedAt", "") or ""))
            hidden = bool(metadata.get("hidden", False))
            favorite = bool(metadata.get("favorite", False))
            edited = bool(metadata.get("edited", False)) or asset_id in edit_stack_asset_ids
            asset_metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
            utility_match: dict[str, str] | None = None
            if utility == "favorites" and (not favorite or hidden or deleted):
                continue
            if utility == "hidden" and (not hidden or deleted):
                continue
            if utility == "recentlyDeleted" and not deleted:
                continue
            if import_ids is not None and str(asset.get("sourceScanRun", "") or "") not in import_ids:
                continue
            if utility == "recovered" and source_path not in recovered_paths:
                continue
            if utility == "recentlyAdded" and (hidden or deleted):
                continue
            if utility == "recentlySaved" and (hidden or deleted):
                continue
            if utility.startswith("importSource:") and (hidden or deleted):
                continue
            if utility == "recentlyEdited" and (not edited or hidden or deleted):
                continue
            if event_asset_ids is not None and (asset_id not in event_asset_ids or hidden or deleted):
                continue
            if utility.startswith("media:") and (hidden or deleted or str(asset.get("mediaKind", "") or "").strip().lower() != media_filter):
                continue
            if utility == "duplicates" and (asset_id not in duplicate_asset_ids or hidden or deleted):
                continue
            if (utility == "places" or utility.startswith("place:")) and asset_id not in place_asset_ids:
                continue
            if trip_source_paths is not None and source_path not in trip_source_paths:
                continue
            if memory_source_paths is not None and source_path not in memory_source_paths:
                continue
            if utility == "pets" or pet_filter:
                if hidden or deleted:
                    continue
                pet_labels = self._photo_pet_labels(
                    source_path=source_path,
                    metadata=metadata,
                    asset_metadata=asset_metadata,
                )
                if pet_filter and not any(str(pet.get("name", "") or "").casefold() == pet_filter.casefold() for pet in pet_labels):
                    continue
                if utility == "pets":
                    pet_labels = [
                        pet for pet in pet_labels
                        if not bool((pet_profiles_for_filter.get(str(pet.get("name", "") or "")) or {}).get("hidden"))
                    ]
                if utility == "pets" and not pet_labels:
                    continue
            if utility == "petReview":
                if hidden or deleted:
                    continue
                pet_labels = self._photo_pet_labels(
                    source_path=source_path,
                    metadata=metadata,
                    asset_metadata=asset_metadata,
                )
                review_record = self._photo_pet_review_record_from_labels(pet_labels)
                if review_record is None:
                    continue
                if pet_review_kind and str(review_record.get("kind", "") or "") != pet_review_kind:
                    continue
            if utility_classifier_id:
                if hidden or deleted:
                    continue
                utility_match = self._photo_utility_classifier_match_evidence(
                    classifier_id=utility_classifier_id,
                    source_path=source_path,
                    metadata=metadata,
                    asset_metadata=asset_metadata,
                )
                if not utility_match:
                    continue
            entry = self._photo_source_entry(
                source_path=source_path,
                media_kind=str(asset.get("mediaKind", "") or self._media_kind_for_source(source_path)),
                matches_by_source=matches,
                scan_date=str(asset.get("addedAt", "") or ""),
            )
            entry["_metadata"] = metadata
            entry["_assetId"] = asset_id
            entry["_asset"] = asset
            entry["_peopleRows"] = people_by_asset_id.get(asset_id, [])
            entry["_hasEditStack"] = asset_id in edit_stack_asset_ids
            entry["edited"] = edited
            if utility_match:
                entry["_utilityMatch"] = utility_match
            if utility == "recentlySaved":
                entry["savedAt"] = saved_import_times.get(str(asset.get("sourceScanRun", "") or ""), str(asset.get("addedAt", "") or ""))
            if event_asset_ids is not None:
                event_details = event_details_by_asset_id.get(asset_id, {})
                event_metadata = event_details.get("metadata", {}) if isinstance(event_details.get("metadata", {}), dict) else {}
                entry["eventAt"] = str(event_details.get("eventAt", event_times.get(asset_id, "")) or "")
                entry["eventType"] = event_type
                entry["eventActor"] = str(event_details.get("actor", "") or "")
                entry["eventMetadata"] = event_metadata
            entries.append(entry)
        if event_asset_ids is not None:
            entries.sort(key=lambda entry: (str(entry.get("eventAt", "") or ""), str(entry.get("sourcePath", "") or "").casefold()), reverse=True)
        return entries

    def _clean_album_people(self, values: Any) -> list[str]:
        if not isinstance(values, list):
            return []
        seen: set[str] = set()
        people: list[str] = []
        for value in values:
            person = str(value or "").strip()
            key = person.casefold()
            if person and key not in seen:
                seen.add(key)
                people.append(person)
        return people

