    def _photo_slideshow_clean_caption_region(self, value: Any) -> dict[str, float] | None:
        record = value if isinstance(value, dict) else None
        pair = value if isinstance(value, list) else None
        raw_x = (record or {}).get("x", (record or {}).get("left", (record or {}).get("l"))) if record else pair[0] if pair and len(pair) > 0 else None
        raw_y = (record or {}).get("y", (record or {}).get("top", (record or {}).get("t"))) if record else pair[1] if pair and len(pair) > 1 else None
        raw_width = (record or {}).get("width", (record or {}).get("w")) if record else pair[2] if pair and len(pair) > 2 else None
        raw_height = (record or {}).get("height", (record or {}).get("h")) if record else pair[3] if pair and len(pair) > 3 else None
        raw_right = (record or {}).get("right", (record or {}).get("r")) if record else None
        raw_bottom = (record or {}).get("bottom", (record or {}).get("b")) if record else None
        try:
            parsed_x = float(raw_x)
            parsed_y = float(raw_y)
            parsed_width = float(raw_width) if raw_width is not None else float("nan")
            parsed_height = float(raw_height) if raw_height is not None else float("nan")
            parsed_right = float(raw_right) if raw_right is not None else float("nan")
            parsed_bottom = float(raw_bottom) if raw_bottom is not None else float("nan")
        except (TypeError, ValueError):
            return None
        if not math.isfinite(parsed_width) and math.isfinite(parsed_right):
            parsed_width = parsed_right - parsed_x
        if not math.isfinite(parsed_height) and math.isfinite(parsed_bottom):
            parsed_height = parsed_bottom - parsed_y
        if not all(math.isfinite(item) for item in (parsed_x, parsed_y, parsed_width, parsed_height)):
            return None
        max_value = max(abs(parsed_x), abs(parsed_y), abs(parsed_width), abs(parsed_height))
        unit = str((record or {}).get("unit", (record or {}).get("units", (record or {}).get("coordinateUnit", (record or {}).get("coordinateSpace", "")))) or "").lower()
        scale = 100.0 if "normal" in unit or "relative" in unit or unit == "fraction" or max_value <= 1.5 else 1.0
        left = max(0.0, min(100.0, parsed_x * scale))
        top = max(0.0, min(100.0, parsed_y * scale))
        right = max(left, min(100.0, (parsed_x + parsed_width) * scale))
        bottom = max(top, min(100.0, (parsed_y + parsed_height) * scale))
        width = right - left
        height = bottom - top
        if width < 1.0 or height < 1.0:
            return None
        return {"x": round(left, 1), "y": round(top, 1), "width": round(width, 1), "height": round(height, 1)}

    def _photo_slideshow_clean_template_region_slot(self, value: Any) -> str:
        slot = str(value or "").strip().lower().replace("_", "-").replace(" ", "-")
        aliases = {
            "caption": "primary",
            "main": "primary",
            "body": "primary",
            "primary-caption": "primary",
            "subtitle": "context",
            "subhead": "context",
            "collection": "context",
            "label": "context",
            "source-label": "context",
            "count": "counter",
            "page": "counter",
            "number": "counter",
            "slide-number": "counter",
            "slide-counter": "counter",
            "heading": "title",
            "headline": "title",
            "project-title": "title",
            "origin": "source",
            "album": "source",
            "memory": "source",
            "source-name": "source",
            "slide": "chapter",
            "chapter-label": "chapter",
            "cue": "chapter",
        }
        slot = aliases.get(slot, slot)
        return slot if slot in {"primary", "context", "counter", "title", "source", "chapter"} else ""

    def _photo_slideshow_clean_template_region_map(self, value: Any) -> dict[str, dict[str, float]]:
        regions: dict[str, dict[str, float]] = {}

        def assign(slot_value: Any, region_value: Any) -> None:
            slot = self._photo_slideshow_clean_template_region_slot(slot_value)
            if not slot:
                return
            region = self._photo_slideshow_clean_caption_region(region_value)
            if region:
                regions[slot] = region

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, dict):
                    continue
                assign(
                    item.get("slot", item.get("id", item.get("key", item.get("name", item.get("regionSlot"))))),
                    item.get("region", item.get("captionRegion", item.get("bounds", item.get("box", item.get("frame", item.get("rect")))))) or item,
                )
            return regions
        if not isinstance(value, dict):
            return regions
        for slot in ("primary", "context", "counter", "title", "source", "chapter"):
            assign(slot, value.get(slot))
        for key, region_value in value.items():
            assign(key, region_value)
        return regions

    def _photo_slideshow_resolved_caption_preset(self, preset: str, layout: str = "auto") -> str:
        clean_preset = str(preset or "auto").strip().lower().replace("_", "-")
        if clean_preset in {"lower", "lowerthird", "caption-bar"}:
            clean_preset = "lower-third"
        elif clean_preset in {"title", "title-sub", "headline-subtitle"}:
            clean_preset = "title-subtitle"
        elif clean_preset in {"split", "story-split", "split-notes"}:
            clean_preset = "split-story"
        elif clean_preset in {"gallery", "gallery-tags", "labels"}:
            clean_preset = "gallery-labels"
        elif clean_preset in {"cinema", "letterbox", "letterbox-bars"}:
            clean_preset = "cinema-bars"
        if clean_preset != "auto" and clean_preset in {"lower-third", "title-subtitle", "split-story", "gallery-labels", "cinema-bars"}:
            return clean_preset
        clean_layout = str(layout or "auto").strip().lower().replace("_", "-")
        if clean_layout == "poster":
            return "title-subtitle"
        if clean_layout == "split":
            return "split-story"
        if clean_layout == "gallery":
            return "gallery-labels"
        if clean_layout in {"cinema", "immersive"}:
            return "cinema-bars"
        return "lower-third"

