    def export_photo_memory_movie(self, params: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(params, dict):
            raise ValueError("Photo Memory movie export params must be an object.")
        memory_id = str(params.get("memoryId", params.get("id", "")) or "").strip()
        if memory_id.startswith("memory:"):
            memory_id = memory_id[len("memory:"):]
        if not memory_id:
            raise ValueError("memoryId is required.")
        memory = self._photo_memory_by_id(memory_id)
        if not memory:
            raise ValueError("Unknown photo memory id.")
        source_paths = [str(path or "").strip() for path in memory.get("sourcePaths", []) if str(path or "").strip()]
        if len(source_paths) < 2:
            raise ValueError("Memory movie export requires at least two visible photos or videos.")
        memory_name = self._photo_export_clean_text(memory.get("name", ""), limit=120) or "Memory"
        title = self._photo_export_clean_text(params.get("title", params.get("name", memory_name)), limit=120) or memory_name
        source_label = self._photo_export_clean_text(
            params.get("sourceLabel", memory.get("subtitle") or memory.get("dateRangeLabel") or "Memory"),
            limit=80,
        )
        memory_movie_settings = memory.get("movieSettings") if isinstance(memory.get("movieSettings"), dict) else {}

        def memory_movie_value(key: str, default: Any = None, *aliases: str) -> Any:
            for param_key in (key, *aliases):
                if param_key in params:
                    return params.get(param_key)
            return memory_movie_settings.get(key, default)

        movie_params = dict(params)
        movie_params.update({
            "sourcePaths": source_paths,
            "title": title,
            "name": title,
            "sourceLabel": source_label,
            "memoryId": memory_id,
            "memoryName": memory_name,
            "outputMode": "video",
            "renderVideo": True,
            "exportAction": "export_photo_memory_movie",
            "exportKind": "memoryMovie",
            "bundlePrefix": "vintrace-memory-movie",
            "videoBaseName": f"{title}-memory-movie",
            "theme": memory_movie_value("theme", "ken-burns"),
            "themeTimelinePreset": memory_movie_value("themeTimelinePreset", "auto", "themePreset", "timelinePreset"),
            "themeTemplateName": memory_movie_value("themeTemplateName", "", "templateName", "slideshowTemplateName"),
            "themeTemplatePalette": memory_movie_value("themeTemplatePalette", "auto", "templatePalette", "slideshowTemplatePalette"),
            "themeTemplateTypography": memory_movie_value("themeTemplateTypography", "auto", "templateTypography", "slideshowTemplateTypography"),
            "themeTemplateBackdrop": memory_movie_value("themeTemplateBackdrop", "auto", "templateBackdrop", "slideshowTemplateBackdrop"),
            "themeTemplateLayout": memory_movie_value("themeTemplateLayout", "auto", "templateLayout", "slideshowTemplateLayout"),
            "themeTemplateBackdropIntensity": memory_movie_value("themeTemplateBackdropIntensity", 100, "templateBackdropIntensity", "slideshowTemplateBackdropIntensity"),
            "themeTemplateStageWidth": memory_movie_value("themeTemplateStageWidth", 100, "templateStageWidth", "slideshowTemplateStageWidth"),
            "themeTemplateFrameStyle": memory_movie_value("themeTemplateFrameStyle", "auto", "templateFrameStyle", "slideshowTemplateFrameStyle"),
            "themeTemplateChromeDensity": memory_movie_value("themeTemplateChromeDensity", "auto", "templateChromeDensity", "slideshowTemplateChromeDensity"),
            "themeTemplateCaptionPreset": memory_movie_value("themeTemplateCaptionPreset", "auto", "templateCaptionPreset", "slideshowTemplateCaptionPreset", "captionPreset", "captionLayoutPreset"),
            "themeTemplateRegionMap": memory_movie_value("themeTemplateRegionMap", {}, "templateRegionMap", "slideshowTemplateRegionMap", "themeTemplateCaptionRegions", "templateCaptionRegions", "captionRegionMap"),
            "music": memory_movie_value("music", "calm"),
            "audioPath": memory_movie_value("audioPath", memory_movie_settings.get("musicPath", ""), "musicPath"),
            "audioVolume": memory_movie_value("audioVolume", 1.0),
            "audioFadeMs": memory_movie_value("audioFadeMs", 0),
            "audioStartMs": memory_movie_value("audioStartMs", 0),
            "audioEndMs": memory_movie_value("audioEndMs", 0),
            "audioPlacementStartSourcePath": memory_movie_value("audioPlacementStartSourcePath", ""),
            "audioPlacementEndSourcePath": memory_movie_value("audioPlacementEndSourcePath", ""),
            "intervalMs": memory_movie_value("intervalMs", 4500, "delayMs"),
            "fitMode": memory_movie_value("fitMode", "fill", "fit"),
            "includeTitleCard": memory_movie_value("includeTitleCard", True),
            "titleCardTitle": memory_movie_value("titleCardTitle", title),
            "titleCardSubtitle": memory_movie_value("titleCardSubtitle", source_label),
            "titleCardDurationMs": memory_movie_value("titleCardDurationMs", memory_movie_value("intervalMs", 4500, "delayMs")),
            "titleCardPalette": memory_movie_value("titleCardPalette", "auto"),
            "titleCardLayout": memory_movie_value("titleCardLayout", "center"),
            "titleCardFontScale": memory_movie_value("titleCardFontScale", "regular"),
            "titleCardShowFooter": memory_movie_value("titleCardShowFooter", True),
            "transitionEffect": memory_movie_value("transitionEffect", "auto", "transitionStyle", "transition"),
            "transitionDurationMs": memory_movie_value("transitionDurationMs", 650, "transitionMs"),
        })
        return self.export_photo_slideshow(movie_params)

    def relink_photo_library_paths(self, params: dict[str, Any]) -> dict[str, Any]:
        old_root = str(params.get("oldRoot", "") or params.get("old_root", "") or "").strip()
        new_root = str(params.get("newRoot", "") or params.get("new_root", "") or "").strip()
        if not old_root:
            raise ValueError("oldRoot is required.")
        if not new_root:
            raise ValueError("newRoot is required.")
        result = self.project.db.relink_photo_asset_paths(
            Path(old_root).expanduser(),
            Path(new_root).expanduser(),
            dry_run=bool(params.get("dryRun", True)),
            force_partial=bool(params.get("forcePartial", False)),
        )
        if not result.get("dryRun") and int(result.get("relinkedAssets", 0) or 0):
            if int(result.get("candidateRowsUpdated", 0) or 0):
                self._refresh_project_candidates_from_db()
            self.project._append_audit(
                {
                    "action": "relink_photo_library_paths",
                    "old_root": result.get("oldRoot", old_root),
                    "new_root": result.get("newRoot", new_root),
                    "matched_assets": int(result.get("matchedAssets", 0) or 0),
                    "relinked_assets": int(result.get("relinkedAssets", 0) or 0),
                    "skipped_assets": int(result.get("skippedAssets", 0) or 0),
                    "missing_targets": len(result.get("missingTargets", []) or []),
                    "conflicts": len(result.get("conflicts", []) or []),
                }
            )
        return result

    def consolidate_photo_library_assets(self, params: dict[str, Any]) -> dict[str, Any]:
        source_paths_raw = params.get("sourcePaths", [])
        asset_ids_raw = params.get("assetIds", [])
        if not isinstance(source_paths_raw, list):
            raise ValueError("sourcePaths must be a list.")
        if not isinstance(asset_ids_raw, list):
            raise ValueError("assetIds must be a list.")
        source_paths = [str(path or "").strip() for path in source_paths_raw if str(path or "").strip()]
        asset_ids = [str(asset_id or "").strip() for asset_id in asset_ids_raw if str(asset_id or "").strip()]
        managed_root_param = str(params.get("managedRoot", params.get("managedFolder", "")) or "").strip()
        managed_root = Path(managed_root_param).expanduser() if managed_root_param else self._photo_managed_root_from_settings()
        result = self.project.db.consolidate_photo_assets(
            source_paths=source_paths,
            asset_ids=asset_ids,
            managed_root=managed_root,
            dry_run=bool(params.get("dryRun", False)),
        )
        if not result.get("dryRun") and int(result.get("consolidatedAssets", 0) or 0):
            def audit_sample_name(value: Any) -> str:
                raw = str(value or "").strip()
                if not raw:
                    return ""
                try:
                    return Path(raw).name or raw
                except Exception:
                    return raw.replace("\\", "/").rstrip("/").split("/")[-1] or raw

            def audit_sample_names(samples: Any, *keys: str, limit: int = 6) -> list[str]:
                names: list[str] = []
                raw_samples = samples if isinstance(samples, list) else []
                for sample in raw_samples:
                    raw_value: Any = sample
                    if isinstance(sample, dict):
                        raw_value = ""
                        for key in keys:
                            value = sample.get(key)
                            if str(value or "").strip():
                                raw_value = value
                                break
                    name = audit_sample_name(raw_value)
                    if name and name not in names:
                        names.append(name)
                    if len(names) >= limit:
                        break
                return names

            skipped_samples: list[Any] = []
            for key in ("alreadyManaged", "missingSources", "deletedAssets", "failures", "missingInputs"):
                value = result.get(key)
                if isinstance(value, list):
                    skipped_samples.extend(value)
            if int(result.get("candidateRowsUpdated", 0) or 0):
                self._refresh_project_candidates_from_db()
            self.project._append_audit(
                {
                    "action": "consolidate_photo_library_assets",
                    "managed_root": result.get("managedRoot", ""),
                    "run_root": result.get("runRoot", ""),
                    "selected_assets": int(result.get("selectedAssets", 0) or 0),
                    "consolidated_assets": int(result.get("consolidatedAssets", 0) or 0),
                    "skipped_assets": int(result.get("skippedAssets", 0) or 0),
                    "paired_motion_copied": int(result.get("pairedMotionCopiedCount", 0) or 0),
                    "related_media_copied": int(result.get("relatedMediaCopiedCount", 0) or 0),
                    "failures": len(result.get("failures", []) or []),
                    "operation_id": str((result.get("operation") or {}).get("operationId", "") or ""),
                    "copied_sample_names": audit_sample_names(result.get("samples"), "from", "sourcePath", "assetId"),
                    "skipped_sample_names": audit_sample_names(skipped_samples, "sourcePath", "from", "assetId"),
                    "companion_sample_names": audit_sample_names(
                        list(result.get("pairedMotionSamples", []) or []) + list(result.get("relatedMediaSamples", []) or []),
                        "from",
                        "sourcePath",
                        "assetId",
                    ),
                }
            )
        return result

    def list_photo_saved_filters(self, params: dict[str, Any]) -> dict[str, Any]:
        return {
            "filters": [
                self._photo_saved_filter_preview(row)
                for row in self.project.db.list_photo_saved_filters()
            ]
        }

    def save_photo_saved_filter(self, params: dict[str, Any]) -> dict[str, Any]:
        name = str(params.get("name", "") or "").strip()
        if not name:
            raise ValueError("Saved filter name is required.")
        filter_id = str(params.get("filterId", "") or params.get("id", "") or "").strip() or new_id("filter")
        raw_position = params.get("position", None)
        position = int(raw_position) if raw_position is not None and str(raw_position).strip() != "" else None
        raw_pinned = params.get("pinned", None)
        pinned = self._photo_query_bool(raw_pinned) if raw_pinned is not None else None
        saved = self.project.db.upsert_photo_saved_filter(
            filter_id=filter_id,
            name=name,
            description=str(params.get("description", "") or "").strip(),
            filters=self._photo_saved_filter_json_object(params.get("filters", {}), "filters"),
            rules=self._photo_saved_filter_json_object(params.get("rules", {}), "rules"),
            pinned=pinned,
            position=position,
        )
        saved = self._photo_saved_filter_preview(saved)
        self.project._append_audit(
            {
                "action": "save_photo_saved_filter",
                "filter_id": saved["filterId"],
                "name": saved["name"],
                "pinned": bool(saved.get("pinned", False)),
                "rule_count": len(saved.get("rules", {})),
            }
        )
        return saved

    def delete_photo_saved_filter(self, params: dict[str, Any]) -> dict[str, Any]:
        filter_id = str(params.get("filterId", "") or params.get("id", "") or "").strip()
        if not filter_id:
            raise ValueError("filterId is required.")
        deleted = self.project.db.delete_photo_saved_filter(filter_id)
        if deleted:
            self.project._append_audit({"action": "delete_photo_saved_filter", "filter_id": filter_id})
        return {"filterId": filter_id, "deleted": bool(deleted)}

    def preview_photo_album_rules(self, params: dict[str, Any]) -> dict[str, Any]:
        album_kind = str(params.get("albumKind", "smart") or "smart").strip().lower()
        if album_kind not in {"smart", "manual"}:
            raise ValueError("albumKind must be smart or manual.")
        include_people = self._clean_album_people(params.get("includePeople", []))
        exclude_people = self._clean_album_people(params.get("excludePeople", []))
        rules = self._clean_album_rules(params.get("rules", {}))
        if album_kind == "manual":
            include_people = []
            exclude_people = []
            rules = {}
        exclude_keys = {person.casefold() for person in exclude_people}
        include_people = [person for person in include_people if person.casefold() not in exclude_keys]
        album = {
            "albumId": str(params.get("albumId", "") or "preview"),
            "name": str(params.get("name", "") or "Preview"),
            "albumKind": album_kind,
            "description": str(params.get("description", "") or ""),
            "includePeople": include_people,
            "excludePeople": exclude_people,
            "rules": rules,
            "coverSourcePath": str(params.get("coverSourcePath", "") or "").strip(),
            "folderId": str(params.get("folderId", "") or "").strip(),
            "folderPosition": 0,
            "createdAt": "",
            "updatedAt": "",
        }
        summary = self._photo_album_summary(album) if album_kind == "smart" else None
        items: list[dict[str, Any]] = []
        if summary is not None:
            criteria = self._photo_smart_album_sql_criteria(album)
            if criteria is not None:
                sample_page = self._photo_smart_album_sql_page_for_criteria(criteria, offset=0, limit=3, sort="newest")
                items = self._photo_entries_for_assets(sample_page.get("assets", []))
            else:
                union_entries = self._photo_smart_album_entries_sql_union(album, sort="newest")
                items = union_entries[:3] if union_entries is not None else []
        elif album_kind == "smart":
            items = self._photo_album_items(album)
        sample_titles: list[str] = []
        for item in items[:3]:
            source = str(item.get("sourcePath", "") or "")
            metadata = self._photo_entry_metadata(item)
            title = str(metadata.get("title", "") or "").strip() or Path(source).name or source
            if title:
                sample_titles.append(title)
        validation = (
            self._photo_album_validation_from_summary(album, summary)
            if summary is not None
            else self._photo_album_validation(album, items)
        )
        return {
            "count": int(summary.get("count", 0) or 0) if summary is not None else len(items),
            "ruleSummary": self._photo_album_rule_summary(rules),
            "validation": validation,
            "previewSamples": sample_titles,
        }

    def save_photo_album(self, params: dict[str, Any]) -> dict[str, Any]:
        name = str(params.get("name", "") or "").strip()
        if not name:
            raise ValueError("Album name is required.")
        description = str(params.get("description", "") or "").strip()[:1200]
        album_kind = str(params.get("albumKind", "smart") or "smart").strip().lower()
        if album_kind not in {"smart", "manual"}:
            raise ValueError("albumKind must be smart or manual.")
        include_people = self._clean_album_people(params.get("includePeople", []))
        exclude_people = self._clean_album_people(params.get("excludePeople", []))
        rules = self._clean_album_rules(params.get("rules", {}))
        if album_kind == "manual":
            include_people = []
            exclude_people = []
            rules = {}
        exclude_keys = {person.casefold() for person in exclude_people}
        include_people = [person for person in include_people if person.casefold() not in exclude_keys]
        album_id = str(params.get("albumId", "") or "").strip() or new_id("album")
        cover_source_path = str(params.get("coverSourcePath", "") or "").strip()
        folder_id = str(params.get("folderId", "") or "").strip()
        raw_folder_position = params.get("folderPosition", None)
        folder_position = int(raw_folder_position) if raw_folder_position is not None and str(raw_folder_position).strip() != "" else None
        album = self.project.db.upsert_photo_album(
            album_id=album_id,
            name=name,
            album_kind=album_kind,
            description=description,
            include_people=include_people,
            exclude_people=exclude_people,
            rules=rules,
            cover_source_path=cover_source_path,
            folder_id=folder_id,
            folder_position=folder_position,
        )
        summary = self._photo_album_summary(album)
        folder = self._photo_album_folder(album, summary=summary) if summary is not None else self._photo_album_folder(album)
        self.project._append_audit(
            {
                "action": "save_photo_album",
                "album_id": album["albumId"],
                "name": album["name"],
                "album_kind": album.get("albumKind", "smart"),
                "include_count": len(album["includePeople"]),
                "exclude_count": len(album["excludePeople"]),
                "rule_count": len(rules),
                "cover_set": bool(album["coverSourcePath"]),
                "folder_id": album.get("folderId", ""),
            }
        )
        return {**album, "count": folder["count"], "validation": folder.get("validation", []), "ruleSummary": folder.get("ruleSummary", [])}

    def delete_photo_album(self, params: dict[str, Any]) -> dict[str, Any]:
        album_id = str(params.get("albumId", "") or "").strip()
        if not album_id:
            raise ValueError("albumId is required.")
        deleted = self.project.db.delete_photo_album(album_id)
        if deleted:
            self.project._append_audit({"action": "delete_photo_album", "album_id": album_id})
        return {"albumId": album_id, "deleted": int(deleted)}

    def _photo_query_status_condition(self, statuses: list[str]) -> dict[str, Any] | None:
        values = [str(status or "").strip().lower() for status in statuses if str(status or "").strip()]
        values = list(dict.fromkeys(values))
        if not values:
            return None
        if len(values) == 1:
            return {"field": "status", "operator": "is", "value": values[0]}
        return {
            "op": "any",
            "conditions": [
                {"field": "status", "operator": "is", "value": status}
                for status in values
            ],
        }

    def _photo_album_rules_as_query_dsl(self, album: dict[str, Any]) -> dict[str, Any] | None:
        conditions: list[dict[str, Any]] = []
        include_people = self._clean_album_people(album.get("includePeople", []))
        exclude_people = self._clean_album_people(album.get("excludePeople", []))
        if include_people:
            if len(include_people) == 1:
                conditions.append({"field": "person", "operator": "is", "value": include_people[0]})
            else:
                conditions.append({
                    "op": "any",
                    "conditions": [
                        {"field": "person", "operator": "is", "value": person}
                        for person in include_people
                    ],
                })
        for person in exclude_people:
            conditions.append({"field": "person", "operator": "isNot", "value": person})

        rules = self._clean_album_rules(album.get("rules", {}))
        status_condition = self._photo_query_status_condition(list(rules.get("statuses", []) or []))
        if status_condition:
            conditions.append(status_condition)
        if rules.get("query"):
            conditions.append({"field": "query", "operator": "contains", "value": str(rules["query"])})
        if rules.get("keyword"):
            conditions.append({"field": "keyword", "operator": "is", "value": str(rules["keyword"])})
        if rules.get("mediaKind"):
            conditions.append({"field": "mediaKind", "operator": "is", "value": str(rules["mediaKind"])})
        if rules.get("dateFrom"):
            conditions.append({"field": "date", "operator": "onOrAfter", "value": str(rules["dateFrom"])})
        if rules.get("dateTo"):
            conditions.append({"field": "date", "operator": "onOrBefore", "value": str(rules["dateTo"])})
        if rules.get("folder"):
            conditions.append({"field": "folder", "operator": "contains", "value": str(rules["folder"])})
        if rules.get("minScore"):
            conditions.append({"field": "score", "operator": "atLeast", "value": float(rules["minScore"])})
        if rules.get("minQuality"):
            conditions.append({"field": "quality", "operator": "atLeast", "value": float(rules["minQuality"])})
        if rules.get("favoriteOnly"):
            conditions.append({"field": "favorite", "operator": "is", "value": True})
        if rules.get("editedOnly"):
            conditions.append({"field": "edited", "operator": "is", "value": True})
        if rules.get("hasVideoFrames"):
            conditions.append({"field": "hasVideoFrames", "operator": "is", "value": True})
        if rules.get("unknownOnly"):
            conditions.append({"field": "unknown", "operator": "is", "value": True})
        if rules.get("recentDays"):
            conditions.append({"field": "recentDays", "operator": "withinLast", "value": int(rules["recentDays"])})
        query_dsl = self._album_rules_query_dsl(rules)
        if query_dsl:
            conditions.append(query_dsl)
        if not conditions:
            return None
        return {"op": "all", "conditions": conditions}

    def _photo_album_needs_smart_query_migration(self, album: dict[str, Any]) -> bool:
        if str(album.get("albumKind", "smart") or "smart") != "smart":
            return False
        if self._clean_album_people(album.get("includePeople", [])):
            return True
        if self._clean_album_people(album.get("excludePeople", [])):
            return True
        rules = self._clean_album_rules(album.get("rules", {}))
        legacy_rule_keys = {
            "statuses",
            "query",
            "keyword",
            "mediaKind",
            "dateFrom",
            "dateTo",
            "folder",
            "minScore",
            "minQuality",
            "favoriteOnly",
            "editedOnly",
            "hasVideoFrames",
            "unknownOnly",
            "recentDays",
            "queryDsl",
        }
        return any(key in rules for key in legacy_rule_keys)

    def _photo_smart_album_migration_record(
        self,
        album: dict[str, Any],
        *,
        apply_changes: bool,
        allow_count_delta: bool = False,
        force_record: bool = False,
    ) -> dict[str, Any] | None:
        if str(album.get("albumKind", "smart") or "smart") != "smart":
            if not force_record:
                return None
            return {
                "albumId": str(album.get("albumId", "") or ""),
                "name": str(album.get("name", "") or ""),
                "albumKind": str(album.get("albumKind", "smart") or "smart"),
                "needsMigration": False,
                "migrated": False,
                "beforeCount": 0,
                "afterCount": 0,
                "countDelta": 0,
                "includePeople": self._clean_album_people(album.get("includePeople", [])),
                "excludePeople": self._clean_album_people(album.get("excludePeople", [])),
                "rules": self._clean_album_rules(album.get("rules", {})),
                "ruleSummary": self._photo_album_rule_summary(self._clean_album_rules(album.get("rules", {}))),
                "validation": [],
            }

        needs_migration = self._photo_album_needs_smart_query_migration(album)
        if not needs_migration and not force_record:
            return None

        before_items = self._photo_album_items(album)
        converted = self._photo_album_rules_as_query_dsl(album)
        next_rules = self._clean_album_rules(converted or album.get("rules", {}))
        migrated_album = {
            **album,
            "includePeople": [],
            "excludePeople": [],
            "rules": next_rules,
        }
        after_items = self._photo_album_items(migrated_album)
        saved_album = migrated_album
        migrated = False
        if needs_migration and apply_changes:
            if len(before_items) != len(after_items) and not allow_count_delta:
                raise ValueError(
                    "Smart album migration changed the match count; run a dry-run and review before applying."
                )
            saved_album = self.project.db.upsert_photo_album(
                album_id=str(album.get("albumId", "") or ""),
                name=str(album.get("name", "") or ""),
                album_kind="smart",
                description=str(album.get("description", "") or ""),
                include_people=[],
                exclude_people=[],
                rules=next_rules,
                cover_source_path=str(album.get("coverSourcePath", "") or ""),
                folder_id=str(album.get("folderId", "") or ""),
                folder_position=int(album.get("folderPosition", 0) or 0),
            )
            migrated = True
        return {
            "albumId": str(saved_album.get("albumId", "") or album.get("albumId", "") or ""),
            "name": str(saved_album.get("name", "") or album.get("name", "") or ""),
            "albumKind": "smart",
            "needsMigration": bool(needs_migration),
            "migrated": migrated,
            "beforeCount": len(before_items),
            "afterCount": len(after_items),
            "countDelta": len(after_items) - len(before_items),
            "includePeople": self._clean_album_people(album.get("includePeople", [])),
            "excludePeople": self._clean_album_people(album.get("excludePeople", [])),
            "rules": next_rules,
            "ruleSummary": self._photo_album_rule_summary(next_rules),
            "validation": self._photo_album_validation(migrated_album, after_items),
        }

    def migrate_photo_smart_albums(self, params: dict[str, Any]) -> dict[str, Any]:
        album_id = str(params.get("albumId", params.get("id", "")) or "").strip()
        apply_value = params.get("apply", False)
        apply_changes = bool(apply_value) if isinstance(apply_value, bool) else self._photo_query_bool(apply_value) is True
        allow_count_delta_value = params.get("allowCountDelta", False)
        allow_count_delta = bool(allow_count_delta_value) if isinstance(allow_count_delta_value, bool) else self._photo_query_bool(allow_count_delta_value) is True
        raw_limit = params.get("limit", 200)
        try:
            limit = max(1, min(500, int(raw_limit)))
        except (TypeError, ValueError):
            limit = 200

        if album_id:
            album = self.project.db.photo_album_by_id(album_id)
            if album is None:
                raise ValueError("Unknown photo album id.")
            albums = [album]
        else:
            albums = self.project.db.list_photo_albums()[:limit]

        records: list[dict[str, Any]] = []
        for album in albums:
            record = self._photo_smart_album_migration_record(
                album,
                apply_changes=apply_changes,
                allow_count_delta=allow_count_delta,
                force_record=bool(album_id),
            )
            if record is not None:
                records.append(record)

        eligible = sum(1 for record in records if bool(record.get("needsMigration", False)))
        migrated = sum(1 for record in records if bool(record.get("migrated", False)))
        if migrated:
            self.project._append_audit(
                {
                    "action": "migrate_photo_smart_albums",
                    "album_id": album_id,
                    "eligible": eligible,
                    "migrated": migrated,
                }
            )
        return {
            "dryRun": not apply_changes,
            "requested": len(albums),
            "eligible": eligible,
            "migrated": migrated,
            "albums": records,
        }

    def _merged_photo_album_description(self, target: dict[str, Any], sources: list[dict[str, Any]]) -> str:
        parts: list[str] = []
        seen: set[str] = set()
        target_description = str(target.get("description", "") or "").strip()
        if target_description:
            parts.append(target_description)
            seen.add(target_description.casefold())
        for source in sources:
            description = str(source.get("description", "") or "").strip()
            if not description:
                continue
            text = f"Merged from {str(source.get('name', '') or 'album')}: {description}"
            key = text.casefold()
            if key in seen:
                continue
            seen.add(key)
            parts.append(text)
        return "\n\n".join(parts)[:1200]

    def _merged_photo_album_cover(self, target: dict[str, Any], sources: list[dict[str, Any]]) -> str:
        cover = str(target.get("coverSourcePath", "") or "").strip()
        if cover:
            return cover
        for source in sources:
            source_cover = str(source.get("coverSourcePath", "") or "").strip()
            if source_cover:
                return source_cover
        return ""

    def merge_photo_albums(self, params: dict[str, Any]) -> dict[str, Any]:
        target_album_id = str(params.get("targetAlbumId", params.get("albumId", "")) or "").strip()
        if not target_album_id:
            raise ValueError("targetAlbumId is required.")
        raw_sources = params.get("sourceAlbumIds", params.get("sourceIds", []))
        if isinstance(raw_sources, str):
            raw_sources = [raw_sources]
        if not isinstance(raw_sources, list):
            raise ValueError("sourceAlbumIds must be a list.")
        source_album_ids: list[str] = []
        seen_sources: set[str] = {target_album_id}
        for value in raw_sources:
            source_id = str(value or "").strip()
            if not source_id or source_id in seen_sources:
                continue
            seen_sources.add(source_id)
            source_album_ids.append(source_id)
        if not source_album_ids:
            raise ValueError("At least one source album is required.")
        if len(source_album_ids) > 24:
            raise ValueError("At most 24 source albums can be merged at once.")

        target = self.project.db.photo_album_by_id(target_album_id)
        if target is None:
            raise ValueError("Unknown target photo album id.")
        sources: list[dict[str, Any]] = []
        for source_id in source_album_ids:
            source = self.project.db.photo_album_by_id(source_id)
            if source is None:
                raise ValueError(f"Unknown source photo album id: {source_id}")
            sources.append(source)

        target_kind = str(target.get("albumKind", "smart") or "smart")
        delete_sources = params.get("deleteSourceAlbums", True) is not False
        description = self._merged_photo_album_description(target, sources)
        cover_source_path = self._merged_photo_album_cover(target, sources)
        added = 0
        duplicates = 0
        missing = 0
        merged_source_paths = 0

        if target_kind == "manual":
            for source in sources:
                if str(source.get("albumKind", "smart") or "smart") == "manual":
                    source_paths = [
                        str(asset.get("sourcePath", "") or "")
                        for asset in self.project.db.list_photo_album_assets(str(source.get("albumId", "") or ""))
                    ]
                else:
                    source_paths = [
                        str(item.get("sourcePath", "") or "")
                        for item in self._photo_album_items(source)
                    ]
                source_paths = [path for path in source_paths if path]
                merged_source_paths += len(source_paths)
                result = self.project.db.add_photo_album_items(target_album_id, source_paths)
                added += int(result.get("added", 0) or 0)
                duplicates += int(result.get("duplicates", 0) or 0)
                missing += int(result.get("missing", 0) or 0)
            target = self.project.db.upsert_photo_album(
                album_id=str(target["albumId"]),
                name=str(target.get("name", "") or ""),
                album_kind="manual",
                description=description,
                include_people=[],
                exclude_people=[],
                rules={},
                cover_source_path=cover_source_path,
                folder_id=str(target.get("folderId", "") or ""),
                folder_position=int(target.get("folderPosition", 0) or 0),
            )
        else:
            if any(str(source.get("albumKind", "smart") or "smart") == "manual" for source in sources):
                raise ValueError("Manual albums can only be merged into a manual target album.")
            album_logic: list[dict[str, Any]] = []
            all_photos = False
            for album in [target, *sources]:
                logic = self._photo_album_rules_as_query_dsl(album)
                if logic is None:
                    all_photos = True
                    break
                album_logic.append(logic)
            merged_rules = {} if all_photos else self._clean_album_rules({"op": "any", "conditions": album_logic})
            target = self.project.db.upsert_photo_album(
                album_id=str(target["albumId"]),
                name=str(target.get("name", "") or ""),
                album_kind="smart",
                description=description,
                include_people=[],
                exclude_people=[],
                rules=merged_rules,
                cover_source_path=cover_source_path,
                folder_id=str(target.get("folderId", "") or ""),
                folder_position=int(target.get("folderPosition", 0) or 0),
            )

        deleted_source_album_ids: list[str] = []
        if delete_sources:
            for source in sources:
                source_id = str(source.get("albumId", "") or "")
                if source_id and self.project.db.delete_photo_album(source_id):
                    deleted_source_album_ids.append(source_id)

        folder = self._photo_album_folder(target)
        self.project._append_audit(
            {
                "action": "merge_photo_albums",
                "target_album_id": str(target.get("albumId", "") or ""),
                "source_album_ids": source_album_ids,
                "deleted_source_album_ids": deleted_source_album_ids,
                "album_kind": target_kind,
                "added": added,
                "duplicates": duplicates,
                "missing": missing,
            }
        )
        return {
            "targetAlbumId": str(target.get("albumId", "") or ""),
            "sourceAlbumIds": source_album_ids,
            "deletedSourceAlbumIds": deleted_source_album_ids,
            "albumKind": target_kind,
            "added": added,
            "duplicates": duplicates,
            "missing": missing,
            "mergedSourcePaths": merged_source_paths,
            "count": int(folder.get("count", 0) or 0),
            "folder": folder,
        }

    def list_photo_album_folders(self, params: dict[str, Any]) -> dict[str, Any]:
        albums = self.project.db.list_photo_albums()
        return {
            "folders": [
                self._photo_album_folder_node(
                    folder,
                    summary=self._photo_album_folder_summary(str(folder.get("folderId", "") or ""), albums=albums),
                    albums=albums,
                )
                for folder in self.project.db.list_photo_album_folders()
            ]
        }

    def save_photo_album_folder(self, params: dict[str, Any]) -> dict[str, Any]:
        name = str(params.get("name", "") or "").strip()
        if not name:
            raise ValueError("Album folder name is required.")
        folder_id = str(params.get("folderId", "") or "").strip() or new_id("albumFolder")
        parent_folder_id = str(params.get("parentFolderId", "") or "").strip()
        raw_position = params.get("position", None)
        position = int(raw_position) if raw_position is not None and str(raw_position).strip() != "" else None
        folder = self.project.db.upsert_photo_album_folder(
            folder_id=folder_id,
            name=name,
            parent_folder_id=parent_folder_id,
            position=position,
        )
        node = self._photo_album_folder_node(folder)
        self.project._append_audit(
            {
                "action": "save_photo_album_folder",
                "folder_id": folder["folderId"],
                "name": folder["name"],
                "parent_folder_id": folder.get("parentFolderId", ""),
            }
        )
        return node

    def delete_photo_album_folder(self, params: dict[str, Any]) -> dict[str, Any]:
        folder_id = str(params.get("folderId", "") or "").strip()
        if not folder_id:
            raise ValueError("folderId is required.")
        deleted = self.project.db.delete_photo_album_folder(folder_id)
        if deleted:
            self.project._append_audit({"action": "delete_photo_album_folder", "folder_id": folder_id})
        return {"folderId": folder_id, "deleted": int(deleted)}

    def move_photo_album_to_folder(self, params: dict[str, Any]) -> dict[str, Any]:
        album_id = str(params.get("albumId", "") or "").strip()
        if not album_id:
            raise ValueError("albumId is required.")
        folder_id = str(params.get("folderId", "") or "").strip()
        raw_position = params.get("position", params.get("folderPosition", None))
        position = int(raw_position) if raw_position is not None and str(raw_position).strip() != "" else None
        album = self.project.db.move_photo_album_to_folder(album_id, folder_id, position=position)
        folder = self._photo_album_folder(album)
        self.project._append_audit(
            {
                "action": "move_photo_album_to_folder",
                "album_id": album_id,
                "folder_id": album.get("folderId", ""),
            }
        )
        return {**album, "count": folder["count"], "folder": folder}

    def reorder_photo_album_folder_children(self, params: dict[str, Any]) -> dict[str, Any]:
        parent_folder_id = str(params.get("parentFolderId", "") or "").strip()
        items = params.get("items", [])
        if not isinstance(items, list):
            raise ValueError("items must be a list.")
        clean_items: list[dict[str, Any]] = []
        for item in items:
            if not isinstance(item, dict):
                continue
            kind = str(item.get("kind", "") or "").strip()
            item_id = str(item.get("id", item.get("itemId", "")) or "").strip()
            if kind in {"album", "albumFolder", "folder"} and item_id:
                clean_items.append({"kind": kind, "id": item_id})
        result = self.project.db.reorder_photo_album_folder_children(parent_folder_id, clean_items)
        if result.get("updated", 0):
            self.project._append_audit(
                {
                    "action": "reorder_photo_album_folder_children",
                    "parent_folder_id": parent_folder_id,
                    "requested": result.get("requested", 0),
                    "updated": result.get("updated", 0),
                }
            )
        return result

    def _photo_album_source_paths_param(self, params: dict[str, Any]) -> list[str]:
        values = params.get("sourcePaths", [])
        if not isinstance(values, list):
            raise ValueError("sourcePaths must be a list.")
        return [str(value or "").strip() for value in values if str(value or "").strip()]

    def add_photo_album_items(self, params: dict[str, Any]) -> dict[str, Any]:
        album_id = str(params.get("albumId", "") or "").strip()
        if not album_id:
            raise ValueError("albumId is required.")
        source_paths = self._photo_album_source_paths_param(params)
        result = self.project.db.add_photo_album_items(album_id, source_paths)
        album = self.project.db.photo_album_by_id(album_id)
        folder = self._photo_album_folder(album) if album else {}
        self.project._append_audit(
            {
                "action": "add_photo_album_items",
                "album_id": album_id,
                "added": result.get("added", 0),
                "duplicates": result.get("duplicates", 0),
                "requested": result.get("requested", 0),
                "operation_id": (result.get("operation") or {}).get("operationId", "") if isinstance(result.get("operation"), dict) else "",
            }
        )
        return {**result, "count": folder.get("count", result.get("itemCount", 0)), "folder": folder}

    def remove_photo_album_items(self, params: dict[str, Any]) -> dict[str, Any]:
        album_id = str(params.get("albumId", "") or "").strip()
        if not album_id:
            raise ValueError("albumId is required.")
        source_paths = self._photo_album_source_paths_param(params)
        result = self.project.db.remove_photo_album_items(album_id, source_paths)
        album = self.project.db.photo_album_by_id(album_id)
        folder = self._photo_album_folder(album) if album else {}
        if result.get("removed", 0):
            self.project._append_audit(
                {
                    "action": "remove_photo_album_items",
                    "album_id": album_id,
                    "removed": result.get("removed", 0),
                    "requested": result.get("requested", 0),
                    "operation_id": (result.get("operation") or {}).get("operationId", "") if isinstance(result.get("operation"), dict) else "",
                }
            )
        return {**result, "count": folder.get("count", result.get("itemCount", 0)), "folder": folder}

    def reorder_photo_album_items(self, params: dict[str, Any]) -> dict[str, Any]:
        album_id = str(params.get("albumId", "") or "").strip()
        if not album_id:
            raise ValueError("albumId is required.")
        source_paths = self._photo_album_source_paths_param(params)
        result = self.project.db.reorder_photo_album_items(album_id, source_paths)
        if result.get("updated", 0):
            self.project._append_audit(
                {
                    "action": "reorder_photo_album_items",
                    "album_id": album_id,
                    "updated": result.get("updated", 0),
                    "requested": result.get("requested", 0),
                    "missing": result.get("missing", 0),
                    "duplicates": result.get("duplicates", 0),
                    "appended": result.get("appended", 0),
                    "operation_id": (result.get("operation") or {}).get("operationId", "") if isinstance(result.get("operation"), dict) else "",
                }
            )
        return result

    def _candidate_album_keys(self, candidate: ReviewCandidate) -> set[str]:
        return self._photo_source_keys(candidate)

    def _album_candidate_people_by_source(self) -> dict[str, set[str]]:
        people_by_source: dict[str, set[str]] = {}
        for source, matches in self._photo_matches_by_source().items():
            for candidate in matches:
                if not self._photo_person_match(candidate):
                    continue
                person = str(candidate.person_name or "").strip()
                if person:
                    people_by_source.setdefault(source, set()).add(person.casefold())
        return people_by_source

    def _photo_album_items(self, album: dict[str, Any]) -> list[dict[str, Any]]:
        if str(album.get("albumKind", "smart")) == "manual":
            matches_by_source = self._photo_matches_by_source()
            entries: list[dict[str, Any]] = []
            for asset in self.project.db.list_photo_album_assets(str(album.get("albumId", "") or "")):
                source_path = str(asset.get("sourcePath", "") or "")
                if not source_path:
                    continue
                entry = self._photo_source_entry(
                    source_path=source_path,
                    media_kind=str(asset.get("mediaKind", "") or self._media_kind_for_source(source_path)),
                    matches_by_source=matches_by_source,
                    scan_date=str(asset.get("albumAddedAt", "") or asset.get("addedAt", "") or ""),
                )
                if not self._photo_entry_default_visible(entry):
                    continue
                entries.append(entry)
            return entries

        include_keys = {str(person).casefold() for person in album.get("includePeople", []) if str(person).strip()}
        exclude_keys = {str(person).casefold() for person in album.get("excludePeople", []) if str(person).strip()}
        rules = self._clean_album_rules(album.get("rules", {}))
        if self._photo_rules_mention_query_field(rules, "duplicate"):
            self.project.db.ensure_photo_duplicate_groups()
        include_hidden_deleted = self._photo_rules_mention_query_field(rules, "hidden") or self._photo_rules_mention_query_field(rules, "deleted")
        matches_by_source = self._photo_matches_by_source()
        entries: list[dict[str, Any]] = []
        seen: set[str] = set()

        rows = self._all_photo_entries(matches_by_source)
        for row in rows:
            source_path = str(row.get("sourcePath", "") or "")
            if not source_path or source_path in seen:
                continue
            if not include_hidden_deleted and not self._photo_entry_default_visible(row):
                continue
            if not self._photo_album_entry_included(row, include_keys):
                continue
            if self._photo_album_entry_excluded(row, exclude_keys):
                continue
            if not self._photo_album_entry_matches_rules(row, rules):
                continue
            seen.add(source_path)
            entries.append(row)

        # Test/dev workspaces can still hold raw in-memory candidates that have
        # not been persisted into photo_assets yet. Keep them visible without
        # making them the primary smart-album read path.
        for candidate in sorted(
            self.project.candidates.values(),
            key=lambda c: (c.capture_date or "", c.created_at, c.candidate_id),
            reverse=True,
        ):
            person_key = str(candidate.person_name or "").casefold()
            if not self._photo_person_match(candidate):
                continue
            if include_keys and person_key not in include_keys:
                continue
            source_path = self._photo_tile_source(candidate)
            if not source_path or source_path in seen:
                continue
            entry = self._photo_source_entry(
                source_path=source_path,
                media_kind=str(candidate.media_kind or self._media_kind_for_source(source_path)),
                matches_by_source=matches_by_source,
                candidate=candidate,
            )
            if not self._photo_entry_default_visible(entry):
                continue
            if not self._photo_album_entry_included(entry, include_keys):
                continue
            if self._photo_album_entry_excluded(entry, exclude_keys):
                continue
            if not self._photo_album_entry_matches_rules(entry, rules):
                continue
            seen.add(source_path)
            entries.append(entry)
        return self._sort_photo_entries(entries, "newest")

    def _photo_entry_in_manual_album(self, entry: dict[str, Any]) -> bool:
        source_path = str(entry.get("sourcePath", "") or "")
        if not source_path:
            return False
        asset = self.project.db.photo_asset_by_path(source_path)
        if not asset:
            return False
        return bool(self.project.db.list_photo_asset_album_memberships(str(asset.get("assetId", "") or "")))

    def _filter_photo_entries_not_in_manual_album(self, entries: list[dict[str, Any]]) -> list[dict[str, Any]]:
        return [entry for entry in entries if not self._photo_entry_in_manual_album(entry)]

    def _photo_manual_album_filter_ids(self, album_filter: str) -> tuple[str, ...] | None:
        clean = str(album_filter or "").strip()
        if clean.startswith("album:"):
            clean = clean[len("album:"):]
        if not clean:
            return ()
        clean_key = clean.casefold()
        album_ids: list[str] = []
        for album in self.project.db.list_photo_albums():
            album_id = str(album.get("albumId", "") or "")
            album_name = str(album.get("name", "") or "")
            if clean not in {album_id, f"album:{album_id}"} and clean_key != album_name.casefold():
                continue
            if str(album.get("albumKind", "smart") or "smart") != "manual":
                return None
            if album_id and album_id not in album_ids:
                album_ids.append(album_id)
        return tuple(album_ids)

    def _photo_album_filter_source_set(self, album_filter: str) -> set[str]:
        clean = str(album_filter or "").strip()
        if clean.startswith("album:"):
            clean = clean[len("album:"):]
        if not clean:
            return set()
        clean_key = clean.casefold()
        sources: set[str] = set()
        for album in self.project.db.list_photo_albums():
            album_id = str(album.get("albumId", "") or "")
            album_name = str(album.get("name", "") or "")
            if clean not in {album_id, f"album:{album_id}"} and clean_key != album_name.casefold():
                continue
            if str(album.get("albumKind", "smart") or "smart") == "manual":
                for asset in self.project.db.list_photo_album_assets(album_id):
                    source = str(asset.get("sourcePath", "") or "")
                    if source:
                        sources.add(source)
            else:
                for item in self._photo_album_items(album):
                    source = str(item.get("sourcePath", "") or "")
                    if source:
                        sources.add(source)
        return sources

    def _filter_photo_entries_by_album_filter(self, entries: list[dict[str, Any]], album_filter: str) -> list[dict[str, Any]]:
        clean = str(album_filter or "").strip()
        if not clean:
            return entries
        sources = self._photo_album_filter_source_set(clean)
        return [entry for entry in entries if str(entry.get("sourcePath", "") or "") in sources]

    def _normalize_photo_visibility_filter(self, value: Any, *, hidden_only: bool = False, deleted_only: bool = False) -> str:
        if hidden_only:
            return "hidden"
        if deleted_only:
            return "deleted"
        clean = str(value or "").strip().casefold()
        aliases = {
            "all": "all",
            "any": "all",
            "everything": "all",
            "visible": "visible",
            "default": "visible",
            "hidden": "hidden",
            "private": "hidden",
            "deleted": "deleted",
            "recentlydeleted": "deleted",
            "trash": "deleted",
        }
        return aliases.get(clean, "")

    def _filter_photo_entries_by_visibility_filter(self, entries: list[dict[str, Any]], visibility: str) -> list[dict[str, Any]]:
        clean = str(visibility or "").strip().lower()
        if clean == "all" or not clean:
            return entries
        if clean == "hidden":
            return [entry for entry in entries if self._photo_entry_hidden(entry) and not self._photo_entry_deleted(entry)]
        if clean == "deleted":
            return [entry for entry in entries if self._photo_entry_deleted(entry)]
        if clean == "visible":
            return self._visible_photo_entries(entries)
        return entries

    def _photo_entry_matches_candidate_filters(
        self,
        entry: dict[str, Any],
        *,
        person: str = "",
        status: str = "",
        min_quality: float = 0.0,
    ) -> bool:
        person_key = str(person or "").strip().casefold()
        status_key = str(status or "").strip().lower()
        if status_key not in {"", "pending", "accepted", "rejected", "uncertain"}:
            status_key = ""
        quality_floor = max(0.0, min(1.0, float(min_quality or 0.0)))
        if not person_key and not status_key and not quality_floor:
            return True
        for match in entry.get("matches", []) or []:
            if not isinstance(match, ReviewCandidate):
                continue
            if person_key and str(match.person_name or "").casefold() != person_key:
                continue
            if status_key and str(match.status or "").lower() != status_key:
                continue
            if quality_floor and float(match.quality or 0.0) < quality_floor:
                continue
            return True
        for person in self._photo_entry_people_rows(entry):
            if person_key and str(person.get("personName", "") or "").casefold() != person_key:
                continue
            if status_key and str(person.get("status", "") or "").lower() != status_key:
                continue
            if quality_floor and float(person.get("quality", 0.0) or 0.0) < quality_floor:
                continue
            return True
        return False

    def _filter_photo_entries_by_candidate_filters(
        self,
        entries: list[dict[str, Any]],
        *,
        person: str = "",
        status: str = "",
        min_quality: float = 0.0,
    ) -> list[dict[str, Any]]:
        return [
            entry for entry in entries
            if self._photo_entry_matches_candidate_filters(
                entry,
                person=person,
                status=status,
                min_quality=min_quality,
            )
        ]

    def _normalize_photo_date_filter(self, value: Any) -> str:
        text = str(value or "").strip()[:10]
        return text if re.match(r"^\d{4}-\d{2}-\d{2}$", text) else ""

    def _photo_file_type_aliases(self, value: str) -> set[str]:
        clean = str(value or "").strip().lower().lstrip(".")
        if not clean:
            return set()
        if clean in {"jpg", "jpeg"}:
            return {"jpg", "jpeg"}
        if clean in {"heic", "heif"}:
            return {"heic", "heif"}
        if clean in {"tif", "tiff"}:
            return {"tif", "tiff"}
        return {clean}

    def _photo_entry_file_type(self, entry: dict[str, Any]) -> str:
        source_path = str(entry.get("sourcePath", "") or "")
        return Path(source_path).suffix.lower().lstrip(".")

    def _photo_entry_asset(self, entry: dict[str, Any]) -> dict[str, Any] | None:
        cached_asset = entry.get("_asset")
        if isinstance(cached_asset, dict):
            return cached_asset
        source_path = str(entry.get("sourcePath", "") or "")
        asset = self.project.db.photo_asset_by_path(source_path) if source_path else None
        if asset:
            entry["_asset"] = asset
        return asset

    def _photo_entry_duplicate_group(self, entry: dict[str, Any]) -> dict[str, Any] | None:
        asset = self._photo_entry_asset(entry)
        asset_id = str(asset.get("assetId", "") or "") if asset else ""
        return self.project.db.photo_duplicate_group_for_asset(asset_id) if asset_id else None

    def _photo_entry_signal_bool(self, value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        return str(value or "").strip().lower() in {"1", "true", "yes", "on"}

    def _photo_entry_duplicate_count(self, entry: dict[str, Any]) -> int:
        for key in ("duplicateCount", "_duplicateCount"):
            try:
                value = int(entry.get(key, 0) or 0)
            except (TypeError, ValueError):
                value = 0
            if value > 0:
                return value
        group = entry.get("duplicateGroup", {}) if isinstance(entry.get("duplicateGroup", {}), dict) else {}
        if str(group.get("groupId", group.get("id", "")) or "").strip():
            try:
                return max(1, int(group.get("count", 1) or 1))
            except (TypeError, ValueError):
                return 1
        if str(entry.get("duplicateGroupId", "") or "").strip():
            return 1
        if self._photo_entry_signal_bool(entry.get("duplicate")) or self._photo_entry_signal_bool(entry.get("duplicateState")):
            return 1
        group = self._photo_entry_duplicate_group(entry)
        if not group:
            return 0
        try:
            return max(1, int(group.get("count", 1) or 1))
        except (TypeError, ValueError):
            return 1

    def _photo_entry_edit_stack_version_count(self, entry: dict[str, Any]) -> int:
        for key in ("editStackVersionCount", "versionCount", "_editStackVersionCount"):
            try:
                value = int(entry.get(key, 0) or 0)
            except (TypeError, ValueError):
                value = 0
            if value > 0:
                return value
        if self._photo_entry_signal_bool(entry.get("hasEditStackVersions")):
            return 1
        asset = self._photo_entry_asset(entry)
        asset_id = str(asset.get("assetId", "") or "") if asset else ""
        if not asset_id:
            return 0
        return int(self.project.db.photo_edit_stack_version_counts_for_assets([asset_id]).get(asset_id, 0) or 0)

    def _photo_annotate_date_bucket_relation_counts(self, entries: list[dict[str, Any]]) -> None:
        asset_ids_by_entry: list[tuple[dict[str, Any], str]] = []
        seen_asset_ids: set[str] = set()
        for entry in entries:
            asset_id = str(entry.get("_assetId", "") or "").strip()
            if not asset_id:
                asset = entry.get("_asset")
                if isinstance(asset, dict):
                    asset_id = str(asset.get("assetId", "") or "").strip()
            if not asset_id:
                asset = self._photo_entry_asset(entry)
                asset_id = str(asset.get("assetId", "") or "").strip() if asset else ""
            if not asset_id:
                continue
            asset_ids_by_entry.append((entry, asset_id))
            seen_asset_ids.add(asset_id)
        if not seen_asset_ids:
            return
        asset_ids = sorted(seen_asset_ids)
        version_counts = self.project.db.photo_edit_stack_version_counts_for_assets(asset_ids)
        duplicate_asset_ids: set[str] = set()
        with self.project.db.connect() as conn:
            for start in range(0, len(asset_ids), 800):
                chunk = asset_ids[start:start + 800]
                placeholders = ",".join("?" for _ in chunk)
                rows = conn.execute(
                    f"""
                    SELECT DISTINCT asset_id
                    FROM photo_duplicate_group_items
                    WHERE asset_id IN ({placeholders})
                    """,
                    tuple(chunk),
                ).fetchall()
                duplicate_asset_ids.update(str(row["asset_id"] or "") for row in rows if str(row["asset_id"] or ""))
        for entry, asset_id in asset_ids_by_entry:
            entry["_duplicateCount"] = 1 if asset_id in duplicate_asset_ids else 0
            entry["_editStackVersionCount"] = int(version_counts.get(asset_id, 0) or 0)

    def _photo_place_labels_by_asset_id(self) -> dict[str, list[str]]:
        labels: dict[str, list[str]] = {}
        for place in self.project.db.list_photo_places():
            values = [
                str(place.get("label", "") or ""),
                str(place.get("name", "") or ""),
                str(place.get("inferredFrom", "") or ""),
            ]
            clean_values: list[str] = []
            for value in values:
                text = value.strip()
                if text and text not in clean_values:
                    clean_values.append(text)
            if not clean_values:
                continue
            for asset_id in place.get("assetIds", []) or []:
                asset_key = str(asset_id or "")
                if asset_key:
                    labels.setdefault(asset_key, [])
                    for value in clean_values:
                        if value not in labels[asset_key]:
                            labels[asset_key].append(value)
        return labels

    def _photo_place_labels_by_asset_id_for_asset_ids(self, asset_ids: Iterable[str]) -> dict[str, list[str]]:
        return self.project.db.photo_place_labels_for_asset_ids(asset_ids)

    def _photo_location_filter_asset_ids(self, location: str) -> tuple[str, ...]:
        needle = str(location or "").strip().casefold()
        if not needle:
            return ()
        matched: dict[str, None] = {}
        for place in self.project.db.list_photo_places():
            values = [
                str(place.get("label", "") or ""),
                str(place.get("name", "") or ""),
                str(place.get("inferredFrom", "") or ""),
            ]
            if not any(needle in value.casefold() for value in values if value.strip()):
                continue
            for asset_id in place.get("assetIds", []) or []:
                asset_key = str(asset_id or "").strip()
                if asset_key:
                    matched.setdefault(asset_key, None)
        return tuple(matched.keys())

    def _photo_entry_location_text(
        self,
        entry: dict[str, Any],
        place_labels_by_asset_id: dict[str, list[str]] | None = None,
    ) -> list[str]:
        metadata = self._photo_entry_metadata(entry)
        if bool(metadata.get("locationHidden", False)):
            return []
        parts: list[str] = []
        override = metadata.get("locationOverride", {}) if isinstance(metadata.get("locationOverride", {}), dict) else {}
        for key in ("label", "latitude", "longitude"):
            value = str(override.get(key, "") or "").strip()
            if value:
                parts.append(value)
        asset = self._photo_entry_asset(entry)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata", {}), dict) else {}
        exif = asset_metadata.get("exif", {}) if isinstance(asset_metadata.get("exif", {}), dict) else {}
        gps = exif.get("gps", {}) if isinstance(exif.get("gps", {}), dict) else {}
        for key in ("latitude", "longitude", "source"):
            value = str(gps.get(key, "") or "").strip()
            if value:
                parts.append(value)
        if place_labels_by_asset_id is not None and asset:
            asset_id = str(asset.get("assetId", "") or "")
            for value in place_labels_by_asset_id.get(asset_id, []):
                if value and value not in parts:
                    parts.append(value)
        return parts

    def _photo_coordinate_value(self, value: Any, *, minimum: float, maximum: float) -> float | None:
        try:
            number = float(str(value).strip())
        except (TypeError, ValueError):
            return None
        if not math.isfinite(number) or number < minimum or number > maximum:
            return None
        return number

    def _photo_entry_coordinates(self, entry: dict[str, Any]) -> tuple[float, float] | None:
        metadata = self._photo_entry_metadata(entry)
        if bool(metadata.get("locationHidden", False)):
            return None
        override = metadata.get("locationOverride", {}) if isinstance(metadata.get("locationOverride", {}), dict) else {}
        latitude = self._photo_coordinate_value(override.get("latitude", override.get("lat", "")), minimum=-90.0, maximum=90.0)
        longitude = self._photo_coordinate_value(override.get("longitude", override.get("lon", override.get("lng", ""))), minimum=-180.0, maximum=180.0)
        if latitude is not None and longitude is not None:
            return (latitude, longitude)
        asset = self._photo_entry_asset(entry)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata", {}), dict) else {}
        exif = asset_metadata.get("exif", {}) if isinstance(asset_metadata.get("exif", {}), dict) else {}
        gps = exif.get("gps", {}) if isinstance(exif.get("gps", {}), dict) else {}
        latitude = self._photo_coordinate_value(gps.get("latitude", gps.get("lat", "")), minimum=-90.0, maximum=90.0)
        longitude = self._photo_coordinate_value(gps.get("longitude", gps.get("lon", gps.get("lng", ""))), minimum=-180.0, maximum=180.0)
        return (latitude, longitude) if latitude is not None and longitude is not None else None

    def _photo_distance_km(self, left: tuple[float, float], right: tuple[float, float]) -> float:
        lat1 = math.radians(left[0])
        lon1 = math.radians(left[1])
        lat2 = math.radians(right[0])
        lon2 = math.radians(right[1])
        d_lat = lat2 - lat1
        d_lon = lon2 - lon1
        a = math.sin(d_lat / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin(d_lon / 2) ** 2
        return 6371.0 * 2 * math.atan2(math.sqrt(a), math.sqrt(max(0.0, 1 - a)))

    def _photo_nearby_filter_from_params(self, params: dict[str, Any]) -> dict[str, float] | None:
        source = params.get("nearby") if isinstance(params.get("nearby"), dict) else {}
        if not isinstance(source, dict):
            source = {}
        latitude = self._photo_coordinate_value(
            params.get("nearbyLatitude", params.get("latitude", params.get("lat", source.get("latitude", source.get("lat", ""))))),
            minimum=-90.0,
            maximum=90.0,
        )
        longitude = self._photo_coordinate_value(
            params.get("nearbyLongitude", params.get("longitude", params.get("lon", params.get("lng", source.get("longitude", source.get("lon", source.get("lng", ""))))))),
            minimum=-180.0,
            maximum=180.0,
        )
        if latitude is None or longitude is None:
            return None
        radius_raw = params.get("nearbyRadiusKm", params.get("radiusKm", params.get("radius", source.get("radiusKm", source.get("radius", 25)))))
        try:
            radius = float(str(radius_raw).strip())
        except (TypeError, ValueError):
            radius = 25.0
        if not math.isfinite(radius):
            radius = 25.0
        return {
            "latitude": latitude,
            "longitude": longitude,
            "radiusKm": max(0.1, min(500.0, radius)),
        }

    def _photo_nearby_filter_from_query_value(self, value: Any) -> dict[str, float] | None:
        raw_values = self._photo_query_values(value)
        raw = raw_values[0] if raw_values else None
        if isinstance(raw, dict):
            return self._photo_nearby_filter_from_params(raw)
        text = str(raw or "").strip()
        if not text:
            return None
        parts = [part for part in re.split(r"[,;|\s]+", text) if part]
        if len(parts) < 2:
            return None
        return self._photo_nearby_filter_from_params({
            "nearbyLatitude": parts[0],
            "nearbyLongitude": parts[1],
            "nearbyRadiusKm": parts[2] if len(parts) >= 3 else 25,
        })

    def _photo_entry_matches_nearby_filter(self, entry: dict[str, Any], nearby: dict[str, float] | None) -> bool:
        if not nearby:
            return True
        coordinates = self._photo_entry_coordinates(entry)
        if coordinates is None:
            return False
        center = (float(nearby["latitude"]), float(nearby["longitude"]))
        return self._photo_distance_km(center, coordinates) <= float(nearby["radiusKm"])

    def _photo_entry_camera_text(self, entry: dict[str, Any]) -> list[str]:
        asset = self._photo_entry_asset(entry)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata", {}), dict) else {}
        exif = asset_metadata.get("exif", {}) if isinstance(asset_metadata.get("exif", {}), dict) else {}
        values = [
            str(exif.get("cameraMake", "") or ""),
            str(exif.get("cameraModel", "") or ""),
            str(exif.get("lensModel", "") or ""),
            str(exif.get("software", "") or ""),
        ]
        return [value for value in values if value.strip()]

    def _photo_entry_asset_number(self, entry: dict[str, Any], key: str) -> float | None:
        asset = self._photo_entry_asset(entry)
        if not asset:
            return None
        try:
            number = float(asset.get(key))
        except (TypeError, ValueError):
            return None
        return number if math.isfinite(number) else None

    def _photo_entry_score_values(self, entry: dict[str, Any]) -> list[float]:
        values: list[float] = []
        for match in entry.get("matches", []) or []:
            if isinstance(match, ReviewCandidate):
                values.append(float(match.score or 0.0))
        for person in self._photo_entry_people_rows(entry):
            try:
                values.append(float(person.get("score", 0.0) or 0.0))
            except (TypeError, ValueError):
                continue
        for key in ("bestScore", "score"):
            try:
                value = float(entry.get(key, 0.0) or 0.0)
            except (TypeError, ValueError):
                value = 0.0
            if value:
                values.append(value)
        return [value for value in values if math.isfinite(value)]

    def _photo_entry_quality_values(self, entry: dict[str, Any]) -> list[float]:
        values: list[float] = []
        for match in entry.get("matches", []) or []:
            if isinstance(match, ReviewCandidate):
                values.append(float(match.quality or 0.0))
        for person in self._photo_entry_people_rows(entry):
            try:
                values.append(float(person.get("quality", 0.0) or 0.0))
            except (TypeError, ValueError):
                continue
        for key in ("bestQuality", "quality"):
            try:
                value = float(entry.get(key, 0.0) or 0.0)
            except (TypeError, ValueError):
                value = 0.0
            if value:
                values.append(value)
        return [value for value in values if math.isfinite(value)]

    def _photo_entry_face_count(self, entry: dict[str, Any]) -> int:
        direct_people = entry.get("people", [])
        if isinstance(direct_people, list) and direct_people:
            return len([person for person in direct_people if isinstance(person, dict) and str(person.get("personName", "") or "").strip()])
        asset_people = self._photo_entry_people_rows(entry)
        if asset_people:
            return len(asset_people)
        return len([match for match in entry.get("matches", []) or [] if isinstance(match, ReviewCandidate) and str(match.person_name or "").strip()])

    def _photo_confidence_number(self, value: Any) -> float | None:
        if isinstance(value, bool):
            return None
        try:
            number = float(value)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(number) or number < 0:
            return None
        if number > 1.0 and number <= 100.0:
            number = number / 100.0
        return max(0.0, min(1.0, number)) if number <= 1.0 else None

    def _photo_metadata_confidence_values(self, value: Any, *, depth: int = 0) -> list[float]:
        if depth > 8:
            return []
        if isinstance(value, list):
            values: list[float] = []
            for item in value[:200]:
                values.extend(self._photo_metadata_confidence_values(item, depth=depth + 1))
            return values
        if isinstance(value, dict):
            values: list[float] = []
            for key, item in value.items():
                key_text = str(key or "").strip().casefold()
                if isinstance(item, (int, float)) and not isinstance(item, bool):
                    if key_text in {"confidence", "score", "probability", "prob"} or key_text not in {"x", "y", "width", "height", "left", "top", "right", "bottom", "bbox", "bounds"}:
                        number = self._photo_confidence_number(item)
                        if number is not None:
                            values.append(number)
                else:
                    values.extend(self._photo_metadata_confidence_values(item, depth=depth + 1))
            return values
        return []

    def _photo_entry_metadata_confidence(self, entry: dict[str, Any], keys: tuple[str, ...]) -> float | None:
        asset = self._photo_entry_asset(entry)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata", {}), dict) else {}
        values: list[float] = []
        for key in keys:
            values.extend(self._photo_metadata_confidence_values(asset_metadata.get(key)))
        return max(values) if values else None

    def _photo_dimension_value_text(self, value: float | int | None) -> str:
        if value is None:
            return ""
        number = float(value)
        return str(int(number)) if math.isclose(number, round(number)) else f"{number:g}"

    def _photo_entry_dimensions_text(self, entry: dict[str, Any]) -> list[str]:
        width = self._photo_entry_asset_number(entry, "width")
        height = self._photo_entry_asset_number(entry, "height")
        if width is None or height is None or width <= 0 or height <= 0:
            return []
        width_text = self._photo_dimension_value_text(width)
        height_text = self._photo_dimension_value_text(height)
        megapixels = (width * height) / 1_000_000.0
        megapixels_text = f"{megapixels:.1f}".rstrip("0").rstrip(".")
        return [
            f"{width_text}x{height_text}",
            f"{width_text} x {height_text}",
            f"{megapixels_text} MP",
            f"{megapixels_text} megapixels",
        ]

    def _photo_entry_lens_text(self, entry: dict[str, Any]) -> list[str]:
        asset = self._photo_entry_asset(entry)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata", {}), dict) else {}
        exif = asset_metadata.get("exif", {}) if isinstance(asset_metadata.get("exif", {}), dict) else {}
        values: list[str] = []
        seen: set[str] = set()

        def add_value(value: Any) -> None:
            for item in self.project.db._photo_asset_metadata_text_values(value):  # noqa: SLF001
                clean = str(item or "").replace("\0", "").strip()
                key = clean.casefold()
                if clean and key not in seen:
                    seen.add(key)
                    values.append(clean)

        for key in (
            "lens",
            "lensMake",
            "lensModel",
            "lensInfo",
            "lensSpecification",
            "lensSerialNumber",
            "focalLength",
            "focalLengthMm",
            "focalLength35mm",
            "focalLengthIn35mmFilm",
            "focalLengthIn35mmFormat",
        ):
            add_value(asset_metadata.get(key))
            add_value(exif.get(key))
        return values

    def _photo_entry_asset_metadata_values(self, entry: dict[str, Any], keys: tuple[str, ...]) -> list[str]:
        asset = self._photo_entry_asset(entry)
        asset_metadata = asset.get("metadata", {}) if asset and isinstance(asset.get("metadata", {}), dict) else {}
        values: list[str] = []
        seen: set[str] = set()
        for key in keys:
            for value in self.project.db._photo_asset_metadata_text_values(asset_metadata.get(key)):  # noqa: SLF001
                clean = str(value or "").replace("\0", "").strip()
                if not clean:
                    continue
                normalized = clean.casefold()
                if normalized in seen:
                    continue
                seen.add(normalized)
                values.append(clean)
        return values

    def _photo_entry_ocr_text(self, entry: dict[str, Any]) -> list[str]:
        cached_rows = entry.get("_ocrBlockText")
        row_values = cached_rows if isinstance(cached_rows, list) else None
        if row_values is None:
            row_values = []
            asset = self._photo_entry_asset(entry)
            asset_id = str(asset.get("assetId", "") or "") if asset else ""
            if asset_id:
                row_values = [
                    str(block.get("text", "") or "")
                    for block in self.project.db.photo_ocr_blocks_for_asset(asset_id)
                    if str(block.get("text", "") or "").strip()
                ]
            entry["_ocrBlockText"] = row_values
        legacy_values = self._photo_entry_asset_metadata_values(
            entry,
            ("ocrText", "liveText", "detectedText", "textRegions", "ocrBlocks", "textBlocks"),
        )
        values: list[str] = []
        seen: set[str] = set()
        for value in [*row_values, *legacy_values]:
            clean = re.sub(r"\s+", " ", str(value or "")).strip()
            normalized = clean.casefold()
            if not clean or normalized in seen:
                continue
            seen.add(normalized)
            values.append(clean)
        return values

    def _photo_entry_object_tags(self, entry: dict[str, Any], sources: tuple[str, ...] = ()) -> list[dict[str, Any]]:
        cached_rows = entry.get("_objectTags")
        rows = cached_rows if isinstance(cached_rows, list) else None
        if rows is None:
            rows = []
            asset = self._photo_entry_asset(entry)
            asset_id = str(asset.get("assetId", "") or "") if asset else ""
            if asset_id:
                rows = self.project.db.photo_object_tags_for_asset(asset_id)
            entry["_objectTags"] = rows
        if not sources:
            return [row for row in rows if isinstance(row, dict)]
        source_set = {str(source or "") for source in sources if str(source or "")}
        return [
            row
            for row in rows
            if isinstance(row, dict) and str(row.get("source", "") or "") in source_set
        ]

