    def _photo_library_root_filter_from_params(self, params: dict[str, Any] | None) -> str:
        body = params if isinstance(params, dict) else {}
        text = ""
        for key in ("libraryRootProfileId", "activeLibraryRootProfileId", "activeLibraryProfileId", "library_profile_id"):
            raw_value = body.get(key, "")
            candidate_text = str(raw_value or "").strip()
            if not candidate_text:
                continue
            profile = self._photo_library_profile_for_id(candidate_text)
            if not profile:
                raise ValueError("Unknown Photos library profile id.")
            text = str(profile.get("path", "") or "").strip()
            break
        for key in ("libraryRoot", "activeLibraryRoot", "library_root"):
            if text:
                break
            raw_value = body.get(key, "")
            candidate_text = str(raw_value or "").strip()
            if candidate_text:
                text = candidate_text
                break
        if not text:
            return ""
        try:
            candidate = Path(text).expanduser()
            text = str(candidate.resolve()) if candidate.exists() else str(candidate)
        except (OSError, RuntimeError, ValueError):
            text = str(Path(text).expanduser())
        return text.rstrip("/\\")

    def _photo_library_root_profile_id_from_params(
        self,
        params: dict[str, Any] | None,
        library_root: str = "",
    ) -> str:
        body = params if isinstance(params, dict) else {}
        for key in ("libraryRootProfileId", "activeLibraryRootProfileId", "activeLibraryProfileId", "library_profile_id"):
            candidate_text = str(body.get(key, "") or "").strip()
            if not candidate_text:
                continue
            profile = self._photo_library_profile_for_id(candidate_text)
            if not profile:
                raise ValueError("Unknown Photos library profile id.")
            return candidate_text
        root = str(library_root or "").strip().rstrip("/\\")
        if not root:
            return ""
        settings = self.photo_library_settings({})
        for key in ("managedRoots", "libraryRoots"):
            rows = settings.get(key, []) if isinstance(settings.get(key, []), list) else []
            for profile in rows:
                if not isinstance(profile, dict):
                    continue
                profile_path = str(profile.get("path", "") or "").strip().rstrip("/\\")
                if profile_path == root:
                    return str(profile.get("profileId", "") or "").strip()
        return ""

    def _photo_library_root_source_text_filters(self, library_root: str) -> tuple[tuple[str, str], ...]:
        root = str(library_root or "").strip().rstrip("/\\")
        return (("folderIs", root),) if root else ()

    def _photo_source_inside_library_root(self, source_path: str, library_root: str) -> bool:
        root = str(library_root or "").strip().rstrip("/\\")
        source = str(source_path or "").strip()
        if not root or not source:
            return True
        root_key = root.replace("\\", "/").rstrip("/").casefold()
        source_key = source.replace("\\", "/").rstrip("/").casefold()
        return source_key == root_key or source_key.startswith(f"{root_key}/")

    def _filter_photo_entries_by_library_root(
        self,
        entries: list[dict[str, Any]],
        library_root: str,
    ) -> list[dict[str, Any]]:
        root = str(library_root or "").strip()
        if not root:
            return entries
        return [
            entry for entry in entries
            if self._photo_source_inside_library_root(str(entry.get("sourcePath", "") or ""), root)
        ]

    def _photo_entry_matches_metadata_filters(
        self,
        entry: dict[str, Any],
        *,
        date_from: str = "",
        date_to: str = "",
        source: str = "",
        library_root: str = "",
        file_type: str = "",
        location: str = "",
        camera: str = "",
        duplicate_only: bool = False,
        place_labels_by_asset_id: dict[str, list[str]] | None = None,
        nearby: dict[str, float] | None = None,
    ) -> bool:
        date_from = self._normalize_photo_date_filter(date_from)
        date_to = self._normalize_photo_date_filter(date_to)
        if date_from or date_to:
            date_text = self._entry_date_text(entry)
            if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_text):
                return False
            if date_from and date_text < date_from:
                return False
            if date_to and date_text > date_to:
                return False
        source_key = str(source or "").strip().casefold()
        if source_key:
            source_path = str(entry.get("sourcePath", "") or "")
            source_text = " ".join([
                source_path,
                str(Path(source_path).parent),
                Path(source_path).name,
            ]).casefold()
            if source_key not in source_text:
                return False
        if library_root and not self._photo_source_inside_library_root(str(entry.get("sourcePath", "") or ""), library_root):
            return False
        file_type_aliases = self._photo_file_type_aliases(file_type)
        if file_type_aliases and self._photo_entry_file_type(entry) not in file_type_aliases:
            return False
        location_key = str(location or "").strip()
        if location_key and not self._photo_query_text_matches(self._photo_entry_location_text(entry, place_labels_by_asset_id), "contains", location_key):
            return False
        camera_key = str(camera or "").strip()
        if camera_key and not self._photo_query_text_matches(self._photo_entry_camera_text(entry), "contains", camera_key):
            return False
        if not self._photo_entry_matches_nearby_filter(entry, nearby):
            return False
        if duplicate_only and not self._photo_entry_duplicate_group(entry):
            return False
        return True

    def _filter_photo_entries_by_metadata_filters(
        self,
        entries: list[dict[str, Any]],
        *,
        date_from: str = "",
        date_to: str = "",
        source: str = "",
        library_root: str = "",
        file_type: str = "",
        location: str = "",
        camera: str = "",
        duplicate_only: bool = False,
        nearby: dict[str, float] | None = None,
    ) -> list[dict[str, Any]]:
        place_labels_by_asset_id = self._photo_place_labels_by_asset_id() if str(location or "").strip() else None
        return [
            entry for entry in entries
            if self._photo_entry_matches_metadata_filters(
                entry,
                date_from=date_from,
                date_to=date_to,
                source=source,
                library_root=library_root,
                file_type=file_type,
                location=location,
                camera=camera,
                duplicate_only=duplicate_only,
                place_labels_by_asset_id=place_labels_by_asset_id,
                nearby=nearby,
            )
        ]

    def _photo_smart_album_scale_asset_count(self) -> int:
        try:
            return max(0, int(self.project.db.count_photo_assets()))
        except Exception:
            return 0

    def _photo_smart_album_scale_warning(self, album: dict[str, Any]) -> dict[str, str] | None:
        if str(album.get("albumKind", "smart") or "smart") != "smart":
            return None
        if self._photo_smart_album_sql_criteria_branches(album) is not None:
            return None
        asset_count = self._photo_smart_album_scale_asset_count()
        if asset_count < PHOTO_SMART_ALBUM_SCALE_WARNING_ASSETS:
            return None
        return {
            "code": "non-sql-smart-album-scale",
            "message": "This smart album uses criteria that need a full local library scan at this library size.",
        }

    def _photo_rules_have_time_relative_terms(self, rules: dict[str, Any]) -> bool:
        return bool(rules.get("recentDays")) or self._photo_rules_mention_query_field(rules, "recentDays")

    def _photo_smart_album_materialization_signature(self, album: dict[str, Any], *, library_root: str = "") -> str:
        clean_rules = self._clean_album_rules(album.get("rules", {}))
        now_for_relative_rules = datetime.utcnow().replace(minute=0, second=0, microsecond=0)
        candidate_rows = [
            {
                "candidateId": str(candidate.candidate_id or ""),
                "sourcePath": str(candidate.source_path or ""),
                "mediaSourcePath": str(candidate.media_source_path or ""),
                "personName": str(candidate.person_name or ""),
                "status": str(candidate.status or ""),
                "score": float(candidate.score or 0.0),
                "quality": float(candidate.quality or 0.0),
                "band": str(candidate.band or ""),
                "captureDate": str(candidate.capture_date or ""),
                "createdAt": str(candidate.created_at or ""),
            }
            for candidate in self.project.candidates.values()
        ]
        body = {
            "schemaVersion": "1",
            "libraryRoot": str(library_root or ""),
            "album": {
                "albumId": str(album.get("albumId", "") or ""),
                "albumKind": str(album.get("albumKind", "smart") or "smart"),
                "includePeople": self._clean_album_people(album.get("includePeople", [])),
                "excludePeople": self._clean_album_people(album.get("excludePeople", [])),
                "rules": clean_rules,
                "updatedAt": str(album.get("updatedAt", "") or ""),
            },
            "relativeTime": {
                "utcHour": now_for_relative_rules.isoformat() + "Z",
            } if self._photo_rules_have_time_relative_terms(clean_rules) else {},
            "catalog": self.project.db.photo_smart_album_materialization_revision(),
            "candidates": sorted(candidate_rows, key=lambda row: (row["sourcePath"], row["candidateId"], row["personName"])),
        }
        encoded = json.dumps(body, separators=(",", ":"), sort_keys=True, default=str).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _photo_smart_album_materialized_cache(self, album: dict[str, Any], *, library_root: str = "") -> dict[str, Any] | None:
        album_id = str(album.get("albumId", "") or "").strip()
        if not album_id or str(album.get("albumKind", "smart") or "smart") != "smart":
            return None
        if self._photo_smart_album_sql_criteria_branches(album) is not None:
            return None
        signature = self._photo_smart_album_materialization_signature(album, library_root=library_root)
        cache = self.project.db.photo_smart_album_materialization_cache(album_id, library_root)
        if str(cache.get("signature", "") or "") != signature:
            return None
        return {**cache, "cacheHit": True}

    def _photo_entries_for_materialized_source_paths(self, source_paths: Iterable[str]) -> list[dict[str, Any]]:
        paths = [str(path or "").strip() for path in source_paths if str(path or "").strip()]
        if not paths:
            return []
        matches_by_source = self._photo_matches_by_source()
        asset_entries = self._photo_entries_for_source_paths(paths, matches_by_source=matches_by_source)
        entries_by_source = {
            str(entry.get("sourcePath", "") or ""): entry
            for entry in asset_entries
            if str(entry.get("sourcePath", "") or "")
        }
        entries: list[dict[str, Any]] = []
        for source_path in paths:
            entry = entries_by_source.get(source_path)
            if entry is None:
                entry = self._photo_source_entry(
                    source_path=source_path,
                    media_kind=str(self._media_kind_for_source(source_path)),
                    matches_by_source=matches_by_source,
                )
            entries.append(entry)
        return entries

    def _photo_smart_album_materialized_source_paths(self, album: dict[str, Any], *, library_root: str = "") -> list[str] | None:
        cache = self._photo_smart_album_materialized_cache(album, library_root=library_root)
        if cache is None and str(library_root or "").strip():
            cache = self._photo_smart_album_materialized_cache(album)
        if cache is None:
            return None
        source_paths = cache.get("sourcePaths", [])
        paths = [str(path or "").strip() for path in source_paths if str(path or "").strip()] if isinstance(source_paths, list) else []
        if str(library_root or "").strip():
            paths = [path for path in paths if self._photo_source_inside_library_root(path, library_root)]
        return paths

    def _photo_smart_album_materialized_summary(self, album: dict[str, Any], *, library_root: str = "") -> dict[str, Any] | None:
        source_paths = self._photo_smart_album_materialized_source_paths(album, library_root=library_root)
        if source_paths is None:
            return None
        selected_cover = str(album.get("coverSourcePath", "") or "")
        source_set = set(source_paths)
        cover_matches = bool(selected_cover and selected_cover in source_set)
        return {
            "count": len(source_paths),
            "coverSourcePath": selected_cover if cover_matches else source_paths[0] if source_paths else "",
            "coverMatches": cover_matches,
            "materialized": True,
        }

    def _photo_save_smart_album_materialization(
        self,
        album: dict[str, Any],
        entries: list[dict[str, Any]],
        *,
        library_root: str = "",
    ) -> dict[str, Any] | None:
        album_id = str(album.get("albumId", "") or "").strip()
        if not album_id or str(album.get("albumKind", "smart") or "smart") != "smart":
            return None
        if self._photo_smart_album_sql_criteria_branches(album) is not None:
            return None
        materialized_entries = self._filter_photo_entries_by_library_root(entries, library_root)
        source_paths = [
            str(entry.get("sourcePath", "") or "")
            for entry in materialized_entries
            if str(entry.get("sourcePath", "") or "")
        ]
        signature = self._photo_smart_album_materialization_signature(album, library_root=library_root)
        return self.project.db.save_photo_smart_album_materialization_cache(
            album_id,
            library_root,
            {
                "signature": signature,
                "assetCount": len(source_paths),
                "sourcePaths": source_paths,
            },
        )

    def _photo_materialize_smart_album(
        self,
        album: dict[str, Any],
        *,
        library_root: str = "",
        force: bool = False,
    ) -> dict[str, Any]:
        cache = None if force else self._photo_smart_album_materialized_cache(album, library_root=library_root)
        if cache is not None:
            return cache
        entries = self._photo_album_items(album)
        saved = self._photo_save_smart_album_materialization(album, entries, library_root=library_root)
        if saved is None:
            return {"cacheHit": False, "assetCount": 0, "sourcePaths": []}
        return {**saved, "cacheHit": False}

    def _photo_album_validation(self, album: dict[str, Any], items: list[dict[str, Any]]) -> list[dict[str, str]]:
        warnings: list[dict[str, str]] = []
        item_sources = {str(item.get("sourcePath", "")) for item in items}
        cover_source = str(album.get("coverSourcePath", "") or "")
        if not items:
            if str(album.get("albumKind", "smart")) == "manual":
                warnings.append({"code": "empty", "message": "No photos have been added to this album."})
            else:
                warnings.append({"code": "empty", "message": "No photos match this album."})
        if cover_source and cover_source not in item_sources:
            warnings.append({"code": "cover-mismatch", "message": "The chosen cover no longer matches this album."})
        if str(album.get("albumKind", "smart")) != "manual" and album.get("excludePeople"):
            without_exclusions = {**album, "excludePeople": []}
            base_count = len(self._photo_album_items(without_exclusions))
            if base_count > 0 and not items:
                warnings.append({"code": "excluded-all", "message": "Excluded people remove every matching photo."})
        scale_warning = self._photo_smart_album_scale_warning(album)
        if scale_warning:
            warnings.append(scale_warning)
        return warnings

    def _photo_album_validation_from_summary(self, album: dict[str, Any], summary: dict[str, Any]) -> list[dict[str, str]]:
        warnings: list[dict[str, str]] = []
        count = int(summary.get("count", 0) or 0)
        cover_source = str(album.get("coverSourcePath", "") or "")
        scale_warning = self._photo_smart_album_scale_warning(album)
        if not count:
            if str(album.get("albumKind", "smart")) == "manual":
                warnings.append({"code": "empty", "message": "No photos have been added to this album."})
            else:
                warnings.append({"code": "empty", "message": "No photos match this album."})
        if cover_source and not bool(summary.get("coverMatches", False)):
            warnings.append({"code": "cover-mismatch", "message": "The chosen cover no longer matches this album."})
        if (
            str(album.get("albumKind", "smart")) != "manual"
            and album.get("excludePeople")
            and count == 0
            and scale_warning is None
        ):
            without_exclusions = {**album, "excludePeople": []}
            base_summary = self._photo_album_summary(without_exclusions)
            base_count = int(base_summary.get("count", 0) or 0) if isinstance(base_summary, dict) else len(self._photo_album_items(without_exclusions))
            if base_count > 0:
                warnings.append({"code": "excluded-all", "message": "Excluded people remove every matching photo."})
        if scale_warning:
            warnings.append(scale_warning)
        return warnings

    def _photo_smart_album_summary_sql(self, album: dict[str, Any]) -> dict[str, Any] | None:
        criteria = self._photo_smart_album_sql_criteria(album)
        if criteria is None:
            entries = self._photo_smart_album_entries_sql_union(album, sort="newest")
            if entries is None:
                return self._photo_smart_album_materialized_summary(album)
            sources = [str(entry.get("sourcePath", "") or "") for entry in entries if str(entry.get("sourcePath", "") or "")]
            selected_cover = str(album.get("coverSourcePath", "") or "")
            cover_matches = bool(selected_cover and selected_cover in set(sources))
            return {
                "count": len(sources),
                "coverSourcePath": selected_cover if cover_matches else sources[0] if sources else "",
                "coverMatches": cover_matches,
            }
        page = self._photo_smart_album_sql_page_for_criteria(criteria, offset=0, limit=1, sort="newest")
        assets = page.get("assets", []) if isinstance(page.get("assets", []), list) else []
        fallback_cover = str(assets[0].get("sourcePath", "") or "") if assets else ""
        selected_cover = str(album.get("coverSourcePath", "") or "")
        cover_matches = False
        if selected_cover:
            cover_asset = self.project.db.photo_asset_by_path(selected_cover)
            entries: list[dict[str, Any]] = []
            if cover_asset:
                entries = self._photo_entries_for_assets([cover_asset])
            cover_entry = entries[0] if entries else {}
            include_keys = {str(person).casefold() for person in album.get("includePeople", []) if str(person).strip()}
            exclude_keys = {str(person).casefold() for person in album.get("excludePeople", []) if str(person).strip()}
            cover_matches = (
                bool(cover_entry)
                and self._photo_entry_default_visible(cover_entry)
                and self._photo_album_entry_included(cover_entry, include_keys)
                and not self._photo_album_entry_excluded(cover_entry, exclude_keys)
                and self._photo_album_entry_matches_rules(cover_entry, self._clean_album_rules(album.get("rules", {})))
            )
        return {
            "count": int(page.get("total", 0) or 0),
            "coverSourcePath": selected_cover if cover_matches else fallback_cover,
            "coverMatches": cover_matches,
        }

    def _photo_smart_album_source_paths_sql(self, album: dict[str, Any], *, library_root: str = "") -> list[str] | None:
        clean_library_root = str(library_root or "").strip()
        branches = self._photo_smart_album_sql_criteria_branches(album)
        if not branches:
            return self._photo_smart_album_materialized_source_paths(album, library_root=clean_library_root)
        if len(branches) > 1:
            entries = self._photo_smart_album_entries_sql_union(album, sort="newest")
            if entries is None:
                return None
            return [
                source_path
                for entry in entries
                for source_path in [str(entry.get("sourcePath", "") or "")]
                if source_path and self._photo_source_inside_library_root(source_path, clean_library_root)
            ]
        criteria = branches[0]
        assets = self._photo_smart_album_sql_assets_for_criteria(criteria, sort="newest")
        return [
            source_path
            for asset in assets
            for source_path in [str(asset.get("sourcePath", "") or "")]
            if source_path and self._photo_source_inside_library_root(source_path, clean_library_root)
        ]

    def _photo_album_summary(self, album: dict[str, Any], *, library_root: str = "") -> dict[str, Any] | None:
        clean_library_root = str(library_root or "").strip()
        if clean_library_root:
            if str(album.get("albumKind", "smart") or "smart") != "manual":
                summary = self._photo_smart_album_materialized_summary(album, library_root=clean_library_root)
                if summary is not None:
                    return summary
                source_paths = self._photo_smart_album_source_paths_sql(album, library_root=clean_library_root)
                if source_paths is not None:
                    entries = self._sort_photo_entries(self._photo_entries_for_materialized_source_paths(source_paths), "newest")
                    selected_cover = str(album.get("coverSourcePath", "") or "")
                    source_set = set(source_paths)
                    cover_matches = bool(selected_cover and selected_cover in source_set)
                    return {
                        "count": len(source_paths),
                        "coverSourcePath": selected_cover if cover_matches else str(entries[0].get("sourcePath", "") or "") if entries else "",
                        "coverMatches": cover_matches,
                    }
            entries = self._filter_photo_entries_by_library_root(self._photo_album_items(album), clean_library_root)
            self._photo_save_smart_album_materialization(album, entries, library_root=clean_library_root)
            cover_source = str(album.get("coverSourcePath", "") or "")
            entry_sources = {str(entry.get("sourcePath", "") or "") for entry in entries}
            if cover_source not in entry_sources:
                sorted_entries = self._sort_photo_entries(entries, "newest")
                cover_source = str(sorted_entries[0].get("sourcePath", "") or "") if sorted_entries else ""
            return {
                "count": len(entries),
                "coverSourcePath": cover_source,
                "coverMatches": bool(cover_source and cover_source in entry_sources),
            }
        if str(album.get("albumKind", "smart") or "smart") == "manual":
            return self.project.db.photo_manual_album_summary(
                str(album.get("albumId", "") or ""),
                cover_source_path=str(album.get("coverSourcePath", "") or ""),
            )
        return self._photo_smart_album_summary_sql(album)

    def _photo_album_folder(
        self,
        album: dict[str, Any],
        items: list[dict[str, Any]] | None = None,
        summary: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        album_items: list[dict[str, Any]] | None = None
        if summary is None:
            album_items = self._photo_album_items(album) if items is None else items
            self._photo_save_smart_album_materialization(album, album_items)
            item_sources = {str(item.get("sourcePath", "")) for item in album_items}
            cover_source = str(album.get("coverSourcePath", "") or "")
            if cover_source not in item_sources:
                cover_source = str(album_items[0].get("sourcePath", "") or "") if album_items else ""
            count = len(album_items)
            validation = self._photo_album_validation(album, album_items)
        else:
            cover_source = str(summary.get("coverSourcePath", "") or "")
            count = int(summary.get("count", 0) or 0)
            validation = self._photo_album_validation_from_summary(album, summary)
        return {
            "id": f"album:{album['albumId']}",
            "kind": "album",
            "name": str(album.get("name", "") or "Untitled album"),
            "count": count,
            "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
            "albumId": str(album.get("albumId", "") or ""),
            "albumKind": str(album.get("albumKind", "smart") or "smart"),
            "folderId": str(album.get("folderId", "") or ""),
            "folderPosition": int(album.get("folderPosition", 0) or 0),
            "description": str(album.get("description", "") or ""),
            "includePeople": album.get("includePeople", []),
            "excludePeople": album.get("excludePeople", []),
            "rules": self._clean_album_rules(album.get("rules", {})),
            "ruleSummary": self._photo_album_rule_summary(self._clean_album_rules(album.get("rules", {}))),
            "validation": validation,
            "coverSourcePath": cover_source,
            "createdAt": album.get("createdAt", ""),
            "updatedAt": album.get("updatedAt", ""),
        }

    def _photo_album_folder_descendant_ids(self, folder_id: str) -> set[str]:
        root_id = str(folder_id or "").strip()
        if not root_id:
            return set()
        children_by_parent: dict[str, list[str]] = {}
        for folder in self.project.db.list_photo_album_folders():
            parent_id = str(folder.get("parentFolderId", "") or "")
            child_id = str(folder.get("folderId", "") or "")
            if child_id:
                children_by_parent.setdefault(parent_id, []).append(child_id)
        folder_ids = {root_id}
        stack = list(children_by_parent.get(root_id, []))
        while stack:
            current = stack.pop()
            if current in folder_ids:
                continue
            folder_ids.add(current)
            stack.extend(children_by_parent.get(current, []))
        return folder_ids

    def _photo_album_folder_collection_items(self, folder_id: str) -> list[dict[str, Any]]:
        folder_ids = self._photo_album_folder_descendant_ids(folder_id)
        if not folder_ids:
            return []
        seen_sources: set[str] = set()
        items: list[dict[str, Any]] = []
        for album in self.project.db.list_photo_albums():
            if str(album.get("folderId", "") or "") not in folder_ids:
                continue
            album_items = self._photo_album_items(album)
            self._photo_save_smart_album_materialization(album, album_items)
            for item in album_items:
                source = str(item.get("sourcePath", "") or "")
                if not source or source in seen_sources:
                    continue
                seen_sources.add(source)
                items.append(item)
        return items

    def _photo_album_folder_source_paths_sql(
        self,
        folder_id: str,
        *,
        albums: list[dict[str, Any]] | None = None,
        library_root: str = "",
    ) -> list[str] | None:
        clean_library_root = str(library_root or "").strip()
        folder_ids = self._photo_album_folder_descendant_ids(folder_id)
        if not folder_ids:
            return []
        folder_albums = [
            album for album in (albums if albums is not None else self.project.db.list_photo_albums())
            if str(album.get("folderId", "") or "") in folder_ids
        ]
        seen_sources: set[str] = set()
        ordered_sources: list[str] = []
        for album in folder_albums:
            album_id = str(album.get("albumId", "") or "")
            album_kind = str(album.get("albumKind", "smart") or "smart")
            if album_kind == "manual":
                source_paths = self.project.db.photo_manual_album_visible_source_paths(album_id)
                if clean_library_root:
                    source_paths = [
                        source_path
                        for source_path in source_paths
                        if self._photo_source_inside_library_root(source_path, clean_library_root)
                    ]
            else:
                smart_paths = self._photo_smart_album_source_paths_sql(album, library_root=clean_library_root)
                if smart_paths is None:
                    return None
                source_paths = smart_paths
            for source_path in source_paths:
                source = str(source_path or "")
                if not source or source in seen_sources:
                    continue
                seen_sources.add(source)
                ordered_sources.append(source)
        return ordered_sources

    def _photo_album_folder_summary(
        self,
        folder_id: str,
        *,
        albums: list[dict[str, Any]] | None = None,
        library_root: str = "",
    ) -> dict[str, Any] | None:
        clean_library_root = str(library_root or "").strip()
        if clean_library_root:
            ordered_sources = self._photo_album_folder_source_paths_sql(folder_id, albums=albums, library_root=clean_library_root)
            if ordered_sources is not None:
                sorted_entries = self._sort_photo_entries(self._photo_entries_for_materialized_source_paths(ordered_sources), "newest")
                return {
                    "count": len(ordered_sources),
                    "coverSourcePath": str(sorted_entries[0].get("sourcePath", "") or "") if sorted_entries else "",
                }
            entries = self._filter_photo_entries_by_library_root(
                self._photo_album_folder_collection_items(folder_id),
                clean_library_root,
            )
            sorted_entries = self._sort_photo_entries(entries, "newest")
            return {
                "count": len(entries),
                "coverSourcePath": str(sorted_entries[0].get("sourcePath", "") or "") if sorted_entries else "",
            }
        folder_ids = self._photo_album_folder_descendant_ids(folder_id)
        if not folder_ids:
            return {"count": 0, "coverSourcePath": ""}
        folder_albums = [
            album for album in (albums if albums is not None else self.project.db.list_photo_albums())
            if str(album.get("folderId", "") or "") in folder_ids
        ]
        if not folder_albums:
            return {"count": 0, "coverSourcePath": ""}
        manual_album_ids = [
            str(album.get("albumId", "") or "")
            for album in folder_albums
            if str(album.get("albumKind", "smart") or "smart") == "manual"
        ]
        smart_albums = [
            album for album in folder_albums
            if str(album.get("albumKind", "smart") or "smart") != "manual"
        ]
        if not smart_albums:
            return self.project.db.photo_manual_album_folder_summary(manual_album_ids)
        if len(smart_albums) == 1 and not manual_album_ids:
            return self._photo_album_summary(smart_albums[0])
        ordered_sources = self._photo_album_folder_source_paths_sql(folder_id, albums=folder_albums)
        if ordered_sources is None:
            return None
        return {
            "count": len(ordered_sources),
            "coverSourcePath": ordered_sources[0] if ordered_sources else "",
        }

    def _photo_album_folder_validation(
        self,
        folder_id: str,
        *,
        albums: list[dict[str, Any]] | None = None,
    ) -> list[dict[str, str]]:
        folder_ids = self._photo_album_folder_descendant_ids(folder_id)
        if not folder_ids:
            return []
        slow_smart_albums = [
            album for album in (albums if albums is not None else self.project.db.list_photo_albums())
            if str(album.get("folderId", "") or "") in folder_ids
            and str(album.get("albumKind", "smart") or "smart") != "manual"
            and self._photo_smart_album_scale_warning(album) is not None
        ]
        if not slow_smart_albums:
            return []
        count = len(slow_smart_albums)
        noun = "smart album" if count == 1 else "smart albums"
        return [
            {
                "code": "non-sql-smart-album-folder-scale",
                "message": f"{count} {noun} in this folder use criteria that need a full local library scan at this library size.",
            }
        ]

    def _photo_album_folder_node(
        self,
        folder: dict[str, Any],
        summary: dict[str, Any] | None = None,
        albums: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        folder_id = str(folder.get("folderId", "") or "")
        if summary is None:
            folder_items = self._photo_album_folder_collection_items(folder_id)
            cover_source = str(folder_items[0].get("sourcePath", "") or "") if folder_items else ""
            count = len(folder_items)
        else:
            cover_source = str(summary.get("coverSourcePath", "") or "")
            count = int(summary.get("count", 0) or 0)
        return {
            "id": f"albumFolder:{folder_id}",
            "kind": "albumFolder",
            "name": str(folder.get("name", "") or "Untitled folder"),
            "count": count,
            "albumCount": int(folder.get("albumCount", 0) or 0),
            "folderId": folder_id,
            "parentFolderId": str(folder.get("parentFolderId", "") or ""),
            "position": int(folder.get("position", 0) or 0),
            "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
            "coverSourcePath": cover_source,
            "validation": self._photo_album_folder_validation(folder_id, albums=albums),
            "createdAt": folder.get("createdAt", ""),
            "updatedAt": folder.get("updatedAt", ""),
        }

    def _photo_entries_for_folder_id(self, folder_id: str) -> list[dict[str, Any]]:
        folder_id = str(folder_id or "").strip() or "all"
        if folder_id == "all":
            return self._visible_photo_entries(self._all_photo_entries())
        if folder_id.startswith("sourceFolder:"):
            return self._visible_photo_entries(self._all_photo_entries())
        if folder_id.startswith("importSource:"):
            if self._photo_import_source_group_from_folder_id(folder_id) is None:
                raise ValueError("Unknown photo import source.")
            return self._photo_asset_entries(folder_id)
        if folder_id.startswith("albumFolder:"):
            album_folder_id = folder_id[len("albumFolder:"):]
            if not self.project.db.photo_album_folder_by_id(album_folder_id):
                raise ValueError("Unknown photo album folder id.")
            return self._photo_album_folder_collection_items(album_folder_id)
        if folder_id.startswith("place:"):
            place_id = folder_id[len("place:"):]
            if not any(str(place.get("placeId", "") or "") == place_id for place in self.project.db.list_photo_places()):
                raise ValueError("Unknown photo place id.")
        if folder_id.startswith("trip:"):
            trip_id = folder_id[len("trip:"):]
            if not self._photo_trip_by_id(trip_id):
                raise ValueError("Unknown photo trip id.")
        if folder_id.startswith("memory:"):
            memory_id = folder_id[len("memory:"):]
            if not self._photo_memory_by_id(memory_id):
                raise ValueError("Unknown photo memory id.")
        if folder_id.startswith("pet:"):
            pet_name = self._photo_pet_name_from_folder_id(folder_id)
            pet_probe = self.project.db.list_photo_asset_page(
                offset=0,
                limit=1,
                visibility="visible",
                pet_names=(pet_name,),
                sort="newest",
            )
            if not int(pet_probe.get("total", 0) or 0):
                raise ValueError("Unknown pet folder id.")
        if folder_id.startswith("media:"):
            media_folder_kind = folder_id[len("media:"):].strip().lower()
            if media_folder_kind not in PHOTO_MEDIA_KINDS:
                raise ValueError("Unknown photo media type folder.")
        if folder_id.startswith("group:"):
            self._photo_people_group_from_id(folder_id)
        utility_ids = {
            "favorites",
            "duplicates",
            "hidden",
            "recentlyDeleted",
            "places",
            "recentlyAdded",
            "recentlySaved",
            "recentlyEdited",
            "recentlyViewed",
            "recentlyShared",
            "imports",
            "lastImport",
            "recentlyImported",
            "recovered",
            "trips",
            "memories",
            "pets",
            "petReview",
        }
        utility_ids.update(PHOTO_UTILITY_CLASSIFIER_IDS)
        if folder_id.startswith("import:"):
            import_id = folder_id[len("import:"):]
            if not self.project.db.photo_import_session_by_id(import_id):
                raise ValueError("Unknown photo import session id.")
        if folder_id.startswith("importSource:") and self._photo_import_source_group_from_folder_id(folder_id) is None:
            raise ValueError("Unknown photo import source.")
        if folder_id in utility_ids or folder_id.startswith("place:") or folder_id.startswith("trip:") or folder_id.startswith("memory:") or folder_id.startswith("pet:") or folder_id.startswith("media:") or folder_id.startswith("import:") or folder_id.startswith("importSource:"):
            return self._photo_asset_entries(folder_id)
        if folder_id.startswith("album:"):
            album_id = folder_id[len("album:"):]
            album = self.project.db.photo_album_by_id(album_id)
            if not album:
                raise ValueError("Unknown photo album id.")
            return self._photo_album_items(album)
        if folder_id.startswith("person:"):
            name = folder_id[len("person:"):]
            entry_match = lambda entry: self._photo_entry_matches_named_person(entry, name)  # noqa: E731
            candidate_match = lambda c: c.person_name == name and self._photo_person_match(c)  # noqa: E731
        elif folder_id.startswith("group:"):
            group_people, group_pets = self._photo_people_group_members_from_id(folder_id)
            excluded_people = self._photo_people_group_excluded_from_id(folder_id)
            excluded_pets = self._photo_people_group_excluded_pets_from_id(folder_id)
            entry_match = lambda entry: self._photo_entry_matches_people_group(entry, group_people, excluded_people, group_pets, excluded_pets)  # noqa: E731
            candidate_match = lambda c: False  # noqa: E731
        elif folder_id.startswith("unknown:"):
            name = folder_id[len("unknown:"):]
            entry_match = lambda entry: self._photo_entry_matches_unknown_cluster(entry, name)  # noqa: E731
            candidate_match = lambda c: c.person_name == name and c.person_name.startswith("Unmatched cluster")  # noqa: E731
        else:
            raise ValueError("Unknown photo folder id.")
        seen: set[str] = set()
        matches_by_source = self._photo_matches_by_source()
        entries: list[dict[str, Any]] = []
        for entry in self._visible_photo_entries(self._all_photo_entries(matches_by_source)):
            source_path = str(entry.get("sourcePath", "") or "")
            if not source_path or source_path in seen:
                continue
            if not entry_match(entry):
                continue
            seen.add(source_path)
            entries.append(entry)
        for candidate in self.project.candidates.values():
            if not candidate_match(candidate):
                continue
            source_path = self._photo_tile_source(candidate)
            if not source_path or source_path in seen:
                continue
            seen.add(source_path)
            entries.append(
                self._photo_source_entry(
                    source_path=source_path,
                    media_kind=str(candidate.media_kind or self._media_kind_for_source(source_path)),
                    matches_by_source=matches_by_source,
                    candidate=candidate,
                )
            )
        return self._visible_photo_entries(entries)

    def _photo_date_bucket_key(self, entry: dict[str, Any], mode: str) -> str:
        date_text = self._entry_date_text(entry)
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_text):
            return ""
        if mode == "years":
            return date_text[:4]
        if mode == "months":
            return date_text[:7]
        if mode in {"days", "recentDays"}:
            return date_text
        return ""

    def _filter_photo_entries_by_date_bucket(self, entries: list[dict[str, Any]], mode: str, key: str) -> list[dict[str, Any]]:
        clean_mode = str(mode or "").strip()
        clean_key = str(key or "").strip()
        if clean_mode not in {"years", "months", "days", "recentDays"} or not clean_key:
            return entries
        return [entry for entry in entries if self._photo_date_bucket_key(entry, clean_mode) == clean_key]

    def _photo_date_bucket_label(self, key: str, mode: str) -> str:
        text = str(key or "").strip()
        if mode == "years":
            return text
        month_names = [
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        ]
        month_short_names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        month_match = re.match(r"^(\d{4})-(\d{2})$", text)
        if mode == "months" and month_match:
            month_index = int(month_match.group(2)) - 1
            if 0 <= month_index < len(month_names):
                return f"{month_names[month_index]} {month_match.group(1)}"
        day_match = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", text)
        if mode in {"days", "recentDays"} and day_match:
            month_index = int(day_match.group(2)) - 1
            day = int(day_match.group(3))
            if 0 <= month_index < len(month_short_names) and 1 <= day <= 31:
                return f"{month_short_names[month_index]} {day}, {day_match.group(1)}"
        return text

    def _photo_entry_direct_bool(self, entry: dict[str, Any], key: str) -> bool:
        if key in entry:
            return bool(entry.get(key, False))
        return bool(self._photo_entry_metadata(entry).get(key, False))

    def _photo_entry_direct_number(self, entry: dict[str, Any], *keys: str) -> float:
        for key in keys:
            try:
                value = float(entry.get(key, 0.0) or 0.0)
            except (TypeError, ValueError):
                value = 0.0
            if value:
                return value
        return 0.0

    def _photo_entry_direct_people_count(self, entry: dict[str, Any]) -> int:
        try:
            direct = int(entry.get("personCount", 0) or 0)
        except (TypeError, ValueError):
            direct = 0
        if direct > 0:
            return direct
        people = entry.get("people", [])
        if isinstance(people, list):
            names = {
                str(person.get("personName", "") or "").strip().casefold()
                for person in people
                if isinstance(person, dict) and str(person.get("personName", "") or "").strip()
            }
            if names:
                return len(names)
        asset_people = {
            str(person.get("personName", "") or "").strip().casefold()
            for person in self._photo_entry_people_rows(entry)
            if str(person.get("personName", "") or "").strip()
        }
        if asset_people:
            return len(asset_people)
        return self._entry_person_count(entry)

    def _photo_entry_direct_has_location(self, entry: dict[str, Any]) -> bool:
        metadata: dict[str, Any] | None = None
        if "locationHidden" in entry:
            if bool(entry.get("locationHidden", False)):
                return False
        else:
            metadata = self._photo_entry_metadata(entry)
            if bool(metadata.get("locationHidden", False)):
                return False
        if "locationOverride" in entry:
            override = entry.get("locationOverride", {}) if isinstance(entry.get("locationOverride", {}), dict) else {}
        else:
            metadata = metadata if metadata is not None else self._photo_entry_metadata(entry)
            override = metadata.get("locationOverride", {}) if isinstance(metadata.get("locationOverride", {}), dict) else {}
        if str(override.get("label", "") or "").strip():
            return True
        latitude = self._photo_coordinate_value(override.get("latitude", override.get("lat", "")), minimum=-90.0, maximum=90.0)
        longitude = self._photo_coordinate_value(override.get("longitude", override.get("lon", override.get("lng", ""))), minimum=-180.0, maximum=180.0)
        if latitude is not None and longitude is not None:
            return True
        asset_metadata = entry.get("assetMetadata", {}) if isinstance(entry.get("assetMetadata", {}), dict) else {}
        exif = asset_metadata.get("exif", {}) if isinstance(asset_metadata.get("exif", {}), dict) else {}
        gps = exif.get("gps", {}) if isinstance(exif.get("gps", {}), dict) else {}
        latitude = self._photo_coordinate_value(gps.get("latitude", gps.get("lat", "")), minimum=-90.0, maximum=90.0)
        longitude = self._photo_coordinate_value(gps.get("longitude", gps.get("lon", gps.get("lng", ""))), minimum=-180.0, maximum=180.0)
        return latitude is not None and longitude is not None

    def _photo_curation_preference_keys(self, preferences: dict[str, Any] | None, key: str) -> set[str]:
        raw_values = preferences.get(key, []) if isinstance(preferences, dict) else []
        if not isinstance(raw_values, list):
            return set()
        return {re.sub(r"\s+", " ", str(value or "")).strip().casefold() for value in raw_values if str(value or "").strip()}

    def _photo_entry_curation_people(self, entry: dict[str, Any]) -> list[str]:
        values: list[str] = []
        direct_people = entry.get("people", [])
        if isinstance(direct_people, list):
            values.extend(
                str(person.get("personName", "") or "").strip()
                for person in direct_people
                if isinstance(person, dict)
            )
        person_name = str(entry.get("personName", "") or "").strip()
        if person_name:
            values.append(person_name)
        values.extend(self._photo_entry_named_people(entry))
        seen: set[str] = set()
        cleaned: list[str] = []
        for value in values:
            key = value.casefold()
            if not value or key in seen:
                continue
            seen.add(key)
            cleaned.append(value)
        return cleaned

    def _photo_entry_curation_dates(self, entry: dict[str, Any]) -> list[str]:
        date_text = self._entry_date_text(entry)
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_text):
            return []
        return [date_text, date_text[:7], date_text[:4]]

    def _photo_entry_curation_content(self, entry: dict[str, Any]) -> list[str]:
        metadata = self._photo_entry_metadata(entry)
        source = str(entry.get("sourcePath", "") or "")
        values = [
            str(entry.get("mediaKind", "") or ""),
            str(metadata.get("title", "") or ""),
            str(metadata.get("caption", "") or ""),
            Path(source).name,
        ]
        raw_keywords = metadata.get("keywords", [])
        if isinstance(raw_keywords, list):
            values.extend(str(keyword or "") for keyword in raw_keywords)
        fixed_holiday = self._photo_memory_fixed_holiday_label(self._entry_date_text(entry))
        if fixed_holiday:
            values.append(fixed_holiday)
        values.extend(label for _category, label in self._photo_memory_event_labels(entry))
        values.extend(self._photo_entry_detected_item_text(entry))
        values.extend(self._photo_entry_accessible_description_text(entry))
        seen: set[str] = set()
        cleaned: list[str] = []
        for value in values:
            clean = re.sub(r"\s+", " ", str(value or "")).strip()
            key = clean.casefold()
            if not clean or key in seen:
                continue
            seen.add(key)
            cleaned.append(clean)
        return cleaned

    def _photo_curation_values_match(self, values: list[str], preference_keys: set[str], *, contains: bool = False) -> bool:
        if not values or not preference_keys:
            return False
        value_keys = {re.sub(r"\s+", " ", str(value or "")).strip().casefold() for value in values if str(value or "").strip()}
        if value_keys & preference_keys:
            return True
        if contains:
            for value_key in value_keys:
                if any(preference_key in value_key or value_key in preference_key for preference_key in preference_keys):
                    return True
        return False

    def _photo_entry_curation_penalty(
        self,
        entry: dict[str, Any],
        preferences: dict[str, Any] | None = None,
        place_labels_by_asset_id: dict[str, list[str]] | None = None,
    ) -> int:
        if preferences is None:
            preferences = self.project.db.photo_curation_preferences()
        if place_labels_by_asset_id is None:
            place_labels_by_asset_id = self._photo_place_labels_by_asset_id()
        penalty = 0
        if self._photo_curation_values_match(
            self._photo_entry_curation_people(entry),
            self._photo_curation_preference_keys(preferences, "featureLessPeople"),
        ):
            penalty += 8
        if self._photo_curation_values_match(
            self._photo_entry_location_text(entry, place_labels_by_asset_id),
            self._photo_curation_preference_keys(preferences, "featureLessPlaces"),
            contains=True,
        ):
            penalty += 6
        if self._photo_curation_values_match(
            self._photo_entry_curation_dates(entry),
            self._photo_curation_preference_keys(preferences, "featureLessDates"),
        ):
            penalty += 4
        if self._photo_curation_values_match(
            self._photo_entry_curation_content(entry),
            self._photo_curation_preference_keys(preferences, "featureLessContent"),
            contains=True,
        ):
            penalty += 2
        return penalty

    def _photo_date_bucket_cover_rank(
        self,
        entry: dict[str, Any],
        curation_preferences: dict[str, Any] | None = None,
        place_labels_by_asset_id: dict[str, list[str]] | None = None,
    ) -> tuple[int, int, float, int, int, int, str, str]:
        return (
            -self._photo_entry_curation_penalty(entry, curation_preferences, place_labels_by_asset_id),
            int(self._photo_entry_direct_bool(entry, "favorite")),
            max(0.0, min(1.0, self._photo_entry_direct_number(entry, "bestQuality", "quality"))),
            self._photo_entry_direct_people_count(entry),
            int(self._photo_entry_direct_has_location(entry)),
            int(self._photo_entry_direct_bool(entry, "edited")),
            self._entry_date_text(entry),
            str(entry.get("sourcePath", "") or "").casefold(),
        )

    def _photo_date_bucket_cover_reason(self, entry: dict[str, Any]) -> str:
        if self._photo_entry_direct_bool(entry, "favorite"):
            return "Favorite"
        if self._photo_entry_direct_people_count(entry) > 0:
            return "People"
        if self._photo_entry_direct_has_location(entry):
            return "Place"
        if self._photo_entry_direct_bool(entry, "edited"):
            return "Edited"
        if str(entry.get("mediaKind", "") or "").strip().lower() in {"video", "time_lapse"}:
            return "Video"
        if self._photo_entry_duplicate_count(entry) > 0:
            return "Duplicate"
        if self._photo_entry_edit_stack_version_count(entry) > 0:
            return "Version"
        if self._photo_entry_direct_number(entry, "bestQuality", "quality") > 0:
            return "Best quality"
        return "Newest"

    def _photo_date_summary_count(self, count: int, singular: str, plural: str | None = None) -> str:
        return f"1 {singular}" if count == 1 else f"{count} {plural or singular + 's'}"

    def _photo_date_bucket_summary_badges(self, entries: list[dict[str, Any]]) -> list[str]:
        favorite_count = sum(1 for entry in entries if self._photo_entry_direct_bool(entry, "favorite"))
        people_photo_count = sum(1 for entry in entries if self._photo_entry_direct_people_count(entry) > 0)
        location_count = sum(1 for entry in entries if self._photo_entry_direct_has_location(entry))
        video_count = sum(1 for entry in entries if str(entry.get("mediaKind", "") or "").strip().lower() in {"video", "time_lapse"})
        edited_count = sum(1 for entry in entries if self._photo_entry_direct_bool(entry, "edited"))
        duplicate_count = sum(1 for entry in entries if self._photo_entry_duplicate_count(entry) > 0)
        version_count = sum(1 for entry in entries if self._photo_entry_edit_stack_version_count(entry) > 0)
        badges = [
            self._photo_date_summary_count(favorite_count, "favorite") if favorite_count else "",
            f"{people_photo_count} with people" if people_photo_count else "",
            self._photo_date_summary_count(location_count, "place") if location_count else "",
            self._photo_date_summary_count(video_count, "video") if video_count else "",
            f"{edited_count} edited" if edited_count else "",
            self._photo_date_summary_count(duplicate_count, "duplicate") if duplicate_count else "",
            self._photo_date_summary_count(version_count, "version") if version_count else "",
        ]
        return [badge for badge in badges if badge]

    def _photo_feature_less_curation_active(self) -> bool:
        preferences = self.project.db.photo_curation_preferences()
        return any(
            preferences.get(key)
            for key in ("featureLessPeople", "featureLessPlaces", "featureLessDates", "featureLessContent")
        )

    def _photo_date_bucket_fast_path_allowed(self, folder_id: str, mode: str, params: dict[str, Any]) -> bool:
        if folder_id != "all" or mode not in {"years", "months", "days"}:
            return False
        if self.project.candidates:
            return False
        if self._photo_feature_less_curation_active():
            return False
        filter_keys = {
            "query", "keyword", "mediaKind", "favoriteOnly", "favorite", "editedOnly", "edited",
            "person", "personName", "status", "reviewStatus", "minQuality", "quality", "dateFrom",
            "fromDate", "dateTo", "toDate", "source", "sourceFolder", "path", "sourcePaths",
            "sources", "libraryRoot", "activeLibraryRoot", "library_root", "fileType", "extension", "duplicateState", "duplicateOnly", "duplicatesOnly",
            "duplicate", "location", "place", "camera", "cameraModel", "nearby", "nearbyLatitude",
            "nearbyLongitude", "nearbyRadiusKm", "latitude", "longitude", "lng", "radius",
            "radiusKm", "album", "albumId", "notInAlbum", "notInAlbumOnly", "hidden", "hiddenOnly",
            "deleted", "deletedOnly", "visibility", "visibilityState", "groupMode", "groupViewMode",
        }
        if any(params.get(key) not in (None, "", False, [], {}) for key in filter_keys):
            return False
        try:
            return self.project.db.count_photo_assets() >= 1000
        except Exception:
            return False

    def _photo_date_bucket_nearby_fast_path_allowed(
        self,
        folder_id: str,
        mode: str,
        params: dict[str, Any],
        nearby_filter: dict[str, float] | None,
    ) -> bool:
        if folder_id != "all" or mode not in {"years", "months", "days", "recentDays"} or not nearby_filter:
            return False
        if self.project.candidates:
            return False
        if self._photo_feature_less_curation_active():
            return False
        filter_keys = {
            "query", "keyword", "mediaKind", "favoriteOnly", "favorite", "editedOnly", "edited",
            "person", "personName", "status", "reviewStatus", "minQuality", "quality", "dateFrom",
            "fromDate", "dateTo", "toDate", "source", "sourceFolder", "path", "sourcePaths",
            "sources", "libraryRoot", "activeLibraryRoot", "library_root", "fileType", "extension", "duplicateState", "duplicateOnly", "duplicatesOnly",
            "duplicate", "location", "place", "camera", "cameraModel", "album", "albumId",
            "notInAlbum", "notInAlbumOnly", "hidden", "hiddenOnly", "deleted", "deletedOnly",
            "visibility", "visibilityState", "groupMode", "groupViewMode",
        }
        return not any(params.get(key) not in (None, "", False, [], {}) for key in filter_keys)

    def _photo_date_buckets_sql_all(self, mode: str, required_asset_ids: Iterable[str] = ()) -> dict[str, Any]:
        key_expr = {
            "years": "SUBSTR(date_text, 1, 4)",
            "months": "SUBSTR(date_text, 1, 7)",
            "days": "date_text",
            "recentDays": "date_text",
        }[mode]
        clean_required_asset_ids: list[str] = []
        seen_required_asset_ids: set[str] = set()
        for value in required_asset_ids:
            asset_id = str(value or "").strip()
            if asset_id and asset_id not in seen_required_asset_ids:
                seen_required_asset_ids.add(asset_id)
                clean_required_asset_ids.append(asset_id)
        required_filter_sql = ""
        with self.project.db.connect() as conn:
            if clean_required_asset_ids:
                conn.execute("DROP TABLE IF EXISTS temp_photo_date_bucket_asset_filter")
                conn.execute("CREATE TEMP TABLE temp_photo_date_bucket_asset_filter(asset_id TEXT PRIMARY KEY)")
                conn.executemany(
                    "INSERT OR IGNORE INTO temp_photo_date_bucket_asset_filter(asset_id) VALUES (?)",
                    [(asset_id,) for asset_id in clean_required_asset_ids],
                )
                required_filter_sql = (
                    "AND EXISTS (SELECT 1 FROM temp_photo_date_bucket_asset_filter AS baf WHERE baf.asset_id = a.asset_id)"
                )
            rows = conn.execute(
                f"""
                WITH visible AS (
                    SELECT
                        a.asset_id AS asset_id,
                        a.source_path AS source_path,
                        a.media_kind AS media_kind,
                        SUBSTR(COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), NULLIF(a.added_at, '')), 1, 10) AS date_text,
                        COALESCE(m.favorite, 0) AS favorite,
                        COALESCE(m.edited, 0) AS edited,
                        COALESCE(m.location_hidden, 0) AS location_hidden,
                        COALESCE(m.location_override_json, '{{}}') AS location_json,
                        EXISTS(SELECT 1 FROM photo_asset_people AS p WHERE p.asset_id = a.asset_id LIMIT 1) AS has_people,
                        EXISTS(SELECT 1 FROM photo_duplicate_group_items AS d WHERE d.asset_id = a.asset_id LIMIT 1) AS has_duplicate,
                        EXISTS(SELECT 1 FROM photo_edit_stack_versions AS v WHERE v.asset_id = a.asset_id LIMIT 1) AS has_versions
                    FROM photo_assets AS a
                    LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                    WHERE COALESCE(m.hidden, 0) = 0
                        AND m.deleted_at IS NULL
                        {required_filter_sql}
                ),
                keyed AS (
                    SELECT *, {key_expr} AS bucket_key
                    FROM visible
                    WHERE date_text GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'
                )
                SELECT
                    bucket_key,
                    COUNT(*) AS n,
                    SUM(CASE WHEN favorite THEN 1 ELSE 0 END) AS favorite_count,
                    SUM(CASE WHEN has_people THEN 1 ELSE 0 END) AS people_count,
                    SUM(CASE WHEN location_hidden = 0 AND location_json NOT IN ('', '{{}}') THEN 1 ELSE 0 END) AS location_count,
                    SUM(CASE WHEN media_kind IN ('video', 'time_lapse') THEN 1 ELSE 0 END) AS video_count,
                    SUM(CASE WHEN edited THEN 1 ELSE 0 END) AS edited_count,
                    SUM(CASE WHEN has_duplicate THEN 1 ELSE 0 END) AS duplicate_count,
                    SUM(CASE WHEN has_versions THEN 1 ELSE 0 END) AS version_count
                FROM keyed
                WHERE bucket_key != ''
                GROUP BY bucket_key
                ORDER BY bucket_key DESC
                """
            ).fetchall()
            if mode == "recentDays" and rows:
                latest_key = str(rows[0]["bucket_key"] or "")
                try:
                    latest_date = datetime.fromisoformat(f"{latest_key}T00:00:00")
                    cutoff_key = (latest_date - timedelta(days=30)).strftime("%Y-%m-%d")
                    rows = [
                        row for row in rows
                        if cutoff_key <= str(row["bucket_key"] or "") <= latest_key
                    ]
                except ValueError:
                    rows = []
            buckets = []
            for row in rows:
                key = str(row["bucket_key"] or "")
                cover = conn.execute(
                    f"""
                    WITH visible AS (
                        SELECT
                            a.asset_id AS asset_id,
                            a.source_path AS source_path,
                            a.media_kind AS media_kind,
                            SUBSTR(COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), NULLIF(a.added_at, '')), 1, 10) AS date_text,
                            COALESCE(m.title, '') AS title,
                            COALESCE(m.favorite, 0) AS favorite,
                            COALESCE(m.edited, 0) AS edited,
                            COALESCE(m.location_hidden, 0) AS location_hidden,
                            COALESCE(m.location_override_json, '{{}}') AS location_json,
                            EXISTS(SELECT 1 FROM photo_asset_people AS p WHERE p.asset_id = a.asset_id LIMIT 1) AS has_people,
                            EXISTS(SELECT 1 FROM photo_duplicate_group_items AS d WHERE d.asset_id = a.asset_id LIMIT 1) AS has_duplicate,
                            EXISTS(SELECT 1 FROM photo_edit_stack_versions AS v WHERE v.asset_id = a.asset_id LIMIT 1) AS has_versions
                        FROM photo_assets AS a
                        LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                        WHERE COALESCE(m.hidden, 0) = 0
                            AND m.deleted_at IS NULL
                            {required_filter_sql}
                    ),
                    keyed AS (
                        SELECT *, {key_expr} AS bucket_key
                        FROM visible
                        WHERE date_text GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'
                    )
                    SELECT *
                    FROM keyed
                    WHERE bucket_key = ?
                    ORDER BY favorite DESC, has_people DESC,
                        CASE WHEN location_hidden = 0 AND location_json NOT IN ('', '{{}}') THEN 1 ELSE 0 END DESC,
                        edited DESC,
                        date_text DESC,
                        source_path ASC
                    LIMIT 1
                    """,
                    (key,),
                ).fetchone()
                cover_source = str(cover["source_path"] or "") if cover else ""
                cover_title = str(cover["title"] or "").strip() if cover else ""
                cover_reason = "Newest"
                if cover:
                    if int(cover["favorite"] or 0):
                        cover_reason = "Favorite"
                    elif int(cover["has_people"] or 0):
                        cover_reason = "People"
                    elif int(cover["location_hidden"] or 0) == 0 and str(cover["location_json"] or "{}") not in {"", "{}"}:
                        cover_reason = "Place"
                    elif int(cover["edited"] or 0):
                        cover_reason = "Edited"
                    elif str(cover["media_kind"] or "") in {"video", "time_lapse"}:
                        cover_reason = "Video"
                    elif int(cover["has_duplicate"] or 0):
                        cover_reason = "Duplicate"
                    elif int(cover["has_versions"] or 0):
                        cover_reason = "Version"
                favorite_count = int(row["favorite_count"] or 0)
                people_count = int(row["people_count"] or 0)
                location_count = int(row["location_count"] or 0)
                video_count = int(row["video_count"] or 0)
                edited_count = int(row["edited_count"] or 0)
                duplicate_count = int(row["duplicate_count"] or 0)
                version_count = int(row["version_count"] or 0)
                summary_badges = [
                    self._photo_date_summary_count(favorite_count, "favorite") if favorite_count else "",
                    f"{people_count} with people" if people_count else "",
                    self._photo_date_summary_count(location_count, "place") if location_count else "",
                    self._photo_date_summary_count(video_count, "video") if video_count else "",
                    f"{edited_count} edited" if edited_count else "",
                    self._photo_date_summary_count(duplicate_count, "duplicate") if duplicate_count else "",
                    self._photo_date_summary_count(version_count, "version") if version_count else "",
                ]
                buckets.append({
                    "key": key,
                    "label": self._photo_date_bucket_label(key, mode),
                    "count": int(row["n"] or 0),
                    "coverTitle": cover_title or (Path(cover_source).name if cover_source else ""),
                    "coverReason": cover_reason,
                    "coverSourcePath": cover_source,
                    "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
                    "favoriteCount": favorite_count,
                    "peoplePhotoCount": people_count,
                    "locationCount": location_count,
                    "videoCount": video_count,
                    "editedCount": edited_count,
                    "duplicateCount": duplicate_count,
                    "versionCount": version_count,
                    "summaryBadges": [badge for badge in summary_badges if badge],
                })
        return {"folderId": "all", "mode": mode, "total": len(buckets), "buckets": buckets}

    def _photo_sql_date_bucket_payload(
        self,
        *,
        folder_id: str,
        mode: str,
        summaries: list[dict[str, Any]],
        search_index: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        buckets: list[dict[str, Any]] = []
        for row in summaries:
            key = str(row.get("key", "") or "")
            cover_source = str(row.get("coverSourcePath", "") or "")
            favorite_count = int(row.get("favoriteCount", 0) or 0)
            people_count = int(row.get("peoplePhotoCount", 0) or 0)
            location_count = int(row.get("locationCount", 0) or 0)
            video_count = int(row.get("videoCount", 0) or 0)
            edited_count = int(row.get("editedCount", 0) or 0)
            duplicate_count = int(row.get("duplicateCount", 0) or 0)
            version_count = int(row.get("versionCount", 0) or 0)
            summary_badges = [
                self._photo_date_summary_count(favorite_count, "favorite") if favorite_count else "",
                f"{people_count} with people" if people_count else "",
                self._photo_date_summary_count(location_count, "place") if location_count else "",
                self._photo_date_summary_count(video_count, "video") if video_count else "",
                f"{edited_count} edited" if edited_count else "",
                self._photo_date_summary_count(duplicate_count, "duplicate") if duplicate_count else "",
                self._photo_date_summary_count(version_count, "version") if version_count else "",
            ]
            buckets.append({
                "key": key,
                "label": self._photo_date_bucket_label(key, mode),
                "count": int(row.get("count", 0) or 0),
                "coverTitle": str(row.get("coverTitle", "") or "").strip() or (Path(cover_source).name if cover_source else ""),
                "coverReason": str(row.get("coverReason", "") or "Newest"),
                "coverSourcePath": cover_source,
                "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
                "favoriteCount": favorite_count,
                "peoplePhotoCount": people_count,
                "locationCount": location_count,
                "videoCount": video_count,
                "editedCount": edited_count,
                "duplicateCount": duplicate_count,
                "versionCount": version_count,
                "summaryBadges": [badge for badge in summary_badges if badge],
            })
        payload: dict[str, Any] = {"folderId": folder_id, "mode": mode, "total": len(buckets), "buckets": buckets}
        if search_index:
            payload["searchIndex"] = search_index
        return payload

    def _photo_all_date_buckets_sql_from_params(
        self,
        folder_id: str,
        mode: str,
        params: dict[str, Any],
        nearby_filter: dict[str, float] | None,
    ) -> dict[str, Any] | None:
        if folder_id != "all" or mode not in {"years", "months", "days", "recentDays"}:
            return None
        group_mode = self._normalize_photo_group_mode(params.get("groupMode", params.get("groupViewMode", "all")))
        if group_mode != "all":
            return None
        query = str(params.get("query", "") or "").strip()
        keyword = str(params.get("keyword", "") or "").strip()
        media_kind_filter = str(params.get("mediaKind", "") or "").strip().lower()
        date_from_filter = self._normalize_photo_date_filter(params.get("dateFrom", params.get("fromDate", "")))
        date_to_filter = self._normalize_photo_date_filter(params.get("dateTo", params.get("toDate", "")))
        source_filter = str(params.get("source", params.get("sourceFolder", params.get("path", ""))) or "").strip()
        library_root_filter = self._photo_library_root_filter_from_params(params)
        library_root_source_filters = self._photo_library_root_source_text_filters(library_root_filter)
        source_paths_raw = params.get("sourcePaths", params.get("sources", []))
        source_paths_filter = {
            str(path or "").strip()
            for path in source_paths_raw
            if str(path or "").strip()
        } if isinstance(source_paths_raw, list) else set()
        if source_paths_filter:
            return None
        if self._photo_feature_less_curation_active():
            return None
        file_type_filter = str(params.get("fileType", params.get("extension", "")) or "").strip().lower().lstrip(".")
        location_filter = str(params.get("location", params.get("place", "")) or "").strip()
        camera_filter = str(params.get("camera", params.get("cameraModel", "")) or "").strip()
        album_filter = str(params.get("albumId", params.get("album", "")) or "").strip()
        person_filter = str(params.get("person", params.get("personName", "")) or "").strip()
        status_filter = str(params.get("status", params.get("reviewStatus", "")) or "").strip().lower()
        if status_filter not in {"", "pending", "accepted", "rejected", "uncertain"}:
            status_filter = ""
        try:
            min_quality_filter = max(0.0, min(1.0, float(params.get("minQuality", params.get("quality", 0)) or 0.0)))
        except (TypeError, ValueError):
            min_quality_filter = 0.0

        def truthy(value: Any) -> bool:
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return bool(value)
            return str(value or "").strip().lower() in {"1", "true", "yes", "on"}

        favorite_only = truthy(params.get("favoriteOnly", params.get("favorite", False)))
        edited_only = truthy(params.get("editedOnly", params.get("edited", False)))
        not_in_album_only = truthy(params.get("notInAlbumOnly", params.get("notInAlbum", False)))
        duplicate_only = truthy(params.get("duplicateOnly", params.get("duplicatesOnly", params.get("duplicate", False))))
        visibility_filter = self._normalize_photo_visibility_filter(
            params.get("visibility", params.get("visibilityState", "")),
            hidden_only=truthy(params.get("hiddenOnly", False)),
            deleted_only=truthy(params.get("deletedOnly", False)),
        )
        manual_album_ids = self._photo_manual_album_filter_ids(album_filter)
        if album_filter and not manual_album_ids:
            return None
        if self.project.candidates:
            return None
        if duplicate_only:
            self.project.db.ensure_photo_duplicate_groups()
        media_kind = media_kind_filter if media_kind_filter in PHOTO_MEDIA_KINDS else ""
        visibility = visibility_filter if visibility_filter in {"all", "hidden", "deleted", "visible"} else "visible"
        search_index_status: dict[str, Any] = {}
        if str(query or "").strip():
            search_index_status = self.project.db.ensure_photo_search_index(allow_rebuild=False, enqueue_on_cold=True, repair_limit=1000)
        location_asset_ids = self._photo_location_filter_asset_ids(location_filter)
        nearby_asset_ids: tuple[str, ...] = ()
        if nearby_filter:
            nearby_asset_ids = tuple(
                self.project.db.list_photo_asset_ids_nearby(
                    latitude=float(nearby_filter["latitude"]),
                    longitude=float(nearby_filter["longitude"]),
                    radius_km=float(nearby_filter["radiusKm"]),
                )
            )
            if not nearby_asset_ids:
                return {"folderId": folder_id, "mode": mode, "total": 0, "buckets": []}
        summaries = self.project.db.list_photo_date_bucket_summaries(
            mode,
            query=query,
            visibility=visibility,
            media_kind=media_kind,
            favorite_only=favorite_only,
            edited_only=edited_only,
            keyword=keyword,
            date_from=date_from_filter,
            date_to=date_to_filter,
            source=source_filter,
            source_text_filters=library_root_source_filters,
            required_asset_ids=nearby_asset_ids,
            file_type_aliases=self._photo_file_type_aliases(file_type_filter),
            location=location_filter,
            location_asset_ids=location_asset_ids,
            camera=camera_filter,
            duplicate_state=True if duplicate_only else None,
            manual_album_ids=manual_album_ids or (),
            manual_album_membership_state=False if not_in_album_only else None,
            candidate_person_name=person_filter,
            candidate_status=status_filter,
            candidate_min_quality=min_quality_filter,
        )
        return self._photo_sql_date_bucket_payload(folder_id=folder_id, mode=mode, summaries=summaries, search_index=search_index_status)

    def _photo_trip_location_label(self, entry: dict[str, Any], place_labels_by_asset_id: dict[str, list[str]]) -> str:
        metadata = self._photo_entry_metadata(entry)
        if bool(metadata.get("locationHidden", False)):
            return ""
        override = metadata.get("locationOverride", {}) if isinstance(metadata.get("locationOverride", {}), dict) else {}
        label = str(override.get("label", "") or "").strip()
        if label:
            return label
        asset_id = str(entry.get("_assetId", "") or "")
        if not asset_id:
            asset = self._photo_entry_asset(entry)
            asset_id = str(asset.get("assetId", "") or "") if asset else ""
        for value in place_labels_by_asset_id.get(asset_id, []):
            clean = str(value or "").strip()
            if clean:
                return clean
        coordinates = self._photo_entry_coordinates(entry)
        return f"{coordinates[0]:.4f}, {coordinates[1]:.4f}" if coordinates else ""

    def _photo_trip_date(self, entry: dict[str, Any]) -> datetime | None:
        date_text = self._entry_date_text(entry)
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_text):
            return None
        try:
            return datetime.fromisoformat(f"{date_text}T00:00:00")
        except ValueError:
            return None

    def _photo_trip_date_range_label(self, start_date: str, end_date: str) -> str:
        if start_date == end_date:
            return self._photo_date_bucket_label(start_date, "days")
        return f"{self._photo_date_bucket_label(start_date, 'days')} to {self._photo_date_bucket_label(end_date, 'days')}"

    def _photo_trip_label(self, labels: list[str], date_range_label: str) -> str:
        clean_labels: list[str] = []
        seen: set[str] = set()
        for label in labels:
            clean = str(label or "").strip()
            if not clean:
                continue
            key = clean.casefold()
            if key in seen:
                continue
            seen.add(key)
            clean_labels.append(clean)
        if not clean_labels:
            return f"Trip {date_range_label}"
        if len(clean_labels) == 1:
            return f"{clean_labels[0]} Trip"
        return f"{' / '.join(clean_labels[:2])} Trip"

    def _photo_trip_summary_from_records(
        self,
        records: list[dict[str, Any]],
        curation_preferences: dict[str, Any] | None = None,
        place_labels_by_asset_id: dict[str, list[str]] | None = None,
    ) -> dict[str, Any] | None:
        if len(records) < 2:
            return None
        sorted_records = sorted(records, key=lambda record: (record["date"], str(record["entry"].get("sourcePath", "") or "").casefold()))
        source_paths = [str(record["entry"].get("sourcePath", "") or "") for record in sorted_records if str(record["entry"].get("sourcePath", "") or "")]
        if len(set(source_paths)) < 2:
            return None
        start_date = sorted_records[0]["date"].strftime("%Y-%m-%d")
        end_date = sorted_records[-1]["date"].strftime("%Y-%m-%d")
        date_range_label = self._photo_trip_date_range_label(start_date, end_date)
        label_counts: dict[str, int] = {}
        for record in sorted_records:
            label = str(record.get("label", "") or "").strip()
            if label:
                label_counts[label] = label_counts.get(label, 0) + 1
        labels = [
            label for label, _count in sorted(
                label_counts.items(),
                key=lambda item: (-item[1], item[0].casefold()),
            )
        ]
        latitude = sum(float(record["coordinates"][0]) for record in sorted_records) / len(sorted_records)
        longitude = sum(float(record["coordinates"][1]) for record in sorted_records) / len(sorted_records)
        movement_km = 0.0
        previous = sorted_records[0]["coordinates"]
        for record in sorted_records[1:]:
            current = record["coordinates"]
            movement_km += self._photo_distance_km(previous, current)
            previous = current
        if curation_preferences is None:
            curation_preferences = self.project.db.photo_curation_preferences()
        if place_labels_by_asset_id is None:
            place_labels_by_asset_id = self._photo_place_labels_by_asset_id()
        cover_entry = max(
            (record["entry"] for record in sorted_records),
            key=lambda entry: self._photo_date_bucket_cover_rank(entry, curation_preferences, place_labels_by_asset_id),
        )
        cover_source = str(cover_entry.get("sourcePath", "") or "")
        digest = hashlib.sha1("|".join(sorted(set(source_paths))).encode("utf-8")).hexdigest()[:12]
        trip_id = f"{start_date}:{end_date}:{digest}"
        return {
            "tripId": trip_id,
            "name": self._photo_trip_label(labels, date_range_label),
            "count": len(set(source_paths)),
            "startDate": start_date,
            "endDate": end_date,
            "dateRangeLabel": date_range_label,
            "locationLabel": " / ".join(labels[:3]),
            "locationLabels": labels[:8],
            "latitude": round(latitude, 6),
            "longitude": round(longitude, 6),
            "movementKm": round(movement_km, 2),
            "coverSourcePath": cover_source,
            "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
            "sourcePaths": sorted(set(source_paths)),
        }

    def _photo_trip_summaries(self, entries: list[dict[str, Any]] | None = None) -> list[dict[str, Any]]:
        base_entries = list(entries) if entries is not None else self._visible_photo_entries(self._all_photo_entries())
        place_labels_by_asset_id = self._photo_place_labels_by_asset_id()
        curation_preferences = self.project.db.photo_curation_preferences()
        records: list[dict[str, Any]] = []
        for entry in base_entries:
            date_value = self._photo_trip_date(entry)
            coordinates = self._photo_entry_coordinates(entry)
            if date_value is None or coordinates is None:
                continue
            records.append({
                "entry": entry,
                "date": date_value,
                "coordinates": coordinates,
                "label": self._photo_trip_location_label(entry, place_labels_by_asset_id),
            })
        records.sort(key=lambda record: (record["date"], str(record["entry"].get("sourcePath", "") or "").casefold()))
        trips: list[dict[str, Any]] = []
        current: list[dict[str, Any]] = []
        for record in records:
            if not current:
                current = [record]
                continue
            last_date = current[-1]["date"]
            gap_days = (record["date"] - last_date).days
            latitude = sum(float(item["coordinates"][0]) for item in current) / len(current)
            longitude = sum(float(item["coordinates"][1]) for item in current) / len(current)
            distance_km = self._photo_distance_km((latitude, longitude), record["coordinates"])
            if gap_days > 3 or distance_km > 250.0:
                summary = self._photo_trip_summary_from_records(current, curation_preferences, place_labels_by_asset_id)
                if summary:
                    trips.append(summary)
                current = [record]
                continue
            current.append(record)
        summary = self._photo_trip_summary_from_records(current, curation_preferences, place_labels_by_asset_id)
        if summary:
            trips.append(summary)
        return sorted(trips, key=lambda trip: (str(trip.get("startDate", "") or ""), str(trip.get("name", "") or "")), reverse=True)

    def _photo_trip_by_id(self, trip_id: str, entries: list[dict[str, Any]] | None = None) -> dict[str, Any] | None:
        clean_id = str(trip_id or "").strip()
        for trip in self._photo_trip_summaries(entries):
            if str(trip.get("tripId", "") or "") == clean_id:
                return trip
        return None

    def _photo_memory_preference_ids(self, preferences: dict[str, Any] | None, key: str) -> set[str]:
        values = preferences.get(key, []) if isinstance(preferences, dict) else []
        if not isinstance(values, list):
            return set()
        return {
            re.sub(r"\s+", " ", str(value or "")).strip()
            for value in values
            if re.sub(r"\s+", " ", str(value or "")).strip()
        }

    def _photo_memory_removed_sources(self, preferences: dict[str, Any] | None, memory_id: str) -> set[str]:
        if not isinstance(preferences, dict):
            return set()
        removed = preferences.get("memoryRemovedItems", {})
        if not isinstance(removed, dict):
            return set()
        values = removed.get(memory_id, [])
        if not isinstance(values, list):
            return set()
        return {str(value or "").strip() for value in values if str(value or "").strip()}

    def _photo_nth_weekday_date(self, year: int, month: int, weekday: int, occurrence: int) -> datetime:
        first = datetime(year, month, 1)
        return first + timedelta(days=(weekday - first.weekday()) % 7 + (max(1, occurrence) - 1) * 7)

    def _photo_last_weekday_date(self, year: int, month: int, weekday: int) -> datetime:
        if month == 12:
            last = datetime(year, month, 31)
        else:
            last = datetime(year, month + 1, 1) - timedelta(days=1)
        return last - timedelta(days=(last.weekday() - weekday) % 7)

    def _photo_easter_date(self, year: int) -> datetime:
        # Meeus/Jones/Butcher Gregorian computus; deterministic and offline.
        a = year % 19
        b = year // 100
        c = year % 100
        d = b // 4
        e = b % 4
        f = (b + 8) // 25
        g = (b - f + 1) // 3
        h = (19 * a + b - d - g + 15) % 30
        i = c // 4
        k = c % 4
        l = (32 + 2 * e + 2 * i - h - k) % 7
        m = (a + 11 * h + 22 * l) // 451
        month = (h + l - 7 * m + 114) // 31
        day = ((h + l - 7 * m + 114) % 31) + 1
        return datetime(year, month, day)

    def _photo_memory_fixed_holiday_label(self, date_text: str) -> str:
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", str(date_text or "")):
            return ""
        try:
            day = datetime.strptime(date_text, "%Y-%m-%d")
        except ValueError:
            return ""
        month_day = day.strftime("%m-%d")
        fixed_labels = {
            "01-01": "New Year's Day",
            "02-14": "Valentine's Day",
            "03-17": "St. Patrick's Day",
            "06-19": "Juneteenth",
            "07-04": "Fourth of July",
            "10-31": "Halloween",
            "11-11": "Veterans Day",
            "12-24": "Christmas",
            "12-25": "Christmas",
            "12-26": "Christmas",
            "12-31": "New Year's Eve",
        }
        if month_day in fixed_labels:
            return fixed_labels[month_day]
        calendar_labels = [
            ("Martin Luther King Jr. Day", self._photo_nth_weekday_date(day.year, 1, 0, 3)),
            ("Presidents' Day", self._photo_nth_weekday_date(day.year, 2, 0, 3)),
            ("Mother's Day", self._photo_nth_weekday_date(day.year, 5, 6, 2)),
            ("Memorial Day", self._photo_last_weekday_date(day.year, 5, 0)),
            ("Father's Day", self._photo_nth_weekday_date(day.year, 6, 6, 3)),
            ("Labor Day", self._photo_nth_weekday_date(day.year, 9, 0, 1)),
            ("Indigenous Peoples' Day", self._photo_nth_weekday_date(day.year, 10, 0, 2)),
        ]
        for label, holiday in calendar_labels:
            if day.date() == holiday.date():
                return label
        easter = self._photo_easter_date(day.year)
        if (easter - timedelta(days=2)).date() <= day.date() <= (easter + timedelta(days=1)).date():
            return "Easter"
        if day.month == 11:
            first = datetime(day.year, 11, 1)
            first_thursday = first + timedelta(days=(3 - first.weekday()) % 7)
            thanksgiving = first_thursday + timedelta(days=21)
            if thanksgiving.date() <= day.date() <= (thanksgiving + timedelta(days=3)).date():
                return "Thanksgiving"
        return ""

    def _photo_memory_event_text(self, entry: dict[str, Any]) -> str:
        asset = self._photo_entry_asset(entry) or {}
        asset_metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
        metadata = self._photo_entry_metadata(entry)
        values = [Path(str(entry.get("sourcePath", "") or "")).name]
        values.extend([
            str(metadata.get("title", "") or ""),
            str(metadata.get("caption", "") or ""),
        ])
        keywords = metadata.get("keywords", [])
        if isinstance(keywords, list):
            values.extend(str(keyword or "") for keyword in keywords)
        if isinstance(asset_metadata, dict):
            for key in (
                "detectedEvents",
                "events",
                "eventLabels",
                "eventTags",
                "occasion",
                "occasionLabels",
                "modelTags",
                "tags",
                "labels",
                "sceneTags",
                "objectTags",
            ):
                if key in asset_metadata:
                    values.extend(self._photo_classifier_metadata_values(asset_metadata.get(key)))
        return " ".join(str(value or "") for value in values if str(value or "").strip())

    def _photo_memory_event_labels(self, entry: dict[str, Any]) -> list[tuple[str, str]]:
        text = self._photo_memory_event_text(entry).casefold()
        if not text:
            return []
        normalized = re.sub(r"[^a-z0-9]+", " ", text)
        labels: list[tuple[str, str]] = []
        holiday_patterns = [
            ("Christmas", r"\b(christmas|xmas)\b"),
            ("Halloween", r"\bhalloween\b"),
            ("Thanksgiving", r"\bthanksgiving\b"),
            ("New Year's", r"\bnew year(?:s|'s)?\b"),
            ("Valentine's Day", r"\bvalentine(?:s|'s)?\b"),
            ("Diwali", r"\bdiwali\b"),
            ("Eid", r"\beid\b"),
            ("Hanukkah", r"\bhanukkah\b"),
            ("Holi", r"\bholi\b"),
        ]
        event_patterns = [
            ("Birthday", r"\bbirthday\b"),
            ("Wedding", r"\bwedding\b"),
            ("Graduation", r"\bgraduation\b"),
            ("Anniversary", r"\banniversary\b"),
            ("Concert", r"\bconcert\b"),
            ("Festival", r"\bfestival\b"),
            ("Party", r"\bparty\b"),
            ("Reunion", r"\breunion\b"),
            ("Parade", r"\bparade\b"),
            ("Game Day", r"\b(game|match|tournament)\b"),
        ]
        for label, pattern in holiday_patterns:
            if re.search(pattern, normalized):
                labels.append(("holiday", label))
        for label, pattern in event_patterns:
            if re.search(pattern, normalized):
                labels.append(("event", label))
        seen: set[tuple[str, str]] = set()
        unique: list[tuple[str, str]] = []
        for item in labels:
            if item in seen:
                continue
            seen.add(item)
            unique.append(item)
        return unique[:3]

    def _photo_memory_summary(
        self,
        *,
        category: str,
        name: str,
        entries: list[dict[str, Any]],
        subtitle: str = "",
        sort_hint: str = "",
        memory_id: str = "",
        cover_source_path: str = "",
        created_at: str = "",
        updated_at: str = "",
        movie_settings: dict[str, Any] | None = None,
        curation_preferences: dict[str, Any] | None = None,
        place_labels_by_asset_id: dict[str, list[str]] | None = None,
    ) -> dict[str, Any] | None:
        seen_sources: set[str] = set()
        unique_entries: list[dict[str, Any]] = []
        for entry in entries:
            source = str(entry.get("sourcePath", "") or "")
            if not source or source in seen_sources:
                continue
            seen_sources.add(source)
            unique_entries.append(entry)
        if len(unique_entries) < 2:
            return None
        if curation_preferences is None:
            curation_preferences = self.project.db.photo_curation_preferences()
        if place_labels_by_asset_id is None:
            place_labels_by_asset_id = self._photo_place_labels_by_asset_id()
        raw_source_paths = sorted(str(entry.get("sourcePath", "") or "") for entry in unique_entries if str(entry.get("sourcePath", "") or ""))
        digest = hashlib.sha1(f"{category}|{name}|{'|'.join(sorted(raw_source_paths))}".encode("utf-8")).hexdigest()[:12]
        memory_id = str(memory_id or "").strip() or f"{category}:{digest}"
        hidden_memory_ids = self._photo_memory_preference_ids(curation_preferences, "hiddenMemories")
        if memory_id in hidden_memory_ids:
            return None
        removed_sources = self._photo_memory_removed_sources(curation_preferences, memory_id)
        personalized_entries = [
            entry
            for entry in unique_entries
            if str(entry.get("sourcePath", "") or "") not in removed_sources
            and self._photo_entry_curation_penalty(entry, curation_preferences, place_labels_by_asset_id) <= 0
        ]
        if len(personalized_entries) < 2:
            return None
        if cover_source_path and any(str(entry.get("sourcePath", "") or "") == cover_source_path for entry in personalized_entries):
            cover_entry = next(entry for entry in personalized_entries if str(entry.get("sourcePath", "") or "") == cover_source_path)
        else:
            cover_entry = max(
                personalized_entries,
                key=lambda entry: self._photo_date_bucket_cover_rank(entry, curation_preferences, place_labels_by_asset_id),
            )
        if category == "user":
            source_paths = [
                str(entry.get("sourcePath", "") or "")
                for entry in personalized_entries
                if str(entry.get("sourcePath", "") or "")
            ]
        else:
            source_paths = sorted(str(entry.get("sourcePath", "") or "") for entry in personalized_entries if str(entry.get("sourcePath", "") or ""))
        dates = sorted({self._entry_date_text(entry) for entry in personalized_entries if self._entry_date_text(entry)})
        favorite_memory_ids = self._photo_memory_preference_ids(curation_preferences, "favoriteMemories")
        result = {
            "memoryId": memory_id,
            "category": category,
            "name": str(name or "Memory"),
            "subtitle": subtitle,
            "count": len(source_paths),
            "rawCount": len(raw_source_paths),
            "userCreated": category == "user",
            "createdAt": created_at,
            "updatedAt": updated_at,
            "startDate": dates[0] if dates else "",
            "endDate": dates[-1] if dates else "",
            "dateRangeLabel": self._photo_trip_date_range_label(dates[0], dates[-1]) if dates else "",
            "coverSourcePath": str(cover_entry.get("sourcePath", "") or ""),
            "coverPreviewPath": self.project.preview_path_for(str(cover_entry.get("sourcePath", "") or ""), create=False) if cover_entry else None,
            "sourcePaths": source_paths,
            "favorite": memory_id in favorite_memory_ids,
            "hidden": False,
            "removedSourceCount": len([path for path in raw_source_paths if path in removed_sources]),
            "sortHint": sort_hint or updated_at or (dates[-1] if dates else ""),
        }
        if category == "user" and isinstance(movie_settings, dict):
            result["movieSettings"] = movie_settings
        return result

    def _photo_memory_summaries(
        self,
        entries: list[dict[str, Any]] | None = None,
        *,
        trips: list[dict[str, Any]] | None = None,
    ) -> list[dict[str, Any]]:
        base_entries = list(entries) if entries is not None else self._visible_photo_entries(self._all_photo_entries())
        if not base_entries:
            return []
        curation_preferences = self.project.db.photo_curation_preferences()
        place_labels_by_asset_id = self._photo_place_labels_by_asset_id()
        memories: list[dict[str, Any]] = []
        seen_keys: set[str] = set()

        def add_memory(
            category: str,
            name: str,
            selected: list[dict[str, Any]],
            subtitle: str = "",
            sort_hint: str = "",
            memory_id: str = "",
            cover_source_path: str = "",
            created_at: str = "",
            updated_at: str = "",
            movie_settings: dict[str, Any] | None = None,
        ) -> None:
            summary = self._photo_memory_summary(
                category=category,
                name=name,
                entries=selected,
                subtitle=subtitle,
                sort_hint=sort_hint,
                memory_id=memory_id,
                cover_source_path=cover_source_path,
                created_at=created_at,
                updated_at=updated_at,
                movie_settings=movie_settings,
                curation_preferences=curation_preferences,
                place_labels_by_asset_id=place_labels_by_asset_id,
            )
            if not summary:
                return
            key = f"user:{summary.get('memoryId', '')}" if category == "user" else "|".join(sorted(str(path or "") for path in summary.get("sourcePaths", [])))
            if not key or key in seen_keys:
                return
            seen_keys.add(key)
            memories.append(summary)

        favorite_entries = [entry for entry in base_entries if self._photo_entry_direct_bool(entry, "favorite")]
        add_memory("favorites", "Favorite Moments", favorite_entries, "Favorites from your local library", "zzzz-favorites")

        by_year: dict[str, list[dict[str, Any]]] = {}
        by_month: dict[str, list[dict[str, Any]]] = {}
        for entry in base_entries:
            date_text = self._entry_date_text(entry)
            if re.match(r"^\d{4}-\d{2}-\d{2}$", date_text):
                by_year.setdefault(date_text[:4], []).append(entry)
                by_month.setdefault(date_text[:7], []).append(entry)
        for year, year_entries in sorted(by_year.items(), reverse=True)[:6]:
            ranked = sorted(
                year_entries,
                key=lambda entry: self._photo_date_bucket_cover_rank(entry, curation_preferences, place_labels_by_asset_id),
                reverse=True,
            )
            add_memory("year", f"Best of {year}", ranked[:24], f"{len(year_entries)} photos from {year}", year)
        for month, month_entries in sorted(by_month.items(), reverse=True)[:12]:
            if len(month_entries) < 3:
                continue
            add_memory(
                "month",
                self._photo_date_bucket_label(month, "months"),
                month_entries,
                f"{len(month_entries)} photos",
                month,
            )

        holiday_entries: dict[tuple[str, str], list[dict[str, Any]]] = {}
        event_entries: dict[tuple[str, str], list[dict[str, Any]]] = {}

        def add_memory_group_entry(target: dict[tuple[str, str], list[dict[str, Any]]], key: tuple[str, str], entry: dict[str, Any]) -> None:
            source = str(entry.get("sourcePath", "") or "")
            group = target.setdefault(key, [])
            if source and any(str(existing.get("sourcePath", "") or "") == source for existing in group):
                return
            group.append(entry)

        for entry in base_entries:
            date_text = self._entry_date_text(entry)
            year = date_text[:4] if re.match(r"^\d{4}-\d{2}-\d{2}$", date_text) else ""
            fixed_holiday = self._photo_memory_fixed_holiday_label(date_text)
            if fixed_holiday:
                add_memory_group_entry(holiday_entries, (fixed_holiday, year), entry)
            for category, label in self._photo_memory_event_labels(entry):
                target = holiday_entries if category == "holiday" else event_entries
                add_memory_group_entry(target, (label, year), entry)

        def memory_group_sort_key(item: tuple[tuple[str, str], list[dict[str, Any]]]) -> tuple[str, int, str]:
            (label, year), selected = item
            dates = [self._entry_date_text(entry) for entry in selected if self._entry_date_text(entry)]
            return (max(dates, default=year), len(selected), label)

        for (label, year), selected in sorted(holiday_entries.items(), key=memory_group_sort_key, reverse=True)[:12]:
            name = f"{label} {year}" if year else f"{label} Memories"
            add_memory(
                "holiday",
                name,
                selected,
                f"{len(selected)} holiday photos",
                max((self._entry_date_text(entry) for entry in selected if self._entry_date_text(entry)), default=year),
            )
        for (label, year), selected in sorted(event_entries.items(), key=memory_group_sort_key, reverse=True)[:12]:
            name = f"{label} {year}" if year else f"{label} Moments"
            add_memory(
                "event",
                name,
                selected,
                f"{len(selected)} event photos",
                max((self._entry_date_text(entry) for entry in selected if self._entry_date_text(entry)), default=year),
            )

        person_entries: dict[str, list[dict[str, Any]]] = {}
        place_entries: dict[str, list[dict[str, Any]]] = {}
        for entry in base_entries:
            for person in self._photo_entry_named_people(entry):
                person_entries.setdefault(person, []).append(entry)
            place_label = self._photo_trip_location_label(entry, place_labels_by_asset_id)
            if place_label:
                place_entries.setdefault(place_label, []).append(entry)
        for person, selected in sorted(person_entries.items(), key=lambda item: (-len(item[1]), item[0].casefold()))[:12]:
            add_memory("person", f"{person} Highlights", selected, f"{len(selected)} photos with {person}", str(len(selected)).zfill(6))
        for place, selected in sorted(place_entries.items(), key=lambda item: (-len(item[1]), item[0].casefold()))[:12]:
            add_memory("place", f"{place} Memories", selected, f"{len(selected)} photos around {place}", str(len(selected)).zfill(6))

        trip_summaries = trips if trips is not None else self._photo_trip_summaries(base_entries)
        for trip in trip_summaries[:12]:
            source_set = {str(path or "") for path in trip.get("sourcePaths", []) if str(path or "")}
            selected = [entry for entry in base_entries if str(entry.get("sourcePath", "") or "") in source_set]
            add_memory(
                "trip",
                str(trip.get("name", "") or "Trip Memory"),
                selected,
                str(trip.get("dateRangeLabel", "") or ""),
                str(trip.get("endDate", "") or ""),
            )

        entries_by_source = {str(entry.get("sourcePath", "") or ""): entry for entry in base_entries if str(entry.get("sourcePath", "") or "")}
        for user_memory in self.project.db.photo_user_memories():
            source_paths = [str(path or "") for path in user_memory.get("sourcePaths", []) if str(path or "")]
            selected = [entries_by_source[path] for path in source_paths if path in entries_by_source]
            add_memory(
                "user",
                str(user_memory.get("name", "") or "Memory"),
                selected,
                str(user_memory.get("subtitle", "") or "User-created memory"),
                str(user_memory.get("updatedAt", "") or ""),
                str(user_memory.get("memoryId", "") or ""),
                str(user_memory.get("coverSourcePath", "") or ""),
                str(user_memory.get("createdAt", "") or ""),
                str(user_memory.get("updatedAt", "") or ""),
                user_memory.get("movieSettings") if isinstance(user_memory.get("movieSettings"), dict) else None,
            )

        return sorted(
            memories,
            key=lambda memory: (
                int(bool(memory.get("favorite", False))),
                str(memory.get("sortHint", "") or ""),
                int(memory.get("count", 0) or 0),
                str(memory.get("name", "") or ""),
            ),
            reverse=True,
        )[:32]

    def _photo_memory_by_id(
        self,
        memory_id: str,
        entries: list[dict[str, Any]] | None = None,
        trips: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any] | None:
        clean_id = str(memory_id or "").strip()
        for memory in self._photo_memory_summaries(entries, trips=trips):
            if str(memory.get("memoryId", "") or "") == clean_id:
                return memory
        return None

    def _photo_generated_collection_cache_for_paging(
        self,
        library_root: str = "",
    ) -> dict[str, Any]:
        cache = self.project.db.photo_generated_collection_cache(library_root)
        trips = cache.get("trips", []) if isinstance(cache.get("trips", []), list) else []
        memories = cache.get("memories", []) if isinstance(cache.get("memories", []), list) else []
        if trips or memories:
            return {
                **cache,
                "trips": self._photo_refresh_generated_summary_previews(trips),
                "memories": self._photo_refresh_generated_summary_previews(memories),
                "cacheHit": True,
            }
        base_entries = self._filter_photo_entries_by_library_root(
            self._visible_photo_entries(self._all_photo_entries()),
            library_root,
        ) if library_root else self._visible_photo_entries(self._all_photo_entries())
        trip_summaries, memory_summaries, refreshed_cache = self._photo_generated_collection_summaries(
            base_entries,
            library_root=library_root,
        )
        return {
            **refreshed_cache,
            "trips": trip_summaries,
            "memories": memory_summaries,
        }

    def _photo_cached_trip_by_id(self, trip_id: str, library_root: str = "") -> dict[str, Any] | None:
        clean_id = str(trip_id or "").strip()
        if not clean_id:
            return None
        cache = self._photo_generated_collection_cache_for_paging(library_root)
        for trip in cache.get("trips", []) if isinstance(cache.get("trips", []), list) else []:
            if str(trip.get("tripId", "") or "") == clean_id:
                return trip
        return None

    def _photo_cached_memory_by_id(self, memory_id: str, library_root: str = "") -> dict[str, Any] | None:
        clean_id = str(memory_id or "").strip()
        if not clean_id:
            return None
        cache = self._photo_generated_collection_cache_for_paging(library_root)
        for memory in cache.get("memories", []) if isinstance(cache.get("memories", []), list) else []:
            if str(memory.get("memoryId", "") or "") == clean_id:
                return memory
        return None

    def _photo_generated_collection_signature(
        self,
        entries: list[dict[str, Any]],
        *,
        library_root: str = "",
        curation_preferences: dict[str, Any] | None = None,
        user_memories: list[dict[str, Any]] | None = None,
    ) -> str:
        signature_entries: list[dict[str, Any]] = []
        for entry in sorted(entries, key=lambda item: str(item.get("sourcePath", "") or "").casefold()):
            source_path = str(entry.get("sourcePath", "") or "")
            if not source_path:
                continue
            asset = self._photo_entry_asset(entry) or {}
            asset_metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
            metadata = self._photo_entry_metadata(entry)
            people_rows = [
                {
                    "candidateId": str(row.get("candidateId", "") or ""),
                    "personName": str(row.get("personName", "") or ""),
                    "status": str(row.get("status", "") or ""),
                    "score": float(row.get("score", 0.0) or 0.0),
                    "quality": float(row.get("quality", 0.0) or 0.0),
                    "band": str(row.get("band", "") or ""),
                    "updatedAt": str(row.get("updatedAt", "") or ""),
                }
                for row in self._photo_entry_people_rows(entry)
                if isinstance(row, dict)
            ]
            matches = [
                {
                    "candidateId": str(match.candidate_id or ""),
                    "sourcePath": str(match.source_path or ""),
                    "mediaSourcePath": str(match.media_source_path or ""),
                    "personName": str(match.person_name or ""),
                    "status": str(match.status or ""),
                    "score": float(match.score or 0.0),
                    "quality": float(match.quality or 0.0),
                    "band": str(match.band or ""),
                    "captureDate": str(match.capture_date or ""),
                    "createdAt": str(match.created_at or ""),
                }
                for match in entry.get("matches", []) or []
                if isinstance(match, ReviewCandidate)
            ]
            signature_entries.append({
                "sourcePath": source_path,
                "assetId": str(asset.get("assetId", entry.get("_assetId", "")) or ""),
                "mediaKind": str(asset.get("mediaKind", entry.get("mediaKind", "")) or ""),
                "captureDate": str(asset.get("captureDate", "") or ""),
                "addedAt": str(asset.get("addedAt", entry.get("scanDate", "")) or ""),
                "updatedAt": str(asset.get("updatedAt", "") or ""),
                "metadata": metadata,
                "assetMetadata": asset_metadata,
                "people": sorted(people_rows, key=lambda row: (row["personName"].casefold(), row["candidateId"])),
                "matches": sorted(matches, key=lambda row: (row["personName"].casefold(), row["candidateId"])),
            })
        body = {
            "schemaVersion": "1",
            "libraryRoot": str(library_root or ""),
            "entries": signature_entries,
            "curationPreferences": curation_preferences if isinstance(curation_preferences, dict) else {},
            "userMemories": user_memories if isinstance(user_memories, list) else [],
        }
        encoded = json.dumps(body, separators=(",", ":"), sort_keys=True, default=str).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _photo_refresh_generated_summary_previews(self, summaries: list[dict[str, Any]]) -> list[dict[str, Any]]:
        refreshed: list[dict[str, Any]] = []
        for summary in summaries:
            if not isinstance(summary, dict):
                continue
            cover_source = str(summary.get("coverSourcePath", "") or "")
            refreshed.append({
                **summary,
                "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
            })
        return refreshed

    def _photo_generated_collection_summaries(
        self,
        entries: list[dict[str, Any]],
        *,
        library_root: str = "",
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
        base_entries = list(entries)
        curation_preferences = self.project.db.photo_curation_preferences()
        user_memories = self.project.db.photo_user_memories()
        signature = self._photo_generated_collection_signature(
            base_entries,
            library_root=library_root,
            curation_preferences=curation_preferences,
            user_memories=user_memories,
        )
        cache = self.project.db.photo_generated_collection_cache(library_root)
        if str(cache.get("signature", "") or "") == signature:
            cached_trips = self._photo_refresh_generated_summary_previews(cache.get("trips", []) if isinstance(cache.get("trips", []), list) else [])
            cached_memories = self._photo_refresh_generated_summary_previews(cache.get("memories", []) if isinstance(cache.get("memories", []), list) else [])
            return (
                cached_trips,
                cached_memories,
                {**cache, "cacheHit": True},
            )
        trips = self._photo_trip_summaries(base_entries)
        memories = self._photo_memory_summaries(base_entries, trips=trips)
        cache_payload = self.project.db.save_photo_generated_collection_cache(
            library_root,
            {
                "signature": signature,
                "assetCount": len(base_entries),
                "trips": trips,
                "memories": memories,
            },
        )
        return trips, memories, {**cache_payload, "cacheHit": False}

    def _apply_photo_folder_cover_previews(self, folders: list[dict[str, Any]], budget: int) -> dict[str, int]:
        remaining = max(0, min(64, int(budget or 0)))
        generated = 0
        existing = 0
        attempted = 0
        for folder in folders:
            if folder.get("coverPreviewPath"):
                existing += 1
                continue
            cover_source = str(folder.get("coverSourcePath", "") or "").strip()
            if not cover_source:
                continue
            cover_asset = self.project.db.photo_asset_by_path(cover_source)
            cover_stack = self.project.db.photo_edit_stack_by_asset(asset_id=str(cover_asset.get("assetId", ""))) if cover_asset else None
            cover_edit_preview = str(cover_stack.get("renderedPreviewPath", "") or "") if cover_stack else ""
            if cover_edit_preview:
                try:
                    preview = Path(cover_edit_preview).expanduser()
                    if preview.exists() and preview.is_file():
                        folder["coverPreviewPath"] = str(preview)
                        existing += 1
                        continue
                except OSError:
                    pass
            preview_path = self.project.preview_path_for(cover_source, create=False)
            if preview_path:
                folder["coverPreviewPath"] = preview_path
                existing += 1
                continue
            if remaining <= 0:
                continue
            remaining -= 1
            attempted += 1
            preview_path = self.project.preview_path_for(cover_source, create=True)
            if preview_path:
                folder["coverPreviewPath"] = preview_path
                generated += 1
        return {
            "coverPreviewBudget": max(0, min(64, int(budget or 0))),
            "coverPreviewAttempts": attempted,
            "coverPreviewGenerated": generated,
            "coverPreviewExisting": existing,
        }

    def _photo_filtered_entries_from_params(self, folder_id: str, params: dict[str, Any]) -> list[dict[str, Any]]:
        query = str(params.get("query", "") or "").strip()
        group_mode = self._normalize_photo_group_mode(params.get("groupMode", params.get("groupViewMode", "all")))
        keyword = str(params.get("keyword", "") or "").strip()
        media_kind_filter = str(params.get("mediaKind", "") or "").strip().lower()
        date_from_filter = self._normalize_photo_date_filter(params.get("dateFrom", params.get("fromDate", "")))
        date_to_filter = self._normalize_photo_date_filter(params.get("dateTo", params.get("toDate", "")))
        source_filter = str(params.get("source", params.get("sourceFolder", params.get("path", ""))) or "").strip()
        library_root_filter = self._photo_library_root_filter_from_params(params)
        source_paths_raw = params.get("sourcePaths", params.get("sources", []))
        source_paths_filter = {
            str(path or "").strip()
            for path in source_paths_raw
            if str(path or "").strip()
        } if isinstance(source_paths_raw, list) else set()
        file_type_filter = str(params.get("fileType", params.get("extension", "")) or "").strip().lower().lstrip(".")
        location_filter = str(params.get("location", params.get("place", "")) or "").strip()
        camera_filter = str(params.get("camera", params.get("cameraModel", "")) or "").strip()
        nearby_filter = self._photo_nearby_filter_from_params(params)
        album_filter = str(params.get("albumId", params.get("album", "")) or "").strip()
        person_filter = str(params.get("person", params.get("personName", "")) or "").strip()
        status_filter = str(params.get("status", params.get("reviewStatus", "")) or "").strip().lower()
        if status_filter not in {"", "pending", "accepted", "rejected", "uncertain"}:
            status_filter = ""
        try:
            min_quality_filter = max(0.0, min(1.0, float(params.get("minQuality", params.get("quality", 0)) or 0.0)))
        except (TypeError, ValueError):
            min_quality_filter = 0.0

        def truthy(value: Any) -> bool:
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return bool(value)
            return str(value or "").strip().lower() in {"1", "true", "yes", "on"}

        duplicate_only = truthy(params.get("duplicateOnly", params.get("duplicatesOnly", params.get("duplicate", False))))
        if duplicate_only:
            self.project.db.ensure_photo_duplicate_groups()
        visibility_filter = self._normalize_photo_visibility_filter(
            params.get("visibility", params.get("visibilityState", "")),
            hidden_only=truthy(params.get("hiddenOnly", False)),
            deleted_only=truthy(params.get("deletedOnly", False)),
        )

        base_entries = self._photo_entries_for_folder_id(folder_id)
        if folder_id == "all" and visibility_filter in {"all", "hidden", "deleted"}:
            base_entries = self._all_photo_entries()
        filtered_entries = self._filter_photo_entries_by_view_filters(
            self._filter_photo_entries_by_keyword(
                self._filter_photo_entries_by_query(base_entries, query),
                keyword,
            ),
            media_kind=media_kind_filter,
            favorite_only=truthy(params.get("favoriteOnly", params.get("favorite", False))),
            edited_only=truthy(params.get("editedOnly", params.get("edited", False))),
        )
        filtered_entries = self._filter_photo_entries_by_metadata_filters(
            filtered_entries,
            date_from=date_from_filter,
            date_to=date_to_filter,
            source=source_filter,
            library_root=library_root_filter,
            file_type=file_type_filter,
            location=location_filter,
            camera=camera_filter,
            duplicate_only=duplicate_only,
            nearby=nearby_filter,
        )
        filtered_entries = self._filter_photo_entries_by_visibility_filter(filtered_entries, visibility_filter)
        filtered_entries = self._filter_photo_entries_by_album_filter(filtered_entries, album_filter)
        filtered_entries = self._filter_photo_entries_by_candidate_filters(
            filtered_entries,
            person=person_filter,
            status=status_filter,
            min_quality=min_quality_filter,
        )
        if truthy(params.get("notInAlbumOnly", params.get("notInAlbum", False))):
            filtered_entries = self._filter_photo_entries_not_in_manual_album(filtered_entries)
        if source_paths_filter:
            filtered_entries = [
                entry
                for entry in filtered_entries
                if str(entry.get("sourcePath", "") or "") in source_paths_filter
            ]
        if folder_id.startswith("group:") and group_mode == "best":
            filtered_entries = self._photo_best_group_entries(filtered_entries)
        return filtered_entries

    def list_photo_date_buckets(self, params: dict[str, Any]) -> dict[str, Any]:
        folder_id = str(params.get("folderId", "all") or "all").strip()
        mode = str(params.get("mode", params.get("dateMode", "")) or "").strip()
        if mode not in {"years", "months", "days", "recentDays"}:
            raise ValueError("mode must be years, months, days, or recentDays.")
        nearby_filter = self._photo_nearby_filter_from_params(params)
        sql_bucket_payload = self._photo_all_date_buckets_sql_from_params(folder_id, mode, params, nearby_filter)
        if sql_bucket_payload is not None:
            return sql_bucket_payload
        if self._photo_date_bucket_nearby_fast_path_allowed(folder_id, mode, params, nearby_filter):
            nearby_asset_ids = tuple(
                self.project.db.list_photo_asset_ids_nearby(
                    latitude=float(nearby_filter["latitude"]),
                    longitude=float(nearby_filter["longitude"]),
                    radius_km=float(nearby_filter["radiusKm"]),
                )
            )
            if not nearby_asset_ids:
                return {"folderId": folder_id, "mode": mode, "total": 0, "buckets": []}
            return self._photo_date_buckets_sql_all(mode, required_asset_ids=nearby_asset_ids)
        if self._photo_date_bucket_fast_path_allowed(folder_id, mode, params):
            return self._photo_date_buckets_sql_all(mode)
        entries = self._sort_photo_entries(self._photo_filtered_entries_from_params(folder_id, params), "newest")
        if mode == "recentDays":
            dates = sorted({self._entry_date_text(entry) for entry in entries if self._entry_date_text(entry)})
            latest = dates[-1] if dates else ""
            if latest:
                try:
                    latest_date = datetime.fromisoformat(f"{latest}T00:00:00")
                    cutoff = latest_date - timedelta(days=30)
                    entries = [
                        entry for entry in entries
                        if (date_text := self._entry_date_text(entry))
                        and (parsed := datetime.fromisoformat(f"{date_text}T00:00:00"))
                        and cutoff <= parsed <= latest_date
                    ]
                except ValueError:
                    entries = []
        buckets: dict[str, list[dict[str, Any]]] = {}
        self._photo_annotate_date_bucket_relation_counts(entries)
        for entry in entries:
            key = self._photo_date_bucket_key(entry, mode)
            if not key:
                continue
            buckets.setdefault(key, []).append(entry)
        curation_preferences = self.project.db.photo_curation_preferences()
        place_labels_by_asset_id = self._photo_place_labels_by_asset_id()
        rows = []
        for key in sorted(buckets.keys(), reverse=True):
            bucket_entries = buckets[key]
            cover_entry = max(
                bucket_entries,
                key=lambda entry: self._photo_date_bucket_cover_rank(entry, curation_preferences, place_labels_by_asset_id),
            )
            cover_source = str(cover_entry.get("sourcePath", "") or "")
            cover_asset = self.project.db.photo_asset_by_path(cover_source) if cover_source else None
            cover_metadata = self.project.db.photo_asset_metadata_by_id(str(cover_asset["assetId"])) if cover_asset else {}
            cover_title = str(cover_metadata.get("title", "") or "").strip() or (Path(cover_source).name if cover_source else "")
            rows.append({
                "key": key,
                "label": self._photo_date_bucket_label(key, mode),
                "count": len(bucket_entries),
                "coverTitle": cover_title,
                "coverReason": self._photo_date_bucket_cover_reason(cover_entry),
                "coverSourcePath": cover_source,
                "coverPreviewPath": self.project.preview_path_for(cover_source, create=False) if cover_source else None,
                "favoriteCount": sum(1 for entry in bucket_entries if self._photo_entry_direct_bool(entry, "favorite")),
                "peoplePhotoCount": sum(1 for entry in bucket_entries if self._photo_entry_direct_people_count(entry) > 0),
                "locationCount": sum(1 for entry in bucket_entries if self._photo_entry_direct_has_location(entry)),
                "videoCount": sum(1 for entry in bucket_entries if str(entry.get("mediaKind", "") or "").strip().lower() in {"video", "time_lapse"}),
                "editedCount": sum(1 for entry in bucket_entries if self._photo_entry_direct_bool(entry, "edited")),
                "duplicateCount": sum(1 for entry in bucket_entries if self._photo_entry_duplicate_count(entry) > 0),
                "versionCount": sum(1 for entry in bucket_entries if self._photo_entry_edit_stack_version_count(entry) > 0),
                "summaryBadges": self._photo_date_bucket_summary_badges(bucket_entries),
            })
        return {"folderId": folder_id, "mode": mode, "total": len(rows), "buckets": rows}

    def _photo_all_folder_items_sql_page(
        self,
        *,
        offset: int,
        limit: int,
        sort: str,
        query: str,
        keyword: str,
        media_kind_filter: str,
        date_bucket_mode: str,
        date_bucket_key: str,
        date_from_filter: str,
        date_to_filter: str,
        source_filter: str,
        source_text_filters: tuple[tuple[str, str], ...],
        source_paths_filter: set[str],
        source_scan_runs: Iterable[str] = (),
        file_type_filter: str,
        location_filter: str,
        camera_filter: str,
        nearby_filter: dict[str, float] | None,
        album_filter: str,
        person_filter: str,
        status_filter: str,
        min_quality_filter: float,
        favorite_only: bool,
        edited_only: bool,
        not_in_album_only: bool,
        duplicate_only: bool,
        visibility_filter: str,
    ) -> dict[str, Any] | None:
        if sort not in {"newest", "oldest", "scanDate", "title", "filename", "mediaKind"}:
            return None
        if source_paths_filter:
            return None
        manual_album_ids = self._photo_manual_album_filter_ids(album_filter)
        if album_filter and not manual_album_ids:
            return None
        if self.project.candidates and (
            date_from_filter
            or date_to_filter
            or date_bucket_key
            or album_filter
            or not_in_album_only
            or person_filter
            or status_filter
            or min_quality_filter
            or location_filter
            or nearby_filter
            or sort in {"newest", "oldest"}
        ):
            return None
        media_kind = media_kind_filter if media_kind_filter in PHOTO_MEDIA_KINDS else ""
        visibility = visibility_filter if visibility_filter in {"all", "hidden", "deleted", "visible"} else "visible"
        search_index_status: dict[str, Any] = {}
        if str(query or "").strip():
            search_index_status = self.project.db.ensure_photo_search_index(allow_rebuild=False, enqueue_on_cold=True, repair_limit=1000)
        location_asset_ids = self._photo_location_filter_asset_ids(location_filter)
        nearby_asset_ids: tuple[str, ...] = ()
        if nearby_filter:
            nearby_asset_ids = tuple(
                self.project.db.list_photo_asset_ids_nearby(
                    latitude=float(nearby_filter["latitude"]),
                    longitude=float(nearby_filter["longitude"]),
                    radius_km=float(nearby_filter["radiusKm"]),
                )
            )
            if not nearby_asset_ids:
                return {"total": 0, "entries": []}
        result = self.project.db.list_photo_asset_page(
            offset=offset,
            limit=limit,
            query=query,
            visibility=visibility,
            media_kind=media_kind,
            favorite_only=favorite_only,
            edited_only=edited_only,
            keyword=keyword,
            date_from=date_from_filter,
            date_to=date_to_filter,
            date_bucket_mode=date_bucket_mode,
            date_bucket_key=date_bucket_key,
            source=source_filter,
            source_scan_runs=source_scan_runs,
            source_text_filters=source_text_filters,
            required_asset_ids=nearby_asset_ids,
            file_type_aliases=self._photo_file_type_aliases(file_type_filter),
            location=location_filter,
            location_asset_ids=location_asset_ids,
            camera=camera_filter,
            duplicate_state=True if duplicate_only else None,
            manual_album_ids=manual_album_ids or (),
            manual_album_membership_state=False if not_in_album_only else None,
            candidate_person_name=person_filter,
            candidate_status=status_filter,
            candidate_min_quality=min_quality_filter,
            sort=sort,
        )
        return {
            "total": int(result.get("total", 0) or 0),
            "entries": self._photo_entries_for_assets(result.get("assets", [])),
            **({"searchIndex": search_index_status} if search_index_status else {}),
        }

    def _photo_pet_folder_items_sql_page(
        self,
        folder_id: str,
        *,
        offset: int,
        limit: int,
        sort: str,
        query: str,
        keyword: str,
        media_kind_filter: str,
        date_bucket_mode: str,
        date_bucket_key: str,
        date_from_filter: str,
        date_to_filter: str,
        source_filter: str,
        source_text_filters: tuple[tuple[str, str], ...],
        source_paths_filter: set[str],
        file_type_filter: str,
        location_filter: str,
        camera_filter: str,
        nearby_filter: dict[str, float] | None,
        album_filter: str,
        person_filter: str,
        status_filter: str,
        min_quality_filter: float,
        favorite_only: bool,
        edited_only: bool,
        not_in_album_only: bool,
        duplicate_only: bool,
        pet_review_kind_filter: str = "",
    ) -> dict[str, Any] | None:
        if sort not in {"newest", "oldest", "scanDate", "title", "filename", "mediaKind"}:
            return None
        if source_paths_filter:
            return None
        if not (folder_id in {"pets", "petReview"} or folder_id.startswith("pet:")):
            return None
        manual_album_ids = self._photo_manual_album_filter_ids(album_filter)
        if album_filter and not manual_album_ids:
            return None
        if self.project.candidates and (
            date_from_filter
            or date_to_filter
            or date_bucket_key
            or album_filter
            or not_in_album_only
            or person_filter
            or status_filter
            or min_quality_filter
            or location_filter
            or nearby_filter
            or sort in {"newest", "oldest"}
        ):
            return None
        if duplicate_only:
            self.project.db.ensure_photo_duplicate_groups()
        nearby_asset_ids: tuple[str, ...] = ()
        if nearby_filter:
            nearby_asset_ids = tuple(
                self.project.db.list_photo_asset_ids_nearby(
                    latitude=float(nearby_filter["latitude"]),
                    longitude=float(nearby_filter["longitude"]),
                    radius_km=float(nearby_filter["radiusKm"]),
                )
            )
            if not nearby_asset_ids:
                return {"total": 0, "entries": []}
        pet_names: tuple[str, ...] = ()
        any_pet_state: bool | None = None
        pet_review_kind = ""
        excluded_pet_names: tuple[str, ...] = ()
        if folder_id.startswith("pet:"):
            pet_name = self._photo_pet_name_from_folder_id(folder_id)
            if not pet_name:
                return {"total": 0, "entries": []}
            pet_names = (pet_name,)
        elif folder_id == "pets":
            any_pet_state = True
            hidden_pet_names = [
                str(profile.get("petName", "") or name)
                for name, profile in self.project.db.list_photo_pet_profiles().items()
                if bool(profile.get("hidden"))
            ]
            excluded_pet_names = tuple(name for name in hidden_pet_names if self._clean_photo_pet_label(name))
        elif folder_id == "petReview":
            pet_review_kind = pet_review_kind_filter or "*"
        media_kind = media_kind_filter if media_kind_filter in PHOTO_MEDIA_KINDS else ""
        result = self.project.db.list_photo_asset_page(
            offset=offset,
            limit=limit,
            query=query,
            visibility="visible",
            media_kind=media_kind,
            favorite_only=favorite_only,
            edited_only=edited_only,
            keyword=keyword,
            date_from=date_from_filter,
            date_to=date_to_filter,
            date_bucket_mode=date_bucket_mode,
            date_bucket_key=date_bucket_key,
            source=source_filter,
            source_text_filters=source_text_filters,
            required_asset_ids=nearby_asset_ids,
            file_type_aliases=self._photo_file_type_aliases(file_type_filter),
            location=location_filter,
            location_asset_ids=self._photo_location_filter_asset_ids(location_filter),
            camera=camera_filter,
            duplicate_state=True if duplicate_only else None,
            manual_album_ids=manual_album_ids or (),
            manual_album_membership_state=False if not_in_album_only else None,
            candidate_person_name=person_filter,
            candidate_status=status_filter,
            candidate_min_quality=min_quality_filter,
            pet_names=pet_names,
            excluded_pet_names=excluded_pet_names,
            any_pet_state=any_pet_state,
            pet_review_kind=pet_review_kind,
            sort=sort,
        )
        entries = self._photo_entries_for_assets(result.get("assets", []))
        if folder_id == "pets":
            hidden_pet_keys = {self._clean_photo_pet_label(name).casefold() for name in excluded_pet_names}
            entries = [
                entry
                for entry in entries
                if any(
                    str(pet.get("name", "") or "").casefold() not in hidden_pet_keys
                    for pet in self._photo_pet_labels_for_entry(entry)
                )
            ]
        elif folder_id == "petReview":
            entries = [
                entry
                for entry in entries
                for review_record in [self._photo_pet_review_record_for_entry(entry)]
                if review_record is not None
                and (
                    not pet_review_kind_filter
                    or str(review_record.get("kind", "") or "") == pet_review_kind_filter
                )
            ]
        return {
            "total": int(result.get("total", 0) or 0),
            "entries": entries,
        }

    def _photo_album_folder_items_sql_page(
        self,
        album_folder_id: str,
        *,
        offset: int,
        limit: int,
        sort: str,
        query: str,
        keyword: str,
        media_kind_filter: str,
        date_bucket_mode: str,
        date_bucket_key: str,
        date_from_filter: str,
        date_to_filter: str,
        source_filter: str,
        source_text_filters: tuple[tuple[str, str], ...],
        source_paths_filter: set[str],
        file_type_filter: str,
        location_filter: str,
        camera_filter: str,
        nearby_filter: dict[str, float] | None,
        album_filter: str,
        person_filter: str,
        status_filter: str,
        min_quality_filter: float,
        favorite_only: bool,
        edited_only: bool,
        not_in_album_only: bool,
        duplicate_only: bool,
        visibility_filter: str,
        library_root: str = "",
    ) -> dict[str, Any] | None:
        clean_library_root = str(library_root or "").strip()
        allowed_source_text_filters = self._photo_library_root_source_text_filters(clean_library_root)
        if sort not in {"newest", "oldest", "scanDate", "title", "filename", "mediaKind"}:
            return None
        if source_paths_filter:
            return None
        manual_album_ids = self._photo_manual_album_filter_ids(album_filter)
        if album_filter and not manual_album_ids:
            return None
        if source_text_filters and tuple(source_text_filters) != allowed_source_text_filters:
            return None
        folder_sources = self._photo_album_folder_source_paths_sql(album_folder_id, library_root=clean_library_root)
        if folder_sources is None:
            return None
        if not folder_sources:
            return {"total": 0, "entries": []}
        if self.project.candidates:
            if (
                query
                or keyword
                or media_kind_filter
                or date_bucket_mode
                or date_bucket_key
                or date_from_filter
                or date_to_filter
                or source_filter
                or file_type_filter
                or location_filter
                or camera_filter
                or nearby_filter
                or album_filter
                or person_filter
                or status_filter
                or min_quality_filter
                or favorite_only
                or edited_only
                or not_in_album_only
                or duplicate_only
                or visibility_filter not in {"", "visible"}
            ):
                return None
            entries = self._sort_photo_entries(
                self._photo_entries_for_materialized_source_paths(folder_sources),
                sort,
            )
            return {
                "total": len(entries),
                "entries": entries[offset:offset + limit],
            }
        folder_assets = self.project.db.photo_assets_by_paths(folder_sources)
        required_asset_ids = tuple(
            str(asset.get("assetId", "") or "")
            for asset in folder_assets
            if str(asset.get("assetId", "") or "")
        )
        if not required_asset_ids:
            return {"total": 0, "entries": []}
        if duplicate_only:
            self.project.db.ensure_photo_duplicate_groups()
        if nearby_filter:
            nearby_asset_ids = tuple(
                self.project.db.list_photo_asset_ids_nearby(
                    latitude=float(nearby_filter["latitude"]),
                    longitude=float(nearby_filter["longitude"]),
                    radius_km=float(nearby_filter["radiusKm"]),
                )
            )
            if not nearby_asset_ids:
                return {"total": 0, "entries": []}
            nearby_set = set(nearby_asset_ids)
            required_asset_ids = tuple(asset_id for asset_id in required_asset_ids if asset_id in nearby_set)
            if not required_asset_ids:
                return {"total": 0, "entries": []}
        media_kind = media_kind_filter if media_kind_filter in PHOTO_MEDIA_KINDS else ""
        visibility = visibility_filter if visibility_filter in {"all", "hidden", "deleted", "visible"} else "visible"
        result = self.project.db.list_photo_asset_page(
            offset=offset,
            limit=limit,
            query=query,
            visibility=visibility,
            media_kind=media_kind,
            favorite_only=favorite_only,
            edited_only=edited_only,
            keyword=keyword,
            date_from=date_from_filter,
            date_to=date_to_filter,
            date_bucket_mode=date_bucket_mode,
            date_bucket_key=date_bucket_key,
            source=source_filter,
            source_text_filters=source_text_filters,
            required_asset_ids=required_asset_ids,
            file_type_aliases=self._photo_file_type_aliases(file_type_filter),
            location=location_filter,
            location_asset_ids=self._photo_location_filter_asset_ids(location_filter),
            camera=camera_filter,
            duplicate_state=True if duplicate_only else None,
            manual_album_ids=manual_album_ids or (),
            manual_album_membership_state=False if not_in_album_only else None,
            candidate_person_name=person_filter,
            candidate_status=status_filter,
            candidate_min_quality=min_quality_filter,
            sort=sort,
        )
        return {
            "total": int(result.get("total", 0) or 0),
            "entries": self._photo_entries_for_assets(result.get("assets", [])),
        }

    def _photo_workspace_has_review_candidates(self) -> bool:
        if self.project.candidates:
            return True
        return False

    def _photo_smart_album_sql_set(self, criteria: dict[str, Any], key: str, value: Any) -> bool:
        if value in ("", None, []):
            return True
        if key in criteria and criteria[key] != value:
            return False
        criteria[key] = value
        return True

    def _photo_smart_album_sql_nearby_asset_ids(self, value: Any) -> tuple[str, ...] | None:
        nearby = self._photo_nearby_filter_from_query_value(value)
        if nearby is None:
            return None
        asset_ids = tuple(
            self.project.db.list_photo_asset_ids_nearby(
                latitude=float(nearby["latitude"]),
                longitude=float(nearby["longitude"]),
                radius_km=float(nearby["radiusKm"]),
            )
        )
        return asset_ids or ("__vintrace_no_nearby_smart_album_match__",)

    def _photo_smart_album_sql_add_filter(self, criteria: dict[str, Any], key: str, value: tuple[Any, ...]) -> bool:
        current = criteria.get(key, ())
        if current in ("", None, []):
            current = ()
        if not isinstance(current, tuple):
            return False
        next_values = current if value in current else (*current, value)
        if len(next_values) > 16:
            return False
        criteria[key] = next_values
        return True

    def _photo_smart_album_sql_number_filter(self, operator: str, value: Any) -> tuple[str, float] | None:
        if operator not in {"is", "isNot", "greaterThan", "atLeast", "onOrAfter", "lessThan", "atMost", "onOrBefore"}:
            return None
        try:
            number = float(self._photo_query_values(value)[0])
        except (TypeError, ValueError, IndexError):
            return None
        return (operator, number) if math.isfinite(number) else None

    def _photo_smart_album_recent_cutoff(self, value: Any) -> str:
        try:
            days = max(1, min(3650, int(float(self._photo_query_values(value)[0]))))
        except (TypeError, ValueError, IndexError):
            return ""
        return (datetime.utcnow() - timedelta(days=days)).replace(microsecond=0).isoformat()

    def _photo_smart_album_sql_promote_visibility_all(self, criteria: dict[str, Any]) -> bool:
        current = str(criteria.get("visibility", "visible") or "visible")
        if current not in {"", "visible", "all"}:
            return False
        criteria["visibility"] = "all"
        return True

    def _photo_smart_album_sql_apply_condition(
        self,
        criteria: dict[str, Any],
        condition: dict[str, Any],
        *,
        album_stack: tuple[str, ...] = (),
    ) -> bool:
        op = str(condition.get("op", "") or "")
        if op:
            if op != "all":
                return False
            return all(
                self._photo_smart_album_sql_apply_condition(criteria, child, album_stack=album_stack)
                for child in condition.get("conditions", [])
                if isinstance(child, dict)
            )
        field = str(condition.get("field", "") or "")
        operator = str(condition.get("operator", "is") or "is")
        values = self._photo_query_values(condition.get("value"))
        value = values[0] if len(values) == 1 else None
        if value in (None, "") and not isinstance(value, bool):
            return False
        if field == "query":
            if operator in {"isNot", "notContains"}:
                return self._photo_smart_album_sql_add_filter(criteria, "queryTextFilters", (operator, str(value)))
            return self._photo_smart_album_sql_set(criteria, "query", str(value))
        if field == "keyword":
            if operator not in {"is", "isNot", "contains", "notContains"}:
                return False
            if operator in {"contains", "notContains"}:
                return self._photo_smart_album_sql_add_filter(criteria, "keywordTextFilters", (operator, str(value)))
            if operator == "isNot":
                return self._photo_smart_album_sql_add_filter(criteria, "excludedKeywords", str(value))
            return self._photo_smart_album_sql_set(criteria, "keyword", str(value))
        if field in {"title", "caption", "filename"}:
            if operator not in {"is", "isNot", "contains", "notContains"}:
                return False
            return self._photo_smart_album_sql_add_filter(criteria, "textFilters", (field, operator, str(value)))
        if field == "mediaKind":
            if operator not in {"is", "isNot"}:
                return False
            media_kind = str(value or "").strip().lower()
            if media_kind not in PHOTO_MEDIA_KINDS:
                return False
            if operator == "isNot":
                return self._photo_smart_album_sql_add_filter(criteria, "excludedMediaKinds", media_kind)
            return self._photo_smart_album_sql_set(criteria, "mediaKind", media_kind)
        if field == "favorite":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired = not target if operator == "isNot" else target
            return self._photo_smart_album_sql_set(criteria, "favoriteState", desired)
        if field == "edited":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired = not target if operator == "isNot" else target
            return self._photo_smart_album_sql_set(criteria, "editedState", desired)
        if field in {"hidden", "deleted"}:
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired = not target if operator == "isNot" else target
            if not self._photo_smart_album_sql_promote_visibility_all(criteria):
                return False
            state_key = "hiddenState" if field == "hidden" else "deletedState"
            return self._photo_smart_album_sql_set(criteria, state_key, desired)
        if field == "date":
            date_value = self._normalize_photo_date_filter(value)
            if not date_value:
                return False
            if operator == "is":
                return (
                    self._photo_smart_album_sql_set(criteria, "dateFrom", date_value)
                    and self._photo_smart_album_sql_set(criteria, "dateTo", date_value)
                )
            if operator in {"atLeast", "onOrAfter"}:
                return self._photo_smart_album_sql_set(criteria, "dateFrom", date_value)
            if operator in {"atMost", "onOrBefore"}:
                return self._photo_smart_album_sql_set(criteria, "dateTo", date_value)
            if operator in {"isNot", "greaterThan", "lessThan"}:
                return self._photo_smart_album_sql_add_filter(criteria, "effectiveDateFilters", (operator, date_value))
            return False
        if field == "addedDate":
            date_value = self._normalize_photo_date_filter(value)
            if not date_value or operator not in {"is", "isNot", "greaterThan", "atLeast", "onOrAfter", "lessThan", "atMost", "onOrBefore"}:
                return False
            return self._photo_smart_album_sql_add_filter(criteria, "addedDateFilters", (operator, date_value))
        if field in {"folder", "path"}:
            if operator not in {"is", "isNot", "contains", "notContains"}:
                return False
            if operator == "isNot":
                source_operator = "isNot" if field == "path" else "folderIsNot"
                return self._photo_smart_album_sql_add_filter(criteria, "sourceTextFilters", (source_operator, str(value)))
            if operator == "notContains":
                return self._photo_smart_album_sql_add_filter(criteria, "sourceTextFilters", ("notContains", str(value)))
            return self._photo_smart_album_sql_set(criteria, "source", str(value))
        if field == "fileType":
            if operator not in {"is", "isNot"}:
                return False
            aliases = tuple(sorted(self._photo_file_type_aliases(str(value))))
            if not aliases:
                return False
            key = "excludedFileTypeAliases" if operator == "isNot" else "fileTypeAliases"
            return self._photo_smart_album_sql_set(criteria, key, aliases)
        if field == "location":
            if operator in {"is", "contains"}:
                return self._photo_smart_album_sql_set(criteria, field, str(value))
            if operator in {"isNot", "notContains"}:
                return self._photo_smart_album_sql_add_filter(criteria, "locationTextFilters", (operator, str(value)))
            return False
        if field == "nearby":
            if operator not in {"is", "isNot"}:
                return False
            nearby_asset_ids = self._photo_smart_album_sql_nearby_asset_ids(value)
            if nearby_asset_ids is None:
                return False
            key = "excludedAssetIds" if operator == "isNot" else "requiredAssetIds"
            return self._photo_smart_album_sql_set(criteria, key, nearby_asset_ids)
        if field in {"iptcCreator", "iptcRights", "iptcEvent", "iptcLocation"}:
            if operator not in {"is", "isNot", "contains", "notContains"}:
                return False
            return self._photo_smart_album_sql_add_filter(criteria, "iptcTextFilters", (field, operator, str(value)))
        if field in {"camera", "lens"}:
            if operator in {"is", "contains"}:
                return self._photo_smart_album_sql_set(criteria, field, str(value))
            if operator in {"isNot", "notContains"}:
                key = "cameraTextFilters" if field == "camera" else "lensTextFilters"
                return self._photo_smart_album_sql_add_filter(criteria, key, (operator, str(value)))
            return False
        if field == "dimensions":
            if operator in {"is", "contains"}:
                return self._photo_smart_album_sql_set(criteria, "dimensions", str(value))
            if operator in {"isNot", "notContains"}:
                return self._photo_smart_album_sql_add_filter(criteria, "dimensionsTextFilters", (operator, str(value)))
            return False
        fts_text_columns = {
            "ocrText": "ocr_text",
            "detectedItem": "model_tags",
            "modelTag": "model_tags",
            "sceneTag": "model_tags",
            "detectedEvent": "model_tags",
            "imageDescription": "model_tags",
        }
        if field in fts_text_columns:
            if operator in {"is", "contains"}:
                return self._photo_smart_album_sql_add_filter(criteria, "ftsColumnFilters", (fts_text_columns[field], str(value)))
            if operator == "isNot":
                return self._photo_smart_album_sql_add_filter(criteria, "metadataExactTextFilters", (field, operator, str(value)))
            if operator == "notContains":
                return self._photo_smart_album_sql_add_filter(criteria, "ftsColumnTextFilters", (fts_text_columns[field], operator, str(value)))
            return False
        if field == "group":
            if operator not in {"is", "contains", "isNot", "notContains"}:
                return False
            group_spec = self._photo_smart_album_sql_people_group_spec(value)
            if group_spec is None:
                if operator in {"contains", "notContains"}:
                    return self._photo_smart_album_sql_add_filter(criteria, "groupTextFilters", (operator, str(value)))
                return False
            key = "excludedGroupPeopleFilters" if operator in {"isNot", "notContains"} else "groupPeopleFilters"
            return self._photo_smart_album_sql_add_filter(criteria, key, group_spec)
        numeric_filter_keys = {
            "width": "widthFilters",
            "height": "heightFilters",
            "duration": "durationFilters",
            "durationMs": "durationMsFilters",
            "megapixels": "megapixelsFilters",
            "ocrConfidence": "ocrConfidenceFilters",
            "detectedItemConfidence": "detectedItemConfidenceFilters",
            "modelConfidence": "modelConfidenceFilters",
            "detectedEventConfidence": "detectedEventConfidenceFilters",
            "personCount": "personCountFilters",
            "faceCount": "faceCountFilters",
            "matchCount": "matchCountFilters",
        }
        if field in numeric_filter_keys:
            filter_value = self._photo_smart_album_sql_number_filter(operator, value)
            if filter_value is None:
                return False
            return self._photo_smart_album_sql_add_filter(criteria, numeric_filter_keys[field], filter_value)
        if field == "person":
            if operator not in {"is", "isNot"}:
                return False
            person_name = str(value or "").strip()
            if not person_name:
                return False
            key = "excludedPersonNames" if operator == "isNot" else "personNames"
            return self._photo_smart_album_sql_set(criteria, key, (person_name,))
        if field == "status":
            if operator not in {"is", "isNot"}:
                return False
            status = str(value or "").strip().lower()
            if not status:
                return False
            key = "excludedPersonStatuses" if operator == "isNot" else "personStatuses"
            return self._photo_smart_album_sql_set(criteria, key, (status,))
        if field in {"score", "quality"}:
            filter_value = self._photo_smart_album_sql_number_filter(operator, value)
            if filter_value is None:
                return False
            key = "personScoreFilter" if field == "score" else "personQualityFilter"
            return self._photo_smart_album_sql_set(criteria, key, filter_value)
        if field == "duplicate":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired = not target if operator == "isNot" else target
            return self._photo_smart_album_sql_set(criteria, "duplicateState", desired)
        if field == "unknown":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired = not target if operator == "isNot" else target
            return self._photo_smart_album_sql_set(criteria, "unknownPersonState", desired)
        if field == "hasVideoFrames":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired = not target if operator == "isNot" else target
            return self._photo_smart_album_sql_set(criteria, "hasVideoFramesState", desired)
        if field == "recentDays":
            if operator not in {"is", "withinLast", "isNot"}:
                return False
            cutoff = self._photo_smart_album_recent_cutoff(value)
            if not cutoff:
                return False
            key = "effectiveTimeBefore" if operator == "isNot" else "effectiveTimeFrom"
            return self._photo_smart_album_sql_set(criteria, key, cutoff)
        if field == "album":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_album_filter_sql_target(str(value), album_stack=album_stack)
            if target is None:
                return False
            manual_album_ids = target.get("manualAlbumIds", ())
            smart_asset_ids = target.get("smartAssetIds", ())
            if operator == "isNot":
                if manual_album_ids and not self._photo_smart_album_sql_set(criteria, "excludedManualAlbumIds", manual_album_ids):
                    return False
                if smart_asset_ids and not self._photo_smart_album_sql_set(criteria, "excludedAssetIds", smart_asset_ids):
                    return False
                return True
            if manual_album_ids and smart_asset_ids:
                manual_asset_ids = self._photo_manual_album_asset_ids(manual_album_ids)
                required_asset_ids = tuple(dict.fromkeys((*manual_asset_ids, *smart_asset_ids)))
                return self._photo_smart_album_sql_set(
                    criteria,
                    "requiredAssetIds",
                    required_asset_ids or ("__vintrace_no_album_target_match__",),
                )
            if smart_asset_ids:
                return self._photo_smart_album_sql_set(criteria, "requiredAssetIds", smart_asset_ids)
            if manual_album_ids:
                return self._photo_smart_album_sql_set(criteria, "manualAlbumIds", manual_album_ids)
            return self._photo_smart_album_sql_set(criteria, "requiredAssetIds", ("__vintrace_no_album_target_match__",))
        if field == "notInAlbum":
            if operator not in {"is", "isNot"}:
                return False
            target = self._photo_query_bool(value)
            if target is None:
                return False
            desired_not_in_album = not target if operator == "isNot" else target
            return self._photo_smart_album_sql_set(criteria, "manualAlbumMembershipState", not desired_not_in_album)
        return False

    def _photo_smart_album_sql_criteria_key(self, criteria: dict[str, Any]) -> tuple[tuple[str, Any], ...]:
        def normalize(value: Any) -> Any:
            if isinstance(value, (list, tuple, set)):
                return tuple(value)
            return value

        return tuple(sorted((str(key), normalize(value)) for key, value in criteria.items()))

    def _photo_smart_album_sql_merge_criteria(
        self,
        base: dict[str, Any],
        extra: dict[str, Any],
    ) -> dict[str, Any] | None:
        merged = dict(base)
        for key, value in extra.items():
            if key == "visibility" and str(value or "") == "all" and str(merged.get("visibility", "") or "") in {"", "visible", "all"}:
                merged["visibility"] = "all"
                continue
            if key == "effectiveTimeFrom" and key in merged:
                merged[key] = max(str(merged.get(key, "") or ""), str(value or ""))
                continue
            if key == "effectiveTimeBefore" and key in merged:
                merged[key] = min(str(merged.get(key, "") or ""), str(value or ""))
                continue
            if key == "requiredAssetIds":
                incoming = tuple(str(item or "").strip() for item in value if str(item or "").strip())
                if not incoming:
                    return None
                if key not in merged:
                    merged[key] = incoming
                    continue
                current = tuple(str(item or "").strip() for item in merged.get(key, ()) if str(item or "").strip())
                if not current:
                    merged[key] = incoming
                    continue
                incoming_set = set(incoming)
                intersection = tuple(item for item in current if item in incoming_set)
                merged[key] = intersection or ("__vintrace_no_required_asset_match__",)
                continue
            if key == "excludedAssetIds":
                current = merged.get(key, ())
                if current in ("", None, []):
                    current = ()
                if not isinstance(current, tuple):
                    return None
                incoming = tuple(str(item or "").strip() for item in value if str(item or "").strip())
                values = tuple(dict.fromkeys((*current, *incoming)))
                if len(values) > 10_000:
                    return None
                merged[key] = values
                continue
            if key in {
                "excludedKeywords",
                "excludedMediaKinds",
                "excludedFileTypeAliases",
                "sourceTextFilters",
                "queryTextFilters",
                "keywordTextFilters",
                "locationTextFilters",
                "cameraTextFilters",
                "lensTextFilters",
                "dimensionsTextFilters",
                "iptcTextFilters",
                "ftsColumnTextFilters",
                "metadataExactTextFilters",
                "groupTextFilters",
            }:
                current = merged.get(key, ())
                if current in ("", None, []):
                    current = ()
                if not isinstance(current, tuple) or not isinstance(value, tuple):
                    return None
                combined = current
                for item in value:
                    if item not in combined:
                        combined = (*combined, item)
                if len(combined) > 16:
                    return None
                merged[key] = combined
                continue
            if key == "textFilters":
                current = merged.get(key, ())
                if current in ("", None, []):
                    current = ()
                if not isinstance(current, tuple) or not isinstance(value, tuple):
                    return None
                combined = current
                for item in value:
                    if (
                        isinstance(item, tuple)
                        and len(item) == 3
                        and str(item[0] or "") in {"title", "caption", "filename"}
                        and str(item[1] or "") in {"is", "isNot", "contains", "notContains"}
                        and str(item[2] or "").strip()
                        and item not in combined
                    ):
                        combined = (*combined, item)
                if len(combined) > 16:
                    return None
                merged[key] = combined
                continue
            if key == "ftsColumnFilters":
                current = merged.get(key, ())
                if current in ("", None, []):
                    current = ()
                if not isinstance(current, tuple) or not isinstance(value, tuple):
                    return None
                combined = current
                for item in value:
                    if (
                        isinstance(item, tuple)
                        and len(item) == 2
                        and str(item[0] or "") in {"ocr_text", "model_tags"}
                        and str(item[1] or "").strip()
                        and item not in combined
                    ):
                        combined = (*combined, item)
                if len(combined) > 16:
                    return None
                merged[key] = combined
                continue
            if key in {"groupPeopleFilters", "excludedGroupPeopleFilters"}:
                current = merged.get(key, ())
                if current in ("", None, []):
                    current = ()
                if not isinstance(current, tuple) or not isinstance(value, tuple):
                    return None
                combined = current
                for item in value:
                    member_count = 0
                    if isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], tuple):
                        member_count = len(item[0])
                    elif (
                        isinstance(item, tuple)
                        and len(item) == 4
                        and isinstance(item[0], tuple)
                        and isinstance(item[2], tuple)
                    ):
                        member_count = len(item[0]) + len(item[2])
                    if (
                        isinstance(item, tuple)
                        and len(item) in {2, 4}
                        and isinstance(item[0], tuple)
                        and member_count >= 1
                        and isinstance(item[1], tuple)
                        and (len(item) == 2 or (isinstance(item[2], tuple) and isinstance(item[3], tuple)))
                        and item not in combined
                    ):
                        combined = (*combined, item)
                if len(combined) > 16:
                    return None
                merged[key] = combined
                continue
            if key in {
                "widthFilters",
                "heightFilters",
                "durationFilters",
                "durationMsFilters",
                "megapixelsFilters",
                "ocrConfidenceFilters",
                "detectedItemConfidenceFilters",
                "modelConfidenceFilters",
                "detectedEventConfidenceFilters",
                "personCountFilters",
                "faceCountFilters",
                "matchCountFilters",
                "effectiveDateFilters",
                "addedDateFilters",
            }:
                current = merged.get(key, ())
                if current in ("", None, []):
                    current = ()
                if not isinstance(current, tuple) or not isinstance(value, tuple):
                    return None
                combined = current
                for item in value:
                    if item not in combined:
                        combined = (*combined, item)
                if len(combined) > 16:
                    return None
                merged[key] = combined
                continue
            if key == "personNames" and key in merged:
                current = {str(item or "").casefold(): str(item or "") for item in merged.get(key, ()) if str(item or "").strip()}
                incoming = {str(item or "").casefold(): str(item or "") for item in value if str(item or "").strip()}
                intersection = sorted((current[name] for name in current.keys() & incoming.keys()), key=str.casefold)
                if not intersection:
                    return None
                merged[key] = tuple(intersection)
                continue
            if key == "excludedPersonNames" and key in merged:
                values = {
                    str(item or "").casefold(): str(item or "")
                    for item in (*merged.get(key, ()), *value)
                    if str(item or "").strip()
                }
                merged[key] = tuple(sorted(values.values(), key=str.casefold))
                continue
            if key == "personStatuses" and key in merged:
                current = {str(item or "").lower() for item in merged.get(key, ()) if str(item or "").strip()}
                incoming = {str(item or "").lower() for item in value if str(item or "").strip()}
                intersection = tuple(sorted(current & incoming))
                if not intersection:
                    return None
                merged[key] = intersection
                continue
            if key == "excludedPersonStatuses" and key in merged:
                values = {
                    str(item or "").lower()
                    for item in (*merged.get(key, ()), *value)
                    if str(item or "").strip()
                }
                merged[key] = tuple(sorted(values))
                continue
            if not self._photo_smart_album_sql_set(merged, key, value):
                return None
        return merged

    def _photo_smart_album_sql_dedupe_criteria(self, branches: list[dict[str, Any]]) -> list[dict[str, Any]]:
        seen: set[tuple[tuple[str, Any], ...]] = set()
        unique: list[dict[str, Any]] = []
        for branch in branches:
            key = self._photo_smart_album_sql_criteria_key(branch)
            if key in seen:
                continue
            seen.add(key)
            unique.append(branch)
        return unique

    def _photo_smart_album_sql_condition_branches(
        self,
        condition: dict[str, Any],
        *,
        album_stack: tuple[str, ...] = (),
    ) -> list[dict[str, Any]] | None:
        op = str(condition.get("op", "") or "")
        if op == "all":
            branches: list[dict[str, Any]] = [{}]
            children = [child for child in condition.get("conditions", []) if isinstance(child, dict)]
            for child in children:
                child_branches = self._photo_smart_album_sql_condition_branches(child, album_stack=album_stack)
                if child_branches is None:
                    return None
                next_branches: list[dict[str, Any]] = []
                for branch in branches:
                    for child_branch in child_branches:
                        merged = self._photo_smart_album_sql_merge_criteria(branch, child_branch)
                        if merged is not None:
                            next_branches.append(merged)
                branches = self._photo_smart_album_sql_dedupe_criteria(next_branches)
                if not branches or len(branches) > 64:
                    return None
            return branches
        if op == "any":
            branches = []
            children = [child for child in condition.get("conditions", []) if isinstance(child, dict)]
            for child in children:
                child_branches = self._photo_smart_album_sql_condition_branches(child, album_stack=album_stack)
                if child_branches is None:
                    return None
                branches.extend(child_branches)
            branches = self._photo_smart_album_sql_dedupe_criteria(branches)
            return branches if branches and len(branches) <= 64 else None
        criteria: dict[str, Any] = {}
        return [criteria] if self._photo_smart_album_sql_apply_condition(criteria, condition, album_stack=album_stack) else None

    def _photo_smart_album_rule_dsls(self, rules: dict[str, Any]) -> list[dict[str, Any]]:
        dsls: list[dict[str, Any]] = []
        wrapped = rules.get("queryDsl")
        if isinstance(wrapped, dict):
            dsls.append(wrapped)
        if rules.get("op") and isinstance(rules.get("conditions"), list):
            dsls.append({"op": rules.get("op"), "conditions": rules.get("conditions")})
        return dsls

    def _photo_smart_album_sql_base_criteria(self, album: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]] | None:
        if str(album.get("albumKind", "smart") or "smart") != "smart":
            return None
        if self._photo_workspace_has_review_candidates():
            return None
        rules = self._clean_album_rules(album.get("rules", {}))
        unsupported_keys: set[str] = set()
        if any(rules.get(key) for key in unsupported_keys):
            return None
        criteria: dict[str, Any] = {"visibility": "visible"}
        include_people = tuple(sorted(self._clean_album_people(album.get("includePeople", [])), key=str.casefold))
        exclude_people = tuple(sorted(self._clean_album_people(album.get("excludePeople", [])), key=str.casefold))
        if include_people and not self._photo_smart_album_sql_set(criteria, "personNames", include_people):
            return None
        if exclude_people and not self._photo_smart_album_sql_set(criteria, "excludedPersonNames", exclude_people):
            return None
        if not self._photo_smart_album_sql_set(criteria, "query", str(rules.get("query", "") or "")):
            return None
        if not self._photo_smart_album_sql_set(criteria, "keyword", str(rules.get("keyword", "") or "")):
            return None
        media_kind = str(rules.get("mediaKind", "") or "").strip().lower()
        if media_kind and not self._photo_smart_album_sql_set(criteria, "mediaKind", media_kind):
            return None
        if bool(rules.get("favoriteOnly", False)) and not self._photo_smart_album_sql_set(criteria, "favoriteOnly", True):
            return None
        if bool(rules.get("editedOnly", False)) and not self._photo_smart_album_sql_set(criteria, "editedOnly", True):
            return None
        statuses = tuple(sorted(
            {
                str(status or "").strip().lower()
                for status in rules.get("statuses", []) or []
                if str(status or "").strip()
            }
        ))
        if statuses and not self._photo_smart_album_sql_set(criteria, "personStatuses", statuses):
            return None
        if rules.get("minScore"):
            score_filter = self._photo_smart_album_sql_number_filter("atLeast", rules.get("minScore"))
            if score_filter is None or not self._photo_smart_album_sql_set(criteria, "personScoreFilter", score_filter):
                return None
        if rules.get("minQuality"):
            quality_filter = self._photo_smart_album_sql_number_filter("atLeast", rules.get("minQuality"))
            if quality_filter is None or not self._photo_smart_album_sql_set(criteria, "personQualityFilter", quality_filter):
                return None
        if bool(rules.get("unknownOnly", False)) and not self._photo_smart_album_sql_set(criteria, "unknownPersonState", True):
            return None
        if bool(rules.get("hasVideoFrames", False)) and not self._photo_smart_album_sql_set(criteria, "hasVideoFramesState", True):
            return None
        if rules.get("recentDays"):
            cutoff = self._photo_smart_album_recent_cutoff(rules.get("recentDays"))
            if not cutoff or not self._photo_smart_album_sql_set(criteria, "effectiveTimeFrom", cutoff):
                return None
        if not self._photo_smart_album_sql_set(criteria, "dateFrom", str(rules.get("dateFrom", "") or "")):
            return None
        if not self._photo_smart_album_sql_set(criteria, "dateTo", str(rules.get("dateTo", "") or "")):
            return None
        if not self._photo_smart_album_sql_set(criteria, "source", str(rules.get("folder", "") or "")):
            return None
        return criteria, rules

    def _photo_smart_album_sql_criteria_branches(
        self,
        album: dict[str, Any],
        *,
        album_stack: tuple[str, ...] = (),
    ) -> list[dict[str, Any]] | None:
        album_id = str(album.get("albumId", "") or "")
        if album_id and album_id in album_stack:
            return None
        next_album_stack = (*album_stack, album_id) if album_id else album_stack
        base = self._photo_smart_album_sql_base_criteria(album)
        if base is None:
            return None
        base_criteria, rules = base
        branches = [base_criteria]
        for dsl in self._photo_smart_album_rule_dsls(rules):
            dsl_branches = self._photo_smart_album_sql_condition_branches(dsl, album_stack=next_album_stack)
            if dsl_branches is None:
                return None
            next_branches: list[dict[str, Any]] = []
            for branch in branches:
                for dsl_branch in dsl_branches:
                    merged = self._photo_smart_album_sql_merge_criteria(branch, dsl_branch)
                    if merged is not None:
                        next_branches.append(merged)
            branches = self._photo_smart_album_sql_dedupe_criteria(next_branches)
            if not branches or len(branches) > 64:
                return None
        return branches

    def _photo_smart_album_sql_criteria(self, album: dict[str, Any]) -> dict[str, Any] | None:
        branches = self._photo_smart_album_sql_criteria_branches(album)
        if not branches or len(branches) != 1:
            return None
        return branches[0]

    def _photo_smart_album_sql_page_for_criteria(
        self,
        criteria: dict[str, Any],
        *,
        offset: int,
        limit: int,
        sort: str,
    ) -> dict[str, Any]:
        if isinstance(criteria.get("duplicateState"), bool):
            self.project.db.ensure_photo_duplicate_groups()
        return self.project.db.list_photo_asset_page(
            offset=offset,
            limit=limit,
            query=str(criteria.get("query", "") or ""),
            query_text_filters=criteria.get("queryTextFilters", ()),
            visibility=str(criteria.get("visibility", "visible") or "visible"),
            media_kind=str(criteria.get("mediaKind", "") or ""),
            excluded_media_kinds=tuple(
                str(item or "").strip().lower()
                for item in criteria.get("excludedMediaKinds", ())
                if str(item or "").strip()
            ),
            favorite_only=bool(criteria.get("favoriteOnly", False)),
            favorite_state=criteria.get("favoriteState") if isinstance(criteria.get("favoriteState"), bool) else None,
            edited_only=bool(criteria.get("editedOnly", False)),
            edited_state=criteria.get("editedState") if isinstance(criteria.get("editedState"), bool) else None,
            keyword=str(criteria.get("keyword", "") or ""),
            excluded_keywords=criteria.get("excludedKeywords", ()),
            keyword_text_filters=criteria.get("keywordTextFilters", ()),
            date_from=str(criteria.get("dateFrom", "") or ""),
            date_to=str(criteria.get("dateTo", "") or ""),
            effective_date_filters=criteria.get("effectiveDateFilters", ()),
            source=str(criteria.get("source", "") or ""),
            required_asset_ids=criteria.get("requiredAssetIds", ()),
            excluded_asset_ids=criteria.get("excludedAssetIds", ()),
            file_type_aliases=criteria.get("fileTypeAliases", ()),
            excluded_file_type_aliases=criteria.get("excludedFileTypeAliases", ()),
            source_text_filters=criteria.get("sourceTextFilters", ()),
            text_filters=criteria.get("textFilters", ()),
            fts_column_filters=criteria.get("ftsColumnFilters", ()),
            fts_column_text_filters=criteria.get("ftsColumnTextFilters", ()),
            metadata_exact_text_filters=criteria.get("metadataExactTextFilters", ()),
            location=str(criteria.get("location", "") or ""),
            location_text_filters=criteria.get("locationTextFilters", ()),
            camera=str(criteria.get("camera", "") or ""),
            camera_text_filters=criteria.get("cameraTextFilters", ()),
            lens=str(criteria.get("lens", "") or ""),
            lens_text_filters=criteria.get("lensTextFilters", ()),
            dimensions=str(criteria.get("dimensions", "") or ""),
            dimensions_text_filters=criteria.get("dimensionsTextFilters", ()),
            iptc_text_filters=criteria.get("iptcTextFilters", ()),
            width_filters=criteria.get("widthFilters", ()),
            height_filters=criteria.get("heightFilters", ()),
            duration_filters=criteria.get("durationFilters", ()),
            duration_ms_filters=criteria.get("durationMsFilters", ()),
            megapixels_filters=criteria.get("megapixelsFilters", ()),
            ocr_confidence_filters=criteria.get("ocrConfidenceFilters", ()),
            detected_item_confidence_filters=criteria.get("detectedItemConfidenceFilters", ()),
            model_confidence_filters=criteria.get("modelConfidenceFilters", ()),
            detected_event_confidence_filters=criteria.get("detectedEventConfidenceFilters", ()),
            person_count_filters=criteria.get("personCountFilters", ()),
            face_count_filters=criteria.get("faceCountFilters", ()),
            match_count_filters=criteria.get("matchCountFilters", ()),
            added_date_filters=criteria.get("addedDateFilters", ()),
            group_people_filters=criteria.get("groupPeopleFilters", ()),
            excluded_group_people_filters=criteria.get("excludedGroupPeopleFilters", ()),
            group_text_filters=criteria.get("groupTextFilters", ()),
            duplicate_state=criteria.get("duplicateState") if isinstance(criteria.get("duplicateState"), bool) else None,
            manual_album_ids=criteria.get("manualAlbumIds", ()),
            excluded_manual_album_ids=criteria.get("excludedManualAlbumIds", ()),
            manual_album_membership_state=criteria.get("manualAlbumMembershipState") if isinstance(criteria.get("manualAlbumMembershipState"), bool) else None,
            person_names=criteria.get("personNames", ()),
            excluded_person_names=criteria.get("excludedPersonNames", ()),
            person_score_threshold=float(self.project.config.thresholds.confident),
            person_statuses=criteria.get("personStatuses", ()),
            excluded_person_statuses=criteria.get("excludedPersonStatuses", ()),
            person_score_filter=criteria.get("personScoreFilter"),
            person_quality_filter=criteria.get("personQualityFilter"),
            unknown_person_state=criteria.get("unknownPersonState") if isinstance(criteria.get("unknownPersonState"), bool) else None,
            has_video_frames_state=criteria.get("hasVideoFramesState") if isinstance(criteria.get("hasVideoFramesState"), bool) else None,
            hidden_state=criteria.get("hiddenState") if isinstance(criteria.get("hiddenState"), bool) else None,
            deleted_state=criteria.get("deletedState") if isinstance(criteria.get("deletedState"), bool) else None,
            effective_time_from=str(criteria.get("effectiveTimeFrom", "") or ""),
            effective_time_before=str(criteria.get("effectiveTimeBefore", "") or ""),
            sort=sort,
        )

    def _photo_smart_album_sql_assets_for_criteria(
        self,
        criteria: dict[str, Any],
        *,
        sort: str,
    ) -> list[dict[str, Any]]:
        first_page = self._photo_smart_album_sql_page_for_criteria(criteria, offset=0, limit=1, sort=sort)
        total = int(first_page.get("total", 0) or 0)
        if total <= 0:
            return []
        if total <= 1:
            assets = first_page.get("assets", [])
            return assets if isinstance(assets, list) else []
        page = self._photo_smart_album_sql_page_for_criteria(criteria, offset=0, limit=total, sort=sort)
        assets = page.get("assets", [])
        return assets if isinstance(assets, list) else []

    def _photo_smart_album_entries_sql_union(self, album: dict[str, Any], *, sort: str) -> list[dict[str, Any]] | None:
        branches = self._photo_smart_album_sql_criteria_branches(album)
        if not branches or len(branches) <= 1:
            return None
        assets_by_source: dict[str, dict[str, Any]] = {}
        for criteria in branches:
            for asset in self._photo_smart_album_sql_assets_for_criteria(criteria, sort="newest"):
                source = str(asset.get("sourcePath", "") or "")
                if source and source not in assets_by_source:
                    assets_by_source[source] = asset
        if not assets_by_source:
            return []
        return self._sort_photo_entries(self._photo_entries_for_assets(list(assets_by_source.values())), sort)

    def _photo_manual_album_asset_ids(self, album_ids: Iterable[str]) -> tuple[str, ...]:
        seen: set[str] = set()
        asset_ids: list[str] = []
        for album_id in album_ids:
            clean_album_id = str(album_id or "").strip()
            if not clean_album_id:
                continue
            for asset in self.project.db.list_photo_album_assets(clean_album_id):
                asset_id = str(asset.get("assetId", "") or "").strip()
                if asset_id and asset_id not in seen:
                    seen.add(asset_id)
                    asset_ids.append(asset_id)
        return tuple(asset_ids)

    def _photo_smart_album_asset_ids_sql(
        self,
        album: dict[str, Any],
        *,
        album_stack: tuple[str, ...] = (),
    ) -> tuple[str, ...] | None:
        branches = self._photo_smart_album_sql_criteria_branches(album, album_stack=album_stack)
        if not branches:
            return None
        assets_by_id: dict[str, None] = {}
        for criteria in branches:
            for asset in self._photo_smart_album_sql_assets_for_criteria(criteria, sort="newest"):
                asset_id = str(asset.get("assetId", "") or "").strip()
                if asset_id:
                    assets_by_id.setdefault(asset_id, None)
        return tuple(assets_by_id.keys())

    def _photo_album_filter_sql_target(
        self,
        album_filter: str,
        *,
        album_stack: tuple[str, ...] = (),
    ) -> dict[str, tuple[str, ...]] | None:
        clean = str(album_filter or "").strip()
        if clean.startswith("album:"):
            clean = clean[len("album:"):]
        if not clean:
            return {"manualAlbumIds": (), "smartAssetIds": ()}
        clean_key = clean.casefold()
        manual_album_ids: list[str] = []
        smart_asset_ids: list[str] = []
        seen_smart_asset_ids: set[str] = set()
        matched = False
        for album in self.project.db.list_photo_albums():
            album_id = str(album.get("albumId", "") or "")
            album_name = str(album.get("name", "") or "")
            if clean not in {album_id, f"album:{album_id}"} and clean_key != album_name.casefold():
                continue
            matched = True
            if str(album.get("albumKind", "smart") or "smart") == "manual":
                if album_id and album_id not in manual_album_ids:
                    manual_album_ids.append(album_id)
                continue
            if not album_id or album_id in album_stack:
                return None
            asset_ids = self._photo_smart_album_asset_ids_sql(album, album_stack=album_stack)
            if asset_ids is None:
                return None
            for asset_id in asset_ids:
                if asset_id and asset_id not in seen_smart_asset_ids:
                    seen_smart_asset_ids.add(asset_id)
                    smart_asset_ids.append(asset_id)
        if not matched:
            return None
        return {
            "manualAlbumIds": tuple(manual_album_ids),
            "smartAssetIds": tuple(smart_asset_ids),
        }

    def _photo_smart_album_items_sql_page(
        self,
        album: dict[str, Any],
        *,
        offset: int,
        limit: int,
        sort: str,
        query: str,
        keyword: str,
        media_kind_filter: str,
        date_bucket_mode: str,
        date_bucket_key: str,
        date_from_filter: str,
        date_to_filter: str,
        source_filter: str,
        source_text_filters: tuple[tuple[str, str], ...],
        source_paths_filter: set[str],
        file_type_filter: str,
        location_filter: str,
        camera_filter: str,
        nearby_filter: dict[str, float] | None,
        album_filter: str,
        person_filter: str,
        status_filter: str,
        min_quality_filter: float,
        favorite_only: bool,
        edited_only: bool,
        not_in_album_only: bool,
        duplicate_only: bool,
        visibility_filter: str,
        library_root: str = "",
    ) -> dict[str, Any] | None:
        clean_library_root = str(library_root or "").strip()
        allowed_source_text_filters = self._photo_library_root_source_text_filters(clean_library_root)
        if sort not in {"newest", "oldest", "scanDate", "title", "filename", "mediaKind"}:
            return None
        if source_text_filters and tuple(source_text_filters) != allowed_source_text_filters:
            return None
        if (
            query
            or keyword
            or media_kind_filter
            or date_bucket_mode
            or date_bucket_key
            or date_from_filter
            or date_to_filter
            or source_filter
            or source_paths_filter
            or file_type_filter
            or location_filter
            or camera_filter
            or nearby_filter
            or album_filter
            or person_filter
            or status_filter
            or min_quality_filter
            or favorite_only
            or edited_only
            or not_in_album_only
            or duplicate_only
            or visibility_filter not in {"", "visible"}
        ):
            return None
        if clean_library_root:
            source_paths = self._photo_smart_album_source_paths_sql(album, library_root=clean_library_root)
            if source_paths is None:
                return None
            entries = self._sort_photo_entries(
                self._photo_entries_for_materialized_source_paths(source_paths),
                sort,
            )
            return {
                "total": len(entries),
                "entries": entries[offset:offset + limit],
            }
        criteria = self._photo_smart_album_sql_criteria(album)
        if criteria is not None:
            result = self._photo_smart_album_sql_page_for_criteria(criteria, offset=offset, limit=limit, sort=sort)
            return {
                "total": int(result.get("total", 0) or 0),
                "entries": self._photo_entries_for_assets(result.get("assets", [])),
            }
        entries = self._photo_smart_album_entries_sql_union(album, sort=sort)
        if entries is None:
            source_paths = self._photo_smart_album_materialized_source_paths(album)
            if source_paths is None:
                return None
            entries = self._sort_photo_entries(
                self._photo_entries_for_materialized_source_paths(source_paths),
                sort,
            )
        return {
            "total": len(entries),
            "entries": entries[offset:offset + limit],
        }

    def list_photo_folder_items(self, params: dict[str, Any]) -> dict[str, Any]:
        folder_id = str(params.get("folderId", "")).strip()
        offset = max(0, int(params.get("offset", 0) or 0))
        limit = max(1, min(500, int(params.get("limit", 100) or 100)))
        preview_budget = max(0, min(64, int(params.get("previewBudget", 0) or 0)))
        sort = str(params.get("sort", "newest") or "newest")
        group_mode = self._normalize_photo_group_mode(params.get("groupMode", params.get("groupViewMode", "all")))
        query = str(params.get("query", "") or "").strip()
        keyword = str(params.get("keyword", "") or "").strip()
        media_kind_filter = str(params.get("mediaKind", "") or "").strip().lower()
        date_bucket_mode = str(params.get("dateBucketMode", "") or "").strip()
        date_bucket_key = str(params.get("dateBucketKey", "") or "").strip()
        date_from_filter = self._normalize_photo_date_filter(params.get("dateFrom", params.get("fromDate", "")))
        date_to_filter = self._normalize_photo_date_filter(params.get("dateTo", params.get("toDate", "")))
        source_filter = str(params.get("source", params.get("sourceFolder", params.get("path", ""))) or "").strip()
        library_root_filter = self._photo_library_root_filter_from_params(params)
        library_root_source_filters = self._photo_library_root_source_text_filters(library_root_filter)
        source_paths_raw = params.get("sourcePaths", params.get("sources", []))
        source_paths_filter = {
            str(path or "").strip()
            for path in source_paths_raw
            if str(path or "").strip()
        } if isinstance(source_paths_raw, list) else set()
        file_type_filter = str(params.get("fileType", params.get("extension", "")) or "").strip().lower().lstrip(".")
        location_filter = str(params.get("location", params.get("place", "")) or "").strip()
        camera_filter = str(params.get("camera", params.get("cameraModel", "")) or "").strip()
        nearby_filter = self._photo_nearby_filter_from_params(params)
        album_filter = str(params.get("albumId", params.get("album", "")) or "").strip()
        person_filter = str(params.get("person", params.get("personName", "")) or "").strip()
        status_filter = str(params.get("status", params.get("reviewStatus", "")) or "").strip().lower()
        if status_filter not in {"", "pending", "accepted", "rejected", "uncertain"}:
            status_filter = ""
        try:
            min_quality_filter = max(0.0, min(1.0, float(params.get("minQuality", params.get("quality", 0)) or 0.0)))
        except (TypeError, ValueError):
            min_quality_filter = 0.0

        def truthy(value: Any) -> bool:
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return bool(value)
            return str(value or "").strip().lower() in {"1", "true", "yes", "on"}

        favorite_only = truthy(params.get("favoriteOnly", params.get("favorite", False)))
        edited_only = truthy(params.get("editedOnly", params.get("edited", False)))
        not_in_album_only = truthy(params.get("notInAlbumOnly", params.get("notInAlbum", False)))
        detect_missing_originals = truthy(params.get("detectMissingOriginals", params.get("detectMissing", False)))
        duplicate_only = truthy(params.get("duplicateOnly", params.get("duplicatesOnly", params.get("duplicate", False))))
        collapse_bursts = truthy(params.get("collapseBursts", params.get("collapseBurstStacks", False)))
        pet_review_kind_filter = self._photo_pet_kind_from_text(
            params.get("petReviewKind", params.get("petKind", params.get("animalKind", "")))
        ) or ""
        if duplicate_only:
            self.project.db.ensure_photo_duplicate_groups()
        visibility_filter = self._normalize_photo_visibility_filter(
            params.get("visibility", params.get("visibilityState", "")),
            hidden_only=truthy(params.get("hiddenOnly", False)),
            deleted_only=truthy(params.get("deletedOnly", False)),
        )
        search_index_status: dict[str, Any] = {}

        def apply_filters(entries: list[dict[str, Any]]) -> list[dict[str, Any]]:
            nonlocal search_index_status
            query_search_index_status: dict[str, Any] = {}
            filtered_entries = self._filter_photo_entries_by_view_filters(
                self._filter_photo_entries_by_keyword(
                    self._filter_photo_entries_by_query(entries, query, search_index_out=query_search_index_status),
                    keyword,
                ),
                media_kind=media_kind_filter,
                favorite_only=favorite_only,
                edited_only=edited_only,
            )
            if query_search_index_status:
                search_index_status = dict(query_search_index_status)
            filtered_entries = self._filter_photo_entries_by_metadata_filters(
                filtered_entries,
                date_from=date_from_filter,
                date_to=date_to_filter,
                source=source_filter,
                library_root=library_root_filter,
                file_type=file_type_filter,
                location=location_filter,
                camera=camera_filter,
                duplicate_only=duplicate_only,
                nearby=nearby_filter,
            )
            filtered_entries = self._filter_photo_entries_by_visibility_filter(filtered_entries, visibility_filter)
            filtered_entries = self._filter_photo_entries_by_album_filter(filtered_entries, album_filter)
            filtered_entries = self._filter_photo_entries_by_date_bucket(filtered_entries, date_bucket_mode, date_bucket_key)
            filtered_entries = self._filter_photo_entries_by_candidate_filters(
                filtered_entries,
                person=person_filter,
                status=status_filter,
                min_quality=min_quality_filter,
            )
            if not_in_album_only:
                filtered_entries = self._filter_photo_entries_not_in_manual_album(filtered_entries)
            if source_paths_filter:
                filtered_entries = [
                    entry
                    for entry in filtered_entries
                    if str(entry.get("sourcePath", "") or "") in source_paths_filter
                ]
            return filtered_entries

        preview_failure_count = 0
        preview_error_samples: list[dict[str, str]] = []
        missing_original_count = 0
        missing_original_samples: list[dict[str, str]] = []
        album_membership_cache: dict[str, set[str]] = {}
        media_pair_cache: dict[str, list[dict[str, Any]]] = {}
        edit_stack_version_count_cache: dict[str, int] = {}

        def note_preview_error(item: dict[str, Any]) -> None:
            nonlocal preview_failure_count
            message = str(item.get("previewError", "") or "").strip()
            if not message:
                return
            preview_failure_count += 1
            if len(preview_error_samples) < 5:
                preview_error_samples.append({
                    "sourcePath": str(item.get("sourcePath", "") or ""),
                    "message": message,
                })

        def finalize_photo_item(item: dict[str, Any]) -> dict[str, Any]:
            nonlocal missing_original_count
            if detect_missing_originals:
                refreshed = self.project.db.refresh_photo_asset_missing_status(
                    asset_id=str(item.get("assetId", "") or ""),
                    source_path=str(item.get("sourcePath", "") or ""),
                )
                if refreshed:
                    item["missingAt"] = str(refreshed.get("missingAt", "") or "")
            if str(item.get("missingAt", "") or ""):
                missing_original_count += 1
                if len(missing_original_samples) < 5:
                    missing_original_samples.append({
                        "sourcePath": str(item.get("sourcePath", "") or ""),
                        "missingAt": str(item.get("missingAt", "") or ""),
                    })
            note_preview_error(item)
            return item

        def page_payload(
            total: int,
            offset_value: int,
            limit_value: int,
            returned: int,
            items: list[dict[str, Any]],
            *,
            validation: list[dict[str, str]] | None = None,
        ) -> dict[str, Any]:
            payload: dict[str, Any] = {
                "total": total,
                "offset": offset_value,
                "limit": limit_value,
                "returned": returned,
                "items": items,
            }
            if validation is not None:
                payload["validation"] = validation
            if folder_id.startswith("group:"):
                payload["groupMode"] = group_mode
            if nearby_filter:
                payload["nearby"] = nearby_filter
            if preview_failure_count:
                payload["previewFailures"] = preview_failure_count
                payload["previewErrorSamples"] = preview_error_samples
            if missing_original_count:
                payload["missingOriginals"] = missing_original_count
                payload["missingOriginalSamples"] = missing_original_samples
            if search_index_status:
                payload["searchIndex"] = search_index_status
            return payload

        def all_photo_sql_page(
            *,
            favorite_only_value: bool | None = None,
            edited_only_value: bool | None = None,
            media_kind_value: str | None = None,
            visibility_value: str | None = None,
            duplicate_only_value: bool | None = None,
            source_scan_runs_value: Iterable[str] = (),
        ) -> dict[str, Any] | None:
            return self._photo_all_folder_items_sql_page(
                offset=offset,
                limit=limit,
                sort=sort,
                query=query,
                keyword=keyword,
                media_kind_filter=media_kind_filter if media_kind_value is None else media_kind_value,
                date_bucket_mode=date_bucket_mode,
                date_bucket_key=date_bucket_key,
                date_from_filter=date_from_filter,
                date_to_filter=date_to_filter,
                source_filter=source_filter,
                source_text_filters=library_root_source_filters,
                source_paths_filter=source_paths_filter,
                source_scan_runs=source_scan_runs_value,
                file_type_filter=file_type_filter,
                location_filter=location_filter,
                camera_filter=camera_filter,
                nearby_filter=nearby_filter,
                album_filter=album_filter,
                person_filter=person_filter,
                status_filter=status_filter,
                min_quality_filter=min_quality_filter,
                favorite_only=favorite_only if favorite_only_value is None else favorite_only_value,
                edited_only=edited_only if edited_only_value is None else edited_only_value,
                not_in_album_only=not_in_album_only,
                duplicate_only=duplicate_only if duplicate_only_value is None else duplicate_only_value,
                visibility_filter=visibility_filter if visibility_value is None else visibility_value,
            )

        def entry_asset_id(entry: dict[str, Any]) -> str:
            asset_id = str(entry.get("_assetId", "") or "").strip()
            if asset_id:
                return asset_id
            asset = entry.get("_asset")
            if isinstance(asset, dict):
                return str(asset.get("assetId", "") or "").strip()
            return ""

        def prefetch_media_pairs(entries: list[dict[str, Any]]) -> None:
            asset_ids = [
                asset_id
                for entry in entries
                for asset_id in [entry_asset_id(entry)]
                if asset_id and asset_id not in media_pair_cache
            ]
            if asset_ids:
                media_pair_cache.update(self.project.db.photo_media_pairs_for_assets(asset_ids))

        def prefetch_edit_stack_version_counts(entries: list[dict[str, Any]]) -> None:
            asset_ids = [
                asset_id
                for entry in entries
                for asset_id in [entry_asset_id(entry)]
                if asset_id and asset_id not in edit_stack_version_count_cache
            ]
            if asset_ids:
                edit_stack_version_count_cache.update(self.project.db.photo_edit_stack_version_counts_for_assets(asset_ids))

        def collapse_burst_entries(entries: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], dict[str, dict[str, Any]]]:
            if not collapse_bursts:
                return entries, {}
            groups: dict[str, list[tuple[int, dict[str, Any], dict[str, Any]]]] = {}
            for index, entry in enumerate(entries):
                info = self._photo_burst_entry_info(entry)
                if info is None:
                    continue
                groups.setdefault(str(info.get("groupKey", "") or ""), []).append((index, entry, info))
            if not groups:
                return entries, {}
            collapsed_units: list[tuple[int, dict[str, Any]]] = []
            skipped_indexes: set[int] = set()
            burst_stack_by_source: dict[str, dict[str, Any]] = {}
            for rows in groups.values():
                if len(rows) <= 1:
                    continue
                indexes = [index for index, _entry, _info in rows]
                infos = [info for _index, _entry, info in rows]
                stack = self._photo_burst_stack_from_infos(infos, include_items=True)
                representative_source = str(stack.get("coverSourcePath", "") or "")
                representative_entry = next(
                    (entry for _index, entry, _info in rows if str(entry.get("sourcePath", "") or "") == representative_source),
                    rows[0][1],
                )
                representative_source = str(representative_entry.get("sourcePath", "") or representative_source)
                skipped_indexes.update(indexes)
                collapsed_units.append((min(indexes), representative_entry))
                burst_stack_by_source[representative_source] = {
                    "stackId": str(stack.get("stackId", "") or ""),
                    "name": str(stack.get("name", "") or "Burst"),
                    "count": int(stack.get("count", 0) or len(rows)),
                    "keeperCount": int(stack.get("keeperCount", 0) or 0),
                    "coverSourcePath": str(stack.get("coverSourcePath", "") or representative_source),
                    "representativeSourcePath": representative_source,
                    "sourcePaths": [str(path or "") for path in stack.get("sourcePaths", []) if str(path or "")],
                    "collapsed": True,
                }
            if not burst_stack_by_source:
                return entries, {}
            for index, entry in enumerate(entries):
                if index not in skipped_indexes:
                    collapsed_units.append((index, entry))
            collapsed_units.sort(key=lambda unit: unit[0])
            return [entry for _index, entry in collapsed_units], burst_stack_by_source

        def photo_items_for_rows(rows: list[dict[str, Any]], burst_stack_by_source: dict[str, dict[str, Any]] | None = None) -> list[dict[str, Any]]:
            prefetch_media_pairs(rows)
            prefetch_edit_stack_version_counts(rows)
            items: list[dict[str, Any]] = []
            remaining = preview_budget
            burst_lookup = burst_stack_by_source or {}
            for row in rows:
                src = str(row.get("sourcePath", "") or "")
                before = self.project.preview_path_for(src, create=False)
                item = self._photo_item_row(
                    source_path=src,
                    media_kind=str(row.get("mediaKind", "image") or "image"),
                    preview_create=remaining > 0,
                    candidate=row.get("candidate"),
                    matches=row.get("matches", []),
                    scan_date=str(row.get("scanDate", "") or ""),
                    album_membership_cache=album_membership_cache,
                    media_pair_cache=media_pair_cache,
                    edit_stack_version_count_cache=edit_stack_version_count_cache,
                )
                if row.get("eventAt"):
                    item["eventAt"] = str(row.get("eventAt", "") or "")
                    item["eventType"] = str(row.get("eventType", "") or "")
                    item["eventActor"] = str(row.get("eventActor", "") or "")
                    item["eventMetadata"] = row.get("eventMetadata", {}) if isinstance(row.get("eventMetadata", {}), dict) else {}
                if isinstance(row.get("_utilityMatch"), dict):
                    item["utilityMatch"] = row["_utilityMatch"]
                if src in burst_lookup:
                    item["burstStack"] = burst_lookup[src]
                if remaining > 0 and not before and item.get("previewPath"):
                    remaining -= 1
                items.append(finalize_photo_item(item))
            return items

        if folder_id == "all" or folder_id.startswith("sourceFolder:"):
            sql_page = None if collapse_bursts else self._photo_all_folder_items_sql_page(
                    offset=offset,
                    limit=limit,
                    sort=sort,
                    query=query,
                    keyword=keyword,
                    media_kind_filter=media_kind_filter,
                    date_bucket_mode=date_bucket_mode,
                    date_bucket_key=date_bucket_key,
                    date_from_filter=date_from_filter,
                    date_to_filter=date_to_filter,
                    source_filter=source_filter,
                    source_text_filters=library_root_source_filters,
                    source_paths_filter=source_paths_filter,
                    file_type_filter=file_type_filter,
                    location_filter=location_filter,
                    camera_filter=camera_filter,
                    nearby_filter=nearby_filter,
                    album_filter=album_filter,
                    person_filter=person_filter,
                    status_filter=status_filter,
                    min_quality_filter=min_quality_filter,
                    favorite_only=favorite_only,
                    edited_only=edited_only,
                    not_in_album_only=not_in_album_only,
                    duplicate_only=duplicate_only,
                    visibility_filter=visibility_filter,
                )
            if sql_page is not None:
                if isinstance(sql_page.get("searchIndex"), dict):
                    search_index_status = dict(sql_page["searchIndex"])
                rows = sql_page["entries"]
                items = photo_items_for_rows(rows)
                return page_payload(int(sql_page["total"]), offset, limit, len(items), items)
            all_entries = self._all_photo_entries()
            matched = self._sort_photo_entries(
                apply_filters(all_entries if visibility_filter in {"all", "hidden", "deleted"} else self._visible_photo_entries(all_entries)),
                sort,
            )
            matched, burst_stack_by_source = collapse_burst_entries(matched)
            total = len(matched)
            rows = matched[offset:offset + limit]
            items = photo_items_for_rows(rows, burst_stack_by_source)
            return page_payload(total, offset, limit, len(items), items)

        resolved_trip: dict[str, Any] | None = None
        resolved_memory: dict[str, Any] | None = None
        generated_cache_for_paging: dict[str, Any] | None = None

        def cached_generated_collections() -> dict[str, Any]:
            nonlocal generated_cache_for_paging
            if generated_cache_for_paging is None:
                generated_cache_for_paging = self._photo_generated_collection_cache_for_paging(library_root_filter)
            return generated_cache_for_paging

        if folder_id.startswith("place:"):
            place_id = folder_id[len("place:"):]
            if not any(str(place.get("placeId", "") or "") == place_id for place in self.project.db.list_photo_places(source_text_filters=library_root_source_filters)):
                raise ValueError("Unknown photo place id.")

        if folder_id.startswith("trip:"):
            trip_id = folder_id[len("trip:"):]
            resolved_trip = self._photo_cached_trip_by_id(trip_id, library_root_filter)
            if not resolved_trip:
                raise ValueError("Unknown photo trip id.")

        if folder_id.startswith("memory:"):
            memory_id = folder_id[len("memory:"):]
            resolved_memory = self._photo_cached_memory_by_id(memory_id, library_root_filter)
            if not resolved_memory:
                raise ValueError("Unknown photo memory id.")

        if folder_id.startswith("pet:"):
            pet_name = self._photo_pet_name_from_folder_id(folder_id)
            pet_probe = self.project.db.list_photo_asset_page(
                offset=0,
                limit=1,
                visibility="visible",
                source_text_filters=library_root_source_filters,
                pet_names=(pet_name,),
                sort="newest",
            )
            if not int(pet_probe.get("total", 0) or 0):
                raise ValueError("Unknown pet folder id.")

        if folder_id.startswith("media:"):
            media_folder_kind = folder_id[len("media:"):].strip().lower()
            if media_folder_kind not in PHOTO_MEDIA_KINDS:
                raise ValueError("Unknown photo media type folder.")

        utility_ids = {
            "favorites",
            "duplicates",
            "hidden",
            "recentlyDeleted",
            "places",
            "recentlyAdded",
            "recentlySaved",
            "recentlyEdited",
            "recentlyViewed",
            "recentlyShared",
            "imports",
            "lastImport",
            "recentlyImported",
            "recovered",
            "trips",
            "memories",
            "pets",
            "petReview",
        }
        utility_ids.update(PHOTO_UTILITY_CLASSIFIER_IDS)
        if folder_id.startswith("import:"):
            import_id = folder_id[len("import:"):]
            if not self.project.db.photo_import_session_by_id(import_id):
                raise ValueError("Unknown photo import session id.")

        def import_session_ids_for_utility(utility_id: str) -> tuple[str, ...]:
            if utility_id.startswith("import:"):
                return (utility_id[len("import:"):].strip(),)
            if utility_id.startswith("importSource:"):
                group = self._photo_import_source_group_from_folder_id(utility_id)
                return tuple(
                    str(import_id or "")
                    for import_id in (group or {}).get("importIds", [])
                    if str(import_id or "")
                )
            if utility_id not in {"imports", "lastImport", "recentlyImported", "recentlySaved"}:
                return ()
            sessions = self.project.db.list_photo_import_sessions(limit=1000)
            if utility_id == "imports":
                return tuple(str(session.get("importId", "") or "") for session in sessions if str(session.get("importId", "") or ""))
            if utility_id == "lastImport":
                latest = sessions[0] if sessions else {}
                latest_id = str(latest.get("importId", "") or "") if latest else ""
                return (latest_id,) if latest_id else ()
            cutoff = datetime.utcnow() - timedelta(days=30)
            ids: list[str] = []
            for session in sessions:
                if utility_id == "recentlySaved" and str(session.get("sourceKind", "") or "").strip().lower() not in PHOTO_APP_IMPORT_SOURCE_KINDS:
                    continue
                value = str(session.get("completedAt", "") or session.get("updatedAt", "") or session.get("startedAt", "") or "")
                try:
                    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
                except ValueError:
                    continue
                if parsed.tzinfo is not None:
                    parsed = parsed.replace(tzinfo=None)
                if parsed >= cutoff:
                    import_id = str(session.get("importId", "") or "")
                    if import_id:
                        ids.append(import_id)
            return tuple(ids)

        utility_sql_page: dict[str, Any] | None = None
        if not collapse_bursts:
            if folder_id == "favorites":
                utility_sql_page = all_photo_sql_page(favorite_only_value=True, visibility_value="visible")
            elif folder_id == "hidden":
                utility_sql_page = all_photo_sql_page(visibility_value="hidden")
            elif folder_id == "recentlyDeleted":
                utility_sql_page = all_photo_sql_page(visibility_value="deleted")
            elif folder_id == "recentlyAdded":
                utility_sql_page = all_photo_sql_page(visibility_value="visible")
            elif folder_id == "recentlyEdited":
                utility_sql_page = all_photo_sql_page(edited_only_value=True, visibility_value="visible")
            elif folder_id.startswith("media:"):
                utility_sql_page = all_photo_sql_page(media_kind_value=folder_id[len("media:"):].strip().lower(), visibility_value="visible")
            elif folder_id in {"imports", "lastImport", "recentlyImported", "recentlySaved"} or folder_id.startswith("import:") or folder_id.startswith("importSource:"):
                import_ids = import_session_ids_for_utility(folder_id)
                if import_ids:
                    utility_sql_page = all_photo_sql_page(source_scan_runs_value=import_ids, visibility_value="visible")
                else:
                    utility_sql_page = {"total": 0, "entries": []}
            elif folder_id in {"pets", "petReview"} or folder_id.startswith("pet:"):
                utility_sql_page = self._photo_pet_folder_items_sql_page(
                    folder_id,
                    offset=offset,
                    limit=limit,
                    sort=sort,
                    query=query,
                    keyword=keyword,
                    media_kind_filter=media_kind_filter,
                    date_bucket_mode=date_bucket_mode,
                    date_bucket_key=date_bucket_key,
                    date_from_filter=date_from_filter,
                    date_to_filter=date_to_filter,
                    source_filter=source_filter,
                    source_text_filters=library_root_source_filters,
                    source_paths_filter=source_paths_filter,
                    file_type_filter=file_type_filter,
                    location_filter=location_filter,
                    camera_filter=camera_filter,
                    nearby_filter=nearby_filter,
                    album_filter=album_filter,
                    person_filter=person_filter,
                    status_filter=status_filter,
                    min_quality_filter=min_quality_filter,
                    favorite_only=favorite_only,
                    edited_only=edited_only,
                    not_in_album_only=not_in_album_only,
                    duplicate_only=duplicate_only,
                    pet_review_kind_filter=pet_review_kind_filter,
                )
            if utility_sql_page is not None:
                if isinstance(utility_sql_page.get("searchIndex"), dict):
                    search_index_status = dict(utility_sql_page["searchIndex"])
                rows = utility_sql_page["entries"]
                items = photo_items_for_rows(rows)
                return page_payload(int(utility_sql_page["total"]), offset, limit, len(items), items)

        if folder_id == "duplicates" and not collapse_bursts:
            self.project.db.ensure_photo_duplicate_groups()
            sql_page = all_photo_sql_page(duplicate_only_value=True)
            if sql_page is not None:
                if isinstance(sql_page.get("searchIndex"), dict):
                    search_index_status = dict(sql_page["searchIndex"])
                rows = sql_page["entries"]
                items = photo_items_for_rows(rows)
                return page_payload(int(sql_page["total"]), offset, limit, len(items), items)
        if folder_id in utility_ids or folder_id.startswith("place:") or folder_id.startswith("trip:") or folder_id.startswith("memory:") or folder_id.startswith("pet:") or folder_id.startswith("media:") or folder_id.startswith("import:") or folder_id.startswith("importSource:"):
            if resolved_trip is not None:
                base_entries = self._photo_entries_for_source_paths(resolved_trip.get("sourcePaths", []))
            elif resolved_memory is not None:
                base_entries = self._photo_entries_for_source_paths(resolved_memory.get("sourcePaths", []))
            elif folder_id in {"trips", "memories"}:
                cache = cached_generated_collections()
                collection_key = "trips" if folder_id == "trips" else "memories"
                source_paths: list[str] = []
                seen_sources: set[str] = set()
                for summary in cache.get(collection_key, []) if isinstance(cache.get(collection_key, []), list) else []:
                    for source_path in summary.get("sourcePaths", []) if isinstance(summary.get("sourcePaths", []), list) else []:
                        source = str(source_path or "")
                        if source and source not in seen_sources:
                            seen_sources.add(source)
                            source_paths.append(source)
                base_entries = self._photo_entries_for_source_paths(source_paths)
            else:
                base_entries = self._photo_asset_entries(
                    folder_id,
                    pet_review_kind=pet_review_kind_filter if folder_id == "petReview" else "",
                )
            filtered_entries = apply_filters(base_entries)
            if folder_id.startswith("memory:") and sort == "manual":
                memory = resolved_memory
                if memory and memory.get("userCreated"):
                    source_order = {
                        str(source_path or ""): index
                        for index, source_path in enumerate(memory.get("sourcePaths", []))
                        if str(source_path or "")
                    }
                    filtered_entries = sorted(
                        filtered_entries,
                        key=lambda entry: (
                            source_order.get(str(entry.get("sourcePath", "") or ""), 2_147_483_647),
                            str(entry.get("sourcePath", "") or "").casefold(),
                        ),
                    )
            matched = self._sort_photo_entries(
                filtered_entries,
                sort,
            )
            matched, burst_stack_by_source = collapse_burst_entries(matched)
            total = len(matched)
            rows = matched[offset:offset + limit]
            items = photo_items_for_rows(rows, burst_stack_by_source)
            return page_payload(total, offset, limit, len(items), items)

        if folder_id.startswith("albumFolder:"):
            album_folder_id = folder_id[len("albumFolder:"):]
            if not self.project.db.photo_album_folder_by_id(album_folder_id):
                raise ValueError("Unknown photo album folder id.")
            page_validation = self._photo_album_folder_validation(album_folder_id)
            sql_page = None if collapse_bursts else self._photo_album_folder_items_sql_page(
                album_folder_id,
                offset=offset,
                limit=limit,
                sort=sort,
                query=query,
                keyword=keyword,
                media_kind_filter=media_kind_filter,
                date_bucket_mode=date_bucket_mode,
                date_bucket_key=date_bucket_key,
                date_from_filter=date_from_filter,
                date_to_filter=date_to_filter,
                source_filter=source_filter,
                source_text_filters=library_root_source_filters,
                source_paths_filter=source_paths_filter,
                file_type_filter=file_type_filter,
                location_filter=location_filter,
                camera_filter=camera_filter,
                nearby_filter=nearby_filter,
                album_filter=album_filter,
                person_filter=person_filter,
                status_filter=status_filter,
                min_quality_filter=min_quality_filter,
                favorite_only=favorite_only,
                edited_only=edited_only,
                not_in_album_only=not_in_album_only,
                duplicate_only=duplicate_only,
                visibility_filter=visibility_filter,
                library_root=library_root_filter,
            )
            if sql_page is not None:
                page = sql_page["entries"]
                items = photo_items_for_rows(page)
                return page_payload(int(sql_page["total"]), offset, limit, len(items), items, validation=page_validation)
            matched = self._sort_photo_entries(
                apply_filters(self._photo_album_folder_collection_items(album_folder_id)),
                sort,
            )
            total = len(matched)
            page = matched[offset:offset + limit]
            items = photo_items_for_rows(page)
            return page_payload(total, offset, limit, len(page), items, validation=page_validation)

        if folder_id.startswith("album:"):
            album_id = folder_id[len("album:"):]
            album = self.project.db.photo_album_by_id(album_id)
            if not album:
                raise ValueError("Unknown photo album id.")
            scale_warning = self._photo_smart_album_scale_warning(album)
            page_validation = [scale_warning] if scale_warning else []
            sql_page = self._photo_smart_album_items_sql_page(
                album,
                offset=offset,
                limit=limit,
                sort=sort,
                query=query,
                keyword=keyword,
                media_kind_filter=media_kind_filter,
                date_bucket_mode=date_bucket_mode,
                date_bucket_key=date_bucket_key,
                date_from_filter=date_from_filter,
                date_to_filter=date_to_filter,
                source_filter=source_filter,
                source_text_filters=library_root_source_filters,
                source_paths_filter=source_paths_filter,
                file_type_filter=file_type_filter,
                location_filter=location_filter,
                camera_filter=camera_filter,
                nearby_filter=nearby_filter,
                album_filter=album_filter,
                person_filter=person_filter,
                status_filter=status_filter,
                min_quality_filter=min_quality_filter,
                favorite_only=favorite_only,
                edited_only=edited_only,
                not_in_album_only=not_in_album_only,
                duplicate_only=duplicate_only,
                visibility_filter=visibility_filter,
                library_root=library_root_filter,
            )
            if sql_page is not None:
                page = sql_page["entries"]
                prefetch_media_pairs(page)
                prefetch_edit_stack_version_counts(page)
                items: list[dict[str, Any]] = []
                remaining = preview_budget
                for row in page:
                    source_path = str(row.get("sourcePath", "") or "")
                    before = self.project.preview_path_for(source_path, create=False)
                    item = self._photo_item_row(
                        source_path=source_path,
                        media_kind=str(row.get("mediaKind", "image") or "image"),
                        preview_create=remaining > 0,
                        candidate=row.get("candidate"),
                        matches=row.get("matches", []),
                        scan_date=str(row.get("scanDate", "") or ""),
                        album_membership_cache=album_membership_cache,
                        media_pair_cache=media_pair_cache,
                        edit_stack_version_count_cache=edit_stack_version_count_cache,
                    )
                    if remaining > 0 and not before and item.get("previewPath"):
                        remaining -= 1
                    items.append(finalize_photo_item(item))
                return page_payload(int(sql_page["total"]), offset, limit, len(page), items, validation=page_validation)
            album_entries = self._photo_album_items(album)
            self._photo_save_smart_album_materialization(album, album_entries)
            matched = self._sort_photo_entries(
                apply_filters(album_entries),
                sort,
            )
            total = len(matched)
            page = matched[offset:offset + limit]
            prefetch_media_pairs(page)
            prefetch_edit_stack_version_counts(page)
            items: list[dict[str, Any]] = []
            remaining = preview_budget
            for row in page:
                source_path = str(row.get("sourcePath", "") or "")
                before = self.project.preview_path_for(source_path, create=False)
                item = self._photo_item_row(
                    source_path=source_path,
                    media_kind=str(row.get("mediaKind", "image") or "image"),
                    preview_create=remaining > 0,
                    candidate=row.get("candidate"),
                    matches=row.get("matches", []),
                    scan_date=str(row.get("scanDate", "") or ""),
                    album_membership_cache=album_membership_cache,
                    media_pair_cache=media_pair_cache,
                    edit_stack_version_count_cache=edit_stack_version_count_cache,
                )
                if remaining > 0 and not before and item.get("previewPath"):
                    remaining -= 1
                items.append(finalize_photo_item(item))
            return page_payload(total, offset, limit, len(page), items, validation=page_validation)

        if folder_id.startswith("person:"):
            name = folder_id[len("person:"):]
        elif folder_id.startswith("group:"):
            name = self._photo_people_group_name_from_id(folder_id)
        elif folder_id.startswith("unknown:"):
            name = folder_id[len("unknown:"):]
        else:
            raise ValueError("Unknown photo folder id.")

        group_entries = apply_filters(self._photo_entries_for_folder_id(folder_id))
        if folder_id.startswith("group:") and group_mode == "best":
            group_entries = self._photo_best_group_entries(group_entries)
        matched = self._sort_photo_entries(group_entries, sort)
        total = len(matched)
        page = matched[offset:offset + limit]
        prefetch_media_pairs(page)
        prefetch_edit_stack_version_counts(page)
        items = []
        remaining = preview_budget
        for row in page:
            source_path = str(row.get("sourcePath", "") or "")
            before = self.project.preview_path_for(source_path, create=False)
            item = self._photo_item_row(
                source_path=source_path,
                media_kind=str(row.get("mediaKind", "image") or "image"),
                preview_create=remaining > 0,
                candidate=row.get("candidate"),
                matches=row.get("matches", []),
                scan_date=str(row.get("scanDate", "") or ""),
                album_membership_cache=album_membership_cache,
                media_pair_cache=media_pair_cache,
                edit_stack_version_count_cache=edit_stack_version_count_cache,
            )
            if remaining > 0 and not before and item.get("previewPath"):
                remaining -= 1
            items.append(finalize_photo_item(item))
        return page_payload(total, offset, limit, len(page), items)

    def suggest_photo_albums(self, params: dict[str, Any]) -> dict[str, Any]:
        limit = max(1, min(24, int(params.get("limit", 12) or 12)))
        suggestions: list[dict[str, Any]] = []
        seen_names: set[str] = set()
        curation_preferences = self.project.db.photo_curation_preferences()
        feature_less_people = self._photo_curation_preference_keys(curation_preferences, "featureLessPeople")
        feature_less_content = self._photo_curation_preference_keys(curation_preferences, "featureLessContent")

        def suggestion_curation_penalty(
            *,
            name: str,
            description: str,
            include_people: list[str] | None,
            rules: dict[str, Any],
        ) -> int:
            penalty = 0
            if self._photo_curation_values_match([str(person) for person in include_people or []], feature_less_people):
                penalty += 8
            content_values = [name, description]
            content_values.extend(str(value) for value in rules.values() if isinstance(value, (str, int, float, bool)))
            if rules.get("hasVideoFrames"):
                content_values.append("video")
            if rules.get("unknownOnly"):
                content_values.append("unknown")
            if self._photo_curation_values_match(content_values, feature_less_content, contains=True):
                penalty += 2
            return penalty

        def suggestion_match_count(
            *,
            include_people: list[str] | None,
            exclude_people: list[str] | None,
            rules: dict[str, Any],
        ) -> int:
            clean_rules = self._clean_album_rules(rules)
            media_kind = str(clean_rules.get("mediaKind", "") or "").strip().lower()
            if media_kind and media_kind not in PHOTO_MEDIA_KINDS:
                return 0
            try:
                min_score = float(clean_rules.get("minScore", 0) or 0)
            except (TypeError, ValueError):
                min_score = 0.0
            recent_cutoff = ""
            if clean_rules.get("recentDays"):
                recent_cutoff = self._photo_smart_album_recent_cutoff(clean_rules.get("recentDays"))
                if not recent_cutoff:
                    return 0
            result = self.project.db.list_photo_asset_page(
                offset=0,
                limit=1,
                visibility="visible",
                media_kind=media_kind,
                edited_only=bool(clean_rules.get("editedOnly", False)),
                favorite_only=bool(clean_rules.get("favoriteOnly", False)),
                person_names=tuple(self._clean_album_people(include_people or [])),
                excluded_person_names=tuple(self._clean_album_people(exclude_people or [])),
                person_score_threshold=float(self.project.config.thresholds.confident),
                person_statuses=tuple(str(status or "").strip().lower() for status in clean_rules.get("statuses", []) or [] if str(status or "").strip()),
                person_score_filter=("atLeast", min_score) if min_score else None,
                unknown_person_state=True if clean_rules.get("unknownOnly") else None,
                has_video_frames_state=True if clean_rules.get("hasVideoFrames") else None,
                effective_time_from=recent_cutoff,
                date_from=str(clean_rules.get("dateFrom", "") or ""),
                date_to=str(clean_rules.get("dateTo", "") or ""),
                source=str(clean_rules.get("folder", "") or ""),
                keyword=str(clean_rules.get("keyword", "") or ""),
                query=str(clean_rules.get("query", "") or ""),
                sort="newest",
            )
            return int(result.get("total", 0) or 0)

        def add(
            *,
            name: str,
            description: str,
            include_people: list[str] | None = None,
            exclude_people: list[str] | None = None,
            rules: dict[str, Any] | None = None,
            reason: str = "",
        ) -> None:
            clean_rules = self._clean_album_rules(rules or {})
            count = suggestion_match_count(
                include_people=include_people or [],
                exclude_people=exclude_people or [],
                rules=clean_rules,
            )
            key = name.casefold()
            if count <= 0 or key in seen_names:
                return
            seen_names.add(key)
            position = len(suggestions)
            suggestions.append(
                {
                    "id": re.sub(r"[^a-z0-9]+", "-", key).strip("-") or f"suggestion-{len(suggestions) + 1}",
                    "name": name,
                    "description": description,
                    "includePeople": include_people or [],
                    "excludePeople": exclude_people or [],
                    "rules": clean_rules,
                    "ruleSummary": self._photo_album_rule_summary(clean_rules),
                    "matchCount": count,
                    "reason": reason,
                    "_curationPenalty": suggestion_curation_penalty(
                        name=name,
                        description=description,
                        include_people=include_people or [],
                        rules=clean_rules,
                    ),
                    "_position": position,
                }
            )

        confident = float(self.project.config.thresholds.confident)
        add(
            name="Videos with matches",
            description="Videos that produced at least one matched review frame.",
            rules={"mediaKind": "video", "hasVideoFrames": True},
            reason="Useful when reviewing extracted video moments.",
        )
        add(
            name="High-confidence photos",
            description="Photos with at least one strong match.",
            rules={"minScore": confident},
            reason="Good candidates for quick organization.",
        )
        add(
            name="Needs review",
            description="Photos with pending or uncertain matches.",
            rules={"statuses": ["pending", "uncertain"]},
            reason="Keeps undecided review work visible from Photos.",
        )
        add(
            name="Unknown clusters",
            description="Photos grouped as unknown people.",
            rules={"unknownOnly": True},
            reason="Helps find people who may need new labels.",
        )
        add(
            name="Recently scanned",
            description="Media scanned or captured in the last 30 days.",
            rules={"recentDays": 30},
            reason="A lightweight inbox for new imports.",
        )

        source_people: dict[str, set[str]] = {}
        for source, matches in self._photo_matches_by_source().items():
            for candidate in matches:
                if self._photo_person_match(candidate) and not candidate.person_name.startswith("Unmatched cluster"):
                    source_people.setdefault(source, set()).add(candidate.person_name)
        people = sorted({person for values in source_people.values() for person in values}, key=str.casefold)
        for person in people:
            if len(suggestions) >= limit:
                break
            co_people = sorted(
                {
                    other
                    for values in source_people.values()
                    if person in values
                    for other in values
                    if other != person
                },
                key=str.casefold,
            )
            for other in co_people[:2]:
                add(
                    name=f"{person} without {other}",
                    description=f"Photos that include {person} and exclude {other}.",
                    include_people=[person],
                    exclude_people=[other],
                    reason="Suggested from people who often appear in the same library.",
                )
                if len(suggestions) >= limit:
                    break

        ranked = sorted(
            suggestions,
            key=lambda item: (int(item.get("_curationPenalty", 0) or 0), int(item.get("_position", 0) or 0)),
        )
        cleaned = [
            {key: value for key, value in suggestion.items() if not key.startswith("_")}
            for suggestion in ranked
        ]
        return {"suggestions": cleaned[:limit], "total": len(cleaned)}

    def _safe_photo_export_name(self, value: str) -> str:
        cleaned = "".join(character if character.isalnum() or character in {"-", "_", ".", " "} else "_" for character in value.strip())
        cleaned = "-".join(cleaned.split())
        return cleaned[:120] or "item"

    def _photo_export_template_date_parts(self, value: str) -> dict[str, str]:
        text = str(value or "").strip()
        match = re.search(r"(\d{4})-(\d{2})-(\d{2})", text)
        if not match:
            return {"date": text, "year": "", "month": "", "day": ""}
        year, month, day = match.groups()
        return {"date": f"{year}-{month}-{day}", "year": year, "month": month, "day": day}

    def _photo_export_template_context(
        self,
        resolved: Path,
        index: int,
        payload: dict[str, Any],
    ) -> dict[str, str]:
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        people_rows = payload.get("people") if isinstance(payload.get("people"), list) else []
        album_rows = payload.get("albums") if isinstance(payload.get("albums"), list) else []
        people = [
            str(person.get("personName", "") or "").strip()
            for person in people_rows
            if isinstance(person, dict) and str(person.get("personName", "") or "").strip()
        ]
        albums = [
            str(album.get("name", "") or "").strip()
            for album in album_rows
            if isinstance(album, dict) and str(album.get("name", "") or "").strip()
        ]
        try:
            modified_date = datetime.utcfromtimestamp(resolved.stat().st_mtime).strftime("%Y-%m-%d")
        except OSError:
            modified_date = datetime.utcnow().strftime("%Y-%m-%d")
        date_parts = self._photo_export_template_date_parts(
            str(metadata.get("dateOverride", "") or payload.get("captureDate", "") or payload.get("addedAt", "") or modified_date)
        )
        original = resolved.stem or "photo"
        title = str(metadata.get("title", "") or "").strip() or original
        media_kind = str(payload.get("mediaKind", "") or "").strip() or resolved.suffix.lstrip(".") or "media"
        album = albums[0] if albums else "No Album"
        person = people[0] if people else "No People"
        return {
            "sequence": f"{index:05d}",
            "index": str(index),
            "original": original,
            "filename": original,
            "title": title,
            "album": album,
            "albums": " ".join(albums) if albums else album,
            "person": person,
            "people": " ".join(people) if people else person,
            "kind": media_kind,
            "mediaKind": media_kind,
            "sourceFolder": resolved.parent.name or "Source",
            **date_parts,
        }

    def _photo_export_render_template_name(self, template: str, context: dict[str, str], fallback: str) -> str:
        raw_template = str(template or "").strip()
        if not raw_template:
            return self._safe_photo_export_name(fallback)

        def replace_token(match: re.Match[str]) -> str:
            return context.get(match.group(1), "")

        rendered = re.sub(r"\{([A-Za-z][A-Za-z0-9_]*)\}", replace_token, raw_template)
        return self._safe_photo_export_name(rendered or fallback)

    def _photo_export_template_folder(self, media_root: Path, template: str, context: dict[str, str]) -> Path:
        raw_template = str(template or "").strip()
        if not raw_template:
            return media_root

        def replace_token(match: re.Match[str]) -> str:
            return context.get(match.group(1), "")

        rendered = re.sub(r"\{([A-Za-z][A-Za-z0-9_]*)\}", replace_token, raw_template)
        parts = [
            self._safe_photo_export_name(part)
            for part in re.split(r"[\\/]+", rendered)
            if str(part or "").strip() and str(part or "").strip() not in {".", ".."}
        ][:6]
        target_root = media_root
        for part in parts:
            target_root = target_root / part
        target_root.mkdir(parents=True, exist_ok=True)
        return target_root

    def _photo_export_strip_known_suffix(self, value: str) -> str:
        text = self._safe_photo_export_name(value)
        suffix = Path(text).suffix.lower()
        known_suffixes = set(IMAGE_EXTENSIONS) | set(VIDEO_EXTENSIONS) | {".jpg", ".jpeg", ".png", ".tif", ".tiff"}
        if suffix in known_suffixes:
            return text[: -len(suffix)].rstrip(".-_ ") or "item"
        return text

    def _photo_export_render_settings(self, params: dict[str, Any]) -> tuple[str, int, int, str]:
        render_format = str(params.get("renderFormat", params.get("format", "jpeg")) or "jpeg").strip().lower()
        aliases = {"jpg": "jpeg", "tif": "tiff", "heif": "heic", "hif": "heic"}
        render_format = aliases.get(render_format, render_format)
        if render_format not in {"jpeg", "png", "tiff", "heic"}:
            raise ValueError("Photo rendered export format must be jpeg, png, tiff, or heic.")
        try:
            render_quality = max(1, min(100, int(params.get("renderQuality", params.get("quality", 92)) or 92)))
        except (TypeError, ValueError):
            render_quality = 92
        try:
            render_max_dimension = max(0, min(20000, int(params.get("renderMaxDimension", params.get("maxDimension", 0)) or 0)))
        except (TypeError, ValueError):
            render_max_dimension = 0
        render_suffix = { "jpeg": ".jpg", "png": ".png", "tiff": ".tiff", "heic": ".heic" }[render_format]
        return render_format, render_quality, render_max_dimension, render_suffix

    def _photo_export_video_settings(self, params: dict[str, Any]) -> tuple[str, str, str]:
        video_format = str(params.get("videoRenderFormat", params.get("renderVideoFormat", "mp4")) or "mp4").strip().lower()
        aliases = {
            "h264": "mp4",
            "mpeg4": "mp4",
            "quicktime": "mov",
            "qt": "mov",
            "apple": "mov",
            "vp9": "webm",
            "web": "webm",
            "h265": "hevc",
            "h.265": "hevc",
            "x265": "hevc",
            "prores422": "prores",
            "prores_ks": "prores",
        }
        video_format = aliases.get(video_format, video_format)
        if video_format not in {"mp4", "mov", "m4v", "webm", "hevc", "prores"}:
            raise ValueError("Photo rendered video export format must be mp4, mov, m4v, webm, hevc, or prores.")
        quality = str(
            params.get(
                "videoRenderQuality",
                params.get("renderVideoQuality", params.get("videoQuality", "medium")),
            )
            or "medium"
        ).strip().lower()
        quality_aliases = {
            "low": "small",
            "small": "small",
            "compact": "small",
            "medium": "medium",
            "standard": "medium",
            "balanced": "medium",
            "high": "high",
            "best": "high",
            "large": "high",
        }
        quality = quality_aliases.get(quality, "medium")
        suffix = {
            "mp4": ".mp4",
            "mov": ".mov",
            "m4v": ".m4v",
            "webm": ".webm",
            "hevc": ".mp4",
            "prores": ".mov",
        }[video_format]
        return video_format, quality, suffix

    def _photo_export_video_codec_args(self, video_format: str, quality: str) -> tuple[list[str], list[str], bool]:
        quality_map = {
            "small": {
                "h264_crf": "28",
                "hevc_crf": "30",
                "vp9_crf": "32",
                "preset": "fast",
                "audio_bitrate": "96k",
                "vp9_cpu_used": "4",
                "prores_profile": "0",
            },
            "medium": {
                "h264_crf": "23",
                "hevc_crf": "25",
                "vp9_crf": "28",
                "preset": "medium",
                "audio_bitrate": "128k",
                "vp9_cpu_used": "3",
                "prores_profile": "2",
            },
            "high": {
                "h264_crf": "18",
                "hevc_crf": "20",
                "vp9_crf": "24",
                "preset": "slow",
                "audio_bitrate": "192k",
                "vp9_cpu_used": "2",
                "prores_profile": "3",
            },
        }
        settings = quality_map.get(quality, quality_map["medium"])
        if video_format == "webm":
            return (
                [
                    "-c:v",
                    "libvpx-vp9",
                    "-deadline",
                    "good",
                    "-cpu-used",
                    settings["vp9_cpu_used"],
                    "-crf",
                    settings["vp9_crf"],
                    "-b:v",
                    "0",
                    "-pix_fmt",
                    "yuv420p",
                ],
                ["-c:a", "libopus", "-b:a", settings["audio_bitrate"]],
                False,
            )
        if video_format == "hevc":
            return (
                [
                    "-c:v",
                    "libx265",
                    "-preset",
                    settings["preset"],
                    "-crf",
                    settings["hevc_crf"],
                    "-pix_fmt",
                    "yuv420p",
                    "-tag:v",
                    "hvc1",
                ],
                ["-c:a", "aac", "-b:a", settings["audio_bitrate"]],
                True,
            )
        if video_format == "prores":
            return (
                [
                    "-c:v",
                    "prores_ks",
                    "-profile:v",
                    settings["prores_profile"],
                    "-pix_fmt",
                    "yuv422p10le",
                ],
                ["-c:a", "pcm_s16le"],
                True,
            )
        return (
            [
                "-c:v",
                "libx264",
                "-preset",
                settings["preset"],
                "-crf",
                settings["h264_crf"],
                "-pix_fmt",
                "yuv420p",
            ],
            ["-c:a", "aac", "-b:a", settings["audio_bitrate"]],
            True,
        )

    def _photo_export_video_transform_settings(self, params: dict[str, Any]) -> tuple[int, str]:
        rotate_value = params.get(
            "videoRotateDegrees",
            params.get("rotateDegrees", params.get("rotationDegrees", 0)),
        )
        rotate_aliases = {
            "left": 270,
            "counterclockwise": 270,
            "ccw": 270,
            "right": 90,
            "clockwise": 90,
            "cw": 90,
            "half": 180,
            "upside_down": 180,
            "upside-down": 180,
            "none": 0,
            "original": 0,
        }
        rotate_key = str(rotate_value or 0).strip().lower()
        if rotate_key in rotate_aliases:
            rotate_degrees = rotate_aliases[rotate_key]
        else:
            try:
                rotate_degrees = int(float(rotate_key or "0"))
            except (TypeError, ValueError) as exc:
                raise ValueError("Video rotation must be 0, 90, 180, or 270 degrees.") from exc
        rotate_degrees = rotate_degrees % 360
        if rotate_degrees not in {0, 90, 180, 270}:
            raise ValueError("Video rotation must be 0, 90, 180, or 270 degrees.")

        crop_value = str(
            params.get("videoCropAspect", params.get("cropAspect", params.get("cropMode", "none"))) or "none"
        ).strip().lower()
        crop_aliases = {
            "": "none",
            "none": "none",
            "original": "none",
            "source": "none",
            "square": "square",
            "1:1": "square",
            "landscape": "landscape",
            "wide": "landscape",
            "16:9": "landscape",
            "widescreen": "landscape",
            "portrait": "portrait",
            "vertical": "portrait",
            "4:5": "portrait",
        }
        crop_aspect = crop_aliases.get(crop_value)
        if crop_aspect is None:
            raise ValueError("Video crop aspect must be none, square, landscape, or portrait.")
        return rotate_degrees, crop_aspect

    def _photo_export_video_ms_label(self, value: Any) -> str:
        try:
            ms = max(0, int(float(value or 0)))
        except (TypeError, ValueError):
            ms = 0
        if ms <= 0:
            return ""
        seconds = round(ms / 1000)
        minutes, rest = divmod(seconds, 60)
        return f"{minutes}:{rest:02d}" if minutes else f"{rest}s"

    def _photo_export_video_crop_label(self, crop_aspect: str) -> str:
        return {
            "square": "1:1",
            "landscape": "16:9",
            "portrait": "4:5",
        }.get(str(crop_aspect or "none").strip().lower(), "Original")

    def _photo_export_video_edit_stack_settings(self, edit_operations: list[Any]) -> dict[str, Any]:
        settings: dict[str, Any] = {
            "applied": False,
            "startMs": 0,
            "endMs": 0,
            "trimDurationMs": 0,
            "sourceDurationMs": 0,
            "rotateDegrees": 0,
            "cropAspect": "none",
            "transformApplied": False,
            "timelineLabel": "",
            "transformLabel": "",
            "renderLabel": "",
            "summaryLabel": "",
        }
        for operation in edit_operations:
            if not isinstance(operation, dict):
                continue
            kind = str(operation.get("kind", "") or "").strip().lower().replace("-", "_")
            if kind not in {"video_trim_transform", "video_trim", "video_transform"}:
                continue
            try:
                start_ms = max(0, int(float(operation.get("startMs", operation.get("trimStartMs", 0)) or 0)))
            except (TypeError, ValueError):
                start_ms = 0
            try:
                end_ms = max(0, int(float(operation.get("endMs", operation.get("trimEndMs", 0)) or 0)))
            except (TypeError, ValueError):
                end_ms = 0
            if end_ms > 0 and end_ms <= start_ms:
                end_ms = 0
            try:
                source_duration_ms = max(0, int(float(operation.get("sourceDurationMs", operation.get("durationMs", 0)) or 0)))
            except (TypeError, ValueError):
                source_duration_ms = 0
            rotate_degrees, crop_aspect = self._photo_export_video_transform_settings(operation)
            transform_applied = rotate_degrees != 0 or crop_aspect != "none"
            trim_applied = start_ms > 0 or end_ms > 0
            trim_duration_ms = max(0, end_ms - start_ms) if end_ms > start_ms else 0
            start_label = self._photo_export_video_ms_label(start_ms) or "0s"
            end_label = self._photo_export_video_ms_label(end_ms)
            trim_duration_label = self._photo_export_video_ms_label(trim_duration_ms)
            source_duration_label = self._photo_export_video_ms_label(source_duration_ms)
            timeline_label = ""
            if trim_applied:
                trim_window_label = f"Trim {start_label}-{end_label}" if end_label else f"Trim from {start_label}"
                trim_span_label = (
                    f"{trim_duration_label} of {source_duration_label}"
                    if trim_duration_label and source_duration_label
                    else trim_duration_label
                )
                timeline_label = f"{trim_window_label} ({trim_span_label})" if trim_span_label else trim_window_label
            elif source_duration_label:
                timeline_label = f"Source {source_duration_label}"
            crop_label = self._photo_export_video_crop_label(crop_aspect)
            transform_label = f"R{rotate_degrees} / {crop_label}" if transform_applied else ""
            render_format = str(
                operation.get("videoRenderFormat", operation.get("renderVideoFormat", operation.get("renderFormat", ""))) or ""
            ).strip().upper()
            render_quality = str(
                operation.get("videoRenderQuality", operation.get("renderVideoQuality", operation.get("videoQuality", ""))) or ""
            ).strip().lower()
            try:
                render_max_dimension = max(0, int(float(operation.get("renderMaxDimension", operation.get("maxDimension", 0)) or 0)))
            except (TypeError, ValueError):
                render_max_dimension = 0
            render_label = " ".join(
                part
                for part in [
                    render_format,
                    render_quality,
                    f"max {render_max_dimension}px" if render_max_dimension else "",
                ]
                if part
            )
            summary_label = " / ".join(part for part in [timeline_label, transform_label, render_label] if part)
            settings = {
                "applied": trim_applied or transform_applied,
                "startMs": start_ms,
                "endMs": end_ms,
                "trimDurationMs": trim_duration_ms,
                "sourceDurationMs": source_duration_ms,
                "rotateDegrees": rotate_degrees,
                "cropAspect": crop_aspect,
                "transformApplied": transform_applied,
                "timelineLabel": timeline_label,
                "transformLabel": transform_label,
                "renderLabel": render_label,
                "summaryLabel": summary_label,
            }
        return settings

    def _photo_export_ffmpeg_path(self) -> str:
        candidates = [
            str(getattr(self.project.config, "ffmpeg_path", "") or ""),
            os.environ.get("VINTRACE_FFMPEG_PATH", ""),
            os.environ.get("CROSSAGE_FFMPEG_PATH", ""),
            shutil.which("ffmpeg") or "",
        ]
        for candidate in candidates:
            if not candidate:
                continue
            try:
                path = Path(candidate).expanduser()
                if path.is_file():
                    return str(path)
            except (OSError, RuntimeError):
                continue
        return ""

    def _photo_export_render_video(
        self,
        source: Path,
        target: Path,
        *,
        video_format: str,
        quality: str,
        max_dimension: int,
        trim_start_ms: int = 0,
        trim_end_ms: int = 0,
        video_rotate_degrees: int = 0,
        video_crop_aspect: str = "none",
        strip_metadata: bool = False,
    ) -> None:
        if video_format not in {"mp4", "mov", "m4v", "webm", "hevc", "prores"}:
            raise VideoLoadError("Photo rendered video export format must be mp4, mov, m4v, webm, hevc, or prores.")
        ffmpeg = self._photo_export_ffmpeg_path()
        if not ffmpeg:
            raise VideoLoadError("Rendered video export requires FFmpeg.")
        video_codec_args, audio_codec_args, use_faststart = self._photo_export_video_codec_args(video_format, quality)
        target.parent.mkdir(parents=True, exist_ok=True)
        trim_start_ms = max(0, int(trim_start_ms or 0))
        trim_end_ms = max(0, int(trim_end_ms or 0))
        trim_duration_ms = max(0, trim_end_ms - trim_start_ms) if trim_end_ms else 0
        video_rotate_degrees = int(video_rotate_degrees or 0) % 360
        if video_rotate_degrees not in {0, 90, 180, 270}:
            raise VideoLoadError("Video rotation must be 0, 90, 180, or 270 degrees.")
        video_crop_aspect = str(video_crop_aspect or "none").strip().lower()
        if video_crop_aspect not in {"none", "square", "landscape", "portrait"}:
            raise VideoLoadError("Video crop aspect must be none, square, landscape, or portrait.")
        command = [
            ffmpeg,
            "-hide_banner",
            "-loglevel",
            "error",
        ]
        if trim_start_ms > 0:
            command.extend(["-ss", f"{trim_start_ms / 1000:.3f}"])
        command.extend([
            "-i",
            str(source),
            "-map",
            "0:v:0",
            "-map",
            "0:a?",
            "-sn",
        ])
        if strip_metadata:
            command.extend(["-map_metadata", "-1", "-map_chapters", "-1", "-dn"])
        command.extend(video_codec_args)
        command.extend(audio_codec_args)
        if use_faststart:
            command.extend(["-movflags", "+faststart"])
        if trim_duration_ms > 0:
            command.extend(["-t", f"{trim_duration_ms / 1000:.3f}", "-avoid_negative_ts", "make_zero"])
        filters: list[str] = []
        if video_rotate_degrees == 90:
            filters.append("transpose=1")
        elif video_rotate_degrees == 180:
            filters.extend(["transpose=1", "transpose=1"])
        elif video_rotate_degrees == 270:
            filters.append("transpose=2")

        width = height = 0
        if max_dimension > 0 or video_crop_aspect != "none":
            try:
                probe = probe_video(source)
            except Exception:
                probe = {}
            try:
                width = int(probe.get("width", 0) or 0) if isinstance(probe, dict) else 0
                height = int(probe.get("height", 0) or 0) if isinstance(probe, dict) else 0
            except (TypeError, ValueError):
                width = height = 0
        if video_rotate_degrees in {90, 270}:
            width, height = height, width

        def even(value: float) -> int:
            return max(2, int(value) - (int(value) % 2))

        working_width = even(width) if width > 0 else 0
        working_height = even(height) if height > 0 else 0
        if video_crop_aspect != "none" and working_width > 0 and working_height > 0:
            aspect_ratios = {
                "square": 1.0,
                "landscape": 16 / 9,
                "portrait": 4 / 5,
            }
            target_ratio = aspect_ratios[video_crop_aspect]
            current_ratio = working_width / working_height
            crop_width = working_width
            crop_height = working_height
            if current_ratio > target_ratio:
                crop_width = even(working_height * target_ratio)
            elif current_ratio < target_ratio:
                crop_height = even(working_width / target_ratio)
            crop_width = min(working_width, max(2, crop_width))
            crop_height = min(working_height, max(2, crop_height))
            if crop_width < working_width or crop_height < working_height:
                filters.append(f"crop={crop_width}:{crop_height}:(in_w-{crop_width})/2:(in_h-{crop_height})/2")
                working_width, working_height = crop_width, crop_height

        if max_dimension > 0 and working_width > 0 and working_height > 0 and max(working_width, working_height) > max_dimension:
            if working_width >= working_height:
                filters.append(f"scale={even(max_dimension)}:-2")
            else:
                filters.append(f"scale=-2:{even(max_dimension)}")
        if filters:
            command.extend(["-vf", ",".join(filters)])
        command.extend(["-y", str(target)])
        completed = subprocess.run(command, capture_output=True, text=True, timeout=120, check=False)
        if completed.returncode != 0 or not target.exists():
            try:
                target.unlink(missing_ok=True)
            except OSError:
                pass
            raise VideoLoadError((completed.stderr or completed.stdout or f"Could not transcode video {source}").strip()[:400])

    def _photo_export_render_slideshow_video(
        self,
        rows: list[dict[str, Any]],
        target: Path,
        *,
        video_format: str,
        quality: str,
        max_dimension: int,
        fit_mode: str,
        music: str = "none",
        audio_path: str = "",
        audio_volume: float = 1.0,
        audio_fade_ms: int = 0,
        audio_start_ms: int = 0,
        audio_end_ms: int = 0,
        audio_placement_start_ms: int = 0,
        audio_placement_end_ms: int = 0,
        transition_effect: str = "auto",
        transition_duration_ms: int = 650,
        transition_applied: bool = False,
        theme_template_layout: str = "auto",
        theme_template_stage_width: int = 100,
        theme_template_frame_style: str = "auto",
        theme_template_chrome_density: str = "auto",
        theme_template_caption_preset: str = "auto",
        theme_template_region_map: dict[str, Any] | None = None,
        title: str = "",
        source_label: str = "",
    ) -> dict[str, Any]:
        if video_format not in {"mp4", "mov", "m4v", "webm", "hevc", "prores"}:
            raise VideoLoadError("Photo slideshow movie format must be mp4, mov, m4v, webm, hevc, or prores.")
        ffmpeg = self._photo_export_ffmpeg_path()
        if not ffmpeg:
            raise VideoLoadError("Slideshow movie export requires FFmpeg.")
        video_codec_args, audio_codec_args, use_faststart = self._photo_export_video_codec_args(video_format, quality)

        def even(value: float) -> int:
            return max(2, int(value) - (int(value) % 2))

        def even_offset(value: float) -> int:
            parsed = int(value)
            return max(0, parsed - (parsed % 2))

        width = 1920
        height = 1080
        max_dimension = max(0, int(max_dimension or 0))
        if max_dimension > 0 and max(width, height) > max_dimension:
            ratio = max_dimension / max(width, height)
            width = even(width * ratio)
            height = even(height * ratio)
        template_frame_style = str(theme_template_frame_style or "auto").strip().lower().replace("_", "-")
        if template_frame_style not in {"auto", "none", "hairline", "matte", "accent"}:
            template_frame_style = "auto"
        frame_border_px = 0
        frame_color = ""
        if template_frame_style == "hairline":
            frame_border_px = even(max(2, min(width, height) * 0.006))
            frame_color = "white@0.68"
        elif template_frame_style == "matte":
            frame_border_px = even(max(8, min(width, height) * 0.04))
            frame_color = "0x181820"
        elif template_frame_style == "accent":
            frame_border_px = even(max(4, min(width, height) * 0.012))
            frame_color = "0x76b9ff"
        if frame_border_px > 0:
            max_border_px = even(max(2, min(width, height) / 4))
            frame_border_px = min(frame_border_px, max_border_px)
        stage_width = even(width - (frame_border_px * 2)) if frame_border_px > 0 else width
        stage_height = even(height - (frame_border_px * 2)) if frame_border_px > 0 else height
        try:
            template_stage_width = max(50, min(100, int(round(float(theme_template_stage_width or 100)))))
        except (TypeError, ValueError):
            template_stage_width = 100
        template_stage_frame_width = stage_width if template_stage_width >= 100 else even(stage_width * (template_stage_width / 100.0))
        template_stage_frame_width = min(stage_width, max(2, template_stage_frame_width))
        template_stage_frame_height = stage_height
        template_stage_frame_x = even_offset(max(0, (stage_width - template_stage_frame_width) / 2))
        template_stage_frame_y = 0
        template_stage_frame = {
            "x": template_stage_frame_x,
            "y": template_stage_frame_y,
            "width": template_stage_frame_width,
            "height": template_stage_frame_height,
        }
        layout_stage_width = template_stage_frame_width
        layout_stage_height = template_stage_frame_height
        template_chrome_density = str(theme_template_chrome_density or "auto").strip().lower().replace("_", "-")
        if template_chrome_density not in {"auto", "compact", "regular", "spacious"}:
            template_chrome_density = "auto"
        template_layout = str(theme_template_layout or "auto").strip().lower().replace("_", "-")
        if template_layout not in {"auto", "standard", "gallery", "cinema", "minimal", "poster", "split", "immersive"}:
            template_layout = "auto"
        template_caption_preset = str(theme_template_caption_preset or "auto").strip().lower().replace("_", "-")
        if template_caption_preset in {"lower", "lowerthird", "caption-bar"}:
            template_caption_preset = "lower-third"
        elif template_caption_preset in {"title", "title-sub", "headline-subtitle"}:
            template_caption_preset = "title-subtitle"
        elif template_caption_preset in {"split", "story-split", "split-notes"}:
            template_caption_preset = "split-story"
        elif template_caption_preset in {"gallery", "gallery-tags", "labels"}:
            template_caption_preset = "gallery-labels"
        elif template_caption_preset in {"cinema", "letterbox", "letterbox-bars"}:
            template_caption_preset = "cinema-bars"
        if template_caption_preset not in {"auto", "lower-third", "title-subtitle", "split-story", "gallery-labels", "cinema-bars"}:
            template_caption_preset = "auto"
        resolved_caption_preset = self._photo_slideshow_resolved_caption_preset(template_caption_preset, template_layout)
        template_region_map = self._photo_slideshow_clean_template_region_map(theme_template_region_map or {})
        template_caption_resolved_region_map = self._photo_slideshow_resolved_region_map(
            template_caption_preset,
            template_layout,
            template_region_map,
        )
        chrome_bar_px = 0
        chrome_color = "black@0.48"
        if template_chrome_density != "auto":
            density_scale = {
                "compact": 0.045,
                "regular": 0.065,
                "spacious": 0.09,
            }[template_chrome_density]
            density_min_px = {
                "compact": 18,
                "regular": 28,
                "spacious": 40,
            }[template_chrome_density]
            chrome_bar_px = even(max(density_min_px, stage_height * density_scale))
            chrome_bar_px = min(chrome_bar_px, even(max(2, stage_height / 3)))
        if template_layout == "cinema" and chrome_bar_px <= 0:
            chrome_bar_px = even(max(26, stage_height * 0.10))
            chrome_bar_px = min(chrome_bar_px, even(max(2, stage_height / 3)))
            chrome_color = "black@0.62"

        layout_background_color = "0x05070d"
        layout_media_x = template_stage_frame_x
        layout_media_y = template_stage_frame_y
        layout_media_width = layout_stage_width
        layout_media_height = layout_stage_height
        layout_chrome_style = "standard"
        layout_chrome_rendered = template_layout in {"poster", "split", "gallery", "cinema", "immersive"}
        if template_layout == "poster":
            layout_chrome_style = "poster-stage"
            layout_margin_y = even(max(chrome_bar_px + 8 if chrome_bar_px > 0 else 0, layout_stage_height * 0.08))
            layout_media_height = even(max(2, layout_stage_height - layout_margin_y * 2))
            layout_media_width = even(max(2, min(layout_stage_width * 0.78, layout_media_height * 16 / 9)))
            layout_media_x = template_stage_frame_x + even_offset(max(0, (layout_stage_width - layout_media_width) / 2))
            layout_media_y = template_stage_frame_y + even_offset(max(0, (layout_stage_height - layout_media_height) / 2))
            layout_background_color = "0x111018"
        elif template_layout == "gallery":
            layout_chrome_style = "gallery-matte"
            layout_margin = even(max(12, min(layout_stage_width, layout_stage_height) * 0.055))
            layout_media_width = even(max(2, layout_stage_width - layout_margin * 2))
            layout_media_height = even(max(2, layout_stage_height - layout_margin * 2))
            layout_media_x = template_stage_frame_x + layout_margin
            layout_media_y = template_stage_frame_y + layout_margin
            layout_background_color = "0x10131a"
        elif template_layout == "split":
            layout_chrome_style = "split-rail"
            rail_width = even(max(2, min(layout_stage_width * 0.32, layout_stage_width - 2)))
            layout_media_x = template_stage_frame_x + rail_width
            layout_media_width = even(max(2, layout_stage_width - rail_width))
            layout_media_height = layout_stage_height
            layout_background_color = "0x080a0f"
        elif template_layout == "immersive":
            layout_chrome_style = "immersive-gradient"
            layout_background_color = "0x020409"
        elif template_layout == "cinema":
            layout_chrome_style = "cinema-letterbox"
            layout_background_color = "0x000000"
        layout_media_frame = {
            "x": layout_media_x,
            "y": layout_media_y,
            "width": layout_media_width,
            "height": layout_media_height,
        }
        layout_media_is_full_stage = (
            layout_media_x == 0
            and layout_media_y == 0
            and layout_media_width == stage_width
            and layout_media_height == stage_height
        )
        render_title = self._photo_export_clean_text(title, limit=90)
        render_source_label = self._photo_export_clean_text(source_label, limit=80)

        video_rows = [
            row
            for row in rows
            if row.get("result") in {"included", "title_card"} and str(row.get("targetPath", "") or "").strip()
        ]
        if not video_rows:
            raise VideoLoadError("Slideshow movie export requires at least one included slide.")
        title_card_included = any(row.get("result") == "title_card" for row in video_rows)
        motion_presets: list[str] = []
        resolved_motion_presets: list[str] = []
        for row in video_rows:
            motion = str(row.get("motion", "auto") or "auto").strip().lower().replace("_", "-")
            if motion not in {"auto", "still", "slow-zoom", "pan-left", "pan-right"}:
                motion = "auto"
            row["motion"] = motion
            if motion not in motion_presets:
                motion_presets.append(motion)
            resolved_motion = (
                "custom"
                if isinstance(row.get("keyframes"), dict)
                else str(row.get("resolvedMotion", motion) or motion).strip().lower().replace("_", "-")
            )
            if resolved_motion not in {"still", "slow-zoom", "pan-left", "pan-right", "custom"}:
                resolved_motion = "still" if motion == "auto" else motion
            row["resolvedMotion"] = resolved_motion
            if resolved_motion not in resolved_motion_presets:
                resolved_motion_presets.append(resolved_motion)

        row_durations_ms: list[int] = []
        total_duration_ms = 0
        for row in video_rows:
            try:
                duration_ms = max(500, int(row.get("durationMs", 0) or 0))
            except (TypeError, ValueError):
                duration_ms = 4500
            row_durations_ms.append(duration_ms)
            total_duration_ms += duration_ms

        transition_effect = str(transition_effect or "auto").strip().lower().replace("_", "-")
        if transition_effect not in {"auto", "cut", "fade", "dissolve", "zoom"}:
            transition_effect = "auto"
        try:
            transition_duration_ms = max(0, min(3000, int(transition_duration_ms or 0)))
        except (TypeError, ValueError):
            transition_duration_ms = 650
        if transition_effect == "cut":
            transition_duration_ms = 0

        def clean_render_transition_effect(value: Any) -> str:
            effect = str(value or "").strip().lower().replace("_", "-")
            return effect if effect in {"auto", "cut", "fade", "dissolve", "zoom"} else transition_effect

        def ffmpeg_transition_name(effect: str) -> str:
            return {
                "auto": "fade",
                "fade": "fade",
                "dissolve": "dissolve",
                "zoom": "zoomin",
            }.get(effect, "fade")

        row_transition_effects: list[str] = []
        row_transition_durations_ms: list[int] = []
        transition_timeline: list[dict[str, Any]] = []
        for index, row in enumerate(video_rows):
            row_transition = clean_render_transition_effect(row.get("transitionOut", row.get("transitionEffect", transition_effect)))
            if index >= len(video_rows) - 1:
                row_transition = "cut"
            try:
                row_transition_duration_ms = max(
                    0,
                    min(
                        3000,
                        int(row.get("transitionDurationMs", transition_duration_ms) if row.get("transitionDurationMs") is not None else transition_duration_ms),
                    ),
                )
            except (TypeError, ValueError):
                row_transition_duration_ms = transition_duration_ms
            if row_transition == "cut":
                row_transition_duration_ms = 0
            row_transition_effects.append(row_transition)
            row_transition_durations_ms.append(row_transition_duration_ms)
            transition_timeline.append({
                "index": index,
                "transitionOut": row_transition,
                "transitionDurationMs": row_transition_duration_ms,
                "transitionFfmpegEffect": ffmpeg_transition_name(row_transition) if row_transition_duration_ms > 0 and row_transition != "cut" else "",
            })
        applied_transition_effects = [
            item["transitionFfmpegEffect"]
            for item in transition_timeline[:-1]
            if item.get("transitionFfmpegEffect")
        ]
        ffmpeg_transition = applied_transition_effects[0] if applied_transition_effects else {
            "auto": "fade",
            "fade": "fade",
            "dissolve": "dissolve",
            "zoom": "zoomin",
        }.get(transition_effect, "fade")
        transition_applied = bool(applied_transition_effects and len(video_rows) > 1)

        chrome_temp_dir: tempfile.TemporaryDirectory[str] | None = None
        chrome_overlay_paths: list[Path] = []
        chrome_overlay_rows: list[dict[str, Any]] = []

        def row_caption_placement(row: dict[str, Any]) -> str:
            placement = str(row.get("captionPlacement", "") or "").strip().lower().replace("_", "-")
            return placement if placement in {"hidden", "lower-left", "lower-center", "lower-right", "upper-left", "upper-center", "upper-right", "center"} else "auto"

        def row_caption_text(row: dict[str, Any], *, fallback_label: bool = False) -> str:
            text = self._photo_export_clean_text(row.get("captionText", ""), limit=180)
            if text or not fallback_label:
                return text
            return self._photo_export_clean_text(row.get("label", ""), limit=180)

        def row_caption_region(row: dict[str, Any]) -> dict[str, float] | None:
            region = row.get("captionRegion")
            if not isinstance(region, dict):
                return None
            try:
                x = max(0.0, min(100.0, float(region.get("x", 6))))
                y = max(0.0, min(100.0, float(region.get("y", 72))))
                width = max(1.0, min(float(region.get("width", 42)), 100.0 - x))
                height = max(1.0, min(float(region.get("height", 12)), 100.0 - y))
            except (TypeError, ValueError):
                return None
            return {
                "x": round(x, 1),
                "y": round(y, 1),
                "width": round(width, 1),
                "height": round(height, 1),
            }

        def caption_preset_region(caption_layer: dict[str, Any]) -> dict[str, float] | None:
            slot = str(caption_layer.get("id", caption_layer.get("slot", "")) or "").strip().lower().replace("_", "-")
            if not slot:
                slot = "primary"
            if slot.startswith("caption-"):
                slot = "context" if slot.endswith("2") else "counter"
            if slot in {"subtitle", "source", "collection", "context"}:
                slot = "context"
            if slot in {"count", "page", "number"}:
                slot = "counter"
            return template_caption_resolved_region_map.get(slot, template_caption_resolved_region_map.get("context"))

        def row_caption_typography(row: dict[str, Any]) -> str:
            typography = str(row.get("captionTypography", "") or "").strip().lower().replace("_", "-")
            return typography if typography in {"clean", "editorial", "cinematic", "bold"} else "auto"

        def row_caption_wrap(row: dict[str, Any]) -> str:
            wrap = str(row.get("captionWrap", "") or "").strip().lower().replace("_", "-")
            return wrap if wrap in {"single-line", "two-line", "multi-line"} else "auto"

        def row_extra_captions(row: dict[str, Any]) -> list[dict[str, Any]]:
            raw_captions = row.get("captions")
            if not isinstance(raw_captions, list):
                return []
            captions: list[dict[str, Any]] = []
            for index, raw_caption in enumerate(raw_captions):
                if not isinstance(raw_caption, dict) or len(captions) >= 8:
                    continue
                caption_placement = row_caption_placement(raw_caption)
                if caption_placement == "hidden":
                    continue
                caption_text = row_caption_text(raw_caption)
                if not caption_text:
                    continue
                caption = {
                    "id": str(raw_caption.get("id", "") or f"caption-{index + 2}")[:40],
                    "captionText": caption_text,
                }
                if caption_placement != "auto":
                    caption["captionPlacement"] = caption_placement
                caption_region = row_caption_region(raw_caption)
                if caption_region:
                    caption["captionRegion"] = caption_region
                caption_typography = row_caption_typography(raw_caption)
                if caption_typography != "auto":
                    caption["captionTypography"] = caption_typography
                caption_wrap = row_caption_wrap(raw_caption)
                if caption_wrap != "auto":
                    caption["captionWrap"] = caption_wrap
                captions.append(caption)
            return captions

        def row_caption_layers(row: dict[str, Any], *, fallback_label: bool = False) -> list[dict[str, Any]]:
            layers: list[dict[str, Any]] = []
            caption_placement = row_caption_placement(row)
            caption_text = "" if caption_placement == "hidden" else row_caption_text(row, fallback_label=fallback_label)
            if caption_text:
                layer = {"id": "primary", "captionText": caption_text}
                if caption_placement != "auto":
                    layer["captionPlacement"] = caption_placement
                caption_region = row_caption_region(row)
                if caption_region:
                    layer["captionRegion"] = caption_region
                caption_typography = row_caption_typography(row)
                if caption_typography != "auto":
                    layer["captionTypography"] = caption_typography
                caption_wrap = row_caption_wrap(row)
                if caption_wrap != "auto":
                    layer["captionWrap"] = caption_wrap
                layers.append(layer)
            layers.extend(row_extra_captions(row))
            return layers

        caption_overlay_requested = any(
            (
                row_caption_placement(row) != "hidden"
                and (
                    bool(row_caption_text(row))
                    or row_caption_placement(row) != "auto"
                    or row_caption_region(row) is not None
                )
            )
            or bool(row_extra_captions(row))
            for row in video_rows
        )
        caption_overlay_item_count = sum(
            len(
                row_caption_layers(
                    row,
                    fallback_label=row_caption_placement(row) != "auto" or row_caption_region(row) is not None,
                )
            )
            for row in video_rows
        )

        def chrome_overlay_row(row: dict[str, Any], index: int) -> dict[str, Any]:
            row_label = self._photo_export_clean_text(row.get("label", ""), limit=120)
            row_cue = self._photo_export_clean_text(row.get("themeCue", ""), limit=80)
            caption_placement = row_caption_placement(row)
            caption_text = "" if caption_placement == "hidden" else row_caption_text(row)
            chapter_label = caption_text or (row_label if row_label and row_label != render_title else row_cue or row_label or f"Chapter {index + 1}")
            overlay_row = {
                "index": index,
                "title": render_title or "Vintrace slideshow",
                "sourceLabel": render_source_label,
                "chapterLabel": chapter_label,
                "counter": f"{index + 1} / {len(video_rows)}",
                "themeTemplateStageWidth": template_stage_width,
                "templateStageFrame": template_stage_frame,
                "themeTemplateLayout": template_layout,
                "templateLayoutChromeRendered": bool(layout_chrome_rendered),
                "templateLayoutChromeStyle": layout_chrome_style,
                "templateLayoutMediaFrame": layout_media_frame,
                "themeTemplateCaptionPreset": template_caption_preset,
                "templateCaptionResolvedPreset": resolved_caption_preset,
                "themeTemplateRegionMap": template_region_map,
                "templateCaptionResolvedRegionMap": template_caption_resolved_region_map,
            }
            if caption_text:
                overlay_row["captionText"] = caption_text
            if caption_placement != "auto":
                overlay_row["captionPlacement"] = caption_placement
            caption_region = row_caption_region(row) or (caption_preset_region({"id": "primary"}) if caption_text else None)
            if caption_region:
                overlay_row["captionRegion"] = caption_region
            caption_typography = row_caption_typography(row)
            if caption_typography != "auto":
                overlay_row["captionTypography"] = caption_typography
            caption_wrap = row_caption_wrap(row)
            if caption_wrap != "auto":
                overlay_row["captionWrap"] = caption_wrap
            extra_captions = row_extra_captions(row)
            if extra_captions:
                overlay_row["captions"] = extra_captions
            return overlay_row

        def create_chrome_overlay(path: Path, row: dict[str, Any], index: int) -> None:
            from PIL import Image, ImageDraw, ImageFont

            image = Image.new("RGBA", (stage_width, stage_height), (0, 0, 0, 0))
            draw = ImageDraw.Draw(image)
            chrome_text_px = chrome_bar_px if chrome_bar_px > 0 else even(max(24, stage_height * 0.055))
            title_size = max(9, min(32, int(chrome_text_px * 0.42)))
            body_size = max(8, min(28, int(chrome_text_px * 0.36)))

            def load_font(size: int, *, bold: bool = False, serif: bool = False, italic: bool = False) -> Any:
                if serif and italic:
                    candidates = (
                        "Georgia Italic.ttf",
                        "Times New Roman Italic.ttf",
                        "DejaVuSerif-Italic.ttf",
                        "/System/Library/Fonts/Supplemental/Georgia Italic.ttf",
                        "/System/Library/Fonts/Supplemental/Times New Roman Italic.ttf",
                    )
                elif serif:
                    candidates = (
                        "Georgia.ttf",
                        "Times New Roman.ttf",
                        "DejaVuSerif.ttf",
                        "/System/Library/Fonts/Supplemental/Georgia.ttf",
                        "/System/Library/Fonts/Supplemental/Times New Roman.ttf",
                    )
                else:
                    candidates = (
                        "Avenir Next.ttc",
                        "Arial Bold.ttf" if bold else "Arial.ttf",
                        "DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf",
                        "/System/Library/Fonts/Supplemental/Arial Bold.ttf" if bold else "/System/Library/Fonts/Supplemental/Arial.ttf",
                    )
                for name in candidates:
                    try:
                        return ImageFont.truetype(name, size)
                    except Exception:
                        continue
                return ImageFont.load_default()

            title_font = load_font(title_size, bold=True)
            body_font = load_font(body_size)

            def text_size(text: str, font: Any) -> tuple[int, int]:
                if not text:
                    return (0, 0)
                box = draw.textbbox((0, 0), text, font=font)
                return (max(0, box[2] - box[0]), max(0, box[3] - box[1]))

            def ellipsize(text: str, font: Any, max_width: int) -> str:
                text = self._photo_export_clean_text(text, limit=140)
                if not text or max_width <= 0:
                    return ""
                if text_size(text, font)[0] <= max_width:
                    return text
                suffix = "..."
                trimmed = text
                while trimmed and text_size(f"{trimmed}{suffix}", font)[0] > max_width:
                    trimmed = trimmed[:-1].rstrip()
                return f"{trimmed}{suffix}" if trimmed else suffix

            def font_line_height(font: Any, fallback_size: int) -> int:
                width, height = text_size("Ag", font)
                del width
                return max(1, height + max(2, int(fallback_size * 0.22)))

            def caption_font_for(typography: str, size: int) -> Any:
                if typography == "editorial":
                    return load_font(size, serif=True, italic=True)
                if typography == "bold":
                    return load_font(size, bold=True)
                if typography == "cinematic":
                    return load_font(max(1, size + 1), bold=True)
                return load_font(size)

            def wrap_caption_lines(text: str, font: Any, max_width: int, max_lines: int) -> list[str]:
                text = self._photo_export_clean_text(text, limit=180)
                if not text or max_width <= 0 or max_lines <= 0:
                    return []
                if max_lines <= 1:
                    return [ellipsize(text, font, max_width)]
                words = text.split()
                if not words:
                    return []
                lines: list[str] = []
                current = ""
                index = 0
                while index < len(words):
                    word = words[index]
                    candidate = f"{current} {word}".strip() if current else word
                    if text_size(candidate, font)[0] <= max_width:
                        current = candidate
                        index += 1
                        continue
                    if current:
                        lines.append(current)
                        current = ""
                    else:
                        lines.append(ellipsize(word, font, max_width))
                        index += 1
                    if len(lines) >= max_lines:
                        remaining = " ".join(words[index:])
                        if remaining:
                            lines[-1] = ellipsize(f"{lines[-1]} {remaining}", font, max_width)
                        return lines[:max_lines]
                if current:
                    lines.append(current)
                if len(lines) > max_lines:
                    overflow = " ".join(lines[max_lines - 1:])
                    lines = lines[:max_lines]
                    lines[-1] = ellipsize(overflow, font, max_width)
                return lines

            def draw_shadowed_text(position: tuple[int, int], text: str, font: Any) -> None:
                if not text:
                    return
                x, y = position
                draw.text((x + 1, y + 1), text, font=font, fill=(0, 0, 0, 188))
                draw.text((x, y), text, font=font, fill=(250, 250, 246, 238))

            margin = max(4, min(18, int(stage_width * 0.012)))
            counter = f"{index + 1} / {len(video_rows)}"

            def draw_layout_chrome() -> None:
                if not layout_chrome_rendered:
                    return
                frame_x = int(layout_media_frame["x"])
                frame_y = int(layout_media_frame["y"])
                frame_width = int(layout_media_frame["width"])
                frame_height = int(layout_media_frame["height"])
                frame_right = frame_x + frame_width
                frame_bottom = frame_y + frame_height
                if layout_chrome_style == "poster-stage":
                    halo = max(4, min(18, int(min(stage_width, stage_height) * 0.02)))
                    shadow_box = (
                        max(0, frame_x - halo),
                        max(0, frame_y - halo),
                        min(stage_width, frame_right + halo),
                        min(stage_height, frame_bottom + halo),
                    )
                    try:
                        draw.rounded_rectangle(shadow_box, radius=max(8, halo), fill=(0, 0, 0, 92))
                        draw.rounded_rectangle(
                            (frame_x, frame_y, frame_right, frame_bottom),
                            radius=max(7, halo // 2),
                            outline=(255, 255, 255, 72),
                            width=max(1, halo // 4),
                        )
                    except Exception:
                        draw.rectangle(shadow_box, fill=(0, 0, 0, 92))
                        draw.rectangle((frame_x, frame_y, frame_right, frame_bottom), outline=(255, 255, 255, 72), width=1)
                elif layout_chrome_style == "gallery-matte":
                    stroke = max(2, min(10, int(min(stage_width, stage_height) * 0.012)))
                    stage_box = (
                        int(template_stage_frame["x"]),
                        int(template_stage_frame["y"]),
                        int(template_stage_frame["x"]) + int(template_stage_frame["width"]),
                        int(template_stage_frame["y"]) + int(template_stage_frame["height"]),
                    )
                    draw.rectangle(stage_box, outline=(255, 255, 255, 34), width=stroke)
                    draw.rectangle(
                        (max(0, frame_x - stroke), max(0, frame_y - stroke), min(stage_width, frame_right + stroke), min(stage_height, frame_bottom + stroke)),
                        outline=(255, 255, 255, 86),
                        width=stroke,
                    )
                    pill_text = counter
                    pill_width, pill_height = text_size(pill_text, body_font)
                    pill_pad = max(5, int(body_size * 0.45))
                    pill_box = (
                        max(margin, frame_right - pill_width - pill_pad * 2),
                        max(margin, frame_y + margin),
                        max(margin, frame_right - pill_width - pill_pad * 2) + pill_width + pill_pad * 2,
                        max(margin, frame_y + margin) + pill_height + pill_pad,
                    )
                    try:
                        draw.rounded_rectangle(pill_box, radius=max(6, pill_pad), fill=(0, 0, 0, 154), outline=(255, 255, 255, 58))
                    except Exception:
                        draw.rectangle(pill_box, fill=(0, 0, 0, 154))
                    draw_shadowed_text((pill_box[0] + pill_pad, pill_box[1] + max(2, pill_pad // 2)), pill_text, body_font)
                elif layout_chrome_style == "split-rail":
                    rail_left = int(template_stage_frame["x"])
                    rail_width = max(0, frame_x - rail_left)
                    if rail_width <= 0:
                        return
                    rail_right = rail_left + rail_width
                    draw.rectangle((rail_left, 0, rail_right, stage_height), fill=(5, 7, 13, 218))
                    draw.rectangle((max(rail_left, rail_right - 2), 0, rail_right, stage_height), fill=(118, 185, 255, 142))
                    rail_margin = max(8, min(24, rail_width // 10))
                    available_width = max(20, rail_width - rail_margin * 2)
                    side_title = ellipsize(render_title or "Vintrace slideshow", title_font, available_width)
                    side_source = ellipsize(render_source_label or "Selection", body_font, available_width)
                    row_label = self._photo_export_clean_text(row.get("label", ""), limit=120)
                    row_cue = self._photo_export_clean_text(row.get("themeCue", ""), limit=80)
                    side_chapter = ellipsize(row_label if row_label and row_label != render_title else row_cue or row_label or f"Chapter {index + 1}", body_font, available_width)
                    y = max(rail_margin, int(stage_height * 0.30))
                    text_x = rail_left + rail_margin
                    draw_shadowed_text((text_x, y), side_title, title_font)
                    y += font_line_height(title_font, title_size) + max(6, rail_margin // 2)
                    if side_source:
                        draw_shadowed_text((text_x, y), side_source, body_font)
                        y += font_line_height(body_font, body_size) + max(6, rail_margin // 2)
                    draw_shadowed_text((text_x, y), side_chapter, body_font)
                    counter_label = ellipsize(counter, body_font, available_width)
                    draw_shadowed_text((text_x, max(rail_margin, stage_height - rail_margin - body_size)), counter_label, body_font)
                elif layout_chrome_style == "immersive-gradient":
                    gradient_height = max(20, int(stage_height * 0.24))
                    for step in range(gradient_height):
                        alpha = int(150 * (1 - step / max(1, gradient_height)))
                        draw.rectangle((0, step, stage_width, step + 1), fill=(0, 0, 0, alpha))
                        draw.rectangle((0, stage_height - step - 1, stage_width, stage_height - step), fill=(0, 0, 0, alpha))
                elif layout_chrome_style == "cinema-letterbox" and chrome_bar_px > 0:
                    line_alpha = 74
                    draw.rectangle((0, chrome_bar_px, stage_width, chrome_bar_px + 1), fill=(255, 255, 255, line_alpha))
                    draw.rectangle((0, stage_height - chrome_bar_px - 1, stage_width, stage_height - chrome_bar_px), fill=(255, 255, 255, line_alpha))

            draw_layout_chrome()
            counter_width, counter_height = text_size(counter, body_font)
            if chrome_bar_px > 0:
                top_right = render_source_label or str(row.get("themeCue", "") or "")
                top_right = ellipsize(top_right, body_font, max(0, stage_width // 3))
                top_right_width, top_right_height = text_size(top_right, body_font)
                top_title = ellipsize(render_title or "Vintrace slideshow", title_font, max(0, stage_width - top_right_width - (margin * 3)))
                top_title_height = text_size(top_title, title_font)[1]
                top_y = max(1, int((chrome_bar_px - max(top_title_height, top_right_height, 1)) / 2))
                draw_shadowed_text((margin, top_y), top_title, title_font)
                if top_right:
                    draw_shadowed_text((max(margin, stage_width - margin - top_right_width), top_y), top_right, body_font)

                row_label = self._photo_export_clean_text(row.get("label", ""), limit=120)
                row_cue = self._photo_export_clean_text(row.get("themeCue", ""), limit=80)
                bottom_left = row_label if row_label and row_label != render_title else row_cue or row_label
                bottom_left = ellipsize(bottom_left or f"Chapter {index + 1}", body_font, max(0, stage_width - counter_width - (margin * 3)))
                bottom_left_height = text_size(bottom_left, body_font)[1]
                bottom_y = stage_height - chrome_bar_px + max(1, int((chrome_bar_px - max(bottom_left_height, counter_height, 1)) / 2))
                draw_shadowed_text((margin, bottom_y), bottom_left, body_font)
                draw_shadowed_text((max(margin, stage_width - margin - counter_width), bottom_y), counter, body_font)

            def draw_caption_layer(caption_layer: dict[str, Any]) -> None:
                caption_placement = row_caption_placement(caption_layer)
                caption_text = "" if caption_placement == "hidden" else row_caption_text(caption_layer)
                if not caption_text:
                    return
                caption_typography = row_caption_typography(caption_layer)
                caption_wrap = row_caption_wrap(caption_layer)
                caption_font = caption_font_for(caption_typography, body_size)
                line_height = font_line_height(caption_font, body_size)
                padding = max(4, min(14, int(body_size * 0.5)))
                caption_region = row_caption_region(caption_layer) or caption_preset_region(caption_layer)
                caption_width = max(80, int(stage_width * 0.42))
                caption_region_height: int | None = None
                caption_x = margin
                caption_y = max(margin, stage_height - chrome_bar_px - margin - (body_size + padding * 2))
                if caption_region:
                    caption_x = int(stage_width * caption_region["x"] / 100.0)
                    caption_y = int(stage_height * caption_region["y"] / 100.0)
                    caption_width = max(40, int(stage_width * caption_region["width"] / 100.0))
                    caption_region_height = max(1, int(stage_height * caption_region["height"] / 100.0))
                else:
                    if caption_placement.startswith("upper"):
                        caption_y = chrome_bar_px + margin
                    elif caption_placement == "center":
                        caption_y = int((stage_height - body_size - padding * 2) / 2)
                    if caption_placement.endswith("center") or caption_placement == "center":
                        caption_x = int((stage_width - caption_width) / 2)
                    elif caption_placement.endswith("right"):
                        caption_x = stage_width - caption_width - margin
                max_text_width = max(20, caption_width - padding * 2)
                max_lines = 1
                if caption_wrap == "two-line":
                    max_lines = 2
                elif caption_wrap == "multi-line":
                    max_lines = 4
                if caption_region_height is not None:
                    region_lines = max(1, int(max(1, caption_region_height - padding * 2) / max(1, line_height)))
                    max_lines = max(1, min(max_lines, region_lines))
                caption_lines = wrap_caption_lines(caption_text, caption_font, max_text_width, max_lines)
                if not caption_lines:
                    caption_lines = [ellipsize(caption_text, caption_font, max_text_width)]
                caption_line_widths = [text_size(line, caption_font)[0] for line in caption_lines]
                caption_text_width = max(caption_line_widths) if caption_line_widths else 0
                caption_text_height = max(1, (line_height * len(caption_lines)) - max(2, int(body_size * 0.22)))
                box_width = min(caption_width, max(caption_text_width + padding * 2, 40))
                box_height = max(caption_text_height + padding * 2, body_size + padding * 2)
                if caption_region:
                    box_width = caption_width
                    if caption_region_height is not None:
                        box_height = max(box_height, caption_region_height)
                caption_x = max(0, min(stage_width - box_width, caption_x))
                caption_y = max(0, min(stage_height - box_height, caption_y))
                text_y = caption_y + max(padding, int((box_height - caption_text_height) / 2))
                try:
                    draw.rounded_rectangle(
                        (caption_x, caption_y, caption_x + box_width, caption_y + box_height),
                        radius=max(4, padding),
                        fill=(0, 0, 0, 142),
                        outline=(255, 255, 255, 54),
                    )
                except Exception:
                    draw.rectangle((caption_x, caption_y, caption_x + box_width, caption_y + box_height), fill=(0, 0, 0, 142))
                for line_index, line in enumerate(caption_lines):
                    line_width = caption_line_widths[line_index] if line_index < len(caption_line_widths) else text_size(line, caption_font)[0]
                    if caption_placement.endswith("center") or caption_placement == "center":
                        text_x = caption_x + max(padding, int((box_width - line_width) / 2))
                    elif caption_placement.endswith("right"):
                        text_x = caption_x + max(padding, box_width - line_width - padding)
                    else:
                        text_x = caption_x + padding
                    text_x = max(caption_x + padding, min(caption_x + box_width - padding - line_width, text_x))
                    draw_shadowed_text((text_x, text_y + line_index * line_height), line, caption_font)

            fallback_caption_label = row_caption_placement(row) != "auto" or row_caption_region(row) is not None
            for caption_layer in row_caption_layers(row, fallback_label=fallback_caption_label):
                draw_caption_layer(caption_layer)
            path.parent.mkdir(parents=True, exist_ok=True)
            image.save(path)

        if chrome_bar_px > 0 or caption_overlay_requested or layout_chrome_rendered:
            chrome_temp_dir = tempfile.TemporaryDirectory(prefix="vintrace-slideshow-chrome-")
            try:
                for index, row in enumerate(video_rows):
                    overlay_path = Path(chrome_temp_dir.name) / f"chrome-overlay-{index:04d}.png"
                    create_chrome_overlay(overlay_path, row, index)
                    chrome_overlay_paths.append(overlay_path)
                    chrome_overlay_rows.append(chrome_overlay_row(row, index))
            except Exception:
                chrome_overlay_paths = []
                chrome_overlay_rows = []
                if chrome_temp_dir is not None:
                    chrome_temp_dir.cleanup()
                    chrome_temp_dir = None

        command = [
            ffmpeg,
            "-hide_banner",
            "-loglevel",
            "error",
        ]
        for index, row in enumerate(video_rows):
            duration_ms = row_durations_ms[index]
            input_duration_ms = duration_ms + (row_transition_durations_ms[index] if index < len(video_rows) - 1 else 0)
            source_path = str(row.get("targetPath", "") or "")
            suffix = Path(source_path).suffix.lower()
            if suffix in VIDEO_EXTENSIONS:
                command.extend(["-t", f"{input_duration_ms / 1000:.3f}", "-i", source_path])
            else:
                command.extend(["-loop", "1", "-t", f"{input_duration_ms / 1000:.3f}", "-i", source_path])
        chrome_overlay_input_start_index = len(video_rows)
        for index, overlay_path in enumerate(chrome_overlay_paths):
            input_duration_ms = row_durations_ms[index] + (row_transition_durations_ms[index] if index < len(video_rows) - 1 else 0)
            command.extend(["-loop", "1", "-t", f"{input_duration_ms / 1000:.3f}", "-i", str(overlay_path)])

        audio_track = str(music or "none").strip().lower().replace("_", "-")
        custom_audio_path = str(audio_path or "").strip()
        audio_frequencies = {
            "calm": 220,
            "bright": 440,
            "cinematic": 110,
        }
        audio_imported = audio_track == "custom" and bool(custom_audio_path) and total_duration_ms > 0
        audio_frequency = 0 if audio_imported else audio_frequencies.get(audio_track, 0)
        audio_generated = audio_frequency > 0 and total_duration_ms > 0
        audio_input_index = len(video_rows) + len(chrome_overlay_paths)
        try:
            audio_volume = max(0.0, min(1.0, float(audio_volume)))
        except (TypeError, ValueError):
            audio_volume = 1.0
        try:
            audio_fade_ms = max(0, min(10000, int(audio_fade_ms or 0)))
        except (TypeError, ValueError):
            audio_fade_ms = 0
        try:
            audio_start_ms = max(0, min(3_600_000, int(audio_start_ms or 0)))
        except (TypeError, ValueError):
            audio_start_ms = 0
        try:
            audio_end_ms = max(0, min(3_600_000, int(audio_end_ms or 0)))
        except (TypeError, ValueError):
            audio_end_ms = 0
        if not audio_imported:
            audio_start_ms = 0
            audio_end_ms = 0
        elif audio_end_ms and audio_end_ms <= audio_start_ms:
            audio_end_ms = 0
        try:
            audio_placement_start_ms = max(0, int(audio_placement_start_ms or 0))
        except (TypeError, ValueError):
            audio_placement_start_ms = 0
        try:
            audio_placement_end_ms = max(0, int(audio_placement_end_ms or 0))
        except (TypeError, ValueError):
            audio_placement_end_ms = 0
        if total_duration_ms > 0:
            audio_placement_start_ms = min(audio_placement_start_ms, total_duration_ms)
            audio_placement_end_ms = min(audio_placement_end_ms, total_duration_ms)
        if audio_placement_end_ms and audio_placement_end_ms <= audio_placement_start_ms:
            audio_placement_end_ms = 0
        audio_has_placement = bool(audio_placement_start_ms or audio_placement_end_ms)
        audio_placement_effective_end_ms = audio_placement_end_ms if audio_placement_end_ms > audio_placement_start_ms else total_duration_ms
        audio_placement_duration_ms = max(0, audio_placement_effective_end_ms - audio_placement_start_ms)
        if total_duration_ms > 0:
            fade_window_ms = audio_placement_duration_ms if audio_has_placement else total_duration_ms
            audio_fade_ms = min(audio_fade_ms, max(0, fade_window_ms // 2))
        if audio_imported:
            command.extend([
                "-stream_loop",
                "-1",
            ])
            if audio_start_ms > 0:
                command.extend(["-ss", f"{audio_start_ms / 1000:.3f}"])
            command.extend([
                "-t",
                f"{total_duration_ms / 1000:.3f}",
                "-i",
                custom_audio_path,
            ])
        if audio_generated:
            command.extend([
                "-f",
                "lavfi",
                "-t",
                f"{total_duration_ms / 1000:.3f}",
                "-i",
                f"sine=frequency={audio_frequency}:sample_rate=48000",
            ])

        filters: list[str] = []
        labels: list[str] = []
        def clean_render_percent(value: Any, fallback: float) -> float:
            try:
                parsed = float(value)
            except (TypeError, ValueError):
                return fallback
            return max(0.0, min(100.0, parsed))

        def clean_render_zoom(value: Any, fallback: float) -> float:
            try:
                parsed = float(value)
            except (TypeError, ValueError):
                return fallback
            return max(1.0, min(1.5, parsed))

        def clean_render_crop_zoom(value: Any, fallback: float = 1.0) -> float:
            try:
                parsed = float(value)
            except (TypeError, ValueError):
                return fallback
            return max(1.0, min(3.0, parsed))

        def render_focal_fraction(row: dict[str, Any], key: str) -> float:
            return clean_render_percent(row.get(key), 50.0) / 100.0

        def focal_crop_filter(row: dict[str, Any], target_width: int, target_height: int) -> str:
            focal_x = render_focal_fraction(row, "focalX")
            focal_y = render_focal_fraction(row, "focalY")
            return f"crop={target_width}:{target_height}:x='(iw-ow)*{focal_x:.4f}':y='(ih-oh)*{focal_y:.4f}'"

        def motion_filter(row: dict[str, Any], input_duration_ms: int, target_width: int, target_height: int) -> str:
            motion = str(row.get("resolvedMotion", row.get("motion", "auto")) or "auto").strip().lower().replace("_", "-")
            duration_seconds = max(0.5, input_duration_ms / 1000.0)
            if motion == "slow-zoom":
                progress = f"min(t\\,{duration_seconds:.3f})/{duration_seconds:.3f}"
                return (
                    f",scale=w='iw*(1+0.065*{progress})':h='ih*(1+0.065*{progress})':eval=frame,"
                    f"{focal_crop_filter(row, target_width, target_height)}"
                )
            if motion in {"pan-left", "pan-right"}:
                motion_width = even(target_width * 1.075)
                motion_height = even(target_height * 1.075)
                progress = f"min(t\\,{duration_seconds:.3f})/{duration_seconds:.3f}"
                x_expr = f"(iw-ow)*(1-{progress})" if motion == "pan-left" else f"(iw-ow)*({progress})"
                focal_y = render_focal_fraction(row, "focalY")
                return (
                    f",scale={motion_width}:{motion_height},"
                    f"crop={target_width}:{target_height}:x='{x_expr}':y='(ih-oh)*{focal_y:.4f}'"
                )
            if motion == "custom" and isinstance(row.get("keyframes"), dict):
                keyframes = row["keyframes"]
                progress = f"min(t\\,{duration_seconds:.3f})/{duration_seconds:.3f}"
                start_zoom = clean_render_zoom(keyframes.get("startZoom"), 1.0)
                end_zoom = clean_render_zoom(keyframes.get("endZoom"), 1.08)
                start_x = clean_render_percent(keyframes.get("startX"), 50.0) / 100.0
                start_y = clean_render_percent(keyframes.get("startY"), 50.0) / 100.0
                end_x = clean_render_percent(keyframes.get("endX"), 50.0) / 100.0
                end_y = clean_render_percent(keyframes.get("endY"), 50.0) / 100.0
                has_midpoint = any(key in keyframes for key in ("midX", "midY", "midZoom"))
                has_quarter_path = any(
                    key in keyframes
                    for key in ("quarterX", "quarterY", "quarterZoom", "threeQuarterX", "threeQuarterY", "threeQuarterZoom")
                )
                mid_zoom = clean_render_zoom(keyframes.get("midZoom"), (start_zoom + end_zoom) / 2.0)
                mid_x = clean_render_percent(keyframes.get("midX"), (start_x + end_x) * 50.0) / 100.0
                mid_y = clean_render_percent(keyframes.get("midY"), (start_y + end_y) * 50.0) / 100.0
                curve = str(keyframes.get("curve") or "").strip().lower().replace("_", "-").replace(" ", "-")
                curve = {
                    "ease-in-out": "ease",
                    "eased": "ease",
                    "bezier": "smooth",
                    "spline": "smooth",
                    "soft": "smooth",
                    "cinema": "cinematic",
                    "dramatic": "cinematic",
                }.get(curve, curve)
                if curve not in {"linear", "ease", "smooth", "cinematic"}:
                    curve = "linear"

                def eased_progress(expression: str) -> str:
                    value = f"({expression})"
                    if curve == "ease":
                        return f"{value}*{value}*(3-2*{value})"
                    if curve == "smooth":
                        return f"{value}*{value}*{value}*({value}*({value}*6-15)+10)"
                    if curve == "cinematic":
                        return f"{value}*{value}*(2.5-1.5*{value})"
                    return expression

                def segmented_expr(points: list[tuple[float, float]], precision: int) -> str:
                    def value_text(value: float) -> str:
                        return f"{value:.{precision}f}"

                    segments: list[str] = []
                    for index in range(len(points) - 1):
                        start_time, start_value = points[index]
                        end_time, end_value = points[index + 1]
                        duration = max(0.001, end_time - start_time)
                        segment_progress = f"({progress})/{duration:.3f}" if start_time <= 0 else f"({progress}-{start_time:.3f})/{duration:.3f}"
                        segments.append(f"{value_text(start_value)}+({value_text(end_value - start_value)})*{eased_progress(segment_progress)}")
                    expression = segments[-1]
                    for index in range(len(segments) - 2, -1, -1):
                        threshold = points[index + 1][0]
                        expression = f"if(lt({progress}\\,{threshold:.3f})\\,{segments[index]}\\,{expression})"
                    return expression

                if has_quarter_path:
                    quarter_zoom = clean_render_zoom(keyframes.get("quarterZoom"), (start_zoom + mid_zoom) / 2.0)
                    three_quarter_zoom = clean_render_zoom(keyframes.get("threeQuarterZoom"), (mid_zoom + end_zoom) / 2.0)
                    quarter_x = clean_render_percent(keyframes.get("quarterX"), (start_x + mid_x) * 50.0) / 100.0
                    quarter_y = clean_render_percent(keyframes.get("quarterY"), (start_y + mid_y) * 50.0) / 100.0
                    three_quarter_x = clean_render_percent(keyframes.get("threeQuarterX"), (mid_x + end_x) * 50.0) / 100.0
                    three_quarter_y = clean_render_percent(keyframes.get("threeQuarterY"), (mid_y + end_y) * 50.0) / 100.0
                    zoom_expr = segmented_expr([
                        (0.0, start_zoom),
                        (0.25, quarter_zoom),
                        (0.5, mid_zoom),
                        (0.75, three_quarter_zoom),
                        (1.0, end_zoom),
                    ], 3)
                    x_expr = segmented_expr([
                        (0.0, start_x),
                        (0.25, quarter_x),
                        (0.5, mid_x),
                        (0.75, three_quarter_x),
                        (1.0, end_x),
                    ], 4)
                    y_expr = segmented_expr([
                        (0.0, start_y),
                        (0.25, quarter_y),
                        (0.5, mid_y),
                        (0.75, three_quarter_y),
                        (1.0, end_y),
                    ], 4)
                elif has_midpoint:
                    zoom_expr = segmented_expr([(0.0, start_zoom), (0.5, mid_zoom), (1.0, end_zoom)], 3)
                    x_expr = segmented_expr([(0.0, start_x), (0.5, mid_x), (1.0, end_x)], 4)
                    y_expr = segmented_expr([(0.0, start_y), (0.5, mid_y), (1.0, end_y)], 4)
                else:
                    full_progress = eased_progress(progress)
                    zoom_expr = f"{start_zoom:.3f}+({end_zoom - start_zoom:.3f})*{full_progress}"
                    x_expr = f"{start_x:.4f}+({end_x - start_x:.4f})*{full_progress}"
                    y_expr = f"{start_y:.4f}+({end_y - start_y:.4f})*{full_progress}"
                return (
                    f",scale=w='iw*({zoom_expr})':h='ih*({zoom_expr})':eval=frame,"
                    f"crop={target_width}:{target_height}:x='(iw-ow)*({x_expr})':y='(ih-oh)*({y_expr})'"
                )
            return ""

        motion_applied = False
        crop_focus_rendered = False
        for index, row in enumerate(video_rows):
            label = f"v{index}"
            labels.append(label)
            stage_label = f"{label}stage" if chrome_overlay_paths else label
            input_duration_ms = row_durations_ms[index] + (row_transition_durations_ms[index] if index < len(video_rows) - 1 else 0)
            motion = str(row.get("resolvedMotion", row.get("motion", "auto")) or "auto")
            row_has_crop_focus = any(key in row for key in ("focalX", "focalY", "cropZoom"))
            if fit_mode == "fill":
                crop_zoom = clean_render_crop_zoom(row.get("cropZoom"), 1.0)
                crop_zoom_filter = f",scale=w='iw*{crop_zoom:.3f}':h='ih*{crop_zoom:.3f}':eval=frame" if crop_zoom > 1 else ""
                transform = (
                    "setpts=PTS-STARTPTS,"
                    f"scale={layout_media_width}:{layout_media_height}:force_original_aspect_ratio=increase,"
                    f"{crop_zoom_filter.lstrip(',') if crop_zoom_filter else ''}"
                )
                if crop_zoom_filter:
                    transform = f"{transform},{focal_crop_filter(row, layout_media_width, layout_media_height)}"
                else:
                    transform = f"{transform}{focal_crop_filter(row, layout_media_width, layout_media_height)}"
                crop_focus_rendered = crop_focus_rendered or row_has_crop_focus
            else:
                transform = (
                    "setpts=PTS-STARTPTS,"
                    f"scale={layout_media_width}:{layout_media_height}:force_original_aspect_ratio=decrease,"
                    f"pad={layout_media_width}:{layout_media_height}:(ow-iw)/2:(oh-ih)/2:color=black"
                )
                crop_focus_rendered = crop_focus_rendered or (row_has_crop_focus and motion in {"slow-zoom", "pan-left", "pan-right"})
            transform = f"{transform}{motion_filter(row, input_duration_ms, layout_media_width, layout_media_height)}"
            if not layout_media_is_full_stage:
                transform = (
                    f"{transform},"
                    f"pad={stage_width}:{stage_height}:{layout_media_x}:{layout_media_y}:color={layout_background_color}"
                )
            if chrome_bar_px > 0:
                transform = (
                    f"{transform},"
                    f"drawbox=x=0:y=0:w=iw:h={chrome_bar_px}:color={chrome_color}:t=fill,"
                    f"drawbox=x=0:y=ih-{chrome_bar_px}:w=iw:h={chrome_bar_px}:color={chrome_color}:t=fill"
                )
            motion_applied = motion_applied or motion in {"slow-zoom", "pan-left", "pan-right", "custom"}
            filters.append(f"[{index}:v]{transform}[{stage_label}]")
            if chrome_overlay_paths:
                overlay_input_index = chrome_overlay_input_start_index + index
                chrome_label = f"{label}chrome"
                filters.append(f"[{stage_label}][{overlay_input_index}:v]overlay=0:0:format=auto[{chrome_label}]")
                final_transform = "setsar=1,fps=30,format=yuv420p"
                if frame_border_px > 0:
                    final_transform = f"pad={width}:{height}:(ow-iw)/2:(oh-ih)/2:color={frame_color},{final_transform}"
                filters.append(f"[{chrome_label}]{final_transform}[{label}]")
            elif frame_border_px > 0:
                filters[-1] = f"[{index}:v]{transform},pad={width}:{height}:(ow-iw)/2:(oh-ih)/2:color={frame_color},setsar=1,fps=30,format=yuv420p[{label}]"
            else:
                filters[-1] = f"[{index}:v]{transform},setsar=1,fps=30,format=yuv420p[{label}]"
        if len(labels) == 1:
            filters.append(f"[{labels[0]}]null[outv]")
        elif transition_applied:
            previous_label = labels[0]
            offset_ms = 0
            for index in range(1, len(labels)):
                offset_ms += row_durations_ms[index - 1]
                output_label = "outv" if index == len(labels) - 1 else f"xf{index}"
                row_transition = row_transition_effects[index - 1]
                row_transition_duration_ms = row_transition_durations_ms[index - 1]
                if row_transition_duration_ms > 0 and row_transition != "cut":
                    filters.append(
                        f"[{previous_label}][{labels[index]}]"
                        f"xfade=transition={ffmpeg_transition_name(row_transition)}:duration={row_transition_duration_ms / 1000.0:.3f}:offset={offset_ms / 1000.0:.3f}"
                        f"[{output_label}]"
                    )
                else:
                    filters.append(f"[{previous_label}][{labels[index]}]concat=n=2:v=1:a=0[{output_label}]")
                previous_label = output_label
        else:
            filters.append(f"{''.join(f'[{label}]' for label in labels)}concat=n={len(labels)}:v=1:a=0[outv]")
        audio_filter_label = ""
        if audio_generated or audio_imported:
            audio_filters: list[str] = []
            total_duration_seconds = total_duration_ms / 1000.0
            placement_duration_seconds = audio_placement_duration_ms / 1000.0
            audio_content_duration_seconds = placement_duration_seconds if audio_has_placement else total_duration_seconds
            if audio_imported and audio_end_ms > audio_start_ms:
                trim_duration_seconds = (audio_end_ms - audio_start_ms) / 1000.0
                audio_filters.append(f"atrim=duration={trim_duration_seconds:.3f}")
                audio_filters.append("asetpts=PTS-STARTPTS")
                if audio_content_duration_seconds > trim_duration_seconds + 0.001:
                    audio_filters.append("aresample=48000")
                    audio_filters.append(f"aloop=loop=-1:size={max(1, int(round(trim_duration_seconds * 48000)))}")
                    audio_filters.append("asetpts=PTS-STARTPTS")
                audio_filters.append(f"atrim=duration={audio_content_duration_seconds:.3f}")
            elif audio_has_placement:
                audio_filters.append(f"atrim=duration={audio_content_duration_seconds:.3f}")
                audio_filters.append("asetpts=PTS-STARTPTS")
            if audio_volume < 0.999:
                audio_filters.append(f"volume={audio_volume:.3f}")
            if audio_fade_ms > 0:
                fade_seconds = audio_fade_ms / 1000.0
                audio_filters.append(f"afade=t=in:st=0:d={fade_seconds:.3f}")
                audio_filters.append(f"afade=t=out:st={max(0.0, audio_content_duration_seconds - fade_seconds):.3f}:d={fade_seconds:.3f}")
            if audio_has_placement:
                if audio_placement_start_ms > 0:
                    audio_filters.append(f"adelay={audio_placement_start_ms}|{audio_placement_start_ms}")
                audio_filters.append("apad")
                audio_filters.append(f"atrim=duration={total_duration_seconds:.3f}")
            if audio_filters:
                audio_filter_label = "outa"
                filters.append(f"[{audio_input_index}:a]{','.join(audio_filters)}[{audio_filter_label}]")

        target.parent.mkdir(parents=True, exist_ok=True)
        command.extend([
            "-filter_complex",
            ";".join(filters),
            "-map",
            "[outv]",
        ])
        command.extend(video_codec_args)
        if audio_generated or audio_imported:
            command.extend([
                "-map",
                f"[{audio_filter_label}]" if audio_filter_label else f"{audio_input_index}:a",
                *audio_codec_args,
                "-shortest",
            ])
        else:
            command.append("-an")
        if use_faststart:
            command.extend(["-movflags", "+faststart"])
        command.extend(["-y", str(target)])
        try:
            completed = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=max(120, int(total_duration_ms / 1000) + 60),
                check=False,
            )
        finally:
            if chrome_temp_dir is not None:
                chrome_temp_dir.cleanup()
        if completed.returncode != 0 or not target.exists():
            try:
                target.unlink(missing_ok=True)
            except OSError:
                pass
            raise VideoLoadError((completed.stderr or completed.stdout or "Could not render slideshow movie.").strip()[:400])
        return {
            "targetPath": str(target),
            "slideCount": len(video_rows),
            "durationMs": total_duration_ms,
            "width": width,
            "height": height,
            "videoRenderFormat": video_format,
            "videoRenderQuality": quality,
            "renderMaxDimension": max_dimension,
            "fitMode": fit_mode,
            "audioTrack": "custom" if audio_imported else audio_track if audio_generated else "none",
            "audioGenerated": audio_generated,
            "audioImported": audio_imported,
            "audioPath": custom_audio_path if audio_imported else "",
            "audioVolume": audio_volume,
            "audioFadeMs": audio_fade_ms,
            "audioStartMs": audio_start_ms,
            "audioEndMs": audio_end_ms,
            "audioPlacementStartMs": audio_placement_start_ms,
            "audioPlacementEndMs": audio_placement_end_ms,
            "transitionEffect": transition_effect,
            "transitionDurationMs": transition_duration_ms,
            "transitionFfmpegEffect": ffmpeg_transition if transition_applied else "",
            "transitionTimeline": transition_timeline,
            "transitionApplied": bool(transition_applied),
            "motionPresets": motion_presets,
            "resolvedMotionPresets": resolved_motion_presets,
            "motionApplied": bool(motion_applied),
            "titleCardIncluded": title_card_included,
            "themeTemplateFrameStyle": template_frame_style,
            "templateFrameRendered": frame_border_px > 0,
            "templateFrameBorderPx": frame_border_px,
            "templateFrameColor": frame_color,
            "themeTemplateStageWidth": template_stage_width,
            "templateStageFrame": template_stage_frame,
            "themeTemplateLayout": template_layout,
            "templateLayoutChromeRendered": bool(layout_chrome_rendered),
            "templateLayoutChromeStyle": layout_chrome_style,
            "templateLayoutMediaFrame": layout_media_frame,
            "templateLayoutBackgroundColor": layout_background_color,
            "themeTemplateChromeDensity": template_chrome_density,
            "templateChromeDensity": template_chrome_density,
            "themeTemplateCaptionPreset": template_caption_preset,
            "templateCaptionPreset": template_caption_preset,
            "templateCaptionResolvedPreset": resolved_caption_preset,
            "themeTemplateRegionMap": template_region_map,
            "templateCaptionResolvedRegionMap": template_caption_resolved_region_map,
            "templateChromeRendered": chrome_bar_px > 0,
            "templateChromeBarPx": chrome_bar_px,
            "templateChromeColor": chrome_color if chrome_bar_px > 0 else "",
            "templateChromeOverlayRendered": bool(chrome_overlay_paths),
            "templateChromeTextRendered": bool(chrome_overlay_paths and (chrome_bar_px > 0 or caption_overlay_requested or template_layout == "split")),
            "templateChromeOverlayCount": len(chrome_overlay_paths),
            "templateChromeOverlayKinds": (
                (["layout"] if layout_chrome_rendered else [])
                + (["title", "chapter", "counter"] if chrome_bar_px > 0 else [])
                + (["caption"] if caption_overlay_requested else [])
            ) if chrome_overlay_paths else [],
            "templateChromeOverlayRows": chrome_overlay_rows,
            "templateCaptionRendered": bool(chrome_overlay_paths and caption_overlay_requested),
            "templateCaptionOverlayCount": len(chrome_overlay_paths) if caption_overlay_requested else 0,
            "templateCaptionItemCount": caption_overlay_item_count if caption_overlay_requested else 0,
            "cropFocusRendered": crop_focus_rendered,
        }

    def _photo_export_create_title_card(
        self,
        target: Path,
        *,
        title: str,
        subtitle: str,
        theme: str,
        generated_at: str,
        palette: str = "auto",
        layout: str = "center",
        font_scale: str = "regular",
        show_footer: bool = True,
    ) -> None:
        from PIL import Image, ImageDraw, ImageFont

        width = 1920
        height = 1080
        auto_palette = {
            "ken-burns": ((17, 19, 24), (48, 55, 64), (236, 178, 98)),
            "fade": ((15, 20, 28), (38, 62, 71), (116, 199, 179)),
            "classic": ((20, 20, 23), (55, 49, 62), (210, 172, 114)),
        }.get(theme, ((20, 20, 23), (55, 49, 62), (210, 172, 114)))
        explicit_palettes = {
            "midnight": ((14, 16, 24), (32, 37, 51), (118, 185, 255), (250, 250, 246), (218, 224, 229), (178, 187, 202), (10, 11, 18)),
            "paper": ((238, 235, 224), (208, 219, 215), (85, 115, 104), (34, 37, 36), (67, 74, 72), (93, 100, 98), (231, 229, 220)),
            "sunset": ((43, 18, 31), (118, 59, 52), (246, 181, 92), (255, 250, 240), (244, 221, 198), (216, 183, 162), (31, 16, 25)),
            "forest": ((16, 31, 26), (41, 73, 54), (151, 199, 127), (244, 250, 238), (213, 230, 204), (177, 201, 169), (12, 25, 20)),
        }
        palette_key = str(palette or "auto").strip().lower().replace("_", "-")
        if palette_key == "auto" or palette_key not in explicit_palettes:
            start_color, end_color, accent_color = auto_palette
            title_color = (250, 250, 246)
            subtitle_color = (218, 224, 229)
            meta_color = (180, 183, 190)
            footer_color = (12, 12, 16)
        else:
            start_color, end_color, accent_color, title_color, subtitle_color, meta_color, footer_color = explicit_palettes[palette_key]
        layout_key = str(layout or "center").strip().lower().replace("_", "-")
        if layout_key not in {"center", "lower-third", "left"}:
            layout_key = "center"
        font_scale_key = str(font_scale or "regular").strip().lower().replace("_", "-")
        font_sizes = {
            "compact": (72, 32, 22),
            "regular": (86, 38, 24),
            "large": (104, 44, 26),
        }.get(font_scale_key, (86, 38, 24))
        image = Image.new("RGB", (width, height), start_color)
        draw = ImageDraw.Draw(image)
        for y in range(height):
            ratio = y / max(1, height - 1)
            color = tuple(int(start_color[index] + (end_color[index] - start_color[index]) * ratio) for index in range(3))
            draw.line((0, y, width, y), fill=color)
        if layout_key == "lower-third":
            draw.rectangle((0, int(height * 0.58), width, height), fill=tuple(max(0, int(value * 0.72)) for value in footer_color))
            draw.rectangle((0, int(height * 0.58), width, int(height * 0.58) + 12), fill=accent_color)
        if show_footer:
            draw.rectangle((0, height - 96, width, height), fill=footer_color)
            draw.rectangle((0, height - 108, width, height - 96), fill=accent_color)

        def font(size: int) -> Any:
            for name in ("DejaVuSans.ttf", "Arial.ttf", "/System/Library/Fonts/Supplemental/Arial.ttf"):
                try:
                    return ImageFont.truetype(name, size)
                except OSError:
                    continue
            return ImageFont.load_default()

        def text_width(active_font: Any, text: str) -> int:
            box = draw.textbbox((0, 0), text, font=active_font)
            return int(box[2] - box[0])

        def text_height(active_font: Any, text: str) -> int:
            box = draw.textbbox((0, 0), text, font=active_font)
            return int(box[3] - box[1])

        def trim_to_width(active_font: Any, text: str, max_width: int) -> str:
            value = str(text or "").strip()
            if text_width(active_font, value) <= max_width:
                return value
            while value and text_width(active_font, f"{value}...") > max_width:
                value = value[:-1]
            return f"{value}..." if value else "..."

        def wrap(active_font: Any, text: str, max_width: int, max_lines: int) -> list[str]:
            lines: list[str] = []
            for raw_line in str(text or "").splitlines() or [""]:
                words = raw_line.split()
                if not words:
                    continue
                current = ""
                for word in words:
                    candidate = f"{current} {word}".strip()
                    if text_width(active_font, candidate) <= max_width or not current:
                        current = candidate
                    else:
                        lines.append(trim_to_width(active_font, current, max_width))
                        current = word
                        if len(lines) >= max_lines:
                            break
                if len(lines) >= max_lines:
                    break
                if current:
                    lines.append(trim_to_width(active_font, current, max_width))
                if len(lines) >= max_lines:
                    break
            return lines[:max_lines]

        max_text_width = int(width * (0.70 if layout_key == "left" else 0.76))
        title_font = font(font_sizes[0])
        title_lines = wrap(title_font, title or "Memory", max_text_width, 2)
        max_title_height = 230 if font_scale_key == "large" else 190
        while title_lines and len(title_lines) >= 2 and sum(text_height(title_font, line) for line in title_lines) > max_title_height:
            title_font = font(max(52, getattr(title_font, "size", font_sizes[0]) - 4))
            title_lines = wrap(title_font, title or "Memory", max_text_width, 2)
        subtitle_font = font(font_sizes[1])
        subtitle_lines = wrap(subtitle_font, subtitle or "Local Memory movie", max_text_width, 2)
        meta_font = font(font_sizes[2])
        line_gap = 24
        title_block_height = sum(text_height(title_font, line) for line in title_lines) + max(0, len(title_lines) - 1) * line_gap
        subtitle_block_height = sum(text_height(subtitle_font, line) for line in subtitle_lines) + max(0, len(subtitle_lines) - 1) * 14
        total_height = title_block_height + (42 if subtitle_lines else 0) + subtitle_block_height
        if layout_key == "lower-third":
            y = max(610, height - 340 - total_height)
        elif layout_key == "left":
            y = max(220, int((height - total_height) / 2) - 20)
        else:
            y = max(220, int((height - total_height) / 2) - 20)
        left_x = int(width * 0.12)
        for line in title_lines:
            line_width = text_width(title_font, line)
            x = left_x if layout_key == "left" else (width - line_width) / 2
            draw.text((x, y), line, fill=title_color, font=title_font)
            y += text_height(title_font, line) + line_gap
        if subtitle_lines:
            y += 18
            for line in subtitle_lines:
                line_width = text_width(subtitle_font, line)
                x = left_x if layout_key == "left" else (width - line_width) / 2
                draw.text((x, y), line, fill=subtitle_color, font=subtitle_font)
                y += text_height(subtitle_font, line) + 14
        if show_footer:
            footer = f"Generated locally - {generated_at}"
            footer_width = text_width(meta_font, footer)
            draw.text(((width - footer_width) / 2, height - 64), footer, fill=meta_color, font=meta_font)
        target.parent.mkdir(parents=True, exist_ok=True)
        image.save(target, "PNG")

    def _photo_export_allocate_target(
        self,
        target_root: Path,
        *,
        index: int,
        base_name: str,
        suffix: str,
        filename_mode: str,
    ) -> Path:
        clean_base = self._photo_export_strip_known_suffix(base_name)
        clean_suffix = suffix if suffix.startswith(".") else f".{suffix}"
        target_name = f"{index:05d}-{clean_base}{clean_suffix}" if filename_mode == "numbered" else f"{clean_base}{clean_suffix}"
        target = target_root / target_name
        target_counter = 2
        while target.exists():
            if filename_mode == "numbered":
                target = target_root / f"{index:05d}-{clean_base}-{target_counter}{clean_suffix}"
            else:
                target = target_root / f"{clean_base}-{target_counter}{clean_suffix}"
            target_counter += 1
        return target

    def _photo_export_target_color_profile(self, value: str, preserve_color_profile: bool = True) -> str:
        clean = re.sub(r"[\s_-]+", "-", str(value or "").strip().lower())
        aliases = {
            "": "source" if preserve_color_profile else "none",
            "source": "source",
            "preserve": "source",
            "keep": "source",
            "keep-source": "source",
            "original": "source",
            "none": "none",
            "strip": "none",
            "stripped": "none",
            "no-profile": "none",
            "srgb": "srgb",
            "s-rgb": "srgb",
            "standard-rgb": "srgb",
            "display-p3": "display-p3",
            "p3": "display-p3",
            "displayp3": "display-p3",
            "wide-gamut": "display-p3",
            "wide-gamut-rgb": "display-p3",
            "adobe-rgb": "adobe-rgb",
            "adobergb": "adobe-rgb",
            "adobe-rgb-(1998)": "adobe-rgb",
            "adobe-rgb-1998": "adobe-rgb",
            "adobergb1998": "adobe-rgb",
            "custom": "custom-icc",
            "custom-icc": "custom-icc",
            "custom-profile": "custom-icc",
            "icc": "custom-icc",
            "printer": "custom-icc",
            "printer-profile": "custom-icc",
        }
        if clean not in aliases:
            raise ValueError("targetColorProfile must be source, sRGB, Display P3, Adobe RGB, custom ICC, or none.")
        return aliases[clean]

    def _photo_export_srgb_profile_bytes(self) -> bytes:
        from PIL import ImageCms

        return ImageCms.ImageCmsProfile(ImageCms.createProfile("sRGB")).tobytes()

    def _photo_export_custom_profile_path(self, target_color_profile_path: str) -> Path:
        clean_path = str(target_color_profile_path or "").strip()
        if not clean_path:
            raise ValueError("targetColorProfilePath is required when targetColorProfile is custom ICC.")
        resolved = Path(clean_path).expanduser().resolve()
        if resolved.suffix.lower() not in {".icc", ".icm"}:
            raise ValueError("Custom color profile file must use an .icc or .icm extension.")
        if not resolved.exists() or not resolved.is_file():
            raise FileNotFoundError(f"Custom color profile file is not available: {clean_path}")
        size = resolved.stat().st_size
        if size <= 0 or size > 4 * 1024 * 1024:
            raise ValueError("Custom color profile file must be between 1 byte and 4 MB.")
        return resolved

    def _photo_export_custom_profile_bytes(self, target_color_profile_path: str) -> bytes:
        from io import BytesIO
        from PIL import ImageCms

        profile_path = self._photo_export_custom_profile_path(target_color_profile_path)
        profile_bytes = profile_path.read_bytes()
        try:
            ImageCms.ImageCmsProfile(BytesIO(profile_bytes))
        except Exception as exc:
            raise ValueError("Custom color profile file is not a valid ICC/ICM profile.") from exc
        return profile_bytes

    def validate_photo_color_profile(self, params: dict[str, Any]) -> dict[str, Any]:
        from io import BytesIO
        from PIL import ImageCms

        profile_path = self._photo_export_custom_profile_path(str(params.get("path", params.get("targetColorProfilePath", "")) or ""))
        profile_bytes = profile_path.read_bytes()
        try:
            profile = ImageCms.ImageCmsProfile(BytesIO(profile_bytes))
        except Exception as exc:
            raise ValueError("Custom color profile file is not a valid ICC/ICM profile.") from exc

        def cms_text(method_name: str) -> str:
            method = getattr(ImageCms, method_name, None)
            if not callable(method):
                return ""
            try:
                return str(method(profile) or "").strip()
            except Exception:
                return ""

        description = cms_text("getProfileDescription")
        name = cms_text("getProfileName")
        info = cms_text("getProfileInfo")
        return {
            "ok": True,
            "path": str(profile_path),
            "fileName": profile_path.name,
            "bytes": len(profile_bytes),
            "description": description,
            "name": name,
            "info": info[:1000],
        }

    def photo_color_profile_status(self, params: dict[str, Any]) -> dict[str, Any]:
        selected_target = self._photo_export_target_color_profile(
            str(params.get("targetColorProfile", params.get("colorProfileTarget", "")) or ""),
            bool(params.get("preserveColorProfile", True)),
        )
        custom_path = str(params.get("targetColorProfilePath", params.get("colorProfilePath", params.get("path", ""))) or "").strip()
        labels = {
            "source": "Source profile",
            "srgb": "sRGB",
            "display-p3": "Display P3",
            "adobe-rgb": "Adobe RGB",
            "custom-icc": "Custom ICC",
            "none": "Strip profile",
        }
        descriptions = {
            "source": "Use each photo's embedded source profile when present.",
            "srgb": "Convert rendered exports to a generated sRGB profile.",
            "display-p3": "Convert rendered exports to an installed Display P3 ICC profile.",
            "adobe-rgb": "Convert rendered exports to an installed Adobe RGB ICC profile.",
            "custom-icc": "Convert rendered exports to the selected custom ICC/ICM file.",
            "none": "Export rendered files without an embedded color profile.",
        }

        def base_profile(target: str) -> dict[str, Any]:
            return {
                "target": target,
                "label": labels.get(target, target),
                "description": descriptions.get(target, ""),
                "available": False,
                "selected": target == selected_target,
            }

        def profile_payload(target: str) -> dict[str, Any]:
            row = base_profile(target)
            if target == "source":
                return {
                    **row,
                    "available": True,
                    "source": "embedded",
                    "message": "Source profiles are preserved when a photo has one.",
                }
            if target == "none":
                return {
                    **row,
                    "available": True,
                    "source": "none",
                    "message": "Exports will omit embedded color-profile bytes.",
                }
            try:
                if target == "srgb":
                    profile_bytes = self._photo_export_srgb_profile_bytes()
                    return {
                        **row,
                        "available": True,
                        "source": "generated",
                        "bytes": len(profile_bytes),
                        "message": "Generated sRGB profile is available.",
                    }
                if target == "custom-icc":
                    validation = self.validate_photo_color_profile({"path": custom_path})
                    return {
                        **row,
                        "available": True,
                        "source": "custom",
                        "path": validation.get("path", ""),
                        "fileName": validation.get("fileName", ""),
                        "bytes": validation.get("bytes", 0),
                        "descriptionText": validation.get("description", ""),
                        "name": validation.get("name", ""),
                        "message": "Custom ICC profile is available.",
                    }
                candidates = self._photo_export_named_profile_candidates(target)
                for profile_path in candidates:
                    if not profile_path.exists():
                        continue
                    profile_bytes = self._photo_export_named_profile_bytes(target)
                    return {
                        **row,
                        "available": True,
                        "source": "system",
                        "path": str(profile_path),
                        "fileName": profile_path.name,
                        "bytes": len(profile_bytes),
                        "candidateCount": len(candidates),
                        "message": f"{labels.get(target, target)} profile is installed.",
                    }
                return {
                    **row,
                    "available": False,
                    "source": "system",
                    "candidateCount": len(candidates),
                    "error": f"{labels.get(target, target)} ICC profile is unavailable on this system.",
                }
            except Exception as exc:
                return {
                    **row,
                    "available": False,
                    "error": str(exc) or f"{labels.get(target, target)} profile is unavailable.",
                }

        targets = ["source", "srgb", "display-p3", "adobe-rgb", "custom-icc", "none"]
        profiles = [profile_payload(target) for target in targets]
        selected = next((profile for profile in profiles if profile.get("target") == selected_target), profiles[0])
        return {
            "targetColorProfile": selected_target,
            "targetColorProfilePath": custom_path if selected_target == "custom-icc" else "",
            "profiles": profiles,
            "selected": selected,
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
        }

    def _photo_export_profile_roots(self) -> list[Path]:
        raw_roots: list[str] = []
        for env_key in ("CROSSAGE_PHOTO_COLOR_PROFILE_ROOTS", "VINTRACE_PHOTO_COLOR_PROFILE_ROOTS"):
            raw_roots.extend(str(os.environ.get(env_key, "") or "").split(os.pathsep))
        raw_roots.extend([
            "~/Library/ColorSync/Profiles",
            "/System/Library/ColorSync/Profiles",
            "/Library/ColorSync/Profiles",
            "/usr/share/color/icc",
            "/usr/local/share/color/icc",
            "/var/lib/color/icc",
            "C:/Windows/System32/spool/drivers/color",
            "C:/Windows/System32/spool/drivers/color/Color",
        ])
        roots: list[Path] = []
        seen: set[str] = set()
        for raw_root in raw_roots:
            clean = str(raw_root or "").strip()
            if not clean:
                continue
            try:
                root = Path(clean).expanduser()
                key = str(root.resolve()) if root.exists() else str(root)
            except OSError:
                key = clean
                root = Path(clean).expanduser()
            if key in seen:
                continue
            seen.add(key)
            roots.append(root)
        return roots

    def _photo_export_named_profile_candidates(self, target_color_profile: str) -> list[Path]:
        profile_names = {
            "display-p3": [
                "Display P3.icc",
                "Display P3.icm",
                "DisplayP3.icc",
                "DisplayP3.icm",
                "Display-P3.icc",
                "Display-P3.icm",
                "display-p3.icc",
                "display-p3.icm",
                "P3.icc",
                "P3.icm",
            ],
            "adobe-rgb": [
                "AdobeRGB1998.icc",
                "AdobeRGB1998.icm",
                "Adobe RGB (1998).icc",
                "Adobe RGB (1998).icm",
                "Adobe RGB 1998.icc",
                "Adobe RGB 1998.icm",
                "Adobe-RGB-1998.icc",
                "Adobe-RGB-1998.icm",
                "AdobeRGB.icc",
                "AdobeRGB.icm",
                "CompatibleWithAdobeRGB1998.icc",
                "CompatibleWithAdobeRGB1998.icm",
            ],
        }
        names = profile_names.get(target_color_profile, [])
        candidates: list[Path] = []
        seen: set[str] = set()
        for root in self._photo_export_profile_roots():
            for name in names:
                direct = root / name
                key = str(direct)
                if key not in seen:
                    seen.add(key)
                    candidates.append(direct)
                for subdir in ("", "rgb", "RGB", "display", "Display", "named", "Named"):
                    nested = root / subdir / name if subdir else direct
                    key = str(nested)
                    if key not in seen:
                        seen.add(key)
                        candidates.append(nested)
        return candidates

    def _photo_export_named_profile_bytes(self, target_color_profile: str, target_color_profile_path: str = "") -> bytes:
        from io import BytesIO
        from PIL import ImageCms

        target = self._photo_export_target_color_profile(target_color_profile)
        if target == "srgb":
            return self._photo_export_srgb_profile_bytes()
        if target == "custom-icc":
            return self._photo_export_custom_profile_bytes(target_color_profile_path)
        labels = {
            "display-p3": "Display P3",
            "adobe-rgb": "Adobe RGB",
        }
        for profile_path in self._photo_export_named_profile_candidates(target):
            if profile_path.exists():
                profile_bytes = profile_path.read_bytes()
                ImageCms.ImageCmsProfile(BytesIO(profile_bytes))
                return profile_bytes
        raise RuntimeError(f"Target color profile {labels.get(target, target)} is unavailable on this system.")

    def _photo_export_apply_target_color_profile(
        self,
        image: Any,
        *,
        source_icc_profile: bytes | bytearray | None = None,
        target_color_profile: str = "source",
        target_color_profile_path: str = "",
        preserve_color_profile: bool = True,
    ) -> tuple[Any, bytes]:
        target = self._photo_export_target_color_profile(target_color_profile, preserve_color_profile)
        source_bytes = bytes(source_icc_profile) if isinstance(source_icc_profile, (bytes, bytearray)) else b""
        if target == "none":
            return image, b""
        if target == "source":
            return image, source_bytes if preserve_color_profile else b""
        if target not in {"srgb", "display-p3", "adobe-rgb", "custom-icc"}:
            return image, source_bytes if preserve_color_profile else b""

        from io import BytesIO
        from PIL import ImageCms

        target_bytes = self._photo_export_named_profile_bytes(target, target_color_profile_path=target_color_profile_path)
        alpha = image.getchannel("A") if "A" in image.getbands() else None
        rgb = image.convert("RGB")
        converted = rgb
        target_profile = ImageCms.ImageCmsProfile(BytesIO(target_bytes))
        if source_bytes:
            try:
                source_profile = ImageCms.ImageCmsProfile(BytesIO(source_bytes))
                converted = ImageCms.profileToProfile(rgb, source_profile, target_profile, outputMode="RGB")
            except Exception:
                converted = rgb
        elif target != "srgb":
            source_profile = ImageCms.ImageCmsProfile(ImageCms.createProfile("sRGB"))
            converted = ImageCms.profileToProfile(rgb, source_profile, target_profile, outputMode="RGB")
        if alpha is not None:
            converted = converted.convert("RGBA")
            converted.putalpha(alpha)
        return converted, target_bytes

    def _photo_export_save_pil_image(
        self,
        image: Any,
        target: Path,
        *,
        render_format: str,
        quality: int,
        max_dimension: int,
        metadata_payload: dict[str, Any] | None = None,
        icc_profile: bytes | bytearray | None = None,
        target_color_profile: str = "source",
        target_color_profile_path: str = "",
        preserve_color_profile: bool = True,
    ) -> tuple[int, int]:
        from PIL import Image

        output = image.copy()
        target.parent.mkdir(parents=True, exist_ok=True)
        if max_dimension > 0 and max(output.size) > max_dimension:
            resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", getattr(Image, "LANCZOS", 1))
            output.thumbnail((max_dimension, max_dimension), resampling)
        accessibility = self._photo_export_accessibility_fields(metadata_payload or {})
        xmp_text = self._photo_export_xmp(metadata_payload) if isinstance(metadata_payload, dict) and metadata_payload else ""
        xmp_bytes = xmp_text.encode("utf-8") if xmp_text and len(xmp_text.encode("utf-8")) <= 60000 else b""
        icc_profile_bytes = b""
        if isinstance(icc_profile, (bytes, bytearray)):
            candidate_icc_profile = bytes(icc_profile)
            if 0 < len(candidate_icc_profile) <= 4 * 1024 * 1024:
                icc_profile_bytes = candidate_icc_profile
        output, icc_profile_bytes = self._photo_export_apply_target_color_profile(
            output,
            source_icc_profile=icc_profile_bytes,
            target_color_profile=target_color_profile,
            target_color_profile_path=target_color_profile_path,
            preserve_color_profile=preserve_color_profile,
        )
        if not icc_profile_bytes:
            output.info.pop("icc_profile", None)
        image_description = accessibility.get("extendedDescription") or accessibility.get("altText") or ""
        if render_format == "jpeg":
            if output.mode not in {"RGB", "L"}:
                background = Image.new("RGB", output.size, "white")
                if "A" in output.getbands():
                    rgba = output.convert("RGBA")
                    background.paste(rgba, mask=rgba.getchannel("A"))
                else:
                    background.paste(output.convert("RGB"))
                output = background
            save_kwargs = {"quality": quality, "optimize": True}
            if xmp_bytes:
                save_kwargs["xmp"] = xmp_bytes
            if icc_profile_bytes:
                save_kwargs["icc_profile"] = icc_profile_bytes
            output.save(target, "JPEG", **save_kwargs)
        elif render_format == "png":
            if output.mode == "CMYK":
                output = output.convert("RGB")
            save_kwargs = {"optimize": True}
            if icc_profile_bytes:
                save_kwargs["icc_profile"] = icc_profile_bytes
            if image_description or xmp_text:
                from PIL.PngImagePlugin import PngInfo

                pnginfo = PngInfo()
                add_png_text = pnginfo.add_itxt if hasattr(pnginfo, "add_itxt") else pnginfo.add_text
                if image_description:
                    add_png_text("Description", image_description)
                if xmp_text:
                    add_png_text("XML:com.adobe.xmp", xmp_text)
                save_kwargs["pnginfo"] = pnginfo
            output.save(target, "PNG", **save_kwargs)
        elif render_format == "heic":
            try:
                import pillow_heif
            except Exception as exc:
                raise RuntimeError("Rendered HEIC export requires pillow-heif.") from exc
            pillow_heif.register_heif_opener()
            if output.mode not in {"RGB", "L"}:
                background = Image.new("RGB", output.size, "white")
                if "A" in output.getbands():
                    rgba = output.convert("RGBA")
                    background.paste(rgba, mask=rgba.getchannel("A"))
                else:
                    background.paste(output.convert("RGB"))
                output = background
            save_kwargs = {"quality": quality}
            if icc_profile_bytes:
                save_kwargs["icc_profile"] = icc_profile_bytes
            output.save(target, "HEIF", **save_kwargs)
        else:
            if output.mode == "P":
                output = output.convert("RGB")
            save_kwargs = {"compression": "tiff_lzw"}
            if icc_profile_bytes:
                save_kwargs["icc_profile"] = icc_profile_bytes
            if image_description or xmp_bytes:
                from PIL import TiffImagePlugin

                tiffinfo = TiffImagePlugin.ImageFileDirectory_v2()
                if image_description:
                    tiffinfo[270] = image_description
                if xmp_bytes:
                    tiffinfo[700] = xmp_bytes
                save_kwargs["tiffinfo"] = tiffinfo
            output.save(target, "TIFF", **save_kwargs)
        return int(output.width), int(output.height)

    def _photo_export_render_image(
        self,
        source: Path,
        target: Path,
        *,
        render_format: str,
        quality: int,
        max_dimension: int,
        metadata_payload: dict[str, Any] | None = None,
        preserve_color_profile: bool = True,
        target_color_profile: str = "source",
        target_color_profile_path: str = "",
    ) -> tuple[int, int]:
        output = load_image(source)
        icc_profile = output.info.get("icc_profile") if preserve_color_profile else None
        return self._photo_export_save_pil_image(
            output,
            target,
            render_format=render_format,
            quality=quality,
            max_dimension=max_dimension,
            metadata_payload=metadata_payload,
            icc_profile=icc_profile,
            target_color_profile=target_color_profile,
            target_color_profile_path=target_color_profile_path,
            preserve_color_profile=preserve_color_profile,
        )

    def _photo_video_frame_image(self, source: Path, timestamp_ms: int):
        try:
            import cv2
            from PIL import Image
        except Exception:
            cv2 = None
            Image = None

        if cv2 is not None and Image is not None:
            capture = cv2.VideoCapture(str(source))
            try:
                if capture.isOpened():
                    if timestamp_ms > 0:
                        capture.set(cv2.CAP_PROP_POS_MSEC, float(timestamp_ms))
                    ok, frame = capture.read()
                    if not ok or frame is None:
                        capture.set(cv2.CAP_PROP_POS_FRAMES, 0)
                        ok, frame = capture.read()
                    if ok and frame is not None:
                        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                        return Image.fromarray(rgb).convert("RGB")
            finally:
                capture.release()

        ffmpeg = (
            os.environ.get("VINTRACE_FFMPEG_PATH")
            or os.environ.get("CROSSAGE_FFMPEG_PATH")
            or shutil.which("ffmpeg")
            or ""
        )
        if not ffmpeg:
            raise VideoLoadError("Video still-frame export requires OpenCV or FFmpeg.")
        from PIL import Image

        with tempfile.TemporaryDirectory(prefix="vintrace-video-frame-") as temp_name:
            target = Path(temp_name) / "frame.png"
            seconds = max(0.0, float(timestamp_ms) / 1000.0)
            command = [
                ffmpeg,
                "-hide_banner",
                "-loglevel",
                "error",
                "-ss",
                f"{seconds:.3f}",
                "-i",
                str(source),
                "-frames:v",
                "1",
                "-y",
                str(target),
            ]
            completed = subprocess.run(command, capture_output=True, text=True, timeout=30, check=False)
            if completed.returncode != 0 or not target.exists():
                raise VideoLoadError((completed.stderr or completed.stdout or f"Could not decode frame from {source}").strip()[:400])
            with Image.open(target) as image:
                return image.convert("RGB")

    def _photo_existing_sidecar_candidates(self, resolved: Path) -> list[Path]:
        suffix = resolved.suffix
        sidecar_suffixes = [
            ".xmp",
            ".json",
            ".xml",
            ".aae",
            ".dop",
            ".pp3",
            ".on1",
            ".cos",
            ".dr4",
            ".dr5",
        ]
        candidates: dict[str, Path] = {}
        for sidecar_suffix in sidecar_suffixes:
            values = [
                resolved.with_suffix(sidecar_suffix),
                resolved.with_name(f"{resolved.name}{sidecar_suffix}"),
            ]
            if suffix:
                values.append(resolved.with_suffix(f"{suffix}{sidecar_suffix}"))
            for candidate in values:
                candidates[str(candidate)] = candidate
        results: list[Path] = []
        for candidate in candidates.values():
            try:
                sidecar = safe_resolve(candidate)
            except OSError:
                continue
            if sidecar == resolved or sidecar.parent != resolved.parent or not sidecar.is_file():
                continue
            results.append(sidecar)
        return sorted(results, key=lambda path: path.name.casefold())

    def _copy_photo_existing_sidecars(self, resolved: Path, sidecar_root: Path, sidecar_base: str) -> list[str]:
        candidates = self._photo_existing_sidecar_candidates(resolved)
        if not candidates:
            return []
        sidecar_root.mkdir(parents=True, exist_ok=True)
        copied: list[str] = []
        for candidate in candidates:
            base_name = self._safe_photo_export_name(f"{sidecar_base}-{candidate.name}")
            target = sidecar_root / base_name
            target_counter = 2
            while target.exists():
                stem = self._safe_photo_export_name(f"{sidecar_base}-{candidate.stem}")
                target = sidecar_root / f"{stem}-{target_counter}{candidate.suffix.lower() or '.sidecar'}"
                target_counter += 1
            try:
                shutil.copy2(candidate, target)
            except OSError:
                continue
            copied.append(str(target))
        return copied

    def _photo_export_sidecar_payload(self, source_path: str, *, strip_location: bool = False) -> dict[str, Any]:
        asset = self.project.db.photo_asset_by_path(str(source_path or ""))
        if not asset:
            return {"sourcePath": str(source_path or ""), "assetId": "", "metadata": {}, "people": [], "albums": []}
        asset_id = str(asset.get("assetId", "") or "")
        metadata = self.project.db.photo_asset_metadata_by_id(asset_id)
        if strip_location:
            metadata = {
                **metadata,
                "locationOverride": {},
                "locationHidden": True,
            }
            asset_metadata = dict(asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {})
            asset_metadata.pop("gps", None)
            if isinstance(asset_metadata.get("exif"), dict):
                exif = dict(asset_metadata["exif"])
                exif.pop("gps", None)
                asset_metadata["exif"] = exif
        else:
            asset_metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
        return {
            "assetId": asset_id,
            "sourcePath": str(asset.get("sourcePath", "") or source_path),
            "sourceKind": str(asset.get("sourceKind", "") or ""),
            "mediaKind": str(asset.get("mediaKind", "") or ""),
            "mimeType": str(asset.get("mimeType", "") or ""),
            "contentHash": str(asset.get("contentHash", "") or ""),
            "perceptualHash": str(asset.get("perceptualHash", "") or ""),
            "captureDate": str(asset.get("captureDate", "") or ""),
            "addedAt": str(asset.get("addedAt", "") or ""),
            "fileSignature": asset.get("fileSignature", {}) if isinstance(asset.get("fileSignature"), dict) else {},
            "locationStripped": bool(strip_location),
            "assetMetadata": asset_metadata,
            "metadata": metadata,
            "people": self.project.db.list_photo_asset_people(asset_id),
            "albums": self.project.db.list_photo_asset_album_memberships(asset_id),
        }

    def _photo_export_clean_text(self, value: Any, *, limit: int = 0) -> str:
        text = re.sub(r"\s+", " ", str(value or "").replace("\0", " ")).strip()
        if limit > 0 and len(text) > limit:
            text = f"{text[:max(0, limit - 3)].rstrip()}..."
        return text

    def _photo_export_accessibility_fields(self, payload: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(payload, dict):
            return {"altText": "", "extendedDescription": "", "descriptionRegions": []}
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        asset_metadata = payload.get("assetMetadata") if isinstance(payload.get("assetMetadata"), dict) else {}
        description_keys = ("accessibilityDescription", "accessibleDescription", "altText", "imageDescription", "markupDescription")
        description = ""
        for source in (metadata, asset_metadata):
            for key in description_keys:
                description = self._photo_export_clean_text(source.get(key))
                if description:
                    break
            if description:
                break
        raw_regions: Any = []
        for source in (metadata, asset_metadata):
            for key in ("descriptionRegions", "accessibilityRegions", "imageDescriptionRegions", "markupDescriptionRegions"):
                value = source.get(key)
                if isinstance(value, list) and value:
                    raw_regions = value
                    break
            if raw_regions:
                break
        regions = self._clean_photo_description_regions(raw_regions)
        region_lines: list[str] = []
        for index, region in enumerate(regions, start=1):
            region_text = self._photo_export_clean_text(region.get("text"))
            if not region_text:
                continue
            region_lines.append(
                "Region "
                f"{index}: {region_text} "
                f"({float(region.get('x', 0)):g}%, {float(region.get('y', 0)):g}%, "
                f"{float(region.get('width', 0)):g}% x {float(region.get('height', 0)):g}%)"
            )
        extended_parts = [description] if description else []
        extended_parts.extend(region_lines)
        extended = "\n".join(extended_parts)
        return {
            "altText": self._photo_export_clean_text(description, limit=250),
            "extendedDescription": extended,
            "descriptionRegions": regions,
        }

    def _photo_export_metadata_first_text(self, *values: Any) -> str:
        for value in values:
            for item in self.project.db._photo_asset_metadata_text_values(value):  # noqa: SLF001
                text = self._photo_export_clean_text(item)
                if text:
                    return text
        return ""

    def _photo_export_deduped_values(self, values: Iterable[Any]) -> list[str]:
        output: list[str] = []
        seen: set[str] = set()
        for value in values:
            text = self._photo_export_clean_text(value)
            key = text.casefold()
            if not text or key in seen:
                continue
            seen.add(key)
            output.append(text)
        return output

    def _photo_export_xmp_bag(self, tag: str, values: Iterable[Any]) -> list[str]:
        rows = [html.escape(value) for value in self._photo_export_deduped_values(values)]
        if not rows:
            return []
        return [f"      <{tag}><rdf:Bag>"] + [f"        <rdf:li>{value}</rdf:li>" for value in rows] + [f"      </rdf:Bag></{tag}>"]

    def _photo_export_xmp_seq(self, tag: str, values: Iterable[Any]) -> list[str]:
        rows = [html.escape(value) for value in self._photo_export_deduped_values(values)]
        if not rows:
            return []
        return [f"      <{tag}><rdf:Seq>"] + [f"        <rdf:li>{value}</rdf:li>" for value in rows] + [f"      </rdf:Seq></{tag}>"]

    def _photo_export_xmp_alt(self, tag: str, value: Any) -> list[str]:
        text = html.escape(self._photo_export_metadata_first_text(value))
        if not text:
            return []
        return [f"      <{tag}><rdf:Alt><rdf:li xml:lang=\"x-default\">{text}</rdf:li></rdf:Alt></{tag}>"]

    def _photo_export_people_names(self, payload: dict[str, Any]) -> list[str]:
        people = payload.get("people") if isinstance(payload.get("people"), list) else []
        return self._photo_export_deduped_values(
            person.get("personName", person.get("name", "")) if isinstance(person, dict) else person
            for person in people
        )

    def _photo_export_album_names(self, payload: dict[str, Any]) -> list[str]:
        albums = payload.get("albums") if isinstance(payload.get("albums"), list) else []
        return self._photo_export_deduped_values(
            album.get("name", album.get("albumName", "")) if isinstance(album, dict) else album
            for album in albums
        )

    def _photo_export_location_fields(self, payload: dict[str, Any]) -> dict[str, str]:
        if bool(payload.get("locationStripped")):
            return {}
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        if bool(metadata.get("locationHidden")):
            return {}
        asset_metadata = payload.get("assetMetadata") if isinstance(payload.get("assetMetadata"), dict) else {}
        xmp_metadata = asset_metadata.get("xmp") if isinstance(asset_metadata.get("xmp"), dict) else {}
        iptc_metadata = xmp_metadata.get("iptc") if isinstance(xmp_metadata.get("iptc"), dict) else {}
        location = metadata.get("locationOverride") if isinstance(metadata.get("locationOverride"), dict) else {}
        if not location:
            location = xmp_metadata.get("location") if isinstance(xmp_metadata.get("location"), dict) else {}
        if not location and isinstance(iptc_metadata.get("locationCreated"), dict):
            location = iptc_metadata.get("locationCreated", {})
        gps = {}
        exif = asset_metadata.get("exif") if isinstance(asset_metadata.get("exif"), dict) else {}
        if isinstance(exif.get("gps"), dict):
            gps = exif.get("gps", {})
        elif isinstance(asset_metadata.get("gps"), dict):
            gps = asset_metadata.get("gps", {})
        label = self._photo_export_clean_text(location.get("label", "") if isinstance(location, dict) else "")
        if not label and isinstance(location, dict):
            label = ", ".join(
                part for part in (
                    self._photo_export_clean_text(location.get("sublocation", "")),
                    self._photo_export_clean_text(location.get("city", "")),
                    self._photo_export_clean_text(location.get("state", "")),
                    self._photo_export_clean_text(location.get("country", "")),
                )
                if part
            )
        latitude = self._photo_export_clean_text(location.get("latitude", gps.get("latitude", "")) if isinstance(location, dict) else gps.get("latitude", ""))
        longitude = self._photo_export_clean_text(location.get("longitude", gps.get("longitude", "")) if isinstance(location, dict) else gps.get("longitude", ""))
        country_code = self._photo_export_clean_text(location.get("countryCode", "") if isinstance(location, dict) else "")
        if not country_code and isinstance(iptc_metadata.get("locationCreated"), dict):
            country_code = self._photo_export_clean_text(iptc_metadata.get("locationCreated", {}).get("countryCode", ""))
        parts = [self._photo_export_clean_text(part) for part in label.split(",") if self._photo_export_clean_text(part)]
        fields: dict[str, str] = {}
        if label:
            fields["location"] = parts[0] if parts else label
            if len(parts) == 2:
                fields["city"] = parts[1]
            elif len(parts) >= 3:
                fields["city"] = parts[-2]
                fields["country"] = parts[-1]
                if len(parts) >= 4:
                    fields["city"] = parts[1]
                    fields["state"] = parts[-2]
        if country_code:
            fields["countryCode"] = country_code
        if latitude and longitude:
            fields["latitude"] = latitude
            fields["longitude"] = longitude
        return fields

    def _photo_export_xmp_extended_lines(self, payload: dict[str, Any]) -> list[str]:
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        asset_metadata = payload.get("assetMetadata") if isinstance(payload.get("assetMetadata"), dict) else {}
        exif = asset_metadata.get("exif") if isinstance(asset_metadata.get("exif"), dict) else {}
        xmp_metadata = asset_metadata.get("xmp") if isinstance(asset_metadata.get("xmp"), dict) else {}
        iptc_metadata = xmp_metadata.get("iptc") if isinstance(xmp_metadata.get("iptc"), dict) else {}
        lines: list[str] = []
        rating = self._photo_export_metadata_first_text(metadata.get("rating"), asset_metadata.get("rating"), xmp_metadata.get("rating"))
        if rating:
            lines.append(f"      <xmp:Rating>{html.escape(rating)}</xmp:Rating>")
        lines.extend(self._photo_export_xmp_seq("dc:creator", self.project.db._photo_asset_metadata_text_values(iptc_metadata.get("creator"))))  # noqa: SLF001
        lines.extend(self._photo_export_xmp_alt("dc:rights", iptc_metadata.get("copyright")))
        lines.extend(self._photo_export_xmp_alt("xmpRights:UsageTerms", iptc_metadata.get("usageTerms")))
        credit = self._photo_export_metadata_first_text(iptc_metadata.get("credit"))
        if credit:
            lines.append(f"      <photoshop:Credit>{html.escape(credit)}</photoshop:Credit>")
        headline = self._photo_export_metadata_first_text(iptc_metadata.get("headline"))
        if headline:
            lines.append(f"      <photoshop:Headline>{html.escape(headline)}</photoshop:Headline>")
        event = self._photo_export_metadata_first_text(iptc_metadata.get("event"))
        if event:
            lines.append(f"      <Iptc4xmpExt:Event>{html.escape(event)}</Iptc4xmpExt:Event>")
        job_id = self._photo_export_metadata_first_text(iptc_metadata.get("jobId"))
        if job_id:
            lines.append(f"      <photoshop:TransmissionReference>{html.escape(job_id)}</photoshop:TransmissionReference>")
        instructions = self._photo_export_metadata_first_text(iptc_metadata.get("instructions"))
        if instructions:
            lines.append(f"      <photoshop:Instructions>{html.escape(instructions)}</photoshop:Instructions>")
        photographic_style = self._photo_export_metadata_first_text(
            metadata.get("photographicStyle"),
            metadata.get("cameraStyle"),
            asset_metadata.get("photographicStyle"),
            asset_metadata.get("photographicStyles"),
            asset_metadata.get("photoStyle"),
            asset_metadata.get("cameraStyle"),
            asset_metadata.get("captureStyle"),
            asset_metadata.get("pictureStyle"),
            asset_metadata.get("creativeStyle"),
            asset_metadata.get("styleName"),
            xmp_metadata.get("photographicStyle"),
            xmp_metadata.get("photographicStyles"),
            xmp_metadata.get("photoStyle"),
            xmp_metadata.get("cameraStyle"),
            xmp_metadata.get("captureStyle"),
            xmp_metadata.get("pictureStyle"),
            xmp_metadata.get("creativeStyle"),
            xmp_metadata.get("styleName"),
            xmp_metadata.get("profileName"),
            xmp_metadata.get("look"),
            exif.get("photographicStyle"),
            exif.get("cameraStyle"),
            exif.get("pictureStyle"),
        )
        if photographic_style:
            lines.append(f"      <xmp:PhotographicStyle>{html.escape(photographic_style)}</xmp:PhotographicStyle>")
        location = self._photo_export_location_fields(payload)
        if location.get("location"):
            lines.append(f"      <Iptc4xmpCore:Location>{html.escape(location['location'])}</Iptc4xmpCore:Location>")
        if location.get("city"):
            lines.append(f"      <photoshop:City>{html.escape(location['city'])}</photoshop:City>")
        if location.get("state"):
            lines.append(f"      <photoshop:State>{html.escape(location['state'])}</photoshop:State>")
        if location.get("countryCode"):
            lines.append(f"      <Iptc4xmpCore:CountryCode>{html.escape(location['countryCode'])}</Iptc4xmpCore:CountryCode>")
        if location.get("country"):
            lines.append(f"      <photoshop:Country>{html.escape(location['country'])}</photoshop:Country>")
        if location.get("latitude") and location.get("longitude"):
            lines.append(f"      <exif:GPSLatitude>{html.escape(location['latitude'])}</exif:GPSLatitude>")
            lines.append(f"      <exif:GPSLongitude>{html.escape(location['longitude'])}</exif:GPSLongitude>")
        camera_make = self._photo_export_metadata_first_text(exif.get("cameraMake"), exif.get("make"), asset_metadata.get("cameraMake"), asset_metadata.get("deviceMake"))
        camera_model = self._photo_export_metadata_first_text(exif.get("cameraModel"), exif.get("model"), asset_metadata.get("cameraModel"), asset_metadata.get("deviceModel"))
        lens = self._photo_export_metadata_first_text(exif.get("lensModel"), exif.get("lens"), asset_metadata.get("lensModel"), asset_metadata.get("lens"))
        software = self._photo_export_metadata_first_text(exif.get("software"), asset_metadata.get("software"), asset_metadata.get("editingSoftware"))
        if camera_make:
            lines.append(f"      <tiff:Make>{html.escape(camera_make)}</tiff:Make>")
        if camera_model:
            lines.append(f"      <tiff:Model>{html.escape(camera_model)}</tiff:Model>")
        if lens:
            lines.append(f"      <aux:Lens>{html.escape(lens)}</aux:Lens>")
        if software:
            lines.append(f"      <tiff:Software>{html.escape(software)}</tiff:Software>")
        lines.extend(self._photo_export_xmp_bag("Iptc4xmpExt:PersonInImage", self._photo_export_people_names(payload)))
        lines.extend(self._photo_export_xmp_bag("photoshop:SupplementalCategories", [f"Album: {name}" for name in self._photo_export_album_names(payload)]))
        return lines

    def _photo_export_xmp(self, payload: dict[str, Any]) -> str:
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        asset_metadata = payload.get("assetMetadata") if isinstance(payload.get("assetMetadata"), dict) else {}
        xmp_metadata = asset_metadata.get("xmp") if isinstance(asset_metadata.get("xmp"), dict) else {}
        iptc_metadata = xmp_metadata.get("iptc") if isinstance(xmp_metadata.get("iptc"), dict) else {}
        keywords = metadata.get("keywords", []) if isinstance(metadata.get("keywords"), list) else []
        title = html.escape(str(metadata.get("title", "") or ""))
        caption = html.escape(str(metadata.get("caption", "") or ""))
        keyword_lines = "\n".join(f"      <rdf:li>{html.escape(str(keyword))}</rdf:li>" for keyword in keywords if str(keyword).strip())
        date_text = html.escape(str(metadata.get("dateOverride", "") or payload.get("captureDate", "") or ""))
        source_path = html.escape(self._photo_export_metadata_first_text(iptc_metadata.get("source")) or str(payload.get("sourcePath", "") or ""))
        accessibility = self._photo_export_accessibility_fields(payload)
        alt_text = html.escape(str(accessibility.get("altText", "") or ""))
        extended_description = html.escape(str(accessibility.get("extendedDescription", "") or ""))
        accessibility_lines = []
        if alt_text:
            accessibility_lines.append(
                f"      <Iptc4xmpCore:AltTextAccessibility><rdf:Alt><rdf:li xml:lang=\"x-default\">{alt_text}</rdf:li></rdf:Alt></Iptc4xmpCore:AltTextAccessibility>"
            )
        if extended_description:
            accessibility_lines.append(
                f"      <Iptc4xmpCore:ExtDescrAccessibility><rdf:Alt><rdf:li xml:lang=\"x-default\">{extended_description}</rdf:li></rdf:Alt></Iptc4xmpCore:ExtDescrAccessibility>"
            )
        extended_lines = self._photo_export_xmp_extended_lines(payload)
        return "\n".join([
            '<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>',
            '<x:xmpmeta xmlns:x="adobe:ns:meta/">',
            '  <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">',
            '    <rdf:Description xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:photoshop="http://ns.adobe.com/photoshop/1.0/" xmlns:Iptc4xmpCore="http://iptc.org/std/Iptc4xmpCore/1.0/xmlns/" xmlns:Iptc4xmpExt="http://iptc.org/std/Iptc4xmpExt/2008-02-29/" xmlns:xmp="http://ns.adobe.com/xap/1.0/" xmlns:xmpRights="http://ns.adobe.com/xap/1.0/rights/" xmlns:exif="http://ns.adobe.com/exif/1.0/" xmlns:tiff="http://ns.adobe.com/tiff/1.0/" xmlns:aux="http://ns.adobe.com/exif/1.0/aux/">',
            f"      <dc:title><rdf:Alt><rdf:li xml:lang=\"x-default\">{title}</rdf:li></rdf:Alt></dc:title>",
            f"      <dc:description><rdf:Alt><rdf:li xml:lang=\"x-default\">{caption}</rdf:li></rdf:Alt></dc:description>",
            "      <dc:subject><rdf:Bag>",
            keyword_lines,
            "      </rdf:Bag></dc:subject>",
            f"      <photoshop:DateCreated>{date_text}</photoshop:DateCreated>",
            f"      <photoshop:Source>{source_path}</photoshop:Source>",
            *accessibility_lines,
            *extended_lines,
            "    </rdf:Description>",
            "  </rdf:RDF>",
            "</x:xmpmeta>",
            "<?xpacket end=\"w\"?>",
            "",
        ])

    def import_photos(self, params: dict[str, Any]) -> dict[str, Any]:
        source_paths = params.get("sourcePaths", [])
        if not isinstance(source_paths, list):
            raise ValueError("sourcePaths must be a list.")
        storage_mode = str(params.get("storageMode", "referenced") or "referenced").strip().lower()
        if storage_mode not in {"referenced", "managed"}:
            raise ValueError("Photo import storageMode must be referenced or managed.")
        managed_root_param = str(params.get("managedRoot", params.get("managedFolder", "")) or "").strip()
        managed_root = Path(managed_root_param).expanduser() if managed_root_param else self._photo_managed_root_from_settings()
        keep_folder_explicit = "keepFolderOrganization" in params or "keep_folder_organization" in params
        if keep_folder_explicit:
            keep_folder_organization = bool(params.get("keepFolderOrganization", params.get("keep_folder_organization", False)))
            keep_folder_source = "explicit"
        elif storage_mode == "managed":
            keep_folder_organization = self._photo_managed_root_keep_folder_default(self.photo_library_settings({}), managed_root)
            keep_folder_source = "root-default"
        else:
            keep_folder_organization = False
            keep_folder_source = "off"
        delete_from_source_requested = bool(params.get("deleteFromSourceAfterImport", params.get("deleteFromDeviceAfterImport", False)))
        # Broad "index everything on this computer" crawls prune caches / build
        # output / app bundles; always exclude our own app folder so we never
        # re-index generated previews or managed copies.
        apply_broad_excludes = bool(params.get("applyBroadExcludes", params.get("broadScan", False)))
        raw_excluded = params.get("excludedDirs", params.get("excluded_dirs", []))
        excluded_dirs = [str(item) for item in raw_excluded if str(item or "").strip()] if isinstance(raw_excluded, list) else []
        try:
            excluded_dirs.append(str(self.project.root))
        except Exception:
            pass
        result = self.project.db.import_photo_files(
            [str(path) for path in source_paths],
            storage_mode=storage_mode,
            managed_root=managed_root,
            source_kind=str(params.get("sourceKind", "folder") or "folder"),
            source_label=str(params.get("sourceLabel", "") or ""),
            source_detail=str(params.get("sourceDetail", params.get("source_detail", "")) or ""),
            keep_folder_organization=keep_folder_organization,
            excluded_dirs=excluded_dirs,
            apply_broad_excludes=apply_broad_excludes,
        )
        result["keepFolderOrganizationSource"] = keep_folder_source
        if storage_mode == "managed":
            managed_profile = self._photo_managed_root_profile_for_path(self.photo_library_settings({}), managed_root)
            managed_policy = managed_profile.get("policy", {}) if isinstance(managed_profile, dict) and isinstance(managed_profile.get("policy", {}), dict) else {}
            if not bool(managed_policy.get("externalBackupCovered", False)):
                backup_warnings = list(result.get("warnings") or [])
                backup_warnings.append(
                    {
                        "code": "managed-root-backup-not-covered",
                        "message": "This managed library has no external backup coverage configured; managed copies are not backed up off this device.",
                    }
                )
                result["warnings"] = backup_warnings
        if delete_from_source_requested:
            result = dict(result)
            warnings = list(result.get("warnings") or [])
            warnings.append(
                {
                    "code": "delete-from-source-not-supported",
                    "message": "Delete from camera/device after import is not available for this local import path; originals were left in place.",
                }
            )
            result["warnings"] = warnings
            result["deleteFromSourceAfterImport"] = False
            result["deleteFromSourceSupported"] = False
        self.project._append_audit(
            {
                "action": "import_photos",
                "import_id": result.get("importId", ""),
                "storage_mode": storage_mode,
                "source_kind": result.get("sourceKind", ""),
                "imported": int(result.get("importedCount", 0) or 0),
                "failed": int(result.get("failedCount", 0) or 0),
                "managed_root": result.get("managedRoot", ""),
                "keep_folder_organization": bool(result.get("keepFolderOrganization", False)),
                "delete_from_source_requested": delete_from_source_requested,
                "delete_from_source_supported": False,
            }
        )
        return result

    def update_photo_import_session_provenance(self, params: dict[str, Any]) -> dict[str, Any]:
        import_id = str(params.get("importId", params.get("import_id", "")) or "").strip()
        if not import_id:
            raise ValueError("importId is required.")
        source_kind = params.get("sourceKind", params.get("source_kind")) if "sourceKind" in params or "source_kind" in params else None
        source_label = params.get("sourceLabel", params.get("source_label")) if "sourceLabel" in params or "source_label" in params else None
        source_detail = params.get("sourceDetail", params.get("source_detail")) if "sourceDetail" in params or "source_detail" in params else None
        result = self.project.db.update_photo_import_session_provenance(
            import_id=import_id,
            source_kind=str(source_kind) if source_kind is not None else None,
            source_label=str(source_label) if source_label is not None else None,
            source_detail=str(source_detail) if source_detail is not None else None,
        )
        session = result.get("session", {}) if isinstance(result.get("session", {}), dict) else {}
        previous = result.get("previous", {}) if isinstance(result.get("previous", {}), dict) else {}
        self.project._append_audit(
            {
                "action": "update_photo_import_session_provenance",
                "import_id": import_id,
                "source_kind": session.get("sourceKind", ""),
                "source_label": session.get("sourceLabel", ""),
                "source_detail": session.get("sourceDetail", ""),
                "previous_source_kind": previous.get("sourceKind", ""),
                "previous_source_label": previous.get("sourceLabel", ""),
                "previous_source_detail": previous.get("sourceDetail", ""),
                "updated_assets": int(result.get("updatedAssets", 0) or 0),
            }
        )
        return result

    def bulk_update_photo_import_session_provenance(self, params: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(params, dict):
            raise ValueError("bulk_update_photo_import_session_provenance params must be an object.")
        raw_ids = params.get("importIds", params.get("import_ids", []))
        if isinstance(raw_ids, str):
            import_ids = [raw_ids]
        elif isinstance(raw_ids, (list, tuple)):
            import_ids = [str(value or "") for value in raw_ids]
        else:
            import_ids = []
        if not any(str(value or "").strip() for value in import_ids):
            raise ValueError("importIds is required.")
        source_kind = params.get("sourceKind", params.get("source_kind")) if "sourceKind" in params or "source_kind" in params else None
        source_label = params.get("sourceLabel", params.get("source_label")) if "sourceLabel" in params or "source_label" in params else None
        source_detail = params.get("sourceDetail", params.get("source_detail")) if "sourceDetail" in params or "source_detail" in params else None
        result = self.project.db.bulk_update_photo_import_session_provenance(
            import_ids=import_ids,
            source_kind=str(source_kind) if source_kind is not None else None,
            source_label=str(source_label) if source_label is not None else None,
            source_detail=str(source_detail) if source_detail is not None else None,
        )
        self.project._append_audit(
            {
                "action": "bulk_update_photo_import_session_provenance",
                "requested": len([value for value in import_ids if str(value or "").strip()]),
                "changed": int(result.get("changed", 0) or 0),
                "missing": len(result.get("missing", [])),
                "updated_assets": int(result.get("updatedAssets", 0) or 0),
                "source_kind": str(source_kind) if source_kind is not None else "",
                "source_label": str(source_label) if source_label is not None else "",
            }
        )
        return result

    def archive_photo_import_sessions(self, params: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(params, dict):
            raise ValueError("archive_photo_import_sessions params must be an object.")
        raw_ids = params.get("importIds", params.get("import_ids", []))
        if isinstance(raw_ids, str):
            import_ids = [raw_ids]
        elif isinstance(raw_ids, (list, tuple)):
            import_ids = [str(value or "") for value in raw_ids]
        else:
            import_id = str(params.get("importId", params.get("import_id", "")) or "")
            import_ids = [import_id] if import_id else []
        archive = bool(params.get("archive", True))
        reason = str(params.get("reason", "") or "")
        result = self.project.db.archive_photo_import_sessions(
            import_ids=import_ids,
            archive=archive,
            reason=reason,
        )
        self.project._append_audit(
            {
                "action": "archive_photo_import_sessions" if archive else "restore_photo_import_sessions",
                "requested": len(result.get("importIds", [])),
                "changed": int(result.get("changed", 0) or 0),
                "missing": len(result.get("missing", [])),
                "archived": bool(result.get("archived", False)),
                "reason": result.get("reason", ""),
            }
        )
        return result

    def export_photo_selection(
        self,
        source_paths: list[str],
        folder: Path | None = None,
        action: str = "export",
        *,
        include_metadata: bool = False,
        include_xmp: bool = False,
        include_existing_sidecars: bool = False,
        strip_location: bool = False,
        layout: str = "bundle",
        filename_mode: str = "numbered",
        filename_template: str = "",
        subfolder_template: str = "",
        export_variant: str = "original",
        render_format: str = "jpeg",
        render_quality: Any = 92,
        render_max_dimension: Any = 0,
        preserve_color_profile: bool = True,
        target_color_profile: str = "",
        target_color_profile_path: str = "",
        allow_render_fallback: bool = True,
        video_render_format: str = "mp4",
        video_render_quality: str = "medium",
    ) -> dict[str, Any]:
        unique_paths = [path for path in dict.fromkeys(str(path or "").strip() for path in source_paths) if path]
        if not unique_paths:
            raise ValueError("Select at least one photo first.")
        action = str(action or "export").strip().lower()
        if action not in {"export", "copy", "move"}:
            raise ValueError("Photo selection action must be export, copy, or move.")
        layout = str(layout or "bundle").strip().lower()
        if layout not in {"bundle", "flat"}:
            raise ValueError("Photo export layout must be bundle or flat.")
        filename_mode = str(filename_mode or "numbered").strip().lower()
        if filename_mode not in {"numbered", "original", "template"}:
            raise ValueError("Photo export filenameMode must be numbered, original, or template.")
        filename_template = str(filename_template or "").strip()
        subfolder_template = str(subfolder_template or "").strip()
        export_variant = str(export_variant or "original").strip().lower()
        if export_variant not in {"original", "rendered"}:
            raise ValueError("Photo exportVariant must be original or rendered.")
        if export_variant == "rendered" and action != "export":
            raise ValueError("Rendered photo export is only available for export actions.")
        target_color_profile = self._photo_export_target_color_profile(target_color_profile, preserve_color_profile)
        target_color_profile_path = str(self._photo_export_custom_profile_path(target_color_profile_path)) if target_color_profile == "custom-icc" and export_variant == "rendered" else ""
        preserve_color_profile = target_color_profile != "none"
        render_format, render_quality, render_max_dimension, render_suffix = self._photo_export_render_settings({
            "renderFormat": render_format,
            "renderQuality": render_quality,
            "renderMaxDimension": render_max_dimension,
        })
        video_render_format, video_render_quality, video_render_suffix = self._photo_export_video_settings({
            "videoRenderFormat": video_render_format,
            "videoRenderQuality": video_render_quality,
        })
        export_root = (folder or self.project.root / "exports").expanduser().resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_root = export_root / f"vintrace-photo-selection-{stamp}"
        counter = 2
        while bundle_root.exists():
            bundle_root = export_root / f"vintrace-photo-selection-{stamp}-{counter}"
            counter += 1
        media_root = bundle_root / "media" if layout == "bundle" else bundle_root
        media_root.mkdir(parents=True, exist_ok=True)
        metadata_root = bundle_root / "metadata"
        if include_metadata or include_xmp or include_existing_sidecars:
            metadata_root.mkdir(parents=True, exist_ok=True)
        existing_sidecar_root = metadata_root / "existing-sidecars"
        copied = 0
        moved = 0
        missing = 0
        duplicate = 0
        metadata_written = 0
        xmp_written = 0
        existing_sidecars_written = 0
        rendered = 0
        video_rendered = 0
        edit_stack_rendered = 0
        raw_proxy_rendered = 0
        render_fallback = 0
        skipped = 0
        rows: list[dict[str, Any]] = []
        copied_sources: set[str] = set()
        moved_items: list[dict[str, Any]] = []

        def append_render_skip(source_value: str, reason: str, result_code: str = "render_skipped_strip_location") -> None:
            rows.append({
                "sourcePath": source_value,
                "targetPath": "",
                "result": f"{result_code}: {reason}",
                "metadataPath": "",
                "xmpPath": "",
                "existingSidecarPaths": [],
                "exportVariant": "rendered",
                "renderFormat": "",
                "videoRenderFormat": "",
                "videoRenderQuality": "",
                "targetColorProfile": "",
                "targetColorProfilePath": "",
                "editStackId": "",
                "rawRenderProxyPath": "",
                "videoTrimStartMs": "",
                "videoTrimEndMs": "",
                "videoTrimDurationMs": "",
                "videoSourceDurationMs": "",
                "videoRotateDegrees": "",
                "videoCropAspect": "",
                "videoTransformApplied": "",
                "videoEditTimeline": "",
                "videoEditTransform": "",
                "videoEditRender": "",
                "videoEditSummary": "",
            })

        for index, source_value in enumerate(unique_paths, start=1):
            source = Path(source_value).expanduser()
            try:
                resolved = safe_resolve(source)
                exists = resolved.exists() and resolved.is_file()
            except OSError as exc:
                rows.append({"sourcePath": source_value, "targetPath": "", "result": f"stat_error: {exc}"})
                missing += 1
                continue
            if not exists:
                rows.append({"sourcePath": source_value, "targetPath": "", "result": "missing"})
                missing += 1
                continue
            source_key = str(resolved)
            if source_key in copied_sources:
                rows.append({"sourcePath": source_value, "targetPath": "", "result": "duplicate_source"})
                duplicate += 1
                continue
            source_suffix = resolved.suffix.lower() or ".bin"
            rendered_requested = export_variant == "rendered"
            should_render_image = rendered_requested and source_suffix in IMAGE_EXTENSIONS
            should_render_video = rendered_requested and source_suffix in VIDEO_EXTENSIONS
            asset = self.project.db.photo_asset_by_path(str(resolved)) or self.project.db.photo_asset_by_path(source_value)
            edit_stack = self.project.db.photo_edit_stack_by_asset(asset_id=str(asset.get("assetId", ""))) if asset else None
            target_suffix = render_suffix if should_render_image else video_render_suffix if should_render_video else source_suffix
            payload = self._photo_export_sidecar_payload(source_value, strip_location=strip_location)
            rendered_metadata_payload = payload if include_xmp else None
            template_context = self._photo_export_template_context(resolved, index, payload)
            target_root = self._photo_export_template_folder(media_root, subfolder_template, template_context)
            original_name = self._safe_photo_export_name(resolved.stem)
            if filename_mode == "template":
                base_name = self._photo_export_render_template_name(filename_template, template_context, f"{index:05d}-{resolved.stem}")
            else:
                base_name = original_name
            target = self._photo_export_allocate_target(
                target_root,
                index=index,
                base_name=base_name,
                suffix=target_suffix,
                filename_mode=filename_mode,
            )
            try:
                row_render_format = ""
                row_video_render_quality = ""
                row_edit_stack_id = ""
                row_raw_render_proxy_path = ""
                row_video_trim_start_ms: Any = ""
                row_video_trim_end_ms: Any = ""
                row_video_trim_duration_ms: Any = ""
                row_video_source_duration_ms: Any = ""
                row_video_rotate_degrees: Any = ""
                row_video_crop_aspect = ""
                row_video_transform_applied: Any = ""
                row_video_edit_timeline = ""
                row_video_edit_transform = ""
                row_video_edit_render = ""
                row_video_edit_summary = ""
                if should_render_image:
                    try:
                        edit_operations = edit_stack.get("operations", []) if isinstance(edit_stack, dict) else []
                        rendered_edit = None
                        render_source = resolved
                        raw_render_proxy_path = ""
                        is_raw_source = source_suffix in RAW_IMAGE_EXTENSIONS
                        if is_raw_source:
                            raw_render_proxy_path = self._photo_raw_preview_proxy_path(
                                str(resolved),
                                self.project.db.photo_media_pairs_for_asset(str(asset.get("assetId", ""))) if asset else None,
                            )
                        if isinstance(edit_operations, list) and edit_operations:
                            try:
                                rendered_edit = self._photo_edit_stack_render_image_operations(
                                    resolved,
                                    target,
                                    [operation for operation in edit_operations if isinstance(operation, dict)],
                                    render_format=render_format,
                                    quality=render_quality,
                                    max_dimension=render_max_dimension,
                                    preserve_color_profile=preserve_color_profile,
                                    target_color_profile=target_color_profile,
                                    target_color_profile_path=target_color_profile_path,
                                    metadata_payload=rendered_metadata_payload,
                                )
                            except Exception:
                                if not (is_raw_source and raw_render_proxy_path):
                                    raise
                                render_source = safe_resolve(Path(raw_render_proxy_path).expanduser())
                                rendered_edit = self._photo_edit_stack_render_image_operations(
                                    render_source,
                                    target,
                                    [operation for operation in edit_operations if isinstance(operation, dict)],
                                    render_format=render_format,
                                    quality=render_quality,
                                    max_dimension=render_max_dimension,
                                    preserve_color_profile=preserve_color_profile,
                                    target_color_profile=target_color_profile,
                                    target_color_profile_path=target_color_profile_path,
                                    metadata_payload=rendered_metadata_payload,
                                )
                        if rendered_edit is not None:
                            edit_stack_rendered += 1
                            row_edit_stack_id = str(edit_stack.get("editId", "") or "") if isinstance(edit_stack, dict) else ""
                            result = "rendered_raw_proxy_edit" if render_source != resolved else "rendered_edit"
                        else:
                            try:
                                self._photo_export_render_image(
                                    resolved,
                                    target,
                                    render_format=render_format,
                                    quality=render_quality,
                                    max_dimension=render_max_dimension,
                                    metadata_payload=rendered_metadata_payload,
                                    preserve_color_profile=preserve_color_profile,
                                    target_color_profile=target_color_profile,
                                    target_color_profile_path=target_color_profile_path,
                                )
                                result = "rendered"
                            except Exception:
                                if not (is_raw_source and raw_render_proxy_path):
                                    raise
                                render_source = safe_resolve(Path(raw_render_proxy_path).expanduser())
                                self._photo_export_render_image(
                                    render_source,
                                    target,
                                    render_format=render_format,
                                    quality=render_quality,
                                    max_dimension=render_max_dimension,
                                    metadata_payload=rendered_metadata_payload,
                                    preserve_color_profile=preserve_color_profile,
                                    target_color_profile=target_color_profile,
                                    target_color_profile_path=target_color_profile_path,
                                )
                                result = "rendered_raw_proxy"
                        if render_source != resolved:
                            row_raw_render_proxy_path = str(render_source)
                            raw_proxy_rendered += 1
                        copied += 1
                        rendered += 1
                        row_render_format = render_format
                    except Exception as exc:
                        if not allow_render_fallback:
                            skipped += 1
                            append_render_skip(source_value, str(exc)[:240] or "render failed", result_code="render_skipped_strip_location" if strip_location else "render_error")
                            continue
                        target = self._photo_export_allocate_target(
                            target_root,
                            index=index,
                            base_name=base_name,
                            suffix=source_suffix,
                            filename_mode=filename_mode,
                        )
                        shutil.copy2(resolved, target)
                        copied += 1
                        render_fallback += 1
                        result = f"copied_original_render_fallback: {exc}"
                elif should_render_video:
                    try:
                        edit_operations = edit_stack.get("operations", []) if isinstance(edit_stack, dict) else []
                        video_edit = self._photo_export_video_edit_stack_settings(
                            [operation for operation in edit_operations if isinstance(operation, dict)]
                            if isinstance(edit_operations, list)
                            else []
                        )
                        self._photo_export_render_video(
                            resolved,
                            target,
                            video_format=video_render_format,
                            quality=video_render_quality,
                            max_dimension=render_max_dimension,
                            trim_start_ms=int(video_edit.get("startMs", 0) or 0),
                            trim_end_ms=int(video_edit.get("endMs", 0) or 0),
                            video_rotate_degrees=int(video_edit.get("rotateDegrees", 0) or 0),
                            video_crop_aspect=str(video_edit.get("cropAspect", "none") or "none"),
                            strip_metadata=bool(strip_location),
                        )
                        copied += 1
                        rendered += 1
                        video_rendered += 1
                        if bool(video_edit.get("applied")):
                            edit_stack_rendered += 1
                            row_edit_stack_id = str(edit_stack.get("editId", "") or "") if isinstance(edit_stack, dict) else ""
                            row_video_trim_start_ms = int(video_edit.get("startMs", 0) or 0)
                            row_video_trim_end_ms = int(video_edit.get("endMs", 0) or 0)
                            row_video_trim_duration_ms = int(video_edit.get("trimDurationMs", 0) or 0)
                            row_video_source_duration_ms = int(video_edit.get("sourceDurationMs", 0) or 0)
                            row_video_rotate_degrees = int(video_edit.get("rotateDegrees", 0) or 0)
                            row_video_crop_aspect = str(video_edit.get("cropAspect", "none") or "none")
                            row_video_transform_applied = bool(video_edit.get("transformApplied"))
                            row_video_edit_timeline = str(video_edit.get("timelineLabel", "") or "")
                            row_video_edit_transform = str(video_edit.get("transformLabel", "") or "")
                            row_video_edit_render = " ".join(
                                part
                                for part in [
                                    video_render_format.upper(),
                                    video_render_quality,
                                    f"max {render_max_dimension}px" if render_max_dimension else "",
                                ]
                                if part
                            )
                            row_video_edit_summary = " / ".join(
                                part
                                for part in [row_video_edit_timeline, row_video_edit_transform, row_video_edit_render]
                                if part
                            )
                            result = "rendered_video_edit"
                        else:
                            result = "rendered_video"
                        row_render_format = video_render_format
                        row_video_render_quality = video_render_quality
                    except Exception as exc:
                        if not allow_render_fallback:
                            skipped += 1
                            append_render_skip(source_value, str(exc)[:240] or "render failed", result_code="render_skipped_strip_location" if strip_location else "render_error")
                            continue
                        target = self._photo_export_allocate_target(
                            target_root,
                            index=index,
                            base_name=base_name,
                            suffix=source_suffix,
                            filename_mode=filename_mode,
                        )
                        shutil.copy2(resolved, target)
                        copied += 1
                        render_fallback += 1
                        result = f"copied_original_render_fallback: {exc}"
                elif rendered_requested:
                    if not allow_render_fallback:
                        skipped += 1
                        append_render_skip(source_value, "unsupported media", result_code="render_skipped_strip_location" if strip_location else "render_error")
                        continue
                    shutil.copy2(resolved, target)
                    copied += 1
                    render_fallback += 1
                    result = "copied_original_render_fallback: unsupported media"
                elif action == "move":
                    shutil.move(str(resolved), str(target))
                    moved += 1
                    result = "moved"
                    moved_items.append(
                        {
                            "assetId": str(asset.get("assetId", "") or "") if asset else "",
                            "sourcePath": str(resolved),
                            "targetPath": str(target),
                        }
                    )
                else:
                    shutil.copy2(resolved, target)
                    copied += 1
                    result = "copied"
                copied_sources.add(source_key)
                metadata_path = ""
                xmp_path = ""
                existing_sidecar_paths: list[str] = []
                try:
                    relative_sidecar = target.relative_to(media_root).with_suffix("").as_posix()
                except ValueError:
                    relative_sidecar = target.stem
                sidecar_base = self._safe_photo_export_name(relative_sidecar)
                if include_metadata or include_xmp:
                    if include_metadata:
                        metadata_path_obj = metadata_root / f"{sidecar_base}.metadata.json"
                        metadata_path_obj.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
                        metadata_path = str(metadata_path_obj)
                        metadata_written += 1
                    if include_xmp:
                        xmp_path_obj = metadata_root / f"{sidecar_base}.xmp"
                        xmp_path_obj.write_text(self._photo_export_xmp(payload), encoding="utf-8")
                        xmp_path = str(xmp_path_obj)
                        xmp_written += 1
                if include_existing_sidecars:
                    existing_sidecar_paths = self._copy_photo_existing_sidecars(resolved, existing_sidecar_root, sidecar_base)
                    existing_sidecars_written += len(existing_sidecar_paths)
                rows.append({
                    "sourcePath": source_value,
                    "targetPath": str(target),
                    "result": result,
                    "metadataPath": metadata_path,
                    "xmpPath": xmp_path,
                    "existingSidecarPaths": existing_sidecar_paths,
                    "exportVariant": "rendered" if row_render_format else "original",
                    "renderFormat": row_render_format,
                    "videoRenderFormat": video_render_format if should_render_video and row_render_format else "",
                    "videoRenderQuality": row_video_render_quality,
                    "targetColorProfile": target_color_profile if row_render_format and not should_render_video else "",
                    "targetColorProfilePath": target_color_profile_path if row_render_format and not should_render_video and target_color_profile == "custom-icc" else "",
                    "editStackId": row_edit_stack_id,
                    "rawRenderProxyPath": row_raw_render_proxy_path,
                    "videoTrimStartMs": row_video_trim_start_ms,
                    "videoTrimEndMs": row_video_trim_end_ms,
                    "videoTrimDurationMs": row_video_trim_duration_ms,
                    "videoSourceDurationMs": row_video_source_duration_ms,
                    "videoRotateDegrees": row_video_rotate_degrees,
                    "videoCropAspect": row_video_crop_aspect,
                    "videoTransformApplied": row_video_transform_applied,
                    "videoEditTimeline": row_video_edit_timeline,
                    "videoEditTransform": row_video_edit_transform,
                    "videoEditRender": row_video_edit_render,
                    "videoEditSummary": row_video_edit_summary,
                })
            except OSError as exc:
                missing += 1
                rows.append({"sourcePath": source_value, "targetPath": "", "result": f"{action}_error: {exc}", "metadataPath": "", "xmpPath": "", "exportVariant": export_variant, "renderFormat": "", "videoRenderFormat": "", "videoRenderQuality": "", "targetColorProfile": "", "targetColorProfilePath": ""})
        manifest = {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "workspace": str(self.project.root),
            "action": action,
            "exportVariant": export_variant,
            "renderFormat": render_format,
            "renderQuality": render_quality,
            "renderMaxDimension": render_max_dimension,
            "preserveColorProfile": bool(preserve_color_profile),
            "targetColorProfile": target_color_profile,
            "targetColorProfilePath": target_color_profile_path if target_color_profile == "custom-icc" else "",
            "videoRenderFormat": video_render_format,
            "videoRenderQuality": video_render_quality,
            "layout": layout,
            "filenameMode": filename_mode,
            "filenameTemplate": filename_template,
            "subfolderTemplate": subfolder_template,
            "includeMetadata": bool(include_metadata),
            "includeXmp": bool(include_xmp),
            "includeExistingSidecars": bool(include_existing_sidecars),
            "stripLocation": bool(strip_location),
            "allowRenderFallback": bool(allow_render_fallback),
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "metadataPath": str(metadata_root) if include_metadata or include_xmp or include_existing_sidecars else "",
            "counts": {
                "selected": len(unique_paths),
                "copied": copied,
                "moved": moved,
                "missing": missing,
                "duplicate": duplicate,
                "metadata": metadata_written,
                "xmp": xmp_written,
                "existingSidecars": existing_sidecars_written,
                "rendered": rendered,
                "videoRendered": video_rendered,
                "editStackRendered": edit_stack_rendered,
                "rawProxyRendered": raw_proxy_rendered,
                "renderFallback": render_fallback,
                "skipped": skipped,
            },
            "items": rows,
            "note": "Original export preserves source media bytes. Rendered export writes new local image files for supported image originals, can render RAW originals from same-stem image proxies when native RAW decoding is unavailable, and can render MP4, MOV, M4V, WebM, HEVC, or ProRes files for supported video originals. Saved video trim, rotate, and crop edits are applied to rendered video exports when present. Metadata sidecars are optional and generated from local library metadata.",
        }
        manifest_path = bundle_root / "manifest.json"
        csv_path = bundle_root / "manifest.csv"
        manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        with csv_path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=["sourcePath", "targetPath", "result", "metadataPath", "xmpPath", "existingSidecarPaths", "exportVariant", "renderFormat", "videoRenderFormat", "videoRenderQuality", "targetColorProfile", "targetColorProfilePath", "editStackId", "rawRenderProxyPath", "videoTrimStartMs", "videoTrimEndMs", "videoTrimDurationMs", "videoSourceDurationMs", "videoRotateDegrees", "videoCropAspect", "videoTransformApplied", "videoEditTimeline", "videoEditTransform", "videoEditRender", "videoEditSummary"])
            writer.writeheader()
            for row in rows:
                writer.writerow({**row, "existingSidecarPaths": json.dumps(row.get("existingSidecarPaths", []))})
        shared_sources = [
            str(row.get("sourcePath", "") or "")
            for row in rows
            if (
                str(row.get("result", "") or "") in {"copied", "moved", "rendered", "rendered_edit", "rendered_raw_proxy", "rendered_raw_proxy_edit", "rendered_video", "rendered_video_edit"}
                or str(row.get("result", "") or "").startswith("copied_original_render_fallback")
            ) and str(row.get("sourcePath", "") or "")
        ]
        shared_event = self.project.db.record_photo_asset_events(
            "shared",
            shared_sources,
            actor=self.actor,
            metadata={
                "action": action,
                "bundlePath": str(bundle_root),
                "layout": layout,
                "filenameMode": filename_mode,
                "filenameTemplate": filename_template,
                "subfolderTemplate": subfolder_template,
                "includeExistingSidecars": bool(include_existing_sidecars),
                "exportVariant": export_variant,
                "renderFormat": render_format,
                "preserveColorProfile": bool(preserve_color_profile),
                "targetColorProfile": target_color_profile,
                "targetColorProfilePath": target_color_profile_path if target_color_profile == "custom-icc" else "",
                "videoRenderFormat": video_render_format,
                "videoRenderQuality": video_render_quality,
            },
        ) if shared_sources else {"eventType": "shared", "recorded": 0, "sourcePaths": []}
        operation: dict[str, Any] = {}
        if moved_items:
            with self.project.db.connect() as conn:
                for item in moved_items:
                    if item.get("assetId"):
                        self.project.db.refresh_photo_asset_missing_status(asset_id=str(item.get("assetId", "")), conn=conn)
                    else:
                        self.project.db.refresh_photo_asset_missing_status(source_path=str(item.get("sourcePath", "")), conn=conn)
                operation = self.project.db.record_photo_file_move_operation(
                    operation_type="file_move",
                    label=f"Moved {len(moved_items)} photo original{'s' if len(moved_items) != 1 else ''}",
                    items=moved_items,
                    conn=conn,
                )
        self.project._append_audit(
            {
                "action": "export_photo_selection",
                "selection_action": action,
                "bundle_path": str(bundle_root),
                "selected": len(unique_paths),
                "copied": copied,
                "moved": moved,
                "missing": missing,
                "metadata": metadata_written,
                "xmp": xmp_written,
                "existing_sidecars": existing_sidecars_written,
                "rendered": rendered,
                "video_rendered": video_rendered,
                "edit_stack_rendered": edit_stack_rendered,
                "raw_proxy_rendered": raw_proxy_rendered,
                "render_fallback": render_fallback,
                "skipped": skipped,
                "operation_id": operation.get("operationId", "") if isinstance(operation, dict) else "",
                "strip_location": bool(strip_location),
                "allow_render_fallback": bool(allow_render_fallback),
                "filename_mode": filename_mode,
                "filename_template": filename_template,
                "subfolder_template": subfolder_template,
                "export_variant": export_variant,
                "render_format": render_format,
                "preserve_color_profile": bool(preserve_color_profile),
                "target_color_profile": target_color_profile,
                "target_color_profile_path": target_color_profile_path if target_color_profile == "custom-icc" else "",
                "video_render_format": video_render_format,
                "video_render_quality": video_render_quality,
            }
        )
        return {
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "metadataPath": str(metadata_root) if include_metadata or include_xmp or include_existing_sidecars else "",
            "manifestPath": str(manifest_path),
            "csvPath": str(csv_path),
            "stripLocation": bool(strip_location),
            "allowRenderFallback": bool(allow_render_fallback),
            "includeExistingSidecars": bool(include_existing_sidecars),
            "exportVariant": export_variant,
            "renderFormat": render_format,
            "renderQuality": render_quality,
            "renderMaxDimension": render_max_dimension,
            "preserveColorProfile": bool(preserve_color_profile),
            "targetColorProfile": target_color_profile,
            "targetColorProfilePath": target_color_profile_path if target_color_profile == "custom-icc" else "",
            "videoRenderFormat": video_render_format,
            "videoRenderQuality": video_render_quality,
            "filenameTemplate": filename_template,
            "subfolderTemplate": subfolder_template,
            "counts": manifest["counts"],
            "items": rows,
            "sharedEvent": shared_event,
            "operation": operation,
        }

    def export_photo_contact_sheet(self, params: dict[str, Any]) -> dict[str, Any]:
        source_paths = params.get("sourcePaths", [])
        if not isinstance(source_paths, list):
            raise ValueError("sourcePaths must be a list.")
        unique_paths = list(dict.fromkeys(str(path) for path in source_paths if str(path).strip()))
        if not unique_paths:
            raise ValueError("Select at least one photo or video for a contact sheet.")
        output_format = str(params.get("format", params.get("renderFormat", "pdf")) or "pdf").strip().lower()
        output_format = {"jpg": "jpeg"}.get(output_format, output_format)
        if output_format not in {"pdf", "png", "jpeg"}:
            raise ValueError("Photo contact sheet format must be pdf, png, or jpeg.")
        layout_raw = str(params.get("layoutPreset", params.get("printLayout", "custom")) or "custom").strip().lower()
        layout_key = layout_raw.replace("-", "_").replace(" ", "_")
        layout_aliases = {
            "": "custom",
            "grid": "custom",
            "custom": "custom",
            "custom_grid": "custom",
            "contact": "custom",
            "contact_sheet": "custom",
            "full": "full_page",
            "full_page": "full_page",
            "one_up": "full_page",
            "1_up": "full_page",
            "2_up": "two_up",
            "two_up": "two_up",
            "4_up": "four_up",
            "four_up": "four_up",
            "wallet": "wallet",
            "wallets": "wallet",
        }
        layout_preset = layout_aliases.get(layout_key)
        if layout_preset is None:
            raise ValueError("Contact sheet layout preset must be custom, full_page, two_up, four_up, or wallet.")
        layout_specs = {
            "custom": {},
            "full_page": {"columns": 1, "thumbnailSize": 1024, "rowsPerPage": 1},
            "two_up": {"columns": 1, "thumbnailSize": 620, "rowsPerPage": 2},
            "four_up": {"columns": 2, "thumbnailSize": 520, "rowsPerPage": 2},
            "wallet": {"columns": 4, "thumbnailSize": 250},
        }
        layout_spec = layout_specs[layout_preset]
        if layout_preset == "custom":
            try:
                columns = max(1, min(8, int(params.get("columns", 4) or 4)))
            except (TypeError, ValueError):
                columns = 4
            try:
                thumb_size = max(96, min(512, int(params.get("thumbnailSize", params.get("thumbSize", 220)) or 220)))
            except (TypeError, ValueError):
                thumb_size = 220
        else:
            columns = int(layout_spec.get("columns", 4))
            thumb_size = int(layout_spec.get("thumbnailSize", 220))
        try:
            render_quality = max(1, min(100, int(params.get("quality", params.get("renderQuality", 92)) or 92)))
        except (TypeError, ValueError):
            render_quality = 92
        include_captions = bool(params.get("includeCaptions", True))
        caption_mode = str(
            params.get("captionMode", params.get("captionPreset", params.get("metadataPreset", "title_date_people"))) or "title_date_people"
        ).strip().lower().replace("-", "_")
        caption_aliases = {
            "": "title_date_people",
            "default": "title_date_people",
            "basic": "title_date_people",
            "title": "title_date_people",
            "title_date": "title_date_people",
            "people": "title_date_people",
            "title_people": "title_date_people",
            "title_date_people": "title_date_people",
            "metadata": "metadata",
            "full": "metadata",
            "full_metadata": "metadata",
            "keywords": "metadata",
            "filename": "filename",
            "file": "filename",
            "path": "filename",
            "none": "none",
            "off": "none",
        }
        caption_mode = caption_aliases.get(caption_mode)
        if caption_mode is None:
            raise ValueError("Contact sheet caption mode must be title_date_people, metadata, filename, or none.")
        if caption_mode == "none":
            include_captions = False
        title = self._photo_export_clean_text(params.get("title", ""), limit=120) or "Vintrace contact sheet"
        page_size_name = str(params.get("pageSize", "letter") or "letter").strip().lower()
        page_size_name = {"us-letter": "letter", "us_letter": "letter", "8.5x11": "letter", "a4": "a4"}.get(page_size_name, page_size_name)
        if page_size_name not in {"letter", "a4"}:
            page_size_name = "letter"
        page_width, page_height = (1240, 1754) if page_size_name == "a4" else (1275, 1650)
        margin = 54
        gap = 22
        header_height = 78
        caption_line_limit = {"filename": 1, "title_date_people": 3, "metadata": 4, "none": 0}[caption_mode]
        caption_height = max(34, 18 + caption_line_limit * 15) if include_captions else 20
        cell_width = max(96, int((page_width - (margin * 2) - (gap * (columns - 1))) / columns))
        tile_size = min(thumb_size, cell_width)
        cell_height = tile_size + caption_height
        rows_per_page = max(1, int((page_height - (margin * 2) - header_height) / cell_height))
        row_cap = int(layout_spec.get("rowsPerPage", 0) or 0)
        if row_cap:
            rows_per_page = max(1, min(rows_per_page, row_cap))
        per_page = max(1, rows_per_page * columns)
        folder_param = str(params.get("folder", "") or "").strip()
        export_root = (Path(folder_param).expanduser() if folder_param else self.project.root / "exports").resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_root = export_root / f"vintrace-contact-sheet-{stamp}"
        counter = 2
        while bundle_root.exists():
            bundle_root = export_root / f"vintrace-contact-sheet-{stamp}-{counter}"
            counter += 1
        bundle_root.mkdir(parents=True, exist_ok=True)

        from PIL import Image, ImageDraw, ImageFont, ImageOps

        font = ImageFont.load_default()
        title_font = ImageFont.load_default()
        thumbs: list[dict[str, Any]] = []
        rows: list[dict[str, Any]] = []
        counts = {
            "selected": len(unique_paths),
            "included": 0,
            "missing": 0,
            "unsupported": 0,
            "duplicate": max(0, len([path for path in source_paths if str(path).strip()]) - len(unique_paths)),
            "pages": 0,
        }

        def contact_label(payload: dict[str, Any], resolved: Path) -> str:
            metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
            title_value = self._photo_export_clean_text(metadata.get("title", ""), limit=120) or resolved.name
            if caption_mode == "filename":
                return resolved.name
            date_value = self._photo_export_clean_text(metadata.get("dateOverride", "") or payload.get("captureDate", ""), limit=32)[:10]
            people = self._photo_export_people_names(payload)[:3]
            details = " · ".join(value for value in [date_value, ", ".join(people)] if value)
            if caption_mode != "metadata":
                return f"{title_value}\n{details}" if details else title_value
            keywords = metadata.get("keywords", []) if isinstance(metadata.get("keywords"), list) else []
            keyword_text = ", ".join(self._photo_export_deduped_values(keywords)[:4])
            location_fields = self._photo_export_location_fields(payload)
            location_text = location_fields.get("location", "")
            file_text = resolved.name
            lines = [title_value]
            if details:
                lines.append(details)
            if keyword_text:
                lines.append(f"Keywords: {keyword_text}")
            if location_text:
                lines.append(f"Place: {location_text}")
            if file_text and file_text != title_value:
                lines.append(file_text)
            return "\n".join(lines)

        for index, source_value in enumerate(unique_paths, start=1):
            source = Path(source_value).expanduser()
            row = {
                "index": index,
                "sourcePath": source_value,
                "result": "missing",
                "label": source.name or "Photo",
                "mediaKind": "",
                "error": "",
            }
            try:
                resolved = safe_resolve(source)
            except OSError as exc:
                row["error"] = str(exc)
                rows.append(row)
                thumbs.append({"row": row, "image": None})
                counts["missing"] += 1
                continue
            row["sourcePath"] = str(resolved)
            if not resolved.exists() or not resolved.is_file():
                row["error"] = "Source file is missing."
                rows.append(row)
                thumbs.append({"row": row, "image": None})
                counts["missing"] += 1
                continue
            suffix = resolved.suffix.lower()
            payload = self._photo_export_sidecar_payload(str(resolved))
            row["label"] = contact_label(payload, resolved)
            try:
                if suffix in IMAGE_EXTENSIONS:
                    thumb = load_image(resolved).convert("RGB")
                    row["mediaKind"] = "image"
                elif suffix in VIDEO_EXTENSIONS:
                    thumb = self._photo_video_frame_image(resolved, 0).convert("RGB")
                    row["mediaKind"] = "video"
                else:
                    raise ValueError("Unsupported contact-sheet media type.")
                resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", getattr(Image, "LANCZOS", 1))
                thumb.thumbnail((tile_size, tile_size), resampling)
                row["result"] = "included"
                counts["included"] += 1
                thumbs.append({"row": row, "image": thumb})
            except Exception as exc:
                row["result"] = "unsupported"
                row["error"] = str(exc)[:240]
                counts["unsupported"] += 1
                thumbs.append({"row": row, "image": None})
            rows.append(row)

        def text_width(draw: Any, text: str) -> int:
            if hasattr(draw, "textlength"):
                return int(draw.textlength(text, font=font))
            return int(draw.textsize(text, font=font)[0])

        def wrap_lines(draw: Any, text: str, max_width: int, max_lines: int) -> list[str]:
            output: list[str] = []
            for source_line in str(text or "").splitlines() or [""]:
                words = source_line.split()
                if not words:
                    output.append("")
                    continue
                line = ""
                for word in words:
                    candidate = f"{line} {word}".strip()
                    if text_width(draw, candidate) <= max_width or not line:
                        line = candidate
                    else:
                        output.append(line)
                        line = word
                        if len(output) >= max_lines:
                            break
                if len(output) >= max_lines:
                    break
                output.append(line)
                if len(output) >= max_lines:
                    break
            if len(output) > max_lines:
                output = output[:max_lines]
            if output and text_width(draw, output[-1]) > max_width:
                line = output[-1]
                while line and text_width(draw, f"{line}...") > max_width:
                    line = line[:-1]
                output[-1] = f"{line}..." if line else "..."
            return output[:max_lines]

        pages = max(1, math.ceil(len(thumbs) / per_page))
        page_images: list[Any] = []
        generated_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        for page_number in range(pages):
            page = Image.new("RGB", (page_width, page_height), "white")
            draw = ImageDraw.Draw(page)
            header = f"{title} · {len(unique_paths)} selected · page {page_number + 1}/{pages}"
            draw.text((margin, margin - 16), header, fill=(24, 24, 27), font=title_font)
            draw.text((margin, margin + 4), generated_at, fill=(100, 100, 108), font=font)
            start = page_number * per_page
            page_items = thumbs[start:start + per_page]
            for local_index, item in enumerate(page_items):
                row = item["row"]
                image = item["image"]
                grid_row = local_index // columns
                grid_col = local_index % columns
                x = margin + grid_col * (cell_width + gap)
                y = margin + header_height + grid_row * cell_height
                thumb_x = x + max(0, (cell_width - tile_size) // 2)
                draw.rectangle((thumb_x, y, thumb_x + tile_size, y + tile_size), outline=(210, 210, 216), width=2)
                if image is not None:
                    paste_x = thumb_x + max(0, (tile_size - image.width) // 2)
                    paste_y = y + max(0, (tile_size - image.height) // 2)
                    page.paste(image, (paste_x, paste_y))
                    if row.get("mediaKind") == "video":
                        draw.rectangle((thumb_x + 8, y + 8, thumb_x + 56, y + 28), fill=(24, 24, 27))
                        draw.text((thumb_x + 13, y + 12), "VIDEO", fill="white", font=font)
                else:
                    placeholder = "Missing" if row.get("result") == "missing" else "Unsupported"
                    draw.text((thumb_x + 12, y + max(12, tile_size // 2 - 6)), placeholder, fill=(140, 36, 36), font=font)
                if include_captions:
                    lines = wrap_lines(draw, str(row.get("label", "") or Path(str(row.get("sourcePath", ""))).name), cell_width, caption_line_limit)
                    for line_index, line in enumerate(lines):
                        draw.text((x, y + tile_size + 9 + line_index * 14), line, fill=(36, 36, 41), font=font)
            page_images.append(page)
        counts["pages"] = len(page_images)

        target_paths: list[str] = []
        if output_format == "pdf":
            target = self._photo_export_allocate_target(bundle_root, index=1, base_name="contact-sheet", suffix=".pdf", filename_mode="original")
            if len(page_images) == 1:
                page_images[0].save(target, "PDF", resolution=150.0)
            else:
                page_images[0].save(target, "PDF", resolution=150.0, save_all=True, append_images=page_images[1:])
            target_paths.append(str(target))
        else:
            suffix = ".jpg" if output_format == "jpeg" else ".png"
            for page_number, page in enumerate(page_images, start=1):
                base_name = "contact-sheet" if len(page_images) == 1 else f"contact-sheet-{page_number:03d}"
                target = self._photo_export_allocate_target(bundle_root, index=page_number, base_name=base_name, suffix=suffix, filename_mode="original")
                self._photo_export_save_pil_image(
                    page,
                    target,
                    render_format=output_format,
                    quality=render_quality,
                    max_dimension=0,
                )
                target_paths.append(str(target))

        manifest = {
            "generatedAt": generated_at,
            "workspace": str(self.project.root),
            "action": "export_photo_contact_sheet",
            "bundlePath": str(bundle_root),
            "format": output_format,
            "layoutPreset": layout_preset,
            "columns": columns,
            "thumbnailSize": thumb_size,
            "effectiveColumns": columns,
            "effectiveThumbnailSize": thumb_size,
            "includeCaptions": include_captions,
            "captionMode": caption_mode,
            "title": title,
            "pageSize": page_size_name,
            "targetPath": target_paths[0] if target_paths else "",
            "targetPaths": target_paths,
            "counts": counts,
            "items": rows,
            "note": "Contact sheet generated locally from selected original media. Missing or unsupported sources are represented as placeholders and counted in this manifest.",
        }
        manifest_path = bundle_root / "manifest.json"
        manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        included_sources = [str(row.get("sourcePath", "") or "") for row in rows if row.get("result") == "included"]
        shared_event = self.project.db.record_photo_asset_events(
            "shared",
            included_sources,
            actor=self.actor,
            metadata={
                "action": "export_photo_contact_sheet",
                "bundlePath": str(bundle_root),
                "format": output_format,
                "layoutPreset": layout_preset,
                "columns": columns,
                "thumbnailSize": thumb_size,
                "captionMode": caption_mode,
                "pageSize": page_size_name,
            },
        ) if included_sources else {"eventType": "shared", "recorded": 0, "sourcePaths": []}
        self.project._append_audit(
            {
                "action": "export_photo_contact_sheet",
                "bundle_path": str(bundle_root),
                "selected": len(unique_paths),
                "included": counts["included"],
                "missing": counts["missing"],
                "unsupported": counts["unsupported"],
                "format": output_format,
                "layout_preset": layout_preset,
                "caption_mode": caption_mode,
                "page_size": page_size_name,
                "pages": counts["pages"],
            }
        )
        return {
            "bundlePath": str(bundle_root),
            "targetPath": target_paths[0] if target_paths else "",
            "targetPaths": target_paths,
            "manifestPath": str(manifest_path),
            "format": output_format,
            "layoutPreset": layout_preset,
            "columns": columns,
            "thumbnailSize": thumb_size,
            "effectiveColumns": columns,
            "effectiveThumbnailSize": thumb_size,
            "includeCaptions": include_captions,
            "captionMode": caption_mode,
            "title": title,
            "pageSize": page_size_name,
            "counts": counts,
            "items": rows,
            "sharedEvent": shared_event,
        }

    def export_photo_video_frame(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        if not source_value:
            raise ValueError("sourcePath is required.")
        source = Path(source_value).expanduser()
        try:
            resolved = safe_resolve(source)
        except OSError as exc:
            raise FileNotFoundError(f"Video source is not available: {source_value}") from exc
        if not resolved.exists() or not resolved.is_file():
            raise FileNotFoundError(f"Video source is not available: {source_value}")
        if resolved.suffix.lower() not in VIDEO_EXTENSIONS:
            raise ValueError("Video still-frame export requires a video source.")
        poster_frame_reused = bool(params.get("usePosterFrame") or str(params.get("timestampSource", "") or "").strip().lower() == "poster")
        poster_preview_path = ""
        if poster_frame_reused:
            asset = self.project.db.photo_asset_by_path(str(resolved))
            asset_metadata = asset.get("metadata", {}) if isinstance(asset, dict) and isinstance(asset.get("metadata", {}), dict) else {}
            poster_metadata = asset_metadata.get("videoPoster") if isinstance(asset_metadata.get("videoPoster"), dict) else {}
            if not poster_metadata:
                raise ValueError("Video does not have a saved poster frame.")
            try:
                timestamp_ms = max(0, int(poster_metadata.get("timestampMs", 0) or 0))
            except (TypeError, ValueError):
                timestamp_ms = 0
            poster_preview_path = str(poster_metadata.get("previewPath", "") or "")
        else:
            try:
                timestamp_ms = max(0, int(params.get("timestampMs", params.get("timestamp", 0)) or 0))
            except (TypeError, ValueError):
                timestamp_ms = 0
        render_format, render_quality, render_max_dimension, render_suffix = self._photo_export_render_settings(params)
        folder_param = str(params.get("folder", "") or "").strip()
        export_root = (Path(folder_param).expanduser() if folder_param else self.project.root / "exports").resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_root = export_root / f"vintrace-video-frame-{stamp}"
        counter = 2
        while bundle_root.exists():
            bundle_root = export_root / f"vintrace-video-frame-{stamp}-{counter}"
            counter += 1
        media_root = bundle_root / "media"
        media_root.mkdir(parents=True, exist_ok=True)
        base_name = f"{resolved.stem}-poster-{timestamp_ms:010d}ms" if poster_frame_reused else f"{resolved.stem}-{timestamp_ms:010d}ms"
        target = self._photo_export_allocate_target(
            media_root,
            index=1,
            base_name=base_name,
            suffix=render_suffix,
            filename_mode="original",
        )
        probe: dict[str, Any]
        try:
            probe = dict(probe_video(resolved))
        except Exception as exc:
            probe = {"error": str(exc), "durationMs": 0, "width": 0, "height": 0}
        frame = self._photo_video_frame_image(resolved, timestamp_ms)
        width, height = self._photo_export_save_pil_image(
            frame,
            target,
            render_format=render_format,
            quality=render_quality,
            max_dimension=render_max_dimension,
        )
        manifest = {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "workspace": str(self.project.root),
            "action": "export_photo_video_frame",
            "sourcePath": str(resolved),
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "timestampMs": timestamp_ms,
            "posterFrameReused": poster_frame_reused,
            "posterTimestampMs": timestamp_ms if poster_frame_reused else None,
            "posterPreviewPath": poster_preview_path,
            "renderFormat": render_format,
            "renderQuality": render_quality,
            "renderMaxDimension": render_max_dimension,
            "width": width,
            "height": height,
            "durationMs": int(probe.get("durationMs", 0) or 0),
            "sourceWidth": int(probe.get("width", 0) or 0),
            "sourceHeight": int(probe.get("height", 0) or 0),
            "probe": probe,
            "note": "Still frame exported from the local video source at timestampMs using local decoder support.",
        }
        manifest_path = bundle_root / "manifest.json"
        manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        shared_event = self.project.db.record_photo_asset_events(
            "shared",
            [str(resolved)],
            actor=self.actor,
            metadata={
                "action": "export_photo_video_frame",
                "bundlePath": str(bundle_root),
                "targetPath": str(target),
                "timestampMs": timestamp_ms,
                "posterFrameReused": poster_frame_reused,
                "renderFormat": render_format,
            },
        )
        self.project._append_audit(
            {
                "action": "export_photo_video_frame",
                "source_path": str(resolved),
                "target_path": str(target),
                "bundle_path": str(bundle_root),
                "timestamp_ms": timestamp_ms,
                "poster_frame_reused": poster_frame_reused,
                "render_format": render_format,
                "render_max_dimension": render_max_dimension,
            }
        )
        return {
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "manifestPath": str(manifest_path),
            "sourcePath": str(resolved),
            "timestampMs": timestamp_ms,
            "posterFrameReused": poster_frame_reused,
            "posterTimestampMs": timestamp_ms if poster_frame_reused else None,
            "posterPreviewPath": poster_preview_path,
            "renderFormat": render_format,
            "renderQuality": render_quality,
            "renderMaxDimension": render_max_dimension,
            "width": width,
            "height": height,
            "durationMs": int(probe.get("durationMs", 0) or 0),
            "sharedEvent": shared_event,
        }

    def export_photo_video_trim(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        if not source_value:
            raise ValueError("sourcePath is required.")
        source = Path(source_value).expanduser()
        try:
            resolved = safe_resolve(source)
        except OSError as exc:
            raise FileNotFoundError(f"Video source is not available: {source_value}") from exc
        if not resolved.exists() or not resolved.is_file():
            raise FileNotFoundError(f"Video source is not available: {source_value}")
        if resolved.suffix.lower() not in VIDEO_EXTENSIONS:
            raise ValueError("Video trim export requires a video source.")
        try:
            probe = dict(probe_video(resolved))
        except Exception as exc:
            probe = {"error": str(exc), "durationMs": 0, "width": 0, "height": 0}
        try:
            start_ms = max(0, int(params.get("startMs", params.get("trimStartMs", 0)) or 0))
        except (TypeError, ValueError):
            start_ms = 0
        raw_end = params.get("endMs", params.get("trimEndMs", None))
        try:
            end_ms = int(raw_end) if raw_end is not None and str(raw_end).strip() != "" else 0
        except (TypeError, ValueError):
            end_ms = 0
        duration_ms = max(0, int(probe.get("durationMs", 0) or 0))
        if duration_ms > 0:
            if end_ms <= 0:
                end_ms = duration_ms
            end_ms = min(duration_ms, max(0, end_ms))
            if start_ms >= duration_ms:
                raise ValueError("Video trim start must be before the end of the source video.")
        elif end_ms <= 0:
            raise ValueError("Video trim export requires trimEndMs when duration is unknown.")
        trim_duration_ms = max(0, end_ms - start_ms)
        if trim_duration_ms < 250:
            raise ValueError("Video trim must be at least 250 ms long.")
        video_render_format, video_render_quality, video_render_suffix = self._photo_export_video_settings(params)
        video_rotate_degrees, video_crop_aspect = self._photo_export_video_transform_settings(params)
        try:
            render_max_dimension = max(0, min(20000, int(params.get("renderMaxDimension", params.get("maxDimension", 0)) or 0)))
        except (TypeError, ValueError):
            render_max_dimension = 0
        folder_param = str(params.get("folder", "") or "").strip()
        export_root = (Path(folder_param).expanduser() if folder_param else self.project.root / "exports").resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_root = export_root / f"vintrace-video-trim-{stamp}"
        counter = 2
        while bundle_root.exists():
            bundle_root = export_root / f"vintrace-video-trim-{stamp}-{counter}"
            counter += 1
        media_root = bundle_root / "media"
        media_root.mkdir(parents=True, exist_ok=True)
        transform_suffix = ""
        if video_rotate_degrees:
            transform_suffix += f"-r{video_rotate_degrees}"
        if video_crop_aspect != "none":
            transform_suffix += f"-crop-{video_crop_aspect}"
        base_name = f"{resolved.stem}-{start_ms:010d}ms-{end_ms:010d}ms{transform_suffix}-trim"
        target = self._photo_export_allocate_target(
            media_root,
            index=1,
            base_name=base_name,
            suffix=video_render_suffix,
            filename_mode="original",
        )
        self._photo_export_render_video(
            resolved,
            target,
            video_format=video_render_format,
            quality=video_render_quality,
            max_dimension=render_max_dimension,
            trim_start_ms=start_ms,
            trim_end_ms=end_ms,
            video_rotate_degrees=video_rotate_degrees,
            video_crop_aspect=video_crop_aspect,
        )
        manifest = {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "workspace": str(self.project.root),
            "action": "export_photo_video_trim",
            "sourcePath": str(resolved),
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "startMs": start_ms,
            "endMs": end_ms,
            "trimDurationMs": trim_duration_ms,
            "sourceDurationMs": duration_ms,
            "videoRenderFormat": video_render_format,
            "videoRenderQuality": video_render_quality,
            "renderMaxDimension": render_max_dimension,
            "videoRotateDegrees": video_rotate_degrees,
            "videoCropAspect": video_crop_aspect,
            "videoTransformApplied": bool(video_rotate_degrees or video_crop_aspect != "none"),
            "sourceWidth": int(probe.get("width", 0) or 0),
            "sourceHeight": int(probe.get("height", 0) or 0),
            "probe": probe,
            "note": "Video trim/transform exported non-destructively from the local source video using local FFmpeg support.",
        }
        manifest_path = bundle_root / "manifest.json"
        manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        shared_event = self.project.db.record_photo_asset_events(
            "shared",
            [str(resolved)],
            actor=self.actor,
            metadata={
                "action": "export_photo_video_trim",
                "bundlePath": str(bundle_root),
                "targetPath": str(target),
                "startMs": start_ms,
                "endMs": end_ms,
                "videoRenderFormat": video_render_format,
                "videoRenderQuality": video_render_quality,
                "videoRotateDegrees": video_rotate_degrees,
                "videoCropAspect": video_crop_aspect,
            },
        )
        self.project._append_audit(
            {
                "action": "export_photo_video_trim",
                "source_path": str(resolved),
                "target_path": str(target),
                "bundle_path": str(bundle_root),
                "start_ms": start_ms,
                "end_ms": end_ms,
                "trim_duration_ms": trim_duration_ms,
                "video_render_format": video_render_format,
                "video_render_quality": video_render_quality,
                "video_rotate_degrees": video_rotate_degrees,
                "video_crop_aspect": video_crop_aspect,
            }
        )
        return {
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "manifestPath": str(manifest_path),
            "sourcePath": str(resolved),
            "startMs": start_ms,
            "endMs": end_ms,
            "trimDurationMs": trim_duration_ms,
            "sourceDurationMs": duration_ms,
            "videoRenderFormat": video_render_format,
            "videoRenderQuality": video_render_quality,
            "renderMaxDimension": render_max_dimension,
            "videoRotateDegrees": video_rotate_degrees,
            "videoCropAspect": video_crop_aspect,
            "videoTransformApplied": bool(video_rotate_degrees or video_crop_aspect != "none"),
            "sharedEvent": shared_event,
        }

    def _photo_live_motion_source(self, source_value: str) -> tuple[Path, dict[str, Any], dict[str, Any], Path]:
        if not source_value:
            raise ValueError("sourcePath is required.")
        source = Path(source_value).expanduser()
        try:
            resolved = safe_resolve(source)
        except OSError as exc:
            raise FileNotFoundError(f"Live Photo source is not available: {source_value}") from exc
        if not resolved.exists() or not resolved.is_file():
            raise FileNotFoundError(f"Live Photo source is not available: {source_value}")
        asset = self.project.db.photo_asset_by_path(str(resolved))
        if not asset:
            raise ValueError("Live Photo must be imported into Photos before using its motion clip.")
        metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
        live_photo = metadata.get("livePhoto") if isinstance(metadata.get("livePhoto"), dict) else {}
        paired_value = str(live_photo.get("pairedVideoPath", "") or "")
        if not paired_value:
            raise ValueError("This photo does not have a paired Live Photo motion clip.")
        try:
            motion = safe_resolve(Path(paired_value).expanduser())
        except OSError as exc:
            raise FileNotFoundError(f"Live Photo motion clip is not available: {paired_value}") from exc
        if not motion.exists() or not motion.is_file():
            raise FileNotFoundError(f"Live Photo motion clip is not available: {paired_value}")
        if motion.suffix.lower() not in VIDEO_EXTENSIONS:
            raise ValueError("Live Photo motion clip must be a local video file.")
        return resolved, asset, live_photo, motion

    def _photo_live_motion_export_variant(self, params: dict[str, Any]) -> str:
        raw = str(
            params.get(
                "exportVariant",
                params.get("variant", params.get("format", params.get("motionFormat", "motion"))),
            )
            or "motion"
        ).strip().lower().replace("-", "_")
        if raw in {"motion", "video", "clip", "mov", "mp4", "original"}:
            return "motion"
        if raw in {"gif", "animated_gif", "loop", "loop_gif"}:
            return "loop_gif"
        if raw in {"bounce", "bounce_gif"}:
            return "bounce_gif"
        raise ValueError("Live Photo exportVariant must be motion, gif, loop, or bounce.")

    def _photo_live_motion_gif_frames(
        self,
        motion: Path,
        probe: dict[str, Any],
        *,
        variant: str,
        max_frames: int,
        max_edge: int,
    ) -> tuple[list[Any], int, int, list[int]]:
        duration_ms = max(0, int(probe.get("durationMs", 0) or 0))
        max_frames = max(2, min(48, int(max_frames or 18)))
        max_edge = max(0, min(2000, int(max_edge or 720)))
        from PIL import Image

        if duration_ms > 0:
            base_frames = max(2, min(max_frames, int(math.ceil(duration_ms / 90.0)) or 2))
            last_ms = max(0, duration_ms - 1)
            timestamps = [
                min(last_ms, int(round((last_ms * index) / max(1, base_frames - 1))))
                for index in range(base_frames)
            ]
        else:
            timestamps = [index * 100 for index in range(max_frames)]
        frames = []
        resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", getattr(Image, "LANCZOS", 1))
        for timestamp_ms in timestamps:
            frame = self._photo_video_frame_image(motion, timestamp_ms).convert("RGB")
            if max_edge:
                frame.thumbnail((max_edge, max_edge), resampling)
            frames.append(frame)
        if not frames:
            raise VideoLoadError("Could not decode Live Photo motion frames for GIF export.")
        original_count = len(frames)
        if variant == "bounce_gif" and len(frames) > 2:
            frames = frames + [frame.copy() for frame in frames[-2:0:-1]]
        frame_duration_ms = 90
        if duration_ms > 0 and original_count > 0:
            frame_duration_ms = max(40, min(250, int(round(duration_ms / original_count))))
        return frames, frame_duration_ms, original_count, timestamps

    def export_photo_live_motion(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        resolved, asset, live_photo, motion = self._photo_live_motion_source(source_value)
        export_variant = self._photo_live_motion_export_variant(params)
        folder_param = str(params.get("folder", "") or "").strip()
        export_root = (Path(folder_param).expanduser() if folder_param else self.project.root / "exports").resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_name = "vintrace-live-photo-motion" if export_variant == "motion" else f"vintrace-live-photo-{export_variant.replace('_', '-')}"
        bundle_root = export_root / f"{bundle_name}-{stamp}"
        counter = 2
        while bundle_root.exists():
            bundle_root = export_root / f"{bundle_name}-{stamp}-{counter}"
            counter += 1
        media_root = bundle_root / "media"
        media_root.mkdir(parents=True, exist_ok=True)
        target_suffix = motion.suffix.lower() or ".mov"
        base_name = f"{self._safe_photo_export_name(resolved.stem)}-motion"
        if export_variant in {"loop_gif", "bounce_gif"}:
            target_suffix = ".gif"
            base_name = f"{self._safe_photo_export_name(resolved.stem)}-{export_variant.replace('_gif', '')}"
        target = self._photo_export_allocate_target(
            media_root,
            index=1,
            base_name=base_name,
            suffix=target_suffix,
            filename_mode="original",
        )
        try:
            probe = dict(probe_video(motion))
        except Exception as exc:
            probe = {"error": str(exc), "durationMs": 0, "width": 0, "height": 0}
        frame_count = 0
        base_frame_count = 0
        frame_duration_ms = 0
        gif_timestamps: list[int] = []
        width = 0
        height = 0
        if export_variant == "motion":
            shutil.copy2(motion, target)
        else:
            try:
                max_frames = int(params.get("gifFrameCount", params.get("frameCount", 18)) or 18)
            except (TypeError, ValueError):
                max_frames = 18
            try:
                max_edge = int(params.get("gifMaxEdge", params.get("maxEdge", 720)) or 720)
            except (TypeError, ValueError):
                max_edge = 720
            frames, frame_duration_ms, base_frame_count, gif_timestamps = self._photo_live_motion_gif_frames(
                motion,
                probe,
                variant=export_variant,
                max_frames=max_frames,
                max_edge=max_edge,
            )
            frame_count = len(frames)
            width = int(frames[0].width)
            height = int(frames[0].height)
            frames[0].save(
                target,
                "GIF",
                save_all=True,
                append_images=frames[1:],
                duration=frame_duration_ms,
                loop=0,
                optimize=True,
            )
        manifest = {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "workspace": str(self.project.root),
            "action": "export_photo_live_motion",
            "exportVariant": export_variant,
            "format": "gif" if export_variant in {"loop_gif", "bounce_gif"} else "video",
            "sourcePath": str(resolved),
            "motionSourcePath": str(motion),
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "durationMs": int(probe.get("durationMs", 0) or 0),
            "frameCount": frame_count,
            "baseFrameCount": base_frame_count,
            "frameDurationMs": frame_duration_ms,
            "gifTimestampsMs": gif_timestamps,
            "width": width,
            "height": height,
            "sourceWidth": int(probe.get("width", 0) or 0),
            "sourceHeight": int(probe.get("height", 0) or 0),
            "livePhoto": live_photo,
            "probe": probe,
            "note": "Live Photo motion exported from the paired local video sidecar.",
        }
        manifest_path = bundle_root / "manifest.json"
        manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        shared_event = self.project.db.record_photo_asset_events(
            "shared",
            [str(resolved)],
            actor=self.actor,
            metadata={
                "action": "export_photo_live_motion",
                "bundlePath": str(bundle_root),
                "targetPath": str(target),
                "motionSourcePath": str(motion),
                "exportVariant": export_variant,
            },
        )
        self.project._append_audit(
            {
                "action": "export_photo_live_motion",
                "asset_id": str(asset.get("assetId", "") or ""),
                "source_path": str(resolved),
                "motion_source_path": str(motion),
                "target_path": str(target),
                "bundle_path": str(bundle_root),
                "export_variant": export_variant,
                "frame_count": frame_count,
            }
        )
        return {
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "manifestPath": str(manifest_path),
            "sourcePath": str(resolved),
            "motionSourcePath": str(motion),
            "exportVariant": export_variant,
            "format": "gif" if export_variant in {"loop_gif", "bounce_gif"} else "video",
            "durationMs": int(probe.get("durationMs", 0) or 0),
            "frameCount": frame_count,
            "baseFrameCount": base_frame_count,
            "frameDurationMs": frame_duration_ms,
            "width": width,
            "height": height,
            "sharedEvent": shared_event,
        }

    def _photo_subject_cutout_variant(self, params: dict[str, Any]) -> str:
        raw = str(
            params.get(
                "exportVariant",
                params.get("variant", params.get("preset", "cutout")),
            )
            or "cutout"
        ).strip().lower().replace("-", "_")
        if raw in {"cutout", "subject", "transparent", "png"}:
            return "cutout"
        if raw in {"sticker", "outline", "outlined", "subject_sticker"}:
            return "sticker"
        raise ValueError("Subject cutout exportVariant must be cutout or sticker.")

    def _photo_subject_cutout_image(
        self,
        source: Path,
        *,
        variant: str,
        feather_px: int,
        outline_px: int,
    ) -> tuple[Any, dict[str, Any]]:
        from PIL import Image, ImageChops, ImageDraw, ImageFilter, ImageOps

        base = load_image(source).convert("RGBA")
        width, height = base.size
        if width <= 1 or height <= 1:
            raise ValueError("Subject cutout export requires an image larger than 1 pixel.")

        rgb = base.convert("RGB")

        # APL-EDIT-CUTOUT: prefer the on-device BiRefNet matte (model-grade
        # segmentation) when the matting pack is vendored; otherwise fall back to
        # the deterministic edge+center heuristic below. Fully offline either way.
        mask = None
        algorithm = "edge-background-plus-center-mask-v1"
        ml_model = ""
        background: Any = (0, 0, 0)
        try:
            from crossage_fr.ingest import matting

            matte = matting.remove_background(image=rgb)
        except Exception:
            matte = None
        if matte is not None and matte.available and matte.alpha is not None:
            mask = matte.alpha_image()
            algorithm = "birefnet-lite-onnx"
            ml_model = matte.model_name

        if mask is None:
            step = max(1, min(width, height) // 96)
            samples: list[tuple[int, int, int]] = []
            for x in range(0, width, step):
                samples.append(rgb.getpixel((x, 0)))
                samples.append(rgb.getpixel((x, height - 1)))
            for y in range(0, height, step):
                samples.append(rgb.getpixel((0, y)))
                samples.append(rgb.getpixel((width - 1, y)))
            background = tuple(
                int(round(sum(pixel[channel] for pixel in samples) / max(1, len(samples))))
                for channel in range(3)
            )
            diff = ImageChops.difference(rgb, Image.new("RGB", rgb.size, background)).convert("L")
            diff = ImageOps.autocontrast(diff)
            threshold = 24
            edge_mask = diff.point(lambda value: 255 if value >= threshold else 0)

            center_mask = Image.new("L", rgb.size, 0)
            margin_x = max(1, int(round(width * 0.11)))
            margin_y = max(1, int(round(height * 0.07)))
            ImageDraw.Draw(center_mask).ellipse(
                (margin_x, margin_y, width - margin_x, height - margin_y),
                fill=224,
            )
            mask = ImageChops.lighter(edge_mask, center_mask)
        feather_px = max(0, min(80, int(feather_px or max(2, min(32, min(width, height) // 80)))))
        if feather_px:
            mask = mask.filter(ImageFilter.GaussianBlur(feather_px))

        cutout = base.copy()
        cutout.putalpha(mask)
        if variant == "cutout":
            return cutout, {
                "algorithm": algorithm,
                "mlModel": ml_model,
                "backgroundColor": list(background),
                "featherPx": feather_px,
                "outlinePx": 0,
                "sourceWidth": width,
                "sourceHeight": height,
            }

        outline_px = max(2, min(160, int(outline_px or max(6, min(width, height) // 28))))
        outline_filter_size = outline_px * 2 + 1
        outline_alpha = mask.filter(ImageFilter.MaxFilter(outline_filter_size))
        outline_alpha = outline_alpha.filter(ImageFilter.GaussianBlur(max(1, outline_px // 5)))
        shadow_alpha = mask.filter(ImageFilter.GaussianBlur(max(2, outline_px // 2)))
        padding = outline_px * 2
        canvas_size = (width + padding * 2, height + padding * 2)
        canvas = Image.new("RGBA", canvas_size, (0, 0, 0, 0))
        shadow = Image.new("RGBA", canvas_size, (0, 0, 0, 0))
        shadow_mask = Image.new("L", canvas_size, 0)
        shadow_mask.paste(shadow_alpha, (padding + max(1, outline_px // 3), padding + max(1, outline_px // 3)))
        shadow.putalpha(shadow_mask.point(lambda value: min(90, value // 3)))
        canvas.alpha_composite(shadow)

        outline = Image.new("RGBA", canvas_size, (255, 255, 255, 0))
        outline_mask = Image.new("L", canvas_size, 0)
        outline_mask.paste(outline_alpha, (padding, padding))
        outline.putalpha(outline_mask)
        canvas.alpha_composite(outline)
        canvas.alpha_composite(cutout, (padding, padding))
        return canvas, {
            "algorithm": algorithm,
            "mlModel": ml_model,
            "backgroundColor": list(background),
            "featherPx": feather_px,
            "outlinePx": outline_px,
            "sourceWidth": width,
            "sourceHeight": height,
        }

    def export_photo_subject_cutout(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        if not source_value:
            raise ValueError("sourcePath is required.")
        source = Path(source_value).expanduser()
        try:
            resolved = safe_resolve(source)
        except OSError as exc:
            raise FileNotFoundError(f"Photo source is not available: {source_value}") from exc
        if not resolved.exists() or not resolved.is_file():
            raise FileNotFoundError(f"Photo source is not available: {source_value}")
        if resolved.suffix.lower() not in IMAGE_EXTENSIONS:
            raise ValueError("Subject cutout export requires an image source.")

        export_variant = self._photo_subject_cutout_variant(params)
        try:
            render_max_dimension = max(0, min(20000, int(params.get("renderMaxDimension", params.get("maxDimension", 0)) or 0)))
        except (TypeError, ValueError):
            render_max_dimension = 0
        try:
            feather_px = max(0, min(80, int(params.get("featherPx", params.get("feather", 0)) or 0)))
        except (TypeError, ValueError):
            feather_px = 0
        try:
            outline_px = max(0, min(160, int(params.get("outlinePx", params.get("outline", 0)) or 0)))
        except (TypeError, ValueError):
            outline_px = 0

        folder_param = str(params.get("folder", "") or "").strip()
        export_root = (Path(folder_param).expanduser() if folder_param else self.project.root / "exports").resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        bundle_root = export_root / f"vintrace-subject-{export_variant}-{stamp}"
        counter = 2
        while bundle_root.exists():
            bundle_root = export_root / f"vintrace-subject-{export_variant}-{stamp}-{counter}"
            counter += 1
        media_root = bundle_root / "media"
        media_root.mkdir(parents=True, exist_ok=True)
        base_name = f"{self._safe_photo_export_name(resolved.stem)}-{export_variant}"
        target = self._photo_export_allocate_target(
            media_root,
            index=1,
            base_name=base_name,
            suffix=".png",
            filename_mode="original",
        )
        generated, mask_metadata = self._photo_subject_cutout_image(
            resolved,
            variant=export_variant,
            feather_px=feather_px,
            outline_px=outline_px,
        )
        width, height = self._photo_export_save_pil_image(
            generated,
            target,
            render_format="png",
            quality=100,
            max_dimension=render_max_dimension,
        )
        manifest = {
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            "workspace": str(self.project.root),
            "action": "export_photo_subject_cutout",
            "exportVariant": export_variant,
            "format": "png",
            "sourcePath": str(resolved),
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "renderMaxDimension": render_max_dimension,
            "width": width,
            "height": height,
            "sourceWidth": int(mask_metadata.get("sourceWidth", 0) or 0),
            "sourceHeight": int(mask_metadata.get("sourceHeight", 0) or 0),
            "mask": mask_metadata,
            "note": (
                f"Subject cutout generated locally with on-device {mask_metadata.get('mlModel') or 'BiRefNet'} "
                "matting (model-grade segmentation, ONNX/onnxruntime CPU, fully offline)."
                if str(mask_metadata.get("algorithm", "")).startswith("birefnet")
                else "Subject cutout generated locally as a deterministic heuristic PNG with alpha. "
                "It is an on-demand first-pass export and not a model-grade segmentation result. "
                "Install the 'birefnet_lite' matting pack to enable model-grade cutouts."
            ),
        }
        manifest_path = bundle_root / "manifest.json"
        manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        shared_event = self.project.db.record_photo_asset_events(
            "shared",
            [str(resolved)],
            actor=self.actor,
            metadata={
                "action": "export_photo_subject_cutout",
                "bundlePath": str(bundle_root),
                "targetPath": str(target),
                "exportVariant": export_variant,
            },
        )
        self.project._append_audit(
            {
                "action": "export_photo_subject_cutout",
                "source_path": str(resolved),
                "target_path": str(target),
                "bundle_path": str(bundle_root),
                "export_variant": export_variant,
                "render_max_dimension": render_max_dimension,
                "algorithm": str(mask_metadata.get("algorithm", "")),
            }
        )
        return {
            "bundlePath": str(bundle_root),
            "mediaPath": str(media_root),
            "targetPath": str(target),
            "manifestPath": str(manifest_path),
            "sourcePath": str(resolved),
            "exportVariant": export_variant,
            "format": "png",
            "renderMaxDimension": render_max_dimension,
            "width": width,
            "height": height,
            "sourceWidth": int(mask_metadata.get("sourceWidth", 0) or 0),
            "sourceHeight": int(mask_metadata.get("sourceHeight", 0) or 0),
            "mask": mask_metadata,
            "sharedEvent": shared_event,
        }

    def _photo_portrait_blur_image(self, source: Path, *, blur_strength: int) -> tuple[Any, dict[str, Any]]:
        """Build a depth-aware portrait blur (subject sharp, background softened).

        Uses the on-device Depth-Anything-V2 map when its pack is vendored; falls
        back to a radial center-weighted mask otherwise. Fully offline either way.
        """
        import numpy as np
        from PIL import Image, ImageFilter

        from crossage_fr.depth import engine as depth_engine

        rgb = load_image(source).convert("RGB")
        width, height = rgb.size
        if width <= 1 or height <= 1:
            raise ValueError("Portrait blur requires an image larger than 1 pixel.")
        radius = max(2, min(80, int(blur_strength or max(6, min(48, min(width, height) // 18)))))

        depth_model = ""
        algorithm = "radial-center-weight-v1"
        try:
            depth_result = depth_engine.estimate_depth(image=rgb)
        except Exception:
            depth_result = None
        if depth_result is not None and depth_result.available and depth_result.depth is not None:
            # depth in [0,1], 1 = nearest -> keep subject (near) sharp.
            weight = depth_result.depth.astype(np.float32)
            algorithm = "depth-anything-v2"
            depth_model = depth_result.model_name
        else:
            yy, xx = np.mgrid[0:height, 0:width]
            cy, cx = (height - 1) / 2.0, (width - 1) / 2.0
            norm = np.sqrt(((xx - cx) / max(cx, 1)) ** 2 + ((yy - cy) / max(cy, 1)) ** 2)
            weight = np.clip(1.0 - norm, 0.0, 1.0).astype(np.float32)

        # Smooth the focus mask to avoid hard transitions, then composite.
        mask = Image.fromarray(np.clip(weight * 255.0, 0, 255).astype(np.uint8), "L")
        mask = mask.filter(ImageFilter.GaussianBlur(max(1, radius // 3)))
        weight = (np.asarray(mask, dtype=np.float32) / 255.0)[:, :, None]
        sharp = np.asarray(rgb, dtype=np.float32)
        blurred = np.asarray(rgb.filter(ImageFilter.GaussianBlur(radius)), dtype=np.float32)
        composited = sharp * weight + blurred * (1.0 - weight)
        result = Image.fromarray(np.clip(composited, 0, 255).astype(np.uint8), "RGB")
        return result, {
            "algorithm": algorithm,
            "depthModel": depth_model,
            "blurStrength": radius,
            "sourceWidth": width,
            "sourceHeight": height,
        }

