    def set_photo_live_key_photo(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        resolved, asset, live_photo, motion = self._photo_live_motion_source(source_value)
        try:
            timestamp_ms = max(0, int(params.get("timestampMs", params.get("timestamp", 0)) or 0))
        except (TypeError, ValueError):
            timestamp_ms = 0
        frame = self._photo_video_frame_image(motion, timestamp_ms)
        try:
            target = self.project._preview_cache_path(resolved)
        except OSError as exc:
            raise VideoLoadError(f"Could not inspect Live Photo preview cache path: {exc}") from exc
        self.project._ensure_generated_dir_sentinel(self.project.previews_path)
        if not self.project._generated_dir_is_owned(self.project.previews_path):
            raise VideoLoadError("Preview cache folder is not owned by this workspace.")
        target.parent.mkdir(parents=True, exist_ok=True)
        temp = target.with_suffix(target.suffix + ".tmp")
        width, height = self._photo_export_save_pil_image(
            frame,
            temp,
            render_format="jpeg",
            quality=84,
            max_dimension=768,
        )
        temp.replace(target)
        selected_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        next_live_photo = {
            **live_photo,
            "keyPhotoTimestampMs": timestamp_ms,
            "keyPhotoPreviewPath": str(target),
            "keyPhotoSelectedAt": selected_at,
            "keyPhotoWidth": width,
            "keyPhotoHeight": height,
        }
        updated_asset = self.project.db.update_photo_asset_metadata_json(
            asset_id=str(asset.get("assetId", "")),
            patch={"livePhoto": next_live_photo},
        )
        self.project._append_audit(
            {
                "action": "set_photo_live_key_photo",
                "asset_id": str(updated_asset.get("assetId", "") or ""),
                "source_path": str(resolved),
                "motion_source_path": str(motion),
                "timestamp_ms": timestamp_ms,
                "preview_path": str(target),
            }
        )
        return {
            "assetId": str(updated_asset.get("assetId", "")),
            "sourcePath": str(resolved),
            "motionSourcePath": str(motion),
            "timestampMs": timestamp_ms,
            "previewPath": str(target),
            "width": width,
            "height": height,
            "selectedAt": selected_at,
            "metadata": updated_asset.get("metadata", {}),
        }

    def reset_photo_live_key_photo(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        resolved, asset, live_photo, motion = self._photo_live_motion_source(source_value)
        next_live_photo = {**live_photo}
        for key in ("keyPhotoTimestampMs", "keyPhotoPreviewPath", "keyPhotoSelectedAt", "keyPhotoWidth", "keyPhotoHeight"):
            next_live_photo.pop(key, None)
        try:
            target = self.project._preview_cache_path(resolved)
            if target.exists():
                target.unlink()
        except OSError:
            pass
        updated_asset = self.project.db.update_photo_asset_metadata_json(
            asset_id=str(asset.get("assetId", "")),
            patch={"livePhoto": next_live_photo},
        )
        preview_path = self.project.preview_path_for(str(resolved), create=True) or ""
        self.project._append_audit(
            {
                "action": "reset_photo_live_key_photo",
                "asset_id": str(updated_asset.get("assetId", "") or ""),
                "source_path": str(resolved),
                "motion_source_path": str(motion),
                "preview_path": preview_path,
            }
        )
        return {
            "assetId": str(updated_asset.get("assetId", "")),
            "sourcePath": str(resolved),
            "motionSourcePath": str(motion),
            "timestampMs": 0,
            "previewPath": preview_path,
            "cleared": True,
            "metadata": updated_asset.get("metadata", {}),
        }

    def set_photo_video_poster(self, params: dict[str, Any]) -> dict[str, Any]:
        source_value = str(params.get("sourcePath", params.get("path", "")) or "").strip()
        if not source_value:
            raise ValueError("sourcePath is required.")
        source = Path(source_value).expanduser()
        try:
            resolved = safe_resolve(source)
        except OSError as exc:
            raise FileNotFoundError(f"Video source is not available: {source_value}") from exc
        if not resolved.exists() or not resolved.is_file():
            raise FileNotFoundError(f"Video source is not available: {source_value}")
        if resolved.suffix.lower() not in VIDEO_EXTENSIONS:
            raise ValueError("Video poster selection requires a video source.")
        asset = self.project.db.photo_asset_by_path(str(resolved))
        if not asset:
            raise ValueError("Video must be imported into Photos before setting a poster frame.")
        raw_policy = str(params.get("policy", params.get("posterPolicy", "manual")) or "manual").strip().lower().replace("_", "-")
        policy = "auto" if raw_policy in {"auto", "automatic", "generated-auto"} else "manual"
        probe: dict[str, Any] = {}
        if policy == "auto":
            try:
                probe = dict(probe_video(resolved))
            except VideoLoadError as exc:
                probe = {"error": str(exc), "durationMs": 0, "width": 0, "height": 0}
            duration_ms = max(0, int(probe.get("durationMs", 0) or 0))
            timestamp_ms = min(max(0, duration_ms - 1), max(0, duration_ms // 2)) if duration_ms > 0 else 0
        else:
            try:
                timestamp_ms = max(0, int(params.get("timestampMs", params.get("timestamp", 0)) or 0))
            except (TypeError, ValueError):
                timestamp_ms = 0
        frame = self._photo_video_frame_image(resolved, timestamp_ms)
        try:
            target = self.project._preview_cache_path(resolved)
        except OSError as exc:
            raise VideoLoadError(f"Could not inspect video poster cache path: {exc}") from exc
        self.project._ensure_generated_dir_sentinel(self.project.previews_path)
        if not self.project._generated_dir_is_owned(self.project.previews_path):
            raise VideoLoadError("Preview cache folder is not owned by this workspace.")
        target.parent.mkdir(parents=True, exist_ok=True)
        temp = target.with_suffix(target.suffix + ".tmp")
        width, height = self._photo_export_save_pil_image(
            frame,
            temp,
            render_format="jpeg",
            quality=84,
            max_dimension=768,
        )
        temp.replace(target)
        selected_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        poster_metadata = {
            "sourcePath": str(resolved),
            "timestampMs": timestamp_ms,
            "previewPath": str(target),
            "policy": policy,
            "selectedAt": selected_at,
            "width": width,
            "height": height,
        }
        updated_asset = self.project.db.update_photo_asset_metadata_json(
            asset_id=str(asset.get("assetId", "")),
            patch={"videoPoster": poster_metadata},
        )
        self.project._append_audit(
            {
                "action": "set_photo_video_poster",
                "asset_id": updated_asset.get("assetId", ""),
                "source_path": str(resolved),
                "timestamp_ms": timestamp_ms,
                "preview_path": str(target),
                "policy": policy,
            }
        )
        return {
            "assetId": str(updated_asset.get("assetId", "")),
            "sourcePath": str(resolved),
            "timestampMs": timestamp_ms,
            "previewPath": str(target),
            "policy": policy,
            "width": width,
            "height": height,
            "selectedAt": selected_at,
            "metadata": updated_asset.get("metadata", {}),
        }

