    def _photo_semantic_search_queries(self, query: str) -> list[str]:
        text = str(query or "").strip()
        if not text:
            return []
        normalized = re.sub(r"[^a-z0-9]+", " ", text.casefold()).strip()
        tokens = re.findall(r"[a-z0-9]+", normalized)
        if not tokens:
            return []

        queries: list[str] = []
        seen: set[str] = set()

        def add(value: Any) -> None:
            candidate = re.sub(r"\s+", " ", str(value or "").strip())
            if len(candidate) < 2:
                return
            key = candidate.casefold()
            if key in seen or key == text.casefold() or len(queries) >= 24:
                return
            seen.add(key)
            queries.append(candidate)

        token_set = set(tokens)
        for triggers, expansions in PHOTO_SEMANTIC_SEARCH_ALIASES:
            if any(trigger in token_set or trigger in normalized for trigger in triggers):
                for expansion in expansions:
                    add(expansion)

        content_tokens = [
            token
            for token in tokens
            if token not in PHOTO_SEMANTIC_STOPWORDS and len(token) > 1
        ][:8]
        if content_tokens:
            add(" ".join(content_tokens))
            if len(content_tokens) > 1:
                for token in content_tokens[:6]:
                    add(token)
        return queries

    def _photo_search_folder_candidates(
        self,
        search_queries: Iterable[str],
        *,
        library_root_filter: str,
        library_root_source_filters: Iterable[tuple[str, str]],
        matches_by_source: dict[str, list[ReviewCandidate]],
        photo_entries: list[dict[str, Any]],
        limit: int,
    ) -> list[dict[str, Any]]:
        needles = [
            str(candidate or "").strip().casefold()
            for candidate in search_queries
            if str(candidate or "").strip()
        ][:16]
        if not needles:
            return []
        candidate_limit = max(24, min(240, int(limit or 24)))
        folders: list[dict[str, Any]] = []
        seen_ids: set[str] = set()

        def text_matches(values: Iterable[Any]) -> bool:
            haystack = " ".join(str(value or "") for value in values if str(value or "").strip()).casefold()
            return bool(haystack and any(needle in haystack for needle in needles))

        def like_clause(columns: list[str]) -> tuple[str, list[Any]]:
            clauses: list[str] = []
            args: list[Any] = []
            for needle in needles:
                pattern = f"%{needle}%"
                for column in columns:
                    clauses.append(f"LOWER(COALESCE({column}, '')) LIKE ?")
                    args.append(pattern)
            return "(" + " OR ".join(clauses or ["0"]) + ")", args

        def preview_for(source_path: Any) -> str | None:
            source = str(source_path or "")
            return self.project.preview_path_for(source, create=False) if source else None

        def add_folder(folder: dict[str, Any]) -> None:
            folder_id = str(folder.get("id", "") or "")
            if not folder_id or folder_id in seen_ids:
                return
            seen_ids.add(folder_id)
            folders.append(folder)

        def source_visible(source_path: Any) -> bool:
            source = str(source_path or "").strip()
            if not source or not self._photo_source_inside_library_root(source, library_root_filter):
                return False
            asset = self.project.db.photo_asset_by_path(source)
            if not asset:
                return False
            metadata = self.project.db.photo_asset_metadata_by_id(str(asset.get("assetId", "") or ""))
            return not metadata.get("hidden") and not str(metadata.get("deletedAt", "") or "")

        def source_asset_id(source_path: Any) -> str:
            asset = self.project.db.photo_asset_by_path(str(source_path or ""))
            return str(asset.get("assetId", "") or "") if asset else ""

        def add_static_collection(folder_id: str, name: str, values: Iterable[Any], extra: dict[str, Any] | None = None) -> None:
            if not text_matches([name, folder_id, *(values or [])]):
                return
            add_folder({
                "id": folder_id,
                "kind": "all" if folder_id == "all" else "utility",
                "name": name,
                "count": 0,
                "coverPreviewPath": None,
                "coverSourcePath": "",
                **(extra or {}),
            })

        add_static_collection("all", "All Photos", ("library", "photos"))
        for folder_id, name, terms in (
            ("favorites", "Favorites", ("favorite", "starred")),
            ("recentlyAdded", "Recently Added", ("recent", "added")),
            ("recentlySaved", "Recently Saved", ("saved", "app import")),
            ("imports", "Imports", ("import", "imported")),
            ("lastImport", "Last Import", ("last import", "recent import")),
            ("recentlyImported", "Recently Imported", ("recently imported", "imports")),
            ("recentlyEdited", "Recently Edited", ("edited", "adjusted")),
            ("recentlyViewed", "Recently Viewed", ("viewed", "seen")),
            ("recentlyShared", "Recently Shared", ("shared", "sent")),
            ("duplicates", "Duplicates", ("duplicate", "similar")),
            ("places", "Places", ("place", "location", "map")),
            ("hidden", "Hidden", ("private",)),
            ("recentlyDeleted", "Recently Deleted", ("deleted", "trash")),
            ("recovered", "Recovered", ("recovered", "failed import")),
        ):
            add_static_collection(folder_id, name, terms)
        for media_kind, label in (
            ("image", "Images"),
            ("video", "Videos"),
            ("screenshot", "Screenshots"),
            ("screen_recording", "Screen Recordings"),
            ("panorama", "Panoramas"),
            ("portrait", "Portraits"),
            ("burst", "Bursts"),
            ("time_lapse", "Time-lapse"),
            ("raw", "RAW"),
            ("live_photo", "Live Photos"),
            ("other", "Other Media"),
        ):
            add_static_collection(f"media:{media_kind}", label, (media_kind.replace("_", " "),), {"mediaKind": media_kind})
        for folder_id, classifier in PHOTO_UTILITY_CLASSIFIERS.items():
            add_static_collection(
                folder_id,
                str(classifier.get("name", "") or folder_id),
                (str(classifier.get("kind", "") or ""), *[str(term) for term in classifier.get("terms", ())]),
                {"utilityClassifier": str(classifier.get("kind", "") or "")},
            )

        source_filter_where, source_filter_args = self.project.db._photo_source_text_filter_sql_parts(library_root_source_filters)  # noqa: SLF001
        visible_predicates = ["COALESCE(m.hidden, 0) = 0", "m.deleted_at IS NULL", *source_filter_where]
        visible_sql = " AND ".join(visible_predicates)
        for import_source in self._photo_import_source_group_summaries(
            source_text_filters=library_root_source_filters,
            limit=candidate_limit,
        ):
            label = str(import_source.get("label", "") or "")
            kind = str(import_source.get("kind", "") or "")
            if not text_matches([label, kind, kind.replace("_", " "), "saved from", "app source", "import source"]):
                continue
            cover_source = str(import_source.get("coverSourcePath", "") or "")
            add_folder({
                "id": str(import_source.get("id", "") or ""),
                "kind": "source",
                "name": label or self._photo_import_source_default_label(kind),
                "count": int(import_source.get("count", 0) or 0),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "importSourceKind": kind,
                "importSourceLabel": label,
                "importSource": {
                    "kind": kind,
                    "label": label,
                    "count": int(import_source.get("count", 0) or 0),
                    "sessionCount": int(import_source.get("sessionCount", 0) or 0),
                    "latestImportAt": str(import_source.get("latestImportAt", "") or ""),
                },
            })
        album_like_sql, album_like_args = like_clause([
            "pa.name",
            "pa.description",
            "pa.album_kind",
            "pa.include_people_json",
            "pa.exclude_people_json",
            "pa.rules_json",
        ])
        folder_like_sql, folder_like_args = like_clause(["f.name"])
        person_like_sql, person_like_args = like_clause(["p.person_name"])
        confident = float(self.project.config.thresholds.confident)

        with self.project.db.connect() as conn:
            album_rows = conn.execute(
                f"""
                SELECT pa.album_id, pa.name, pa.album_kind, pa.description, pa.cover_source_path,
                    COUNT(DISTINCT CASE WHEN {visible_sql} THEN i.asset_id END) AS visible_count,
                    MAX(CASE WHEN {visible_sql} THEN a.source_path ELSE '' END) AS fallback_cover_source
                FROM photo_albums AS pa
                LEFT JOIN photo_album_items AS i ON i.album_id = pa.album_id
                LEFT JOIN photo_assets AS a ON a.asset_id = i.asset_id
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                WHERE {album_like_sql}
                GROUP BY pa.album_id
                ORDER BY pa.updated_at DESC, LOWER(pa.name) ASC, pa.album_id ASC
                LIMIT ?
                """,
                [*source_filter_args, *source_filter_args, *album_like_args, candidate_limit],
            ).fetchall()
            for row in album_rows:
                cover_source = str(row["cover_source_path"] or row["fallback_cover_source"] or "")
                add_folder({
                    "id": f"album:{row['album_id']}",
                    "kind": "album",
                    "name": str(row["name"] or "Album"),
                    "albumKind": str(row["album_kind"] or "smart"),
                    "description": str(row["description"] or ""),
                    "count": int(row["visible_count"] or 0),
                    "coverPreviewPath": preview_for(cover_source),
                    "coverSourcePath": cover_source,
                })

            album_folder_rows = conn.execute(
                f"""
                SELECT f.folder_id, f.name,
                    COUNT(DISTINCT pa.album_id) AS album_count,
                    COUNT(DISTINCT CASE WHEN {visible_sql} THEN i.asset_id END) AS visible_count,
                    MAX(CASE WHEN {visible_sql} THEN a.source_path ELSE '' END) AS cover_source_path
                FROM photo_album_folders AS f
                LEFT JOIN photo_albums AS pa ON pa.folder_id = f.folder_id
                LEFT JOIN photo_album_items AS i ON i.album_id = pa.album_id
                LEFT JOIN photo_assets AS a ON a.asset_id = i.asset_id
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                WHERE {folder_like_sql}
                GROUP BY f.folder_id
                ORDER BY f.position ASC, LOWER(f.name) ASC, f.folder_id ASC
                LIMIT ?
                """,
                [*source_filter_args, *source_filter_args, *folder_like_args, candidate_limit],
            ).fetchall()
            for row in album_folder_rows:
                cover_source = str(row["cover_source_path"] or "")
                add_folder({
                    "id": f"albumFolder:{row['folder_id']}",
                    "kind": "albumFolder",
                    "name": str(row["name"] or "Folder"),
                    "albumCount": int(row["album_count"] or 0),
                    "count": int(row["visible_count"] or 0),
                    "coverPreviewPath": preview_for(cover_source),
                    "coverSourcePath": cover_source,
                })

            person_rows = conn.execute(
                f"""
                SELECT p.person_name,
                    COUNT(DISTINCT p.asset_id) AS visible_count,
                    MAX(a.source_path) AS cover_source_path
                FROM photo_asset_people AS p
                JOIN photo_assets AS a ON a.asset_id = p.asset_id
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                LEFT JOIN photo_people_profiles AS pp ON LOWER(pp.person_name) = LOWER(p.person_name)
                WHERE {visible_sql}
                    AND COALESCE(pp.hidden, 0) = 0
                    AND p.person_name NOT LIKE 'Unmatched cluster%'
                    AND (
                        LOWER(p.status) = 'accepted'
                        OR LOWER(p.band) = 'manual assignment'
                        OR (LOWER(p.status) != 'rejected' AND p.score >= ?)
                    )
                    AND {person_like_sql}
                GROUP BY p.person_name
                ORDER BY visible_count DESC, LOWER(p.person_name) ASC
                LIMIT ?
                """,
                [*source_filter_args, confident, *person_like_args, candidate_limit],
            ).fetchall()
            for row in person_rows:
                cover_source = str(row["cover_source_path"] or "")
                name = str(row["person_name"] or "")
                add_folder({
                    "id": f"person:{name}",
                    "kind": "person",
                    "name": name,
                    "count": int(row["visible_count"] or 0),
                    "coverPreviewPath": preview_for(cover_source),
                    "coverSourcePath": cover_source,
                    "personProfile": self.project.db.photo_person_profile(name),
                })

        dynamic_sources: set[str] = {str(entry.get("sourcePath", "") or "") for entry in photo_entries if str(entry.get("sourcePath", "") or "")}
        dynamic_person_sources: dict[str, set[str]] = {}
        dynamic_person_cover: dict[str, str] = {}
        for source_path, matches in matches_by_source.items():
            source = str(source_path or "")
            if not source or not self._photo_source_inside_library_root(source, library_root_filter):
                continue
            matched_names = [
                str(candidate.person_name or "").strip()
                for candidate in matches
                if self._photo_person_match(candidate)
                and text_matches([candidate.person_name])
            ]
            if not matched_names:
                continue
            if not source_visible(source):
                continue
            dynamic_sources.add(source)
            for name in matched_names:
                dynamic_person_sources.setdefault(name, set()).add(source)
                dynamic_person_cover.setdefault(name, source)
        for name, sources in sorted(dynamic_person_sources.items(), key=lambda item: (-len(item[1]), item[0].casefold()))[:candidate_limit]:
            cover_source = dynamic_person_cover.get(name, next(iter(sources), ""))
            add_folder({
                "id": f"person:{name}",
                "kind": "person",
                "name": name,
                "count": len(sources),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "personProfile": self.project.db.photo_person_profile(name),
            })

        entry_by_source = {
            str(entry.get("sourcePath", "") or ""): entry
            for entry in photo_entries
            if str(entry.get("sourcePath", "") or "") and self._photo_entry_default_visible(entry)
        }
        missing_sources = [source for source in sorted(dynamic_sources) if source not in entry_by_source]
        if missing_sources:
            for entry in self._photo_entries_for_source_paths(missing_sources[:candidate_limit], matches_by_source=matches_by_source):
                source = str(entry.get("sourcePath", "") or "")
                if source and self._photo_entry_default_visible(entry):
                    entry_by_source[source] = entry

        pet_sources: dict[str, set[str]] = {}
        pet_covers: dict[str, str] = {}
        pet_kinds: dict[str, str] = {}
        group_sources: dict[tuple[tuple[str, ...], tuple[str, ...]], set[str]] = {}
        group_covers: dict[tuple[tuple[str, ...], tuple[str, ...]], str] = {}
        for source, entry in entry_by_source.items():
            if not self._photo_source_inside_library_root(source, library_root_filter):
                continue
            people = sorted(set(self._photo_entry_named_people(entry)), key=str.casefold)
            pet_labels = []
            for pet in self._photo_pet_labels_for_entry(entry):
                pet_name = self._clean_photo_pet_label(pet.get("name", ""))
                if not pet_name:
                    continue
                pet_kind = str(pet.get("kind", "") or "pet").strip().lower() or "pet"
                pet_labels.append((pet_name, pet_kind))
                if text_matches([pet_name, pet_kind, self._photo_pet_kind_label(pet_kind)]):
                    pet_sources.setdefault(pet_name, set()).add(source)
                    pet_covers.setdefault(pet_name, source)
                    pet_kinds.setdefault(pet_name, pet_kind)
            pets = sorted({name for name, _kind in pet_labels}, key=str.casefold)
            participants = [("person", name) for name in people] + [("pet", name) for name in pets]
            if len(participants) < 2 or not any(text_matches([name]) for _kind, name in participants):
                continue
            max_group_size = min(4, len(participants))
            for group_size in range(2, max_group_size + 1):
                for group_members in combinations(participants, group_size):
                    group_people = tuple(name for kind, name in group_members if kind == "person")
                    group_pets = tuple(name for kind, name in group_members if kind == "pet")
                    group_name = self._photo_people_group_name(group_people, group_pets)
                    if not text_matches([group_name, " ".join(group_people), " ".join(group_pets)]):
                        continue
                    key = (group_people, group_pets)
                    group_sources.setdefault(key, set()).add(source)
                    group_covers.setdefault(key, source)
        for pet_name, sources in sorted(pet_sources.items(), key=lambda item: (-len(item[1]), item[0].casefold()))[:candidate_limit]:
            pet_kind = pet_kinds.get(pet_name, "pet")
            cover_source = pet_covers.get(pet_name, next(iter(sources), ""))
            add_folder({
                "id": self._photo_pet_folder_id(pet_name),
                "kind": "pet",
                "name": pet_name,
                "count": len(sources),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "petName": pet_name,
                "petKind": pet_kind,
                "petKindLabel": self._photo_pet_kind_label(pet_kind),
                "petProfile": self.project.db.photo_pet_profile(pet_name),
            })
        for (group_people, group_pets), sources in sorted(group_sources.items(), key=lambda item: (-len(item[1]), self._photo_people_group_name(item[0][0], item[0][1]).casefold()))[:candidate_limit]:
            cover_source = group_covers.get((group_people, group_pets), next(iter(sources), ""))
            add_folder({
                "id": self._photo_people_group_id(group_people, group_pets),
                "kind": "group",
                "name": self._photo_people_group_name(group_people, group_pets),
                "count": len(sources),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "groupSource": "generated",
                "groupPeople": list(group_people),
                "groupPets": list(group_pets),
            })

        for group in self.project.db.list_photo_people_groups():
            member_people = [str(person or "").strip() for person in group.get("memberPeople", []) if str(person or "").strip()]
            member_pets = [self._clean_photo_pet_label(pet) for pet in group.get("memberPets", []) if self._clean_photo_pet_label(pet)]
            if group.get("hidden") or not text_matches([group.get("name", ""), *member_people, *member_pets, *group.get("excludePeople", []), *group.get("excludePets", [])]):
                continue
            cover_source = ""
            key_asset_id = str(group.get("keyAssetId", "") or "")
            if key_asset_id:
                asset = self.project.db.photo_asset_by_id(key_asset_id)
                source = str((asset or {}).get("sourcePath", "") or "")
                if source_visible(source):
                    cover_source = source
            add_folder({
                "id": f"group:saved:{group.get('groupId', '')}",
                "kind": "group",
                "name": str(group.get("name", "") or self._photo_people_group_name(member_people, member_pets)),
                "count": 0,
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "groupId": str(group.get("groupId", "") or ""),
                "groupSource": "saved",
                "groupPeople": member_people,
                "groupPets": member_pets,
                "excludePeople": group.get("excludePeople", []),
                "excludePets": group.get("excludePets", []),
                "groupProfile": group,
            })

        for place in self.project.db.search_photo_places(
            needles,
            source_text_filters=library_root_source_filters,
            limit=candidate_limit,
        ):
            cover_source = str(place.get("coverSourcePath", "") or "")
            add_folder({
                "id": f"place:{place.get('placeId', '')}",
                "kind": "place",
                "name": str(place.get("name", "") or "Unknown Place"),
                "count": int(place.get("count", 0) or 0),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "placeId": str(place.get("placeId", "") or ""),
                "placeProfile": place.get("placeProfile", {}),
                "place": place,
            })

        generated_cache = self.project.db.photo_generated_collection_cache(library_root_filter)
        for trip in generated_cache.get("trips", []):
            if not isinstance(trip, dict) or not text_matches([
                trip.get("name", ""),
                trip.get("dateRangeLabel", ""),
                trip.get("locationLabel", ""),
                *(trip.get("locationLabels", []) if isinstance(trip.get("locationLabels", []), list) else []),
            ]):
                continue
            cover_source = str(trip.get("coverSourcePath", "") or "")
            add_folder({
                "id": f"trip:{trip.get('tripId', '')}",
                "kind": "trip",
                "name": str(trip.get("name", "") or "Trip"),
                "count": int(trip.get("count", 0) or 0),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "tripId": str(trip.get("tripId", "") or ""),
                "trip": trip,
            })
        for memory in generated_cache.get("memories", []):
            if not isinstance(memory, dict) or not text_matches([
                memory.get("name", ""),
                memory.get("subtitle", ""),
                memory.get("category", ""),
                memory.get("dateRangeLabel", ""),
                memory.get("startDate", ""),
                memory.get("endDate", ""),
            ]):
                continue
            cover_source = str(memory.get("coverSourcePath", "") or "")
            add_folder({
                "id": f"memory:{memory.get('memoryId', '')}",
                "kind": "memory",
                "name": str(memory.get("name", "") or "Memory"),
                "count": int(memory.get("count", 0) or 0),
                "coverPreviewPath": preview_for(cover_source),
                "coverSourcePath": cover_source,
                "memoryId": str(memory.get("memoryId", "") or ""),
                "memory": memory,
            })

        return folders

    def search_photo_library(self, params: dict[str, Any]) -> dict[str, Any]:
        query = str(params.get("query", "") or "").strip()
        limit = max(1, min(25, int(params.get("limit", 6) or 6)))
        suggestion_limit = max(1, min(80, int(params.get("suggestionLimit", 24) or 24)))
        library_root_filter = self._photo_library_root_filter_from_params(params)
        library_root_source_filters = self._photo_library_root_source_text_filters(library_root_filter)
        needle = query.casefold()
        if not needle:
            return {"query": query, "total": 0, "groups": [], "suggestions": []}
        semantic_queries = self._photo_semantic_search_queries(query)
        search_queries = [query, *semantic_queries]

        search_index = self.project.db.ensure_photo_search_index(allow_rebuild=False, enqueue_on_cold=True, repair_limit=1000)
        photo_hit_limit = max(limit, min(suggestion_limit, 80), 24)
        text_asset_ids: list[str] = []
        facet_asset_ids: list[str] = []
        semantic_match_by_asset_id: dict[str, str] = {}
        seen_text_asset_ids: set[str] = set()
        seen_facet_asset_ids: set[str] = set()
        photo_total = 0
        for search_query in search_queries:
            semantic_query = search_query != query
            text_search = self.project.db.search_photo_assets(
                search_query,
                limit=photo_hit_limit,
                source_text_filters=library_root_source_filters,
            )
            query_text_asset_ids = [str(asset_id or "") for asset_id in text_search.get("assetIds", []) if str(asset_id or "")]
            query_new_text_asset_ids = [asset_id for asset_id in query_text_asset_ids if asset_id not in seen_text_asset_ids]
            for asset_id in query_new_text_asset_ids:
                seen_text_asset_ids.add(asset_id)
                text_asset_ids.append(asset_id)
                if semantic_query:
                    semantic_match_by_asset_id.setdefault(asset_id, search_query)
            facet_excludes = [*seen_text_asset_ids, *seen_facet_asset_ids]
            facet_search = self.project.db.search_photo_asset_facets(
                search_query,
                exclude_asset_ids=facet_excludes,
                limit=photo_hit_limit,
                source_text_filters=library_root_source_filters,
            )
            query_facet_asset_ids = [str(asset_id or "") for asset_id in facet_search.get("assetIds", []) if str(asset_id or "")]
            for asset_id in query_facet_asset_ids:
                if asset_id in seen_facet_asset_ids or asset_id in seen_text_asset_ids:
                    continue
                seen_facet_asset_ids.add(asset_id)
                facet_asset_ids.append(asset_id)
                if semantic_query:
                    semantic_match_by_asset_id.setdefault(asset_id, search_query)
            if not semantic_query:
                photo_total = int(text_search.get("total", 0) or 0) + int(facet_search.get("total", 0) or 0)
        seen_asset_ids: set[str] = set()
        photo_asset_ids = []
        for asset_id in [*text_asset_ids, *facet_asset_ids]:
            if asset_id in seen_asset_ids:
                continue
            seen_asset_ids.add(asset_id)
            photo_asset_ids.append(asset_id)
        photo_assets = self.project.db.photo_assets_by_ids(photo_asset_ids)
        matches_by_source = self._photo_matches_by_source_for_source_paths(
            str(asset.get("sourcePath", "") or "")
            for asset in photo_assets
        )
        place_labels_by_asset_id = self._photo_place_labels_by_asset_id_for_asset_ids(photo_asset_ids)
        photo_entries = self._photo_entries_for_assets(photo_assets, matches_by_source=matches_by_source)
        photo_entries = self._filter_photo_entries_by_library_root(photo_entries, library_root_filter)
        curation_preferences = self.project.db.photo_curation_preferences()
        photo_entries = [
            entry
            for _, entry in sorted(
                enumerate(photo_entries),
                key=lambda pair: (
                    self._photo_entry_curation_penalty(pair[1], curation_preferences, place_labels_by_asset_id),
                    pair[0],
                ),
            )
        ]
        photo_entry_curation_penalty_by_source = {
            str(entry.get("sourcePath", "") or ""): self._photo_entry_curation_penalty(entry, curation_preferences, place_labels_by_asset_id)
            for entry in photo_entries
        }
        photo_total = max(photo_total, len(photo_asset_ids))

        def plural(count: int, singular: str, multiple: str | None = None) -> str:
            return f"{count} {singular if count == 1 else (multiple or singular + 's')}"

        def joined(values: list[str]) -> str:
            return " · ".join(value for value in values if value)

        suggestions: list[dict[str, Any]] = []
        seen_suggestions: dict[str, dict[str, Any]] = {}
        feature_less_people = self._photo_curation_preference_keys(curation_preferences, "featureLessPeople")
        feature_less_places = self._photo_curation_preference_keys(curation_preferences, "featureLessPlaces")
        feature_less_dates = self._photo_curation_preference_keys(curation_preferences, "featureLessDates")
        feature_less_content = self._photo_curation_preference_keys(curation_preferences, "featureLessContent")
        search_needles = [
            candidate.casefold()
            for candidate in search_queries
            if str(candidate or "").strip()
        ]

        def search_suggestion_curation_penalty(values: list[Any]) -> int:
            clean_values = [
                re.sub(r"\s+", " ", str(value or "")).strip()
                for value in values
                if str(value or "").strip()
            ]
            penalty = 0
            if self._photo_curation_values_match(clean_values, feature_less_people):
                penalty += 8
            if self._photo_curation_values_match(clean_values, feature_less_places, contains=True):
                penalty += 6
            if self._photo_curation_values_match(clean_values, feature_less_dates):
                penalty += 4
            if self._photo_curation_values_match(clean_values, feature_less_content, contains=True):
                penalty += 2
            return penalty

        def add_suggestion(value: Any, curation_penalty: int = 0) -> None:
            text = str(value or "").strip()
            if len(text) < 2 or needle not in text.casefold():
                return
            clipped = text[:80].strip()
            key = clipped.casefold()
            penalty = max(int(curation_penalty or 0), search_suggestion_curation_penalty([clipped]))
            existing = seen_suggestions.get(key)
            if existing:
                existing["_curationPenalty"] = min(int(existing.get("_curationPenalty", 0) or 0), penalty)
                return
            suggestion = {
                "text": clipped,
                "_curationPenalty": penalty,
                "_position": len(suggestions),
            }
            seen_suggestions[key] = suggestion
            suggestions.append(suggestion)

        def search_snippet(label: str, value: Any, *, active_needle: str = needle, active_query: str = query) -> str:
            text = str(value or "").strip()
            if not text:
                return ""
            index = text.casefold().find(active_needle)
            if index < 0:
                return ""
            start = max(0, index - 45)
            end = min(len(text), index + len(active_query) + 75)
            snippet = text[start:end].strip()
            if start > 0:
                snippet = "..." + snippet
            if end < len(text):
                snippet += "..."
            return f"{label}: {snippet}" if label else snippet

        def search_match_reason_label(label: str) -> str:
            clean = str(label or "").strip()
            return {
                "Detected text": "OCR",
                "Detected items": "Detected items",
                "File": "Filename",
                "Media": "Media type",
                "Source folder": "Source folder",
            }.get(clean, clean)

        def search_match_reasons(candidates: list[tuple[str, Any]], *, semantic_query: str = "") -> list[str]:
            reasons: list[str] = []

            def add_reason(reason: str) -> None:
                clean = str(reason or "").strip()
                if clean and clean not in reasons:
                    reasons.append(clean)

            if semantic_query:
                add_reason("Semantic")
            for label, value in candidates:
                if value_matches(value):
                    add_reason(search_match_reason_label(label))
                if len(reasons) >= 5:
                    break
            return reasons

        def semantic_snippet(search_query: str, candidates: list[tuple[str, Any]]) -> str:
            terms = [
                term
                for term in re.findall(r"[A-Za-z0-9_]+", str(search_query or "").casefold())
                if len(term) > 1 and term not in PHOTO_SEMANTIC_STOPWORDS
            ][:8]
            for term in terms:
                for label, value in candidates:
                    match = search_snippet(label, value, active_needle=term, active_query=term)
                    if match:
                        return f"Semantic match: {match}"
            return f"Semantic match: {search_query}" if search_query else ""

        def value_matches(value: Any) -> bool:
            text = str(value or "").casefold()
            return bool(text and any(active_needle in text for active_needle in search_needles))

        def photo_result(entry: dict[str, Any]) -> dict[str, Any]:
            source = str(entry.get("sourcePath", "") or "")
            row = self._photo_item_row(
                source_path=source,
                media_kind=str(entry.get("mediaKind", "image") or "image"),
                preview_create=False,
                candidate=entry.get("candidate"),
                matches=entry.get("matches", []),
                scan_date=str(entry.get("scanDate", "") or ""),
            )
            title = str(row.get("title", "") or "").strip() or Path(source).name or "Photo"
            subtitle = joined([
                str(row.get("caption", "") or "").strip(),
                str(row.get("captureDate", "") or "").strip()[:10],
                str(row.get("mediaKind", "") or "").replace("_", " ").title(),
                ", ".join(str(keyword) for keyword in row.get("keywords", [])[:3] if str(keyword).strip()),
            ])
            location_text = ", ".join(self._photo_entry_location_text(entry, place_labels_by_asset_id))
            camera_text = ", ".join(self._photo_entry_camera_text(entry))
            people_text = ", ".join(self._photo_entry_named_people(entry))
            ocr_text = ", ".join(self._photo_entry_ocr_text(entry))
            detected_item_text = ", ".join(self._photo_entry_detected_item_text(entry))
            depth_text = ", ".join(self._photo_entry_depth_metadata_text(entry))
            iptc_text = ", ".join(self._photo_entry_iptc_metadata_text(entry))
            technical_text = ", ".join(self._photo_entry_technical_metadata_text(entry))
            semantic_query = semantic_match_by_asset_id.get(str(row.get("assetId", "") or ""))
            snippet_candidates = [
                ("Title", title),
                ("Caption", row.get("caption", "")),
                ("Detected text", ocr_text),
                ("Detected items", detected_item_text),
                ("Depth", depth_text),
                ("Keywords", ", ".join(str(keyword) for keyword in row.get("keywords", []) if str(keyword).strip())),
                ("People", people_text),
                ("Location", location_text),
                ("Camera", camera_text),
                ("IPTC", iptc_text),
                ("Technical", technical_text),
                ("Media", str(row.get("mediaKind", "") or "").replace("_", " ").title()),
                ("Date", str(row.get("captureDate", "") or "")[:10]),
                ("File", Path(source).name),
                ("Source folder", str(Path(source).parent)),
            ]
            snippet = next(
                (
                    candidate
                    for candidate in [
                        *[search_snippet(label, value) for label, value in snippet_candidates],
                        semantic_snippet(semantic_query, snippet_candidates) if semantic_query else "",
                    ]
                    if candidate
                ),
                "",
            )
            match_reasons = search_match_reasons(snippet_candidates, semantic_query=semantic_query)
            return {
                "id": f"photo:{source}",
                "kind": "photo",
                "title": title,
                "subtitle": subtitle or source,
                "snippet": snippet,
                "matchReasons": match_reasons,
                "sourcePath": source,
                "previewPath": row.get("previewPath"),
                "assetId": str(row.get("assetId", "") or ""),
                "mediaKind": row.get("mediaKind", ""),
                "captureDate": row.get("captureDate", ""),
                "folderId": "all",
                "searchText": source or title,
            }

        def folder_haystack(folder: dict[str, Any]) -> list[str]:
            place = folder.get("place", {}) if isinstance(folder.get("place", {}), dict) else {}
            trip = folder.get("trip", {}) if isinstance(folder.get("trip", {}), dict) else {}
            memory = folder.get("memory", {}) if isinstance(folder.get("memory", {}), dict) else {}
            import_session = folder.get("importSession", {}) if isinstance(folder.get("importSession", {}), dict) else {}
            import_source = folder.get("importSource", {}) if isinstance(folder.get("importSource", {}), dict) else {}
            rule_summary = folder.get("ruleSummary", []) if isinstance(folder.get("ruleSummary", []), list) else []
            group_people = folder.get("groupPeople", []) if isinstance(folder.get("groupPeople", []), list) else []
            group_pets = folder.get("groupPets", []) if isinstance(folder.get("groupPets", []), list) else []
            group_members = [str(person) for person in group_people if str(person).strip()] + [str(pet) for pet in group_pets if str(pet).strip()]
            location_labels = trip.get("locationLabels", []) if isinstance(trip.get("locationLabels", []), list) else []
            utility_classifier = str(folder.get("utilityClassifier", "") or "")
            utility_classifier_terms: list[str] = []
            if utility_classifier:
                classifier = next(
                    (item for item in PHOTO_UTILITY_CLASSIFIERS.values() if str(item.get("kind", "") or "") == utility_classifier),
                    {},
                )
                utility_classifier_terms = [str(term) for term in classifier.get("terms", []) if str(term).strip()]
            values = [
                str(folder.get("name", "") or ""),
                str(folder.get("description", "") or ""),
                str(folder.get("kind", "") or ""),
                str(folder.get("albumKind", "") or ""),
                str(folder.get("mediaKind", "") or ""),
                str(folder.get("petName", "") or ""),
                str(folder.get("petKind", "") or ""),
                str(folder.get("petKindLabel", "") or ""),
                utility_classifier,
                str(folder.get("importSourceKind", "") or ""),
                str(folder.get("importSourceLabel", "") or ""),
                str(import_session.get("sourceLabel", "") or ""),
                str(import_source.get("kind", "") or ""),
                str(import_source.get("label", "") or ""),
                str(place.get("name", "") or ""),
                str(place.get("label", "") or ""),
                str(place.get("latitude", "") or ""),
                str(place.get("longitude", "") or ""),
                str(trip.get("name", "") or ""),
                str(trip.get("dateRangeLabel", "") or ""),
                str(trip.get("locationLabel", "") or ""),
                str(trip.get("startDate", "") or ""),
                str(trip.get("endDate", "") or ""),
                str(memory.get("name", "") or ""),
                str(memory.get("subtitle", "") or ""),
                str(memory.get("category", "") or ""),
                str(memory.get("dateRangeLabel", "") or ""),
                str(memory.get("startDate", "") or ""),
                str(memory.get("endDate", "") or ""),
                *[str(label) for label in location_labels],
                *utility_classifier_terms,
                *[str(item) for item in rule_summary],
                " ".join(str(person) for person in group_people if str(person).strip()),
                *[str(person) for person in group_people],
                " ".join(str(pet) for pet in group_pets if str(pet).strip()),
                *[str(pet) for pet in group_pets],
                " ".join(group_members),
                ", ".join(group_members),
            ]
            return [value for value in values if value]

        def folder_matches(folder: dict[str, Any]) -> bool:
            return any(value_matches(value) for value in folder_haystack(folder))

        def folder_curation_penalty(folder: dict[str, Any]) -> int:
            return search_suggestion_curation_penalty(folder_haystack(folder))

        def folder_subtitle(folder: dict[str, Any]) -> str:
            kind = str(folder.get("kind", "") or "")
            count = int(folder.get("count", 0) or 0)
            album_kind = str(folder.get("albumKind", "") or "")
            if kind == "albumFolder":
                album_count = int(folder.get("albumCount", 0) or 0)
                return joined([plural(album_count, "album"), plural(count, "photo")])
            if kind == "album" and album_kind:
                return joined([album_kind.title(), plural(count, "photo")])
            if kind == "person":
                return plural(count, "photo")
            if kind == "pet":
                return joined([str(folder.get("petKindLabel", "") or "Pet"), plural(count, "photo")])
            if kind == "group":
                people = folder.get("groupPeople", []) if isinstance(folder.get("groupPeople", []), list) else []
                pets = folder.get("groupPets", []) if isinstance(folder.get("groupPets", []), list) else []
                members = [str(person) for person in people if str(person).strip()] + [str(pet) for pet in pets if str(pet).strip()]
                return joined([", ".join(members), plural(count, "photo")])
            if kind == "source":
                source_kind = str(folder.get("importSourceKind", "") or "").replace("_", " ").title()
                return joined([source_kind, plural(count, "photo")])
            if kind == "unknown":
                return joined(["Unmatched cluster", plural(count, "photo")])
            if kind == "place":
                place = folder.get("place", {}) if isinstance(folder.get("place", {}), dict) else {}
                return joined([str(place.get("label", "") or ""), plural(count, "photo")])
            if kind == "trip":
                trip = folder.get("trip", {}) if isinstance(folder.get("trip", {}), dict) else {}
                return joined([str(trip.get("dateRangeLabel", "") or ""), str(trip.get("locationLabel", "") or ""), plural(count, "photo")])
            if kind == "memory":
                memory = folder.get("memory", {}) if isinstance(folder.get("memory", {}), dict) else {}
                return joined([str(memory.get("subtitle", "") or ""), str(memory.get("dateRangeLabel", "") or ""), plural(count, "photo")])
            media_kind = str(folder.get("mediaKind", "") or "").replace("_", " ").title()
            return joined([media_kind, plural(count, "photo")])

        def folder_result(folder: dict[str, Any]) -> dict[str, Any]:
            kind = str(folder.get("kind", "") or "")
            name = str(folder.get("name", "") or "")
            primary_reason = {
                "album": "Album",
                "albumFolder": "Album folder",
                "person": "People",
                "unknown": "People",
                "group": "People",
                "pet": "Pet",
                "place": "Location",
                "trip": "Trip",
                "memory": "Memory",
                "source": "Source",
                "utility": "Collection",
                "all": "Collection",
            }.get(kind, "Collection")
            reason_candidates = [
                (primary_reason, name),
                ("Collection", folder.get("name", "")),
                ("Description", folder.get("description", "")),
                ("Collection type", kind.replace("_", " ").title()),
                ("Album type", folder.get("albumKind", "")),
                ("Media type", folder.get("mediaKind", "")),
                ("Person", ", ".join(str(person) for person in folder.get("groupPeople", []) if str(person).strip()) if isinstance(folder.get("groupPeople", []), list) else ""),
                ("Pet", ", ".join(str(pet) for pet in folder.get("groupPets", []) if str(pet).strip()) if isinstance(folder.get("groupPets", []), list) else ""),
                ("Source", folder.get("importSourceLabel", "")),
                ("Source", folder.get("importSourceKind", "")),
            ]
            return {
                "id": str(folder.get("id", "") or ""),
                "kind": "folder",
                "title": name or "Collection",
                "subtitle": folder_subtitle(folder),
                "matchReasons": search_match_reasons(reason_candidates),
                "folderId": str(folder.get("id", "") or ""),
                "folderKind": kind,
                "albumKind": str(folder.get("albumKind", "") or ""),
                "count": int(folder.get("count", 0) or 0),
                "coverPreviewPath": folder.get("coverPreviewPath"),
                "importSourceKind": str(folder.get("importSourceKind", "") or ""),
                "importSourceLabel": str(folder.get("importSourceLabel", "") or ""),
            }

        folders = [
            folder
            for _, folder in sorted(
                [
                    (index, folder)
                    for index, folder in enumerate(self._photo_search_folder_candidates(
                        search_queries,
                        library_root_filter=library_root_filter,
                        library_root_source_filters=library_root_source_filters,
                        matches_by_source=matches_by_source,
                        photo_entries=photo_entries,
                        limit=max(limit * 6, suggestion_limit),
                    ))
                    if folder_matches(folder)
                ],
                key=lambda pair: (folder_curation_penalty(pair[1]), pair[0]),
            )
        ]
        album_folders = [folder_result(folder) for folder in folders if str(folder.get("kind", "") or "") in {"album", "albumFolder"}]
        people_folders = [folder_result(folder) for folder in folders if str(folder.get("kind", "") or "") in {"person", "unknown", "group", "pet"}]
        place_folders = [folder_result(folder) for folder in folders if str(folder.get("kind", "") or "") == "place"]
        trip_folders = [folder_result(folder) for folder in folders if str(folder.get("kind", "") or "") == "trip"]
        memory_folders = [folder_result(folder) for folder in folders if str(folder.get("kind", "") or "") == "memory"]
        source_folders = [folder_result(folder) for folder in folders if str(folder.get("kind", "") or "") == "source"]
        collection_folders = [
            folder_result(folder)
            for folder in folders
            if str(folder.get("kind", "") or "") in {"all", "utility"}
        ]

        keywords = [
            keyword for keyword in self.project.db.list_photo_keywords()
            if value_matches(keyword.get("name", ""))
            or value_matches(keyword.get("shortcut", ""))
        ]
        keyword_items = [
            {
                "id": f"keyword:{keyword.get('keywordId', keyword.get('name', ''))}",
                "kind": "keyword",
                "title": str(keyword.get("name", "") or "Keyword"),
                "subtitle": plural(int(keyword.get("count", 0) or 0), "photo"),
                "matchReasons": search_match_reasons([
                    ("Keyword", keyword.get("name", "")),
                    ("Shortcut", keyword.get("shortcut", "")),
                ]),
                "keyword": str(keyword.get("name", "") or ""),
                "count": int(keyword.get("count", 0) or 0),
            }
            for keyword in keywords
        ]
        source_folder_by_key: dict[str, dict[str, Any]] = {}
        for search_query in search_queries:
            for folder in self.project.db.search_photo_source_folders(
                search_query,
                limit=max(limit * 3, suggestion_limit),
                source_text_filters=library_root_source_filters,
            ):
                folder_path = str(folder.get("folderPath", "") or "")
                key = folder_path.replace("\\", "/").rstrip("/").casefold()
                if not key or key in source_folder_by_key:
                    continue
                source_folder_by_key[key] = folder
        source_folder_items = [
            {
                "id": f"sourceFolder:{folder_key}",
                "kind": "sourceFolder",
                "title": str(folder.get("name", "") or folder.get("folderPath", "") or "Source folder"),
                "subtitle": joined([str(folder.get("folderPath", "") or ""), plural(int(folder.get("count", 0) or 0), "photo")]),
                "snippet": search_snippet("Source folder", folder.get("folderPath", "")),
                "matchReasons": search_match_reasons([
                    ("Source folder", folder.get("folderPath", "")),
                    ("Name", folder.get("name", "")),
                ]),
                "sourcePath": str(folder.get("folderPath", "") or ""),
                "folderId": "all",
                "count": int(folder.get("count", 0) or 0),
                "coverPreviewPath": self.project.preview_path_for(str(folder.get("coverSourcePath", "") or ""), create=False) if str(folder.get("coverSourcePath", "") or "") else None,
            }
            for folder_key, folder in source_folder_by_key.items()
        ]

        date_items = []
        seen_date_buckets: set[tuple[str, str]] = set()
        if library_root_filter:
            for bucket_mode in ("years", "months", "days", "recentDays"):
                for bucket in self.list_photo_date_buckets({
                    "folderId": "all",
                    "mode": bucket_mode,
                    "libraryRoot": library_root_filter,
                }).get("buckets", []):
                    bucket_key = (bucket_mode, str(bucket.get("key", "") or ""))
                    bucket_label = str(bucket.get("label", "") or "")
                    if not any(value_matches(value) for value in (bucket_key[1], bucket_label)):
                        continue
                    if bucket_key in seen_date_buckets:
                        continue
                    seen_date_buckets.add(bucket_key)
                    bucket["mode"] = bucket_mode
                    bucket["dateBucketKey"] = bucket_key[1]
                    bucket["title"] = bucket_label or bucket_key[1]
                    bucket["subtitle"] = plural(int(bucket.get("count", 0) or 0), "photo")
                    bucket["matchReasons"] = search_match_reasons([
                        ("Date", bucket.get("title", "")),
                        ("Date", bucket.get("dateBucketKey", "")),
                    ])
                    date_items.append(bucket)
        else:
            for search_query in search_queries:
                for bucket in self.project.db.search_photo_date_buckets(search_query, limit=max(limit * 3, suggestion_limit)):
                    bucket_key = (str(bucket.get("mode", "") or ""), str(bucket.get("dateBucketKey", "") or ""))
                    if bucket_key in seen_date_buckets:
                        continue
                    seen_date_buckets.add(bucket_key)
                    bucket["subtitle"] = plural(int(bucket.get("count", 0) or 0), "photo")
                    cover_source = str(bucket.get("coverSourcePath", "") or "")
                    bucket["coverPreviewPath"] = self.project.preview_path_for(cover_source, create=False) if cover_source else None
                    bucket["matchReasons"] = search_match_reasons([
                        ("Date", bucket.get("title", "")),
                        ("Date", bucket.get("dateBucketKey", "")),
                    ])
                    date_items.append(bucket)

        photo_items = [photo_result(entry) for entry in photo_entries]
        for item in photo_items:
            item_penalty = photo_entry_curation_penalty_by_source.get(str(item.get("sourcePath", "") or ""), 0)
            add_suggestion(item.get("title", ""), item_penalty)
            add_suggestion(item.get("snippet", ""), item_penalty)
            add_suggestion(item.get("subtitle", ""), item_penalty)
            add_suggestion(Path(str(item.get("sourcePath", "") or "")).stem, item_penalty)
        for folder in folders:
            folder_penalty = folder_curation_penalty(folder)
            for value in folder_haystack(folder):
                add_suggestion(value, folder_penalty)
        for keyword in keywords:
            add_suggestion(keyword.get("name", ""))
            add_suggestion(keyword.get("shortcut", ""))
        for folder in source_folder_by_key.values():
            source_folder_penalty = search_suggestion_curation_penalty([
                folder.get("name", ""),
                folder.get("folderPath", ""),
            ])
            add_suggestion(folder.get("name", ""), source_folder_penalty)
            add_suggestion(folder.get("folderPath", ""), source_folder_penalty)
        for bucket in date_items:
            bucket_penalty = search_suggestion_curation_penalty([
                bucket.get("title", ""),
                bucket.get("dateBucketKey", ""),
            ])
            add_suggestion(bucket.get("title", ""), bucket_penalty)
            add_suggestion(bucket.get("dateBucketKey", ""), bucket_penalty)

        def group(group_id: str, label: str, items: list[dict[str, Any]], total: int | None = None) -> dict[str, Any] | None:
            if not items:
                return None
            item_total = len(items) if total is None else max(total, len(items))
            returned = min(len(items), limit)
            has_more = item_total > returned
            return {
                "id": group_id,
                "label": label,
                "total": item_total,
                "returned": returned,
                "hasMore": has_more,
                "capped": has_more,
                "estimatedTotal": bool(total is None and has_more),
                "items": items[:limit],
            }

        groups = [
            candidate for candidate in [
                group("photos", "Photos", photo_items, photo_total),
                group("albums", "Albums", album_folders),
                group("people", "People", people_folders),
                group("places", "Places", place_folders),
                group("trips", "Trips", trip_folders),
                group("memories", "Memories", memory_folders),
                group("sources", "Sources", source_folders),
                group("keywords", "Keywords", keyword_items),
                group("sourceFolders", "Source Folders", source_folder_items),
                group("dates", "Dates", date_items),
                group("collections", "Collections", collection_folders),
            ]
            if candidate is not None
        ]
        return {
            "query": query,
            "semanticQueries": semantic_queries,
            "searchIndex": search_index,
            "total": sum(int(group_item.get("total", 0) or 0) for group_item in groups),
            "returned": sum(len(group_item.get("items", []) or []) for group_item in groups),
            "groups": groups,
            "suggestions": [
                str(suggestion.get("text", "") or "")
                for suggestion in sorted(
                    suggestions,
                    key=lambda item: (int(item.get("_curationPenalty", 0) or 0), int(item.get("_position", 0) or 0)),
                )[:suggestion_limit]
            ],
        }

    def _photo_semantic_candidate_assets(self, params: dict[str, Any]) -> list[dict[str, str]]:
        """Resolve candidate image assets for semantic search without a library cap."""
        raw_paths = params.get("sourcePaths")
        source_paths: list[str] = []
        if isinstance(raw_paths, list) and raw_paths:
            for value in raw_paths:
                text = str(value or "").strip()
                if text and text not in source_paths:
                    source_paths.append(text)
        return self.project.db.list_photo_semantic_candidate_assets(source_paths=source_paths or None)

    def _photo_semantic_file_stat(self, path: Path) -> tuple[int, int]:
        try:
            stat = path.stat()
            return int(stat.st_size), int(stat.st_mtime_ns)
        except OSError:
            return -1, -1

    def semantic_search_photos(self, params: dict[str, Any]) -> dict[str, Any]:
        """Rank photos against a free-text query with on-device SigLIP 2 embeddings.

        Fully offline (ONNX/onnxruntime CPU). Degrades to an explicit
        ``available: False`` payload when the 'siglip2' model pack is not installed,
        so callers can fall back to the lexical search_photo_library path.
        """
        import numpy as np

        from crossage_fr.embed import siglip_engine

        query = str(params.get("query", "") or "").strip()
        if not query:
            raise ValueError("query is required.")
        limit = max(1, min(200, int(params.get("limit", 30) or 30)))

        report = siglip_engine.semantic_model_report()
        if not report.get("available"):
            return {
                "available": False,
                "query": query,
                "results": [],
                "scored": 0,
                "reason": report.get("reason")
                or "Install the 'siglip2' semantic-search model pack to enable natural-language photo search.",
            }

        query_vector = siglip_engine.encode_text(query)
        if query_vector is None:
            return {"available": False, "query": query, "results": [], "scored": 0,
                    "reason": "Semantic-search model became unavailable."}
        query_values = np.asarray(query_vector, dtype=np.float32).reshape(-1)
        if query_values.size == 0 or not np.isfinite(query_values).all():
            return {"available": False, "query": query, "results": [], "scored": 0,
                    "reason": "Semantic-search model returned an invalid text vector."}

        model_name = str(report.get("modelName", "SigLIP2") or "SigLIP2")
        candidates = self._photo_semantic_candidate_assets(params)
        scored: list[tuple[float, str]] = []
        encoded = 0
        cached = 0
        skipped = 0
        for asset in candidates:
            asset_id = str(asset.get("assetId", "") or "")
            source_path = str(asset.get("sourcePath", "") or "")
            if not asset_id or not source_path:
                skipped += 1
                continue
            path = Path(source_path).expanduser()
            if path.suffix.lower() not in IMAGE_EXTENSIONS or not path.exists():
                skipped += 1
                continue
            file_size, file_mtime_ns = self._photo_semantic_file_stat(path)
            vector_values = self.project.db.photo_semantic_embedding_for_asset(
                asset_id=asset_id,
                model_name=model_name,
                file_size=file_size,
                file_mtime_ns=file_mtime_ns,
            )
            if vector_values is not None:
                cached += 1
                vector = np.asarray(vector_values, dtype=np.float32).reshape(-1)
            else:
                try:
                    encoded_vector = siglip_engine.encode_image_path_cached(path)
                except Exception:
                    encoded_vector = None
                if encoded_vector is None:
                    skipped += 1
                    continue
                vector = np.asarray(encoded_vector, dtype=np.float32).reshape(-1)
                self.project.db.upsert_photo_semantic_embedding(
                    asset_id=asset_id,
                    model_name=model_name,
                    source_path=source_path,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    vector=vector.tolist(),
                )
                encoded += 1
            if vector.shape != query_values.shape or not np.isfinite(vector).all():
                skipped += 1
                continue
            scored.append((float(np.dot(query_values, vector)), source_path))
        scored.sort(key=lambda item: item[0], reverse=True)
        top = scored[:limit]
        results = [{"sourcePath": path, "score": round(score, 4)} for score, path in top]
        # `items` carries a previewPath so the main process decorates it into a
        # vintrace-media:// previewUrl (thumbnails) — same path the photo grid uses.
        items: list[dict[str, Any]] = []
        for score, path in top:
            try:
                preview_path = self.project.preview_path_for(path, create=True) or ""
            except Exception:
                preview_path = ""
            items.append({
                "sourcePath": path,
                "score": round(score, 4),
                "previewPath": preview_path,
                "mediaKind": self._media_kind_for_source(path),
                "name": Path(path).name,
            })
        return {
            "available": True,
            "engine": report.get("modelName", "SigLIP2"),
            "query": query,
            "candidateCount": len(candidates),
            "scored": len(scored),
            "encoded": encoded,
            "cached": cached,
            "skipped": skipped,
            "dropped": 0,
            "results": results,
            "items": items,
        }

    def list_photo_assets(self, params: dict[str, Any]) -> dict[str, Any]:
        offset = max(0, int(params.get("offset", 0) or 0))
        limit = max(1, min(500, int(params.get("limit", 100) or 100)))
        media_kind = str(params.get("mediaKind", "") or "").strip().lower()
        query = str(params.get("query", "") or "").strip()
        if media_kind and media_kind not in PHOTO_MEDIA_KINDS:
            raise ValueError("mediaKind must be a known Photos media kind or empty.")
        if bool(params.get("backfill", False)):
            self.project.db.backfill_photo_assets_from_scan_media(missing_only=True)
            self.project.db.backfill_photo_assets_from_review_candidates(missing_only=True)
            search_index = self.project.db.ensure_photo_search_index(allow_rebuild=False, enqueue_on_cold=True, repair_limit=1000)
        elif query:
            search_index = self.project.db.ensure_photo_search_index(allow_rebuild=False, enqueue_on_cold=True, repair_limit=1000)
        else:
            search_index = {}
        if query:
            search_result = self.project.db.search_photo_assets(query, offset=offset, limit=limit, media_kind=media_kind)
            asset_ids = search_result["assetIds"]
            assets = [
                asset
                for asset_id in asset_ids
                for asset in [self.project.db.photo_asset_by_id(asset_id)]
                if asset
            ]
            # PC: a search-indexed id can fail to hydrate only if the asset was
            # deleted between the FTS query and hydration. Discount those from
            # total so the client's offset/total pagination math stays
            # consistent (otherwise total counts rows that can never be reached,
            # and a fixed offset+=limit pager loops forever on the last page).
            missing = len(asset_ids) - len(assets)
            total = max(offset + len(assets), int(search_result["total"]) - missing)
        else:
            assets = self.project.db.list_photo_assets(offset=offset, limit=limit, media_kind=media_kind)
            total = self.project.db.count_photo_assets(media_kind=media_kind)
        items = [
            {
                **asset,
                "metadata": {
                    **asset.get("metadata", {}),
                    **self.project.db.photo_asset_metadata_by_id(str(asset.get("assetId", ""))),
                },
                "people": self.project.db.list_photo_asset_people(str(asset.get("assetId", ""))),
            }
            for asset in assets
        ]
        return {
            "total": total,
            "offset": offset,
            "limit": limit,
            "returned": len(items),
            "items": items,
            "searchIndex": search_index,
        }

    def list_photo_keywords(self, params: dict[str, Any]) -> dict[str, Any]:
        query = str(params.get("query", "") or "").strip().casefold()
        keywords = self.project.db.list_photo_keywords()
        if query:
            keywords = [
                keyword for keyword in keywords
                if query in str(keyword.get("name", "") or "").casefold()
            ]
        return {"keywords": keywords}

