    def _photo_keyword_export_payload(self) -> dict[str, Any]:
        keywords = [
            {
                "name": str(keyword.get("name", "") or ""),
                "shortcut": str(keyword.get("shortcut", "") or ""),
                "count": int(keyword.get("count", 0) or 0),
            }
            for keyword in self.project.db.list_photo_keywords()
            if str(keyword.get("name", "") or "").strip()
        ]
        return {
            "format": "vintrace-photo-keywords-v1",
            "generatedAt": datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "keywordCount": len(keywords),
            "keywords": keywords,
        }

    def export_photo_keywords(self, params: dict[str, Any]) -> dict[str, Any]:
        payload = self._photo_keyword_export_payload()
        folder_value = str(params.get("folder", "") or "").strip()
        export_root = safe_resolve(Path(folder_value).expanduser()) if folder_value else (self.project.root / "exports").resolve()
        export_root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        target = export_root / f"vintrace-photo-keywords-{stamp}.json"
        counter = 2
        while target.exists():
            target = export_root / f"vintrace-photo-keywords-{stamp}-{counter}.json"
            counter += 1
        target.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        result = {
            "path": str(target),
            "exported": int(payload["keywordCount"]),
            "keywords": payload["keywords"],
            "format": payload["format"],
            "generatedAt": payload["generatedAt"],
        }
        self.project._append_audit(
            {
                "action": "export_photo_keywords",
                "path": str(target),
                "exported": int(payload["keywordCount"]),
            }
        )
        return result

    def _photo_keyword_import_payload(self, params: dict[str, Any]) -> Any:
        if isinstance(params.get("payload"), (dict, list)):
            return params["payload"]
        json_text = str(params.get("json", "") or params.get("text", "") or "").strip()
        path_text = str(params.get("path", "") or "").strip()
        if json_text:
            if len(json_text.encode("utf-8")) > 2 * 1024 * 1024:
                raise ValueError("Keyword import JSON must be 2 MB or smaller.")
            return json.loads(json_text)
        if path_text:
            source = safe_resolve(Path(path_text).expanduser())
            if not source.is_file():
                raise ValueError("Keyword import path must be a JSON file.")
            if source.stat().st_size > 2 * 1024 * 1024:
                raise ValueError("Keyword import file must be 2 MB or smaller.")
            return json.loads(source.read_text(encoding="utf-8"))
        raise ValueError("Provide keyword import JSON or a local JSON path.")

    def _photo_keyword_import_rows(self, payload: Any) -> list[dict[str, str]]:
        raw_rows = payload
        if isinstance(payload, dict):
            raw_rows = payload.get("keywords", [])
        if not isinstance(raw_rows, list):
            raise ValueError("Keyword import payload must contain a keywords list.")
        rows: list[dict[str, str]] = []
        seen: set[str] = set()
        for raw in raw_rows[:1000]:
            if isinstance(raw, str):
                name = raw
                shortcut = ""
            elif isinstance(raw, dict):
                name = str(raw.get("name", raw.get("keyword", raw.get("title", ""))) or "")
                shortcut = str(raw.get("shortcut", raw.get("key", "")) or "")
            else:
                continue
            cleaned = self.project.db._clean_photo_keywords([name])  # noqa: SLF001
            if not cleaned:
                continue
            clean_name = cleaned[0]
            name_key = clean_name.casefold()
            if name_key in seen:
                continue
            seen.add(name_key)
            rows.append({"name": clean_name, "shortcut": re.sub(r"\s+", " ", shortcut.strip())[:24]})
        return rows

    def import_photo_keywords(self, params: dict[str, Any]) -> dict[str, Any]:
        payload = self._photo_keyword_import_payload(params)
        rows = self._photo_keyword_import_rows(payload)
        before = {
            str(keyword.get("name", "") or "").casefold(): str(keyword.get("shortcut", "") or "")
            for keyword in self.project.db.list_photo_keywords()
        }
        imported: list[dict[str, Any]] = []
        created = 0
        updated = 0
        skipped = 0
        for row in rows:
            name = row["name"]
            name_key = name.casefold()
            shortcut = row["shortcut"]
            if before.get(name_key, None) == shortcut:
                skipped += 1
            elif name_key in before:
                updated += 1
            else:
                created += 1
            imported.append(self.project.db.save_photo_keyword(name=name, shortcut=shortcut))
        result = {
            "imported": len(imported),
            "created": created,
            "updated": updated,
            "skipped": skipped,
            "keywords": imported,
        }
        self.project._append_audit(
            {
                "action": "import_photo_keywords",
                "imported": len(imported),
                "created": created,
                "updated": updated,
                "skipped": skipped,
            }
        )
        return result

