    def save_photo_place_profile(self, params: dict[str, Any]) -> dict[str, Any]:
        place_id = str(params.get("placeId", params.get("place_id", "")) or "").strip()
        if not place_id:
            raise ValueError("placeId is required.")
        key_asset_id = str(params.get("keyAssetId", params.get("key_asset_id", "")) or "").strip() if "keyAssetId" in params or "key_asset_id" in params else None
        places = self.project.db.list_photo_places()
        place = next((item for item in places if str(item.get("placeId", "") or "") == place_id), None)
        if place is None:
            raise KeyError(f"Place {place_id!r} was not found.")
        if key_asset_id:
            asset_ids = {str(asset_id or "") for asset_id in place.get("assetIds", [])}
            if key_asset_id not in asset_ids:
                raise ValueError("keyAssetId must belong to the selected place.")
        profile = self.project.db.save_photo_place_profile(
            place_id=place_id,
            key_asset_id=key_asset_id,
        )
        self.project._append_audit(
            {
                "action": "save_photo_place_profile",
                "place_id": profile.get("placeId", ""),
                "key_asset_id": profile.get("keyAssetId", ""),
            }
        )
        return profile

    def _photo_utility_cover_allowed(self, utility_id: str) -> bool:
        clean_utility_id = str(utility_id or "").strip()
        if clean_utility_id in PHOTO_UTILITY_COVER_ALLOWED_IDS:
            return True
        if clean_utility_id in PHOTO_UTILITY_CLASSIFIER_IDS:
            return True
        if clean_utility_id.startswith("media:"):
            return clean_utility_id[len("media:"):].strip().lower() in PHOTO_MEDIA_KINDS
        return False

    def _photo_utility_folder_contains_asset(self, utility_id: str, key_asset_id: str) -> bool:
        clean_utility_id = str(utility_id or "").strip()
        clean_key_asset_id = str(key_asset_id or "").strip()
        if not clean_utility_id or not clean_key_asset_id:
            return False
        asset = self.project.db.photo_asset_by_id(clean_key_asset_id)
        if not asset:
            return False
        asset_source_path = str(asset.get("sourcePath", "") or "")
        for entry in self._photo_asset_entries(clean_utility_id):
            entry_asset_id = str(entry.get("_assetId", "") or "")
            entry_source_path = str(entry.get("sourcePath", "") or "")
            if entry_asset_id == clean_key_asset_id or (asset_source_path and entry_source_path == asset_source_path):
                return True
        return False

    def save_photo_utility_profile(self, params: dict[str, Any]) -> dict[str, Any]:
        utility_id = str(
            params.get(
                "utilityId",
                params.get("folderId", params.get("utility_id", "")),
            )
            or ""
        ).strip()
        if not utility_id:
            raise ValueError("utilityId is required.")
        if not self._photo_utility_cover_allowed(utility_id):
            raise ValueError("This utility folder does not support custom covers.")
        key_asset_id = str(params.get("keyAssetId", params.get("key_asset_id", "")) or "").strip() if "keyAssetId" in params or "key_asset_id" in params else None
        if key_asset_id and not self._photo_utility_folder_contains_asset(utility_id, key_asset_id):
            raise ValueError("keyAssetId must belong to the selected utility folder.")
        profile = self.project.db.save_photo_utility_profile(
            utility_id=utility_id,
            key_asset_id=key_asset_id,
        )
        self.project._append_audit(
            {
                "action": "save_photo_utility_profile",
                "utility_id": profile.get("utilityId", ""),
                "key_asset_id": profile.get("keyAssetId", ""),
            }
        )
        return profile

    def _rename_photo_pet_scalar(self, value: Any, old_key: str, new_name: str) -> tuple[Any, bool]:
        if isinstance(value, bool) or not isinstance(value, (str, int, float)):
            return value, False
        text = str(value)
        if self._clean_photo_pet_label(text).casefold() == old_key:
            return new_name, True
        if not isinstance(value, str) or not re.search(r"[,;/|\n]", text):
            return value, False
        changed = False
        parts: list[str] = []
        for part in re.split(r"([,;/|\n]+)", text):
            if re.fullmatch(r"[,;/|\n]+", part or ""):
                parts.append(part)
                continue
            if self._clean_photo_pet_label(part).casefold() == old_key:
                parts.append(new_name)
                changed = True
            else:
                parts.append(part)
        return "".join(parts), changed

    def _rename_photo_pet_explicit_value(
        self,
        value: Any,
        *,
        old_key: str,
        new_name: str,
        depth: int = 0,
    ) -> tuple[Any, bool]:
        if depth > 6:
            return value, False
        if isinstance(value, (str, int, float)) and not isinstance(value, bool):
            return self._rename_photo_pet_scalar(value, old_key, new_name)
        if isinstance(value, list):
            changed = False
            next_items: list[Any] = []
            seen_scalar_names: set[str] = set()
            for item in value:
                next_item, item_changed = self._rename_photo_pet_explicit_value(
                    item,
                    old_key=old_key,
                    new_name=new_name,
                    depth=depth + 1,
                )
                if item_changed:
                    changed = True
                if isinstance(next_item, str):
                    name_key = self._clean_photo_pet_label(next_item).casefold()
                    if name_key and name_key in seen_scalar_names:
                        changed = True
                        continue
                    if name_key:
                        seen_scalar_names.add(name_key)
                next_items.append(next_item)
            return next_items, changed
        if isinstance(value, dict):
            changed = False
            next_value: dict[str, Any] = {}
            for key, item in value.items():
                normalized_key = re.sub(r"[^a-z0-9]+", "", str(key or "").casefold())
                if normalized_key in {"confidence", "score", "probability", "bbox", "bounds", "x", "y", "width", "height"}:
                    next_value[key] = item
                    continue
                if normalized_key in {"name", "label", "title", "value", *PHOTO_PET_NAME_KEYS}:
                    next_item, item_changed = self._rename_photo_pet_explicit_value(
                        item,
                        old_key=old_key,
                        new_name=new_name,
                        depth=depth + 1,
                    )
                    next_value[key] = next_item
                    changed = changed or item_changed
                    continue
                if normalized_key in PHOTO_PET_KIND_KEYS:
                    next_value[key] = item
                    continue
                next_item, item_changed = self._rename_photo_pet_explicit_value(
                    item,
                    old_key=old_key,
                    new_name=new_name,
                    depth=depth + 1,
                )
                next_value[key] = next_item
                changed = changed or item_changed
            return next_value, changed
        return value, False

    def _rename_photo_pet_metadata(self, metadata: dict[str, Any], old_name: str, new_name: str) -> tuple[dict[str, Any], bool, str]:
        old_key = old_name.casefold()
        changed = False
        next_metadata = dict(metadata)
        detected_kind = ""
        explicit_keys = {"petname", "petnames", "pets", "animals", "animalnames"}
        for key, value in metadata.items():
            normalized_key = re.sub(r"[^a-z0-9]+", "", str(key or "").casefold())
            if normalized_key not in explicit_keys:
                continue
            for record in self._photo_pet_explicit_records(value):
                if str(record.get("name", "") or "").casefold() == old_key:
                    detected_kind = self._photo_pet_kind_from_text(record.get("kind", "")) or detected_kind
            next_value, value_changed = self._rename_photo_pet_explicit_value(
                value,
                old_key=old_key,
                new_name=new_name,
            )
            if value_changed:
                next_metadata[key] = next_value
                changed = True
        return next_metadata, changed, detected_kind

    def _rewrite_photo_pet_name_list(self, values: Iterable[Any], old_name: str, new_name: str) -> tuple[list[str], bool]:
        old_key = old_name.casefold()
        changed = False
        rewritten: list[str] = []
        seen: set[str] = set()
        for value in values:
            pet = self._clean_photo_pet_label(value)
            if not pet:
                continue
            next_pet = new_name if pet.casefold() == old_key else pet
            changed = changed or next_pet != pet
            key = next_pet.casefold()
            if key in seen:
                changed = True
                continue
            seen.add(key)
            rewritten.append(next_pet)
        return rewritten, changed

    def rename_photo_pet(self, params: dict[str, Any]) -> dict[str, Any]:
        old_name = self._clean_photo_pet_label(params.get("oldName", params.get("oldPetName", "")))
        new_name = self._clean_photo_pet_label(params.get("newName", params.get("newPetName", "")))
        if not old_name or not new_name:
            raise ValueError("Both current and new pet names are required.")
        if old_name.casefold() == new_name.casefold():
            profile = self.project.db.photo_pet_profile(new_name)
            return {
                "oldName": old_name,
                "newName": new_name,
                "metadataRows": 0,
                "groupRows": 0,
                "profileMoved": False,
                "profileMerged": False,
                "profile": profile,
            }

        metadata_rows = 0
        group_rows = 0
        detected_kind = ""
        with self.project.db.connect() as conn:
            offset = 0
            page_size = 500
            while True:
                page = self.project.db.list_photo_asset_page(
                    offset=offset,
                    limit=page_size,
                    visibility="all",
                    sort="filename",
                    conn=conn,
                )
                assets = page.get("assets", []) if isinstance(page.get("assets"), list) else []
                if not assets:
                    break
                for asset in assets:
                    metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
                    next_metadata, changed, asset_kind = self._rename_photo_pet_metadata(metadata, old_name, new_name)
                    detected_kind = asset_kind or detected_kind
                    if not changed:
                        continue
                    self.project.db.update_photo_asset_metadata_json(
                        asset_id=str(asset.get("assetId", "") or ""),
                        patch=next_metadata,
                        conn=conn,
                    )
                    metadata_rows += 1
                offset += page_size
                if offset >= int(page.get("total", 0) or 0):
                    break

            old_profile = self.project.db.photo_pet_profile(old_name, conn)
            old_profile_touched = bool(
                old_profile.get("createdAt")
                or old_profile.get("keyAssetId")
                or old_profile.get("favorite")
                or old_profile.get("hidden")
                or old_profile.get("manualOrder") is not None
                or str(old_profile.get("petKind", "") or "").strip().lower() not in {"", "pet"}
            )
            profile_result = self.project.db.rename_photo_pet_profile(
                old_name,
                new_name,
                pet_kind=detected_kind or self._photo_pet_kind_from_text(params.get("petKind", "")) or None,
                conn=conn,
            )
            profile_touched = old_profile_touched

            for group in self.project.db.list_photo_people_groups(conn):
                member_pets, changed_members = self._rewrite_photo_pet_name_list(group.get("memberPets", []), old_name, new_name)
                exclude_pets, changed_excluded = self._rewrite_photo_pet_name_list(group.get("excludePets", []), old_name, new_name)
                if not changed_members and not changed_excluded:
                    continue
                member_people = group.get("memberPeople", [])
                group_id = str(group.get("groupId", "") or "")
                if len(member_people) + len(member_pets) < 2:
                    self.project.db.delete_photo_people_group(group_id, conn=conn)
                    group_rows += 1
                    continue
                old_default_name = self._photo_people_group_name(member_people, group.get("memberPets", []))
                next_name = str(group.get("name", "") or "")
                if next_name.strip() == old_default_name:
                    next_name = self._photo_people_group_name(member_people, member_pets)
                self.project.db.upsert_photo_people_group(
                    group_id=group_id,
                    name=next_name,
                    member_people=member_people,
                    exclude_people=group.get("excludePeople", []),
                    member_pets=member_pets,
                    exclude_pets=exclude_pets,
                    key_asset_id=str(group.get("keyAssetId", "") or ""),
                    favorite=bool(group.get("favorite")),
                    hidden=bool(group.get("hidden")),
                    manual_order=group.get("manualOrder"),
                    conn=conn,
                )
                group_rows += 1

        if not metadata_rows and not group_rows and not profile_touched:
            raise KeyError(f"Pet {old_name!r} was not found.")
        self.project._append_audit(
            {
                "action": "rename_photo_pet",
                "old_name": old_name,
                "new_name": new_name,
                "metadata_rows": metadata_rows,
                "group_rows": group_rows,
                "profile_moved": bool(profile_result.get("profileMoved")),
                "profile_merged": bool(profile_result.get("profileMerged")),
            }
        )
        return {
            "oldName": old_name,
            "newName": new_name,
            "metadataRows": metadata_rows,
            "groupRows": group_rows,
            "profileMoved": bool(profile_result.get("profileMoved")),
            "profileMerged": bool(profile_result.get("profileMerged")),
            "profile": profile_result.get("profile", {}),
        }

    def assign_photo_pet(self, params: dict[str, Any]) -> dict[str, Any]:
        pet_name = self._clean_photo_pet_label(params.get("petName", params.get("name", "")))
        if not pet_name:
            raise ValueError("petName is required.")
        source_path = str(params.get("sourcePath", "") or "").strip()
        asset_id = str(params.get("assetId", "") or "").strip()
        asset = self.project.db.photo_asset_by_id(asset_id) if asset_id else None
        if asset is None and source_path:
            asset = self.project.db.photo_asset_by_path(source_path)
        if asset is None:
            raise ValueError("A sourcePath or assetId is required.")

        asset_id = str(asset.get("assetId", "") or "")
        source_path = str(asset.get("sourcePath", "") or source_path)
        metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
        pet_kind = self._photo_pet_kind_from_text(params.get("petKind", params.get("kind", "")))
        if not pet_kind:
            entry = self._photo_source_entry(
                source_path=source_path,
                media_kind=str(asset.get("mediaKind", "") or self._media_kind_for_source(source_path)),
                matches_by_source={},
            )
            entry["_asset"] = asset
            entry["_metadata"] = self.project.db.photo_asset_metadata_by_id(asset_id)
            review_record = self._photo_pet_review_record_for_entry(entry)
            pet_kind = self._photo_pet_kind_from_text((review_record or {}).get("kind", "")) or "pet"

        raw_pets = metadata.get("pets", [])
        pets: list[Any] = raw_pets[:] if isinstance(raw_pets, list) else ([raw_pets] if raw_pets else [])
        pet_key = pet_name.casefold()
        assigned = False
        updated_pets: list[Any] = []
        found = False
        for item in pets:
            if isinstance(item, dict):
                item_name = self._clean_photo_pet_label(item.get("name", item.get("label", item.get("value", ""))))
                if item_name.casefold() == pet_key:
                    next_item = dict(item)
                    next_item["name"] = pet_name
                    next_item.setdefault("species", pet_kind)
                    next_item.setdefault("source", "manual")
                    updated_pets.append(next_item)
                    found = True
                    continue
            elif self._clean_photo_pet_label(item).casefold() == pet_key:
                updated_pets.append({"name": pet_name, "species": pet_kind, "source": "manual"})
                found = True
                assigned = True
                continue
            updated_pets.append(item)
        if not found:
            updated_pets.append({"name": pet_name, "species": pet_kind, "source": "manual"})
            assigned = True

        updated_asset = self.project.db.update_photo_asset_metadata_json(
            asset_id=asset_id,
            patch={"pets": updated_pets},
        )
        profile = self.project.db.save_photo_pet_profile(pet_name=pet_name, pet_kind=pet_kind)
        self.project._append_audit(
            {
                "action": "assign_photo_pet",
                "asset_id": asset_id,
                "source_path": source_path,
                "pet_name": pet_name,
                "pet_kind": pet_kind,
                "assigned": assigned,
            }
        )
        return {
            "assetId": asset_id,
            "sourcePath": source_path,
            "petName": pet_name,
            "petKind": pet_kind,
            "assigned": assigned,
            "asset": updated_asset,
            "profile": profile,
        }

    def dismiss_photo_pet_review(self, params: dict[str, Any]) -> dict[str, Any]:
        source_path = str(params.get("sourcePath", "") or "").strip()
        asset_id = str(params.get("assetId", "") or "").strip()
        asset = self.project.db.photo_asset_by_id(asset_id) if asset_id else None
        if asset is None and source_path:
            asset = self.project.db.photo_asset_by_path(source_path)
        if asset is None:
            raise ValueError("A sourcePath or assetId is required.")

        asset_id = str(asset.get("assetId", "") or "")
        source_path = str(asset.get("sourcePath", "") or source_path)
        metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
        entry = self._photo_source_entry(
            source_path=source_path,
            media_kind=str(asset.get("mediaKind", "") or self._media_kind_for_source(source_path)),
            matches_by_source={},
        )
        entry["_asset"] = asset
        entry["_metadata"] = self.project.db.photo_asset_metadata_by_id(asset_id)
        review_record = self._photo_pet_review_record_for_entry(entry)
        pet_kind = self._photo_pet_kind_from_text(params.get("petKind", params.get("kind", "")))
        if not pet_kind:
            pet_kind = self._photo_pet_kind_from_text((review_record or {}).get("kind", ""))
        if not pet_kind:
            raise ValueError("No generic pet review label was found for this photo.")

        existing = metadata.get("petReviewDismissedKinds", [])
        if isinstance(existing, dict):
            raw_values = list(existing.keys())
        elif isinstance(existing, list):
            raw_values = existing
        elif existing:
            raw_values = [existing]
        else:
            raw_values = []
        dismissed_kinds = {
            kind
            for value in raw_values
            for kind in [self._photo_pet_kind_from_text(value)]
            if kind
        }
        already_dismissed = pet_kind in dismissed_kinds
        dismissed_kinds.add(pet_kind)
        updated_asset = self.project.db.update_photo_asset_metadata_json(
            asset_id=asset_id,
            patch={
                "petReviewDismissedKinds": [self._photo_pet_kind_label(kind) for kind in sorted(dismissed_kinds)],
                "petReviewDismissedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            },
        )
        self.project._append_audit(
            {
                "action": "dismiss_photo_pet_review",
                "asset_id": asset_id,
                "source_path": source_path,
                "pet_kind": pet_kind,
                "already_dismissed": already_dismissed,
            }
        )
        return {
            "assetId": asset_id,
            "sourcePath": source_path,
            "petKind": pet_kind,
            "petKindLabel": self._photo_pet_kind_label(pet_kind),
            "dismissed": not already_dismissed,
            "asset": updated_asset,
        }

    def save_photo_people_group(self, params: dict[str, Any]) -> dict[str, Any]:
        member_people = self._clean_album_people(params.get("memberPeople", params.get("groupPeople", [])))
        exclude_people = self._clean_album_people(params.get("excludePeople", []))
        member_pets = [self._clean_photo_pet_label(value) for value in params.get("memberPets", params.get("groupPets", []))] if isinstance(params.get("memberPets", params.get("groupPets", [])), list) else []
        member_pets = list(dict.fromkeys(pet for pet in member_pets if pet))
        exclude_pets = [self._clean_photo_pet_label(value) for value in params.get("excludePets", [])] if isinstance(params.get("excludePets", []), list) else []
        exclude_pets = list(dict.fromkeys(pet for pet in exclude_pets if pet))
        group_id = str(params.get("groupId", "") or "").strip() or new_id("peopleGroup")
        manual_order_value = params.get("manualOrder")
        group = self.project.db.upsert_photo_people_group(
            group_id=group_id,
            name=str(params.get("name", "") or "").strip(),
            member_people=member_people,
            exclude_people=exclude_people,
            member_pets=member_pets,
            exclude_pets=exclude_pets,
            key_asset_id=str(params.get("keyAssetId", "")) if "keyAssetId" in params else None,
            favorite=bool(params.get("favorite")) if "favorite" in params else None,
            hidden=bool(params.get("hidden")) if "hidden" in params else None,
            manual_order=int(manual_order_value) if manual_order_value not in {None, ""} else None,
        )
        self.project._append_audit(
            {
                "action": "save_photo_people_group",
                "group_id": group.get("groupId", ""),
                "name": group.get("name", ""),
                "member_count": len(group.get("memberPeople", []) or []),
                "pet_member_count": len(group.get("memberPets", []) or []),
                "favorite": bool(group.get("favorite")),
                "hidden": bool(group.get("hidden")),
            }
        )
        return group

