    def permanently_delete_photos(self, params: dict[str, Any]) -> dict[str, Any]:
        source_paths_raw = params.get("sourcePaths", [])
        asset_ids_raw = params.get("assetIds", [])
        source_paths = [str(path or "").strip() for path in source_paths_raw if str(path or "").strip()] if isinstance(source_paths_raw, list) else []
        asset_ids = [str(asset_id or "").strip() for asset_id in asset_ids_raw if str(asset_id or "").strip()] if isinstance(asset_ids_raw, list) else []
        deleted_before = str(params.get("deletedBefore", "") or "").strip()
        if not deleted_before and params.get("olderThanDays") not in {None, ""}:
            days = max(1, min(3650, int(params.get("olderThanDays") or 30)))
            deleted_before = (datetime.utcnow() - timedelta(days=days)).isoformat(timespec="seconds") + "Z"
        result = self.project.db.permanently_delete_photo_assets(
            source_paths=source_paths,
            asset_ids=asset_ids,
            deleted_before=deleted_before,
            require_deleted=True,
        )
        for candidate_id in result.get("candidateIds", []) or []:
            self.project.candidates.pop(str(candidate_id or ""), None)
        try:
            self.project.db.ensure_photo_duplicate_groups()
        except Exception:
            pass
        self.project._append_audit(
            {
                "action": "permanently_delete_photos",
                "deleted_assets": int(result.get("deletedAssets", 0) or 0),
                "deleted_scan_files": int(result.get("deletedScanFiles", 0) or 0),
                "deleted_candidates": int(result.get("deletedCandidates", 0) or 0),
                "deleted_files": int(result.get("deletedFiles", 0) or 0),
                "managed_originals_trashed": int(result.get("managedOriginalsTrashed", 0) or 0),
                "deleted_before": str(result.get("deletedBefore", "") or ""),
                "original_media_deleted": bool(result.get("originalMediaDeleted", False)),
                "operation_id": (result.get("operation") or {}).get("operationId", "") if isinstance(result.get("operation"), dict) else "",
            }
        )
        return result

